import React, { Component } from 'react';
import iConfig from 'iConfig';
import styles from './ErrorBoundary.module.scss';

export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI.

    console.log('[ErrorBoundary] getDerivedStateFromError error', error);

    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Example "componentStack":
    //   in ComponentThatThrows (created by App)
    //   in ErrorBoundary (created by App)
    //   in div (created by App)
    //   in App

    console.log('[ErrorBoundary] componentDidCatch error', error);
    console.log('[ErrorBoundary] componentDidCatch errorInfo', errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo,
    });

    this.logErrorToMyService(error, errorInfo);
  }

  // logger service can be your own application monitoring tool etc
  logErrorToMyService(error, errorInfo) {}

  render() {
    if (this.state.hasError) {
      // You can render any custom fallback UI
      //return this.props.fallback;

      return iConfig.level >= 3 ? (
        <div className={styles.main}>
          <div className={styles.contentBox}>
            <div style={{ fontSize: '1.5rem' }}>發生錯誤</div>
            <ul>
              <li>回報黑畫面錯誤時，請額外附上此畫面截圖 (若內容過長請分頁截圖)</li>
              <li>此錯誤訊息只在內部測試版本顯示</li>
            </ul>
            <p style={{ whiteSpace: 'pre-wrap' }}>
              <div>
                版本： v
                {window.deviceInfo?.app_version
                  ? `${window.deviceInfo?.app_version}.${iConfig.web_version}`
                  : `${iConfig.app_version}.${iConfig.web_version}_`}
                {iConfig.level && `(${iConfig.level})`}
              </div>
              <div>錯誤：{this.state?.error?.toString()}</div>
              <div>{this.state?.errorInfo?.componentStack}</div>
            </p>
          </div>
        </div>
      ) : (
        <></>
      );
    }

    return this.props.children;
  }
}
