import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
  config,
} from '@react-spring/web';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  sample as lodash_sample,
  pickBy as lodash_pickBy,
  keys as lodash_keys,
  map as lodash_map,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Teams } from 'component/Teams';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './V3assignTeam.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { Matching } from 'component/modal/Matching';
import { AniDoor } from 'pages/unionbattle/AniDoor';
import { Actorcard } from 'component/Actorcard';
//
import arrow_ATK_left_chosen from 'assets/img2/unionbattle/arrow_ATK_left_chosen.png';
import arrow_ATK_right_chosen from 'assets/img2/unionbattle/arrow_ATK_right_chosen.png';
import golden_halfmoon from 'assets/img2/golden_halfmoon.png';
import highlightCircle from 'assets/img2/highlightCircle.png';
import pvp_teamselected_halo from 'assets/img2/pvp_teamselected_halo.png';

export const V3assignTeam = props => {
  const funcKey = `[V3assignTeam]`;
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();

  const [countdownNum, setCountdownNum] = useState(props.pvpChannelStatus.countdown || 20);
  const [selectedTeamIdx, setSelectedTeamIdx] = useState();
  const [confirmedTeamIdx, setConfirmedTeamIdx] = useState();
  //const [max_team_sent_to_battle, setMax_team_sent_to_battle] = useState(0); //解決 NPC teams 每隊 sent_to_battle 已事先排好有值，造成每隊都反黑
  //用來顯示雙方是否已指派隊伍的狀態(下方指派按鈕亮起)
  const [confirmedPlayers, setConfirmedPlayers] = useState({});

  useEffect(() => {}, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[V3assignTeam] channel player 未連線');
      return;
    }

    console.log('[V3assignTeam] channel player 已連線');
    DCContext.getActors();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    // let tmp = 0;
    // props.pvpChannelStatus._player1.teams.map((team, idx)=>{
    //   if (team.sent_to_battle){
    //     tmp = Math.max(tmp, team.sent_to_battle);
    //   }
    // });
    //console.log("[V3assignTeam] max_team_sent_to_battle", tmp);
    //setMax_team_sent_to_battle(tmp);
  }, [props.pvpChannelStatus._player1.teams]);

  useEffect(() => {
    if (!props.doorShowed) {
      return;
    }

    aniApi_flip.start({
      from: { transform: `rotateY(90deg)` },
      to: { transform: countdownNum === 0 ? `rotateY(0deg)` : `rotateY(-90deg)` },
    });
  }, [countdownNum, props.doorShowed]);

  const clickTeam = teamIdx => {
    console.log('[V3assignTeam] clickTeam', teamIdx);
    setSelectedTeamIdx(teamIdx);
  };

  const clickConfirm = () => {
    console.log(
      '[V3assignTeam] clickConfirm',
      selectedTeamIdx,
      props.pvpChannelStatus._player1.teams[selectedTeamIdx],
    );

    //送出指派隊伍，之後收到 broadcast 進入戰鬥場景
    DCContext.pvp_ready({
      to: 'confirm_team',
      team_id: props.pvpChannelStatus._player1.teams[selectedTeamIdx].id,
    });

    setConfirmedTeamIdx(selectedTeamIdx);
  };

  //Server broadcast pvp_battle:x

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[PvpBattle] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //pvp_battle:x
      case `${DCContext.pvpChannelTopic},team_confirmed`:
        //通知雙方有人已選定隊伍
        //console.log('[PvpBattle] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpData = ChannelContext.messages?.res?.payload;
        console.log('[V3assignTeam] broadcast team_confirmed', tmpData);

        setConfirmedPlayers(preState => {
          let tmp = { ...preState };
          if (tmpData.defender === props.pvpChannelStatus._player1._defender) {
            tmp[props.pvpChannelStatus._player1.user_id] = tmpData;
          }
          if (tmpData.defender === props.pvpChannelStatus._player2._defender) {
            tmp[props.pvpChannelStatus._player2.user_id] = tmpData;
          }

          console.log('[V3assignTeam] setConfirmedPlayers', tmp);

          return tmp;
        });

        break;
    }
  }, [ChannelContext.messages]);

  //我方自動選隊：第一二三回合選隊，倒數為零時，若我方尚未選隊，自動選定一隊
  useEffect(() => {
    //if (props.pvpChannelStatus.battle < 3 && countdownNum == 0 && confirmedTeamIdx == undefined){
    if (countdownNum == 0 && confirmedTeamIdx == undefined) {
      //選出符合條件隊伍並維持原有 index
      let tmpTeamsWithOrigIdx = lodash_pickBy(props.pvpChannelStatus._player1.teams, {
        sent_to_battle: null,
      });
      //console.log('[V3assignTeam] 我方自動選隊 1', tmpTeamsWithOrigIdx);

      let indexes = lodash_keys(tmpTeamsWithOrigIdx);
      //console.log('[V3assignTeam] 我方自動選隊 2', {...indexes});

      //lodash_map(indexes, Number);
      //console.log('[V3assignTeam] 我方自動選隊 3', {...indexes});

      let teamIdx = lodash_sample(indexes);
      console.log('[V3assignTeam] 我方自動選隊 4', teamIdx);

      //更新資料與玩家手動自選時相同
      setSelectedTeamIdx(teamIdx);
      setConfirmedTeamIdx(teamIdx);

      //送出指派隊伍，之後收到 broadcast 進入戰鬥場景
      DCContext.pvp_ready({
        to: 'confirm_team',
        team_id: props.pvpChannelStatus._player1.teams[teamIdx].id,
      });
    }
  }, [countdownNum, confirmedTeamIdx]);

  /* 倒數效果 */
  const [aniStyles_flip, aniApi_flip] = useSpring(() => ({
    loop: false,
    from: { transform: `rotateY(90deg)` },
    to: { transform: `rotateY(-90deg)` },
    config: {
      duration: 1000,
    },
    onRest: r => {
      //console.log(funcKey, "aniStyles_flip onRest", r);

      setCountdownNum(preState => {
        let r = Math.max(0, preState - 1);
        //console.log(funcKey, "aniStyles_flip countdownNum", r);

        return r;
      });
    },
  }));

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div className={styles.headBox}>
          <div className={styles.headHalf}>
            <Iimg className={styles.nationFlagL} src={props.pvpChannelStatus._player1.flag} />
            <div className={styles.titleBoxL}>
              <div className={styles.titleText1}>
                {props.pvpChannelStatus._player1.organization}
              </div>
              <div className={styles.titleText2}>{props.pvpChannelStatus._player1.name}</div>
            </div>
          </div>
          <div className={styles.headHalf}>
            <Iimg className={styles.nationFlagR} src={props.pvpChannelStatus._player2.flag} />
            <div className={styles.titleBoxR}>
              <div className={styles.titleText1}>
                {props.pvpChannelStatus._player2.organization}
              </div>
              <div className={styles.titleText2}>{props.pvpChannelStatus._player2.name}</div>
            </div>
          </div>
          <div className={styles.headBoxShadow}></div>

          <div className={styles.halfMoonBox}>
            <img className={styles.halfMoonImg} src={golden_halfmoon} />
            <div className={styles.countdownTextBox}>
              <animated.div className={styles.countdownText} style={aniStyles_flip}>
                {countdownNum}
              </animated.div>
            </div>
            <div className={styles.winsNumL}>{props.pvpChannelStatus._player1.win}</div>
            <div className={styles.winsNumR}>{props.pvpChannelStatus._player2.win}</div>
          </div>
        </div>

        <div className={styles.bodyBox}>
          <div className={styles.bodyLeft}>
            <div className={styles.teamsBox}>
              {props.pvpChannelStatus._player1.teams.map((team, idx) => {
                //客戶要求改為一旦送出隊伍後不能再改
                //點擊：倒數結束 || 已使用的隊伍 || 隊伍已選好 => 不能點擊
                let clickable =
                  countdownNum == 0 || team.sent_to_battle || confirmedTeamIdx != undefined
                    ? false
                    : true;

                //變暗：表示此隊已使用過
                let filter_black =
                  team.sent_to_battle && team.sent_to_battle < props.pvpChannelStatus.battle //為該場選的隊伍不要變暗
                    ? 'filter_black'
                    : '';

                //確定指派：highlight+箭頭
                let assigned = false;
                if (props.pvpChannelStatus.next_action == 'enter_round') {
                  //已確認隊伍，等待進入戰鬥
                  if (team.sent_to_battle == props.pvpChannelStatus.battle) {
                    //本場戰鬥確定所指派的隊伍
                    assigned = true;
                  }
                } else if (selectedTeamIdx == idx) {
                  //目前所選隊伍，未必是確認的隊伍
                  assigned = true;
                }

                return (
                  <ClickEffect
                    key={idx}
                    enabled={clickable}
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={() => {
                      clickTeam(idx);
                    }}
                  >
                    <div
                      key={idx}
                      className={`${styles.teamBox} ${styles.LEFT} ${
                        assigned ? styles.selected : ''
                      } ${filter_black}`}
                    >
                      <Team actors={team.actors} />
                      {assigned && (
                        <img className={styles.arrow_ATK_left_chosen} src={arrow_ATK_left_chosen} />
                      )}
                    </div>
                  </ClickEffect>
                );
              })}
            </div>

            <div className={styles.tailBox}>
              {selectedTeamIdx != undefined && selectedTeamIdx == confirmedTeamIdx ? (
                <div className={styles.btnBox}>
                  <img className={styles.pvp_teamselected_halo} src={pvp_teamselected_halo} />
                  <div className={styles.btnText}>{tt(`confirm`)}</div>
                </div>
              ) : (
                <ClickEffect
                  enabled={countdownNum > 0 && selectedTeamIdx != undefined ? true : false}
                  effect={{ sound: `/audio/sound_effect/SE2.mp3` }}
                  onClick={() => {
                    clickConfirm();
                  }}
                >
                  <div className={styles.btnBox}>
                    <div className={styles.animatedRing}>
                      <img className={`rotation_highlightCircle`} src={highlightCircle} />
                    </div>
                    <div className={styles.btnText}>{tt(`confirm`)}</div>
                  </div>
                </ClickEffect>
              )}
            </div>
          </div>

          {/* 右半 */}
          <div className={styles.bodyRight}>
            <div className={styles.teamsBox}>
              {props.pvpChannelStatus._player2.teams.map((team, idx) => {
                //NPC 對手 sent_to_battle 都事先排好，須看我方顯示到哪一隊，對手才能顯示到哪一隊
                //let filter_black = (team.sent_to_battle && team.sent_to_battle <= max_team_sent_to_battle) ? 'filter_black' : '';

                //變暗，表示此隊已使用過
                let filter_black =
                  team.sent_to_battle && team.sent_to_battle < props.pvpChannelStatus.battle //為該場選的隊伍不要變暗
                    ? 'filter_black'
                    : '';

                //確定指派：highlight+箭頭
                let assigned = false;
                if (
                  //進入戰鬥場景前，broadcast 雙方最終選定的隊伍
                  (props.pvpChannelStatus.next_action == 'enter_round' &&
                    team.sent_to_battle == props.pvpChannelStatus.battle) ||
                  //倒數結束時，對手已選好的隊伍先顯示 highlight
                  (countdownNum == 0 &&
                    confirmedPlayers[props.pvpChannelStatus._player2.user_id]?.team_id == team.id)
                ) {
                  //已確認隊伍，等待進入戰鬥
                  assigned = true;
                }

                return (
                  <div
                    key={idx}
                    className={`${styles.teamBox} ${styles.RIGHT} ${
                      assigned ? styles.selected : ''
                    } ${filter_black}`}
                  >
                    <Team actors={team.actors} />
                    {assigned && (
                      <img className={styles.arrow_ATK_right_chosen} src={arrow_ATK_right_chosen} />
                    )}
                  </div>
                );
              })}
            </div>

            <div className={styles.tailBox}>
              {confirmedPlayers[props.pvpChannelStatus._player2.user_id] ? (
                <div className={styles.btnBox}>
                  <img className={styles.pvp_teamselected_halo} src={pvp_teamselected_halo} />
                  <div className={styles.btnText}>{tt(`confirm`)}</div>
                </div>
              ) : (
                <div className={styles.btnBox}>
                  <div className={styles.animatedRing}>
                    <img className={`rotation_highlightCircle`} src={highlightCircle} />
                  </div>
                  <div className={styles.btnText}>{tt(`confirm`)}</div>
                </div>
              )}
            </div>
          </div>
        </div>

        <Navigator
          navi={{
            back: 'home',
          }}
        />
      </div>
    </IbgDiv>
  );
};

const Team = props => {
  const DCContext = useDCContext();
  //
  const [actors, setActors] = useState();

  useEffect(() => {
    if (!props.actors) {
      return;
    }

    setActors(props.actors);
  }, [props.actors]);

  return (
    <>
      {[...Array(5)].map((x, idx) => {
        //let i = 4-idx;
        let tmpActor;

        if (actors?.[idx]) {
          //取出多語欄位中應使用的語言
          tmpActor = {
            ...actors?.[idx],
            actor_prototype: {
              ...actors?.[idx].actor_prototype,
              name: actors?.[idx].actor_prototype?.name?.[DCContext.locale],
            },
          };

          //console.log(`[V3assignTeam] [team] 0`, idx, props.actors?.[i].actor_category?.[DCContext.locale]);
        }

        //console.log(`[V3assignTeam] [team]`, idx, tmpActor);

        return (
          <div key={idx} className={`${styles.actorCardBox} ${props.side}`}>
            <Actorcard cardType="S" actor={tmpActor} />
          </div>
        );
      })}
    </>
  );
};
