export const apiUserLogin = data => {
  return doPost(`${iConfig.API.mount_point}/users/log_in`, data);
};

export const apiUserLogout = data => {
  return doPost(`${iConfig.API.mount_point}/users/log_out`, data);
};

export const apiUserRegister = data => {
  return doPost(`${iConfig.API.mount_point}/users/register`, data);
};

//
export const apiStatus = data => {
  return doGet(`${iConfig.API.status}/status`, data);
};

const doPost = (api, data) => {
  return axios({
    url: api,
    method: 'post',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    data: qs.stringify(data),
  });
};

const doGet = (api, data) => {
  return axios({
    url: api,
    method: 'get',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    data: qs.stringify(data),
  });
};

