import React, { useEffect, useState } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useParams,
  useNavigate,
  useLocation,
} from 'react-router-dom';
import { matchPath } from 'react-router';
//
import { SocketProvider, useSocketContext } from 'lib/Phoenix/SocketContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useUserContext } from 'lib/UserContext';
//
import { Button, message, Card, Row, Col } from 'antd';

export function ChannelAllPlayers() {
  const { ...SocketContext } = useSocketContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  const location = useLocation();
  const DCContext = useDCContext();
  //
  let channelName = 'all_players';

  //若 socket 連線，自動加入
  useEffect(() => {
    if (SocketContext.socketStatus?.status !== 'ok') {
      return;
    }

    console.log(
      '[ChannelAllPlayer] SocketContext.socketStatus?.status',
      SocketContext.socketStatus?.status,
    );

    const tmpChannel = SocketContext.socket?.channels.find(element => element.topic == channelName);
    console.log('[ChannelAllPlayer] tmpChannel', { ...tmpChannel });

    //socket 首次連線，channel 不存在 => 手動 join
    //socket 斷線重連，channel 已存在 => Phoenix 會自動 join，不要手動 join
    if (!tmpChannel) {
      handleClick_join(null);
    }
  }, [SocketContext.socketStatus?.status]);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (ChannelContext.channels?.[channelName]?.state != 'joined') {
      console.log(`[ChannelAllPlayer] channel ${channelName} 未連線`);
      return;
    }

    console.log(`[ChannelAllPlayer] channel ${channelName} 已連線`);
  }, [ChannelContext.channels?.[channelName]?.state]);

  /*  */

  //加入 channel
  const handleClick_join = e => {
    //join 前先 leave，避免萬一前一個連線還存在
    //handleClick_leave(); //=>跟下面的join發生時間似乎會有混亂，導致join後又發生leave

    //
    console.log('[ChannelAllPlayer] join channel', channelName);
    //setDoJoin(true);
    // ChannelContext.setJoin({
    // 	topic: channelName,
    // 	params: {fake: "1"}
    // });

    ChannelContext.joinChannel({
      topic: channelName,
      params: { fake: 'ChannelAllPlayer' },
    });
  };

  const handleClick_leave = e => {
    //console.log("client: leave channel");
    // ChannelContext.setLeave({
    // 	topic: channelName
    // });

    ChannelContext.leaveChannel({
      topic: channelName,
      params: { fake: 'ChannelAllPlayer' },
    });
  };

  return (
    <>
      {/* <div className="chat-messages" style={{marginTop: 20}}>
				<Row gutter={16}>
					<Col span={5}>
						<Card title="1. join channel: player">
							<Button type="primary" onClick={handleClick_join}>join</Button>
							<Button type="primary" onClick={handleClick_leave}>leave</Button>
						</Card>
					</Col>
				</Row>
			</div> */}
    </>
  );
}
