import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
import { shuffle as lodash_shuffle } from 'lodash';
import { decimals_digits } from 'lib/funcs';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useDCContext } from 'lib/DCContext';
//
import { highestZindex } from 'lib/funcs';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Downloading.module.scss';
import { Loading } from 'component/Loading';

const _Downloading = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const iZIndex = useRef(highestZindex({ _level: 'middle' }));
  //

  const [loadingProps, setLoadingProps] = useState();

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.dlInfo) {
      return;
    }

    let _dlInfo = DCContext.dlInfo;

    //下載完畢
    if (_dlInfo?.total_files && _dlInfo?.q_files === 0) {
      DCContext.setShowDownloading();
      return;
    }

    //
    let finish_size = _dlInfo?.total_size - _dlInfo?.q_size;

    let total_size_GB = decimals_digits(_dlInfo.total_size / 1024 / 1024 / 1024, 1, false);
    let finish_size_GB = decimals_digits(finish_size / 1024 / 1024 / 1024, 1, false);
    let finish_size_MB = decimals_digits(finish_size / 1024 / 1024, 0, false);

    setLoadingProps({
      preloadedRatio: finish_size / _dlInfo?.total_size,
      //567MB/1.2GB
      loadingText: `${finish_size_GB >= 1 ? finish_size_GB + 'GB' : finish_size_MB + 'MB'}/${
        total_size_GB + 'GB'
      }`,
    });
  }, [DCContext.dlInfo]);

  return (
    <IbgDiv
      className={styles.rootContainer}
      src={null}
      transition={false}
      onReady={() => {}}
      style={{
        zIndex: iZIndex.current,
      }}
    >
      <div className={styles.mainBox}>
        <Loading {...loadingProps} />
      </div>
    </IbgDiv>
  );
};

export const Downloading = props => {
  const DCContext = useDCContext();

  return !DCContext.showDownloading ? <></> : <_Downloading {...props} />;
};
