import React, { useContext, useState, useEffect, useRef } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import { animated, useSpring } from '@react-spring/web';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { ClickEffect } from 'componentx/ClickEffect';
//
import iConfig from 'iConfig';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './ActorSkills.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
//
import bgItemGray from 'assets/img2/bgItemGray.png';

export const ActorSkills = props => {
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [items, setItems] = useState();

  useEffect(() => {
    return () => {};
  }, []);

  useEffect(() => {
    if (!props.actor) {
      return;
    }
    console.log('[ActorSkills] props.actor', props.actor);

    setItems(props.actor?.passive_skills);
  }, [props.actor]);

  const aniStyles_moveup = useSpring(iConfig.aniStyles_moveup);

  return (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      <animated.div className={styles.listBox} style={{ ...aniStyles_moveup }}>
        {items &&
          items.map((el, idx) => {
            return (
              <div
                key={idx}
                onClick={() => {}}
                className={styles.itemRow}
                style={
                  {
                    //backgroundImage: `url(${bgItemGray})`,
                    //opacity: el.level <= props.actor.level ? 1 : 0.4
                  }
                }
              >
                <img
                  className={styles.rowBg}
                  src={bgItemGray}
                  style={{
                    opacity: el.level <= props.actor.level ? 1 : 0.4,
                  }}
                />
                <div className={styles.rowContentBox}>
                  <div className={styles.lvText}>{`Lv ${el.level}`}</div>
                  <div className={styles.descriptionText}>{el.description}</div>
                </div>
              </div>
            );
          })}
      </animated.div>
    </div>
  );
};
