import React, { useContext, useState, useEffect, useRef, useLayoutEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { FitText } from 'lib/FitText';
import { iNumify } from 'lib/funcs';
import iConfig from 'iConfig';
import styles from './Ministers.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { Iimg } from 'componentx/Iimg';
import { ClickEffect } from 'componentx/ClickEffect';
import { UnionListA } from 'component/UnionListA';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import iconPublicity from 'assets/img/iconPublicity.png';
import iconFundsPlus from 'assets/img/iconFundsPlus.png';
import iconEnergyPlus from 'assets/img/iconEnergyPlus.png';
import icon_ingots from 'assets/img2/icon_ingots.png';
import highlightCircle from 'assets/img2/highlightCircle.png';
import iconSort from 'assets/img/iconSort.png';
import icon_bigSeal from 'assets/img2/icon_bigSeal.png';
import iconSearch from 'assets/img/iconSearch.png';
//
import cfgStyle from 'config.module.scss';

export const Ministers = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [nation, setNation] = useState();
  const selectedMinistry = useRef(); //選定要指派的部會
  const [showMinistryUnions, setShowMinistryUnions] = useState(false);
  const [ministryUnions, setMinistryUnions] = useState();
  const [selectedMinistryUnion, setSelectedMinistryUnion] = useState(); //選定要指派的聯盟
  //
  const unionListPanel_height = `calc(${cfgStyle.viewport_flex_height} * (300/${cfgStyle.viewport_rf_height}))`;
  const [ministryUnionsSort, setMinistryUnionsSort] = useState('desc');
  //
  const [keyword, setKeyword] = useState();
  const keywordInput = useRef();
  const [showSearchBar, setShowSearchBar] = useState(false);

  useEffect(() => {
    //debug
    //中央援助（首都一定是中央援助，首都 controlled 一定是 false）
    // DCContext.setShowRewardCollect({
    //   reference_type: "Minister"
    // });
  }, []);

  useEffect(() => {
    if (!props.nation_id) {
      return;
    }

    let tmp = lodash_find(DCContext.nations, { id: props.nation_id });
    console.log(`[Ministers] nation`, tmp);
    setNation(tmp);
  }, [props.nation_id, DCContext.nations]);

  useEffect(() => {
    if (!nation || !props.city) {
      return;
    }

    console.log(`[Ministers] nation.ministers, props.city`, nation.ministers, props.city);
  }, [nation, props.city]);

  const clickMinistry = tmpMinistry => {
    console.log(`[Ministers] clickMinistry`, tmpMinistry);
    selectedMinistry.current = tmpMinistry;

    setShowMinistryUnions(true);
  };

  useEffect(() => {
    if (!DCContext.unions || !nation?.id || !showMinistryUnions) {
      return;
    }

    // 此國聯盟 + 非本人(陣營總指揮)自己的聯盟(總指揮聯盟預設為秘書處) + 未被指派部門
    let tmp = [];
    DCContext.unions.map((o, idx) => {
      if (o.nation.id == nation.id && o.id != DCContext.myUnion?.id && o.minister == false) {
        //配合 API friendlies 周遭友軍格式
        tmp.push({
          id: o.id,
          name: o.name,
          city: DCContext.cityNames[o.city.id],
          medal: o.medal.image,
          power: o.power,
        });
      }
    });
    console.log(`[Ministers] clickMinistry 2`, nation.id, tmp);

    //搜尋
    if (tmp.length && keyword) {
      tmp = tmp.filter((item, idx) => {
        return item.name.includes(keyword);
      });
    }

    //排序
    console.log(`[Ministers] clickMinistry 3`, tmp, ministryUnionsSort);
    if (tmp.length && ministryUnionsSort) {
      tmp = lodash_orderBy(tmp, ['power'], [ministryUnionsSort]);
    }

    setMinistryUnions(tmp);
  }, [DCContext.unions, nation?.id, showMinistryUnions, ministryUnionsSort, keyword]);

  const clickSortMinistryUnions = () => {
    setMinistryUnionsSort(preState => {
      return preState == 'asc' ? 'desc' : 'asc';
    });
  };

  const clickSearchBtn = () => {
    if (showSearchBar) {
      setKeyword();
    }
    setShowSearchBar(!showSearchBar);
  };

  const keywordChange = () => {
    console.log('[Ministers] keywordChange', keywordInput.current.value);
    setKeyword(keywordInput.current.value.trim());
  };

  const ministryUnions_callback = selectedUnion => {
    console.log('[Ministers] ministryUnions_callback', selectedUnion);
    setSelectedMinistryUnion(selectedUnion);
  };

  const clickAssignMinistry = () => {
    console.log('[Ministers] clickAssignMinistry', selectedMinistry.current, selectedMinistryUnion);
    if (!selectedMinistry.current || !selectedMinistryUnion) {
      return;
    }

    showModal_confirm({
      confirm: {
        /*確定要將{{ministry_name}}委由{{union_name}}負責？*/
        message: {
          i18nKey: `minister_assign_confirm`,
          values: {
            ministry_name: selectedMinistry.current.name,
            union_name: selectedMinistryUnion.name,
          },
          options: null,
        },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              DCContext.playSound(`/audio/sound_effect/SE145.mp3`);
              //
              DCContext.assign_minister(selectedMinistry.current.id, selectedMinistryUnion.id);
              setShowMinistryUnions(false);
              //
              callbackConfirm({});
            },
          },
        ],
      },
    });
  };

  // 此段 Ministers.js 和 LocalReward.js 同
  const clickCollectReward = () => {
    console.log('[LocalReward] clickCollectReward', props.city.id, props.city.controlled);

    if (props.city.controlled) {
      // DCContext.collectBundle({
      //   reference_type: "Control Union",
      //   reference_id: props.city.id
      // });

      //本地援助
      DCContext.setShowRewardCollect({
        reference_type: 'Control Union',
        reference_id: props.city.id,
        _city_name: props.city.name, //只顯示在描述
      });
    } else {
      // DCContext.collectBundle({
      //   reference_type: "Minister"
      // });

      //中央援助（首都一定是中央援助，首都 controlled 一定是 false）
      DCContext.setShowRewardCollect({
        reference_type: 'Minister',
      });
    }
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div className={styles.mainBox}>
      <div className={styles.headBox}>
        <div className={styles.headBoxCell}>
          <img className={styles.headBoxCellIcon} src={iconPublicity} />
          <div className={styles.headBoxCellText}>{iNumify(DCContext.userProfile?.media)}</div>
        </div>

        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/store/bundleorders`);
          }}
        >
          <div className={styles.headBoxCell}>
            <img className={styles.headBoxCellIcon} src={iconFundsPlus} />
            <div className={styles.headBoxCellText}>{iNumify(DCContext.userProfile?.fund)}</div>
          </div>
        </ClickEffect>

        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            DCContext.showEnergyboostModal();
          }}
        >
          <div className={styles.headBoxCell}>
            <img className={styles.headBoxCellIcon} src={iconEnergyPlus} />
            <div className={styles.headBoxCellText}>
              {DCContext.userProfile?.energy} / {DCContext.getUser_maxEnergyByLevel()}
            </div>
          </div>
        </ClickEffect>
      </div>

      <div className={styles.bodyBox}>
        {nation?.ministers.map((item, idx) => {
          const canAssign =
            props.city.can_appoint_minister && //陣營總指揮
            !item?.minister //該職位尚未指派
              ? true
              : false;

          return (
            <div key={idx} className={styles.ministerBox}>
              {idx == 4 && (
                <div className={styles.highlightCircleBox}>
                  <img className={`rotation_highlightCircle`} src={highlightCircle} />
                </div>
              )}

              <div className={styles.ministry}>
                <FitText _align={'center'}>{item?.ministry.name}</FitText>
              </div>
              <div className={styles.ministerImgBox}>
                <ClickEffect
                  enabled={canAssign}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickMinistry(item?.ministry);
                  }}
                >
                  <Iimg
                    className={styles.ministerImg}
                    src={item?.image}
                    transition={false}
                    onReady={() => {}}
                  />
                </ClickEffect>
              </div>
              {item?.minister ? (
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    DCContext.showUnionModal(item.minister_union_id);
                  }}
                >
                  <div className={styles.minister}>{item?.minister}</div>
                </ClickEffect>
              ) : (
                <div className={`${styles.minister} ${styles.ministerEmpty}`}>
                  {tt(`vacancy`) /* 懸缺 */}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className={styles.footBox}>
        {props.city?.reward && (
          <>
            <div className={styles.footCell}>
              <ClickEffect
                enabled={!props.city?.reward_collected}
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={e => {
                  clickCollectReward();
                }}
              >
                <img className={styles.footBtnImg} src={icon_ingots} />
              </ClickEffect>
            </div>
            <div className={styles.footCell}>
              {
                props.city?.reward_collected
                  ? tt(`daily_aid_collected`) /*本日領取完畢*/
                  : tt(`aid_collect`) /*領取援助*/
              }
            </div>
          </>
        )}
      </div>

      {showMinistryUnions && (
        <div className={styles.unionListBox}>
          <UnionListA
            selectedCity={props.city}
            unions={ministryUnions}
            callback={ministryUnions_callback}
            scrollInline_padding_bottom={unionListPanel_height}
          />

          <div className={styles.unionListPanel} style={{ height: unionListPanel_height }}>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                clickSortMinistryUnions();
              }}
            >
              <img className={styles.unionList_sortBtn} src={iconSort} />
            </ClickEffect>

            <ClickEffect
              enabled={selectedMinistryUnion ? true : false}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                clickAssignMinistry();
              }}
            >
              <div className={styles.sealBtnBox}>
                <img className={styles.icon_bigSeal} src={icon_bigSeal} />
                <div className={styles.sealBtnText}>{tt(`appoint`) /* 任命 */}</div>
              </div>
            </ClickEffect>

            {/* 搜尋 */}
            <div className={styles.searchBox}>
              {showSearchBar && (
                <div className={styles.searchBarBox}>
                  <input
                    ref={keywordInput}
                    className={`ant-input opacity0 ${styles.searchInput}`}
                    onChange={() => {
                      keywordChange();
                    }}
                    placeholder={tt(`search`) /* 搜尋 */}
                  />
                </div>
              )}

              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={e => {
                  clickSearchBtn();
                }}
              >
                <div className={styles.filterIcons}>
                  <img src={iconSearch} />
                </div>
              </ClickEffect>
            </div>
          </div>
        </div>
      )}

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
