import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import styles from './ContactRequestForm.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { BtnGrey } from 'component/BtnGrey';

export const ContactRequestForm = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const api_processing = useRef(false);

  useEffect(() => {
    console.log(
      '[ContactRequestForm] DCContext.showContactRequestForm',
      DCContext.showContactRequestForm,
    );
  }, []);

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    //檢查執行中
    if (api_processing.current) {
      console.log(`[ContactRequestForm] API 執行中 request_contact`, api_processing.current);
      return;
    }
    api_processing.current = true;

    //
    let data = {
      friend_id: DCContext.showContactRequestForm.friend_id,
      request_message: values.message,
    };

    console.log('[ContactRequestForm] form data', data);

    DCContext.request_contact(data);
  };

  const submitForm = () => {
    form.submit();
    console.log('submitForm');
  };

  //request_contact 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},request_contact`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //發起 contact request 的來源會清除 (playerinfo contacts unions)
    //清除本次 send message 結果
    //DCContext.setMsgRes((prevState)=>{
    //	delete prevState[_key];
    //	return {...prevState};
    //});

    //
    console.log(`[ContactRequestForm] ${_key}`, { ..._res });

    //解除執行中
    api_processing.current = false;
    console.log(`[ContactRequestForm] API 執行中 解除`, api_processing.current);

    //
    if (_res.status == 'error') {
      showModal_confirm({
        confirm: {
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                //
                if (props.callback) {
                  props.callback();
                }
              },
            },
          ],
        },
      });

      return;
    } else if (_res.status == 'ok') {
      //success
      if (props.callback) {
        props.callback();
      }
    } else {
      console.log(`[ContactRequestForm] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},request_contact`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[ContactRequestForm] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <div className={styles.descriptionBox}>
            {tt(`contact_request_form_description`) /* 請向對方說明來意： */}
          </div>

          <Form
            action=""
            form={form}
            name="control-hooks"
            onFinish={onFinish}
            initialValues={{}}
            //labelCol={{ span: 8, className: styles.colTitle }}
            wrapperCol={{ span: 24, className: styles.colContent }}
            colon={false}
          >
            <Form.Item
              name="message"
              label={null}
              rules={[
                {
                  required: false,
                  message: tt(`form_field_required`, { field_name: tt(`message`) }), //留言為必填
                },
              ]}
              message
            >
              <Input.TextArea
                className={styles.inputBox}
                bordered={true}
                autoSize={{ minRows: 3, maxRows: 3 }}
                placeholder={``}
              />
            </Form.Item>
          </Form>

          <div>
            <BtnGrey text={tt(`confirm`)} callback={submitForm} />
          </div>
        </div>
      </div>

      {/* modal confirm */}
      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
