import React, { useContext, useState, useEffect, useRef } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  sumBy as lodash_sumBy,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { ClickEffect } from 'componentx/ClickEffect';
import { FitText } from 'lib/FitText';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Actorpicks.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
//
import bgItemGray from 'assets/img2/actor_pools/bgItemGray.png';
import bgItemGreen from 'assets/img2/actor_pools/bgItemGreen.png';
import btnLeft from 'assets/img2/actor_pools/btnLeft.png';
import btnLeft_active from 'assets/img2/actor_pools/btnLeft_active.png';
import btnRight from 'assets/img2/actor_pools/btnRight.png';
import btnRight_active from 'assets/img2/actor_pools/btnRight_active.png';

export const Actorpicks = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [showMode, setShowMode] = useState(0);
  const [items, setItems] = useState();

  useEffect(() => {
    return () => {};
  }, []);

  useEffect(() => {
    if (!props.markupPicks || !props.origPicks) {
      return;
    }
    console.log('[Actorpicks] props.markupPicks', props.markupPicks);

    let tmp = [];
    if (showMode === 1) {
      //原始機率: 稀有度(SSR->SR->R)、陣營順序 nation_id 小->大
      tmp = lodash_orderBy(
        props.origPicks,
        [item => item.scarcity.length, item => item.nation_id],
        ['desc', 'asc'],
      );
    } else {
      //當前加權: 機率提升(是->否)、稀有度(SSR->SR->R)、陣營順序排列(由小到大)
      tmp = lodash_orderBy(
        props.markupPicks,
        [item => (item.mark_up ? 1 : 0), item => item.scarcity.length, item => item.nation_id],
        ['desc', 'desc', 'asc'],
      );
    }

    setItems(tmp);
  }, [props.markupPicks, props.origPicks, showMode]);

  return (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.listBox} style={{}}>
        {items &&
          items.map((el, idx) => {
            return (
              <div
                key={idx}
                onClick={() => {}}
                className={styles.itemRow}
                style={{ backgroundImage: `url(${el.mark_up ? bgItemGreen : bgItemGray})` }}
              >
                <div className={styles.scarcityText}>{el.scarcity}</div>
                <div className={styles.nationText}>
                  <FitText>{DCContext.nationNames[el.nation_id]}</FitText>
                </div>
                <div className={styles.actor_categoryText}>
                  <FitText>{el.actor_category}</FitText>
                </div>
                <FitText className={styles.nameText}>{el.name}</FitText>
                <div className={styles.probabilityText}>
                  <FitText>{el.probability}%</FitText>
                </div>
              </div>
            );
          })}
      </div>

      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          setShowMode(0);
        }}
      >
        <div className={`${styles.leftBtnBox} ${showMode === 0 ? styles.active : ''}`}>
          {showMode === 0 ? (
            <img className={styles.btnImg} src={btnLeft_active} />
          ) : (
            <img className={styles.btnImg} src={btnLeft} />
          )}
          <div className={styles.leftBtnText}>{tt(`current_weighting`) /* 當前加權 */}</div>
        </div>
      </ClickEffect>

      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          setShowMode(1);
        }}
      >
        <div className={`${styles.rightBtnBox} ${showMode === 1 ? styles.active : ''}`}>
          {showMode === 1 ? (
            <img className={styles.btnImg} src={btnRight_active} />
          ) : (
            <img className={styles.btnImg} src={btnRight} />
          )}
          <div className={styles.rightBtnText}>{tt(`initial_probability`) /* 原始機率 */}</div>
        </div>
      </ClickEffect>
    </div>
  );
};
