import React, { useContext, useState, useEffect, useRef, useMemo } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { useDeepCompareEffect } from 'use-deep-compare';
import { Row, Col, Space } from 'antd';
import { v4 as uuidv4 } from 'uuid';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { Swiper, SwiperSlide } from 'swiper/react';
import { Pagination, Navigation, Grid, Mousewheel } from 'swiper';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { UserContextProvider, useUserContext } from 'lib/UserContext';
import { decimals_digits } from 'lib/funcs';
//
import { highestZindex } from 'lib/funcs';
import iConfig from 'iConfig';
import styles from './Navigator.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { ShortMessage } from 'component/ShortMessage';
import iconMenu from 'assets/img2/navigator/iconMenu.png';
import iconBack from 'assets/img2/navigator/iconBack.png';
//
import btnBg1 from 'assets/img2/navigator/btnBg1.png';
import btnBg2 from 'assets/img2/navigator/btnBg2.png';
import btnBg3 from 'assets/img2/navigator/btnBg3.png';
import btnBg4 from 'assets/img2/navigator/btnBg4.png';
import btnBg5 from 'assets/img2/navigator/btnBg5.png';
import btnBg6 from 'assets/img2/navigator/btnBg6.png';
import { SwitchTransition } from 'react-transition-group';
//
import { Announcements } from 'component/modal/Announcements';
import { Accountbind } from 'pages/settings/Accountbind';
import { LocaleForm } from 'component/modal/LocaleForm';
import { GiveawayForm } from 'component/modal/GiveawayForm';

const btnBgs = [btnBg1, btnBg2, btnBg3, btnBg4, btnBg5, btnBg6];

const spotRoutes = {
  back: -1,
  home: '/home',
  actors: '/user/actors',
  contacts: '/user/contacts',
};

const _Navigator = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const location = useLocation();
  const { ...UserContext } = useUserContext();
  const [iZIndex, setIZIndex] = useState();

  let navigate = useNavigate();

  const cfg_default = {
    navigator: {
      show: true,
    },
    back: {
      show: true,
      spot: 'back',
      url: '',
      urlState: null,
      callback: null,
      position: '', //預設右上，LEFT: 左上
    },
  };

  const [cfg, setCfg] = useState(cfg_default);

  useEffect(() => {
    const tmpIndex = highestZindex({ _level: 'low' });
    console.log('[Navigator] tmpIndex', tmpIndex);
    setIZIndex(tmpIndex);
  }, []);

  useEffect(() => {
    if (!props.navi) {
      return;
    }

    setCfg(prevState => {
      //let tmp = {...prevState};
      let tmp = { ...cfg_default };
      Object.entries(props.navi).forEach(([key, value]) => {
        tmp[key] = {
          //...prevState[key],
          ...cfg_default[key],
          ...value,
        };
      });

      console.log('[Navigator] tmp cfg', tmp);

      return tmp;
    });
  }, [props.navi]);

  const handleShow = id => {
    let tmp = cfg[id].show === false ? 'none' : 'flex';
    return { display: tmp };
  };

  const handleClick = id => {
    console.log('[Navigator] handleClick', id, cfg[id]);

    if (typeof cfg[id].callback === 'function') {
      //console.log("[Navigator] handleClick callback", cfg[id].callback);
      cfg[id].callback();
      return;
    }

    //
    let url = cfg[id].url ? cfg[id].url : cfg[id].spot ? spotRoutes[cfg[id].spot] : '';

    //console.log("url", url);
    if (url) {
      navigate(url, {
        state: cfg[id].urlState,
      });
    }
  };

  /* modal */

  const [modalProps, setModalProps] = useState({
    ratio: 0.82,
    visible: false,
    destroyOnClose: true,
  });

  const showModal = exProps => {
    setModalProps(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* 選單點擊 */

  const switchNation = () => {
    navigate('/settings/nation_change');
  };

  const switchStreetimage = () => {
    if (!DCContext.myNation?.street_sites?.length) {
      showModal_confirm({
        confirm: {
          //沒有可更換的街景
          message: { i18nKey: `no_street_sites` },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });
      return;
    }

    //
    navigate(`/settings/streetimage_change`, {
      state: {
        returnUrl: location.pathname,
        nation: DCContext.myNation,
      },
    });
  };

  const switchSeal = () => {
    console.log(
      '[Navigator] DCContext.myNation?.can_change_seal',
      DCContext.myNation?.can_change_seal,
    );

    //目前僅反賊 can_change_seal: true
    if (!DCContext.myNation?.can_change_seal) {
      showModal_confirm({
        confirm: {
          /*無法更換紋章*/
          message: { i18nKey: `seal_can_not_change` },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });

      return;
    }

    //
    navigate(`/settings/sealimage_change`, {
      state: {
        returnUrl: location.pathname,
        nation: DCContext.myNation,
      },
    });
  };

  /* modal announcement */

  const [modalProps_announcements, setModalProps_announcements] = useState({
    ratio: 0.7,
    destroyOnClose: true, //!!!避免公告停在內容
    //maskClosable: false,
    visible: false,
  });
  const showModal_announcements = () => {
    //
    callbackModal(null, null);
    //
    setModalProps_announcements(prevState => ({
      ...prevState,
      visible: true,
    }));
  };
  const callbackModal_announcements = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_announcements(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* modal accountbind */

  const [modalProps_accountbind, setModalProps_accountbind] = useState({
    ratio: 0.82,
    destroyOnClose: true,
  });
  const showModal_accountbind = () => {
    //
    callbackModal(null, null);
    //
    setModalProps_accountbind(prevState => ({
      ...prevState,
      visible: true,
    }));
  };
  const callbackModal_accountbind = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_accountbind(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* modal locale */

  const [modalProps_locale, setModalProps_locale] = useState({
    //ratio: 0.7,
    //maskClosable: false,
    visible: false,
  });

  const showModal_locale = exProps => {
    //
    callbackModal(null, null);
    //
    setModalProps_locale(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_locale = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_locale(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackLocale = returnParams => {
    console.log('[Navigator] callbackLocale', returnParams, DCContext.locale);
    callbackModal_locale(null, null);
  };

  /* modal GiveawayForm */

  const [modalProps_GiveawayForm, setModalProps_GiveawayForm] = useState({
    ratio: 0.82,
    destroyOnClose: true,
  });
  const showModal_GiveawayForm = () => {
    //
    callbackModal(null, null);
    //
    setModalProps_GiveawayForm(prevState => ({
      ...prevState,
      visible: true,
    }));
  };
  const callbackModal_GiveawayForm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_GiveawayForm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* logout */

  const doLogout = () => {
    UserContext.doLogout();
  };

  const goFeedbackRoom = () => {
    DCContext.getFeedbackRoomInfo();
  };

  //feedback 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},feedback`]) {
      return;
    }

    //如果選單 modal 沒有打開，表示不是這裡觸發 (貨郎>交易>保密選項)
    console.log('[Navigator] modalProps.visible', modalProps.visible);
    if (!modalProps.visible) {
      return;
    }

    //關閉 選單 modal
    callbackModal(null, null);

    console.log('[Navigator] player,feedback', { ...DCContext.msgRes });

    if (DCContext.msgRes[`${DCContext.playerChannelTopic},feedback`]?.res.status == 'ok') {
      navigate(
        `/chatroom/${
          DCContext.msgRes[`${DCContext.playerChannelTopic},feedback`]?.res.payload.feedback_room_id
        }`,
      );
    } else {
      //todo error處理
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},feedback`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},feedback`]?.uuid]);

  //完整下載
  const clickDownload = () => {
    //!!! Navigator.js 用 DCContext.dlInfo，Login.js 用 window.dlInfo
    //如果 DCContext.dlInfo 空的，表示之前已下載完，改檢查 window.dlInfo
    let _dlInfo = DCContext.dlInfo ? DCContext.dlInfo : window.dlInfo;

    //debug
    // _dlInfo = {
    //   total_files: 123, //檔案總數
    //   total_size: null, //總容量
    //   q_files: 1, //等待下載檔案數
    //   q_size: null, //等待下載檔案容量
    // }

    console.log('[Navigator] clickDownload _dlInfo', _dlInfo);

    if (_dlInfo?.q_files === 0) {
      DCContext.setShowConfirmModal({
        //ratio: 0.82,
        //maskClosable: false,
        confirm: {
          message: {
            //遊戲已完整下載。
            i18nKey: `download_completed`,
            values: {},
          },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                DCContext.setShowConfirmModal();
              },
            },
          ],
        },
      });
    } else {
      //跳出額外下載提示
      DCContext.setShowConfirmModal({
        ratio: 0.82,
        maskClosable: false,
        confirm: {
          message: {
            //使用本遊戲所有功能，需要下載影音檔案 1GB 至 1.2GB，即將於背景中陸續下載
            i18nKey: `extra_download_required_navigator`,
            values: {
              file_size: decimals_digits(_dlInfo?.total_size / 1024 / 1024 / 1024, 1, false),
            },
          },
          buttons: [
            {
              text: { i18nKey: `download_in_background` },
              callback: () => {
                DCContext.promptedExtraDownloadTimes.current++;
                DCContext.savePromptedExtraDownload('background');
                DCContext.setShowConfirmModal();
              },
            },
            {
              text: { i18nKey: `download_in_foreground` },
              callback: () => {
                console.log('[Login] ConfirmModal _dlInfo', _dlInfo);

                DCContext.promptedExtraDownloadTimes.current++;
                DCContext.savePromptedExtraDownload('foreground');
                //顯示下載畫面
                DCContext.setShowDownloading(true);
                DCContext.setShowConfirmModal();
              },
            },
          ],
        },
      });
    }
  };

  const BackBtn = props => {
    return (
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          handleClick('back');
        }}
      >
        <div
          className={
            props.position == 'right' && cfg.navigator.show ? styles.itemBox_others : styles.itemBox
          }
          style={handleShow('back')}
        >
          <img className={styles.itemIcon} src={iconBack} />
        </div>
      </ClickEffect>
    );
  };

  const backBtn_right = useMemo(() => <BackBtn position="right" />, [cfg]);
  const backBtn_left = useMemo(() => {
    return (
      <div className={styles.navigatorL}>
        <BackBtn position="left" />
      </div>
    );
  }, [cfg]);

  const btns = [];
  btns.push(
    <>
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          showModal_announcements();
        }}
      >
        <div className={styles.navItem_text}>{tt(`announcement`)}</div>
      </ClickEffect>
      {DCContext.userProfile?.unread_announcements > 0 && (
        <div className={styles.announcementQuantity2}>
          {DCContext.userProfile?.unread_announcements}
        </div>
      )}
    </>,
  );

  if (DCContext.userProfile?.lobby_url) {
    btns.push(
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          window.ReactNativeWebView?.postMessage(
            JSON.stringify({
              action: 'APP:openUrl',
              data: { url: DCContext.userProfile.lobby_url },
            }),
          );
        }}
      >
        <div className={styles.navItem_text}>{tt(`lobby`) /* 玩家大廳 */}</div>
      </ClickEffect>,
    );
  }

  btns.push(
    <ClickEffect
      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
      onClick={() => {
        showModal_locale();
      }}
    >
      <div className={styles.navItem_text}>{tt(`language`)}</div>
    </ClickEffect>,
  );
  btns.push(
    <ClickEffect
      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
      onClick={() => {
        goFeedbackRoom();
      }}
    >
      <div className={styles.navItem_text}>{tt(`server`) /* 客服 */}</div>
    </ClickEffect>,
  );
  if (DCContext.userProfile?.release === true) {
    btns.push(
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          showModal_GiveawayForm();
        }}
      >
        <div className={styles.navItem_text}>{tt(`serial_number`) /* 序號 */}</div>
      </ClickEffect>,
    );
  }
  btns.push(
    <ClickEffect
      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
      onClick={() => {
        doLogout();
      }}
    >
      <div className={styles.navItem_text}>{tt(`log_out`)}</div>
    </ClickEffect>,
  );
  if (!DCContext.userProfile?.email) {
    btns.push(
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          showModal_accountbind();
        }}
      >
        <div className={styles.navItem_text}>{tt(`linked_account`) /* 綁定帳號 */}</div>
      </ClickEffect>,
    );
  }
  btns.push(
    <ClickEffect
      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
      onClick={() => {
        clickDownload();
      }}
    >
      <div className={styles.navItem_text}>{tt(`download_in_foreground`) /* 完整下載 */}</div>
    </ClickEffect>,
  );

  return (
    <>
      <div
        data-eltype="Navigator"
        className={styles.navigator}
        style={{
          zIndex: iZIndex,
        }}
      >
        <ShortMessage />

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            showModal();
          }}
        >
          <div className={styles.itemBox} style={handleShow('navigator')}>
            <img className={styles.itemIcon} src={iconMenu} />
            {DCContext.userProfile?.unread_announcements > 0 && (
              <div className={styles.announcementQuantity}>
                {DCContext.userProfile?.unread_announcements}
              </div>
            )}
          </div>
        </ClickEffect>

        {!cfg.back.position &&
          // <BackBtn position='right'/>
          backBtn_right}
      </div>

      {cfg.back.position == 'LEFT' &&
        // <div className={styles.navigatorL}>
        //   <BackBtn position='left'/>
        // </div>
        backBtn_left}

      <Imodal {...modalProps} callback={callbackModal}>
        <div className={styles.mainBox}>
          <div className={styles.contentBox}>
            {btns.length <= 6 ? (
              <Row className={styles.navItem_row} gutter={16} align="middle">
                {[...Array(6)].map((tmp, idx) => {
                  return (
                    <Col key={idx} span={12}>
                      <img src={btnBgs[idx]} className={styles.navItem_bg} />
                      {btns[idx]}
                    </Col>
                  );
                })}
              </Row>
            ) : (
              <Swiper
                //slidesPerView={2}
                pagination={true}
                mousewheel={true}
                modules={[Pagination, Mousewheel]}
              >
                {[...Array(Math.ceil(btns.length / 6))].map((_page, _pageIdx) => {
                  return (
                    <SwiperSlide>
                      <Row className={styles.navItem_row} align="middle">
                        {[...Array(6)].map((tmp, idx) => {
                          return (
                            <Col key={idx} className={styles.navItem_col} span={12}>
                              <img src={btnBgs[idx]} className={styles.navItem_bg} />
                              {btns[_pageIdx * 6 + idx]}
                            </Col>
                          );
                        })}
                      </Row>
                    </SwiperSlide>
                  );
                })}
              </Swiper>
            )}

            {/* {lodash_find(iConfig.webDeviceInfo, ['uniqueId', window.deviceInfo?.uniqueId]) && ( */}
            {/* <ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={()=>{DCContext.getChannels()}}>
          <div>Channels</div>
          </ClickEffect> */}
            {/* )} */}
          </div>
        </div>
      </Imodal>

      {/* modal confirm */}

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      {/* 公告 */}
      <Imodal {...modalProps_announcements} callback={callbackModal_announcements}>
        <Announcements />
      </Imodal>

      {/* 帳號綁定 */}
      <Imodal {...modalProps_accountbind} callback={callbackModal_accountbind}>
        <Accountbind
          callback={() => {
            callbackModal_accountbind(null, null);
          }}
        />
      </Imodal>

      {/* 語言設定 */}
      <Imodal {...modalProps_locale} callback={callbackModal_locale}>
        <LocaleForm callback={callbackLocale} />
      </Imodal>

      {/* 序號 */}
      <Imodal {...modalProps_GiveawayForm} callback={callbackModal_GiveawayForm}>
        <GiveawayForm
          callback={() => {
            callbackModal_GiveawayForm(null, null);
          }}
        />
      </Imodal>
    </>
  );
};

const isEqual = (prevProps, nextProps) => {
  const tmp = JSON.stringify(nextProps) === JSON.stringify(prevProps);
  //console.log("[Navigator] props isEqual", tmp);

  return tmp;
};

export const Navigator = React.memo(_Navigator, isEqual);
