import React, { useContext, useState, useEffect, useRef } from 'react';
import Spritesheet from 'react-responsive-spritesheet';
import { useDrop, DropTargetMonitor } from 'react-dnd';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
//
import { useDCContext } from 'lib/DCContext';
//
import { Ispritesheet } from 'componentx/Ispritesheet';
//
//import { mediaPath } from "lib/funcs";
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { usePrevious } from 'lib/usePrevious';
//
import styles from './Character.module.scss';
//
import cfgStyle from 'config.module.scss';

const actionFilenames = {
  STAND: 'a1',
  ATTACK: 'b1',
  UNDERATTACK: 'c2',
  DEAD: 'c7',
  AFTERDEAD: 'a2',
};

export const Character = props => {
  const DCContext = useDCContext();
  //
  const [characterData, setCharacterData] = useState();
  const [action, setAction] = useState('STAND'); //STAND, ATTACK, UNDERATTACK, DEAD
  const ssRefs = useRef({}); //存放 Spritesheet ref
  const [ssRefs_readyNum, setSsRefs_readyNum] = useState(0);

  //console.log("[Character] xxxxxxxxxxxxxxxxxxxxxxx", characterData);

  //
  useEffect(() => {
    //console.log("[Character] mount", props.characterData.id);

    //debug
    // setTimeout(()=>{
    //   setAction("DEAD");
    // }, 5000);

    return () => {};
  }, []);

  useEffect(() => {
    if (!props.characterData) {
      return;
    }
    //console.log("[Character] characterData", characterData);

    setCharacterData(props.characterData);

    //STAND, DEAD => 直接回報動作完成
    if (props.characterData.action == action) {
      //callback 動作完成
      if (props.characterActionFinished) {
        props.characterActionFinished(props.characterData);
      }
    } else {
      setAction(props.characterData.action);
    }
  }, [props.characterData]);

  useEffect(() => {
    if (!characterData) {
      return;
    }

    //播放攻擊音效
    if (action == 'ATTACK' && characterData.sound_effect_prefix) {
      console.log('[Character] play sound', characterData.sound_effect_prefix);
      DCContext.playSound(`${characterData.sound_effect_prefix}b1.mp3`);
    }
  }, [action, characterData]);

  useEffect(() => {
    //console.log("[Character] characterData", characterData, ssRefs_readyNum);

    if (!action || ssRefs_readyNum < 5) {
      return;
    }

    if (props.zoneData.frame_count[actionFilenames[action]] > 1) {
      ssRefs.current[action]?.goToAndPlay(1);

      console.log('[Character] goToAndPlay(1) YES', characterData.name, action, ssRefs.current);
    } else {
      console.log('[Character] goToAndPlay(1) NO', characterData.name, action, ssRefs.current);
    }
  }, [action, ssRefs_readyNum]);

  const flipX_style = {
    transform: props.positionSide == 'R' ? `scaleX(-1)` : `scaleX(1)`,
  };

  /* animation */
  const [aniStyles_fade, aniApi_fade] = useSpring(() => ({
    opacity: 1,
    width: `8.9vw`,
  }));

  return characterData ? (
    <animated.div
      className={styles.characterCont}
      style={{
        zIndex: props.zIndex,
        ...aniStyles_fade,
      }}
    >
      <div className={styles.characterBox}>
        {/* 客戶要求暫不顯示職業背景光 */}
        {/* <Iimg className={styles.bgLightImg} 
            //src={action=="ATTACK" ? "/images/attack/backlight/charge.png" : characterData.backlight} 
            //src={"/images/attack/backlight/charge.png"} 
            src={characterData.backlight} 
            transition={false} onReady={()=>{}}
          /> */}

        {/* 待命 */}
        <div style={{ opacity: action == 'STAND' ? 1 : 0 }} className={styles.spritesheetBox}>
          <div className={styles.flipbox} style={flipX_style}>
            <Ispritesheet
              //加帶給 Ispritesheet 的參數
              styles={styles}
              //e={e}
              //ssRefs={ssRefs}
              getRefCallback={tmpRef => {
                ssRefs.current['STAND'] = tmpRef;
              }}
              //prevActionKey={prevActionKey}
              //callbackLoopComplete={callbackLoopComplete}
              //原本 Spritesheet 的參數
              //ref={(ref)=>{ssRefs.current[e.key] = ref}} //ref搬到component內
              //key={`SS${e.key}`}
              className={`my-element__class--style ${styles.spritesheet}`}
              image={`${characterData.image_prefix}a1.png`}
              widthFrame={props.zoneData.width}
              heightFrame={props.zoneData.height}
              //startAt={1}
              //endAt={4}
              steps={props.zoneData.frame_count['a1']}
              //steps={e.frame_count}
              fps={props.zoneData.fps}
              autoplay={props.zoneData.frame_count['a1'] == 1 ? false : true}
              loop={props.zoneData.frame_count['a1'] == 1 ? false : true}
              getInstance={spritesheet => {
                //setSpritesheet(spritesheet);
              }}
              onInit={spritesheet => {
                setSsRefs_readyNum(preState => {
                  return preState + 1;
                });
              }}
              onLoopComplete={spritesheet => {}}
              onEachFrame={spritesheet => {}}
              onEnterFrame={[
                {
                  frame: 1,
                  callback: () => {},
                },
              ]}
            />
          </div>
        </div>

        {/* 攻擊 */}
        <div style={{ opacity: action == 'ATTACK' ? 1 : 0 }} className={styles.spritesheetBox}>
          <div className={styles.flipbox} style={flipX_style}>
            <Ispritesheet
              //加帶給 Ispritesheet 的參數
              styles={styles}
              //e={e}
              //ssRefs={ssRefs}
              getRefCallback={tmpRef => {
                ssRefs.current['ATTACK'] = tmpRef;
              }}
              //prevActionKey={prevActionKey}
              //callbackLoopComplete={callbackLoopComplete}
              //原本 Spritesheet 的參數
              //ref={(ref)=>{ssRefs.current[e.key] = ref}} //ref搬到component內
              //key={`SS${e.key}`}
              className={`my-element__class--style ${styles.spritesheet}`}
              image={`${characterData.image_prefix}b1.png`}
              widthFrame={props.zoneData.width}
              heightFrame={props.zoneData.height}
              //startAt={1}
              //endAt={4}
              steps={props.zoneData.frame_count['b1'] + 1} /* 多一格隱藏最後畫面 */
              //steps={e.frame_count}
              fps={props.zoneData.fps}
              autoplay={false}
              loop={false}
              getInstance={spritesheet => {
                //setSpritesheet(spritesheet);
              }}
              onInit={spritesheet => {
                setSsRefs_readyNum(preState => {
                  return preState + 1;
                });
              }}
              onPause={spritesheet => {
                console.log('[Character] ATTACK onPause');
                props.characterActionFinished(characterData);
                setAction('STAND');
              }}
              onLoopComplete={spritesheet => {
                //console.log('[Character] ATTACK onLoopComplete');
              }}
              onEachFrame={spritesheet => {}}
              onEnterFrame={[
                {
                  frame: 1,
                  callback: () => {},
                },
              ]}
            />
          </div>
        </div>

        {/* 被攻擊 */}
        <div style={{ opacity: action == 'UNDERATTACK' ? 1 : 0 }} className={styles.spritesheetBox}>
          <div className={styles.flipbox} style={flipX_style}>
            <Ispritesheet
              //加帶給 Ispritesheet 的參數
              styles={styles}
              //e={e}
              //ssRefs={ssRefs}
              getRefCallback={tmpRef => {
                ssRefs.current['UNDERATTACK'] = tmpRef;
              }}
              //prevActionKey={prevActionKey}
              //callbackLoopComplete={callbackLoopComplete}
              //原本 Spritesheet 的參數
              //ref={(ref)=>{ssRefs.current[e.key] = ref}} //ref搬到component內
              //key={`SS${e.key}`}
              className={`my-element__class--style ${styles.spritesheet}`}
              image={`${characterData.image_prefix}c2.png`}
              widthFrame={props.zoneData.width}
              heightFrame={props.zoneData.height}
              //startAt={1}
              //endAt={4}
              steps={props.zoneData.frame_count['c2'] + 1} /* 多一格隱藏最後畫面 */
              //steps={e.frame_count}
              fps={props.zoneData.fps}
              autoplay={false}
              loop={false}
              getInstance={spritesheet => {
                //setSpritesheet(spritesheet);
              }}
              onInit={spritesheet => {
                setSsRefs_readyNum(preState => {
                  return preState + 1;
                });
              }}
              onPause={spritesheet => {
                console.log('[Character] UNDERATTACK onPause');
                props.characterActionFinished(characterData);
                setAction('STAND');
              }}
              onLoopComplete={spritesheet => {
                //console.log('[Character] ATTACK onLoopComplete');
              }}
              onEachFrame={spritesheet => {}}
              onEnterFrame={[
                {
                  frame: 1,
                  callback: () => {},
                },
              ]}
            />
          </div>
        </div>

        {/* 倒地死亡 */}
        <div style={{ opacity: action == 'DEAD' ? 1 : 0 }} className={styles.spritesheetBox}>
          <div className={styles.flipbox} style={flipX_style}>
            <Ispritesheet
              //加帶給 Ispritesheet 的參數
              styles={styles}
              //e={e}
              //ssRefs={ssRefs}
              getRefCallback={tmpRef => {
                ssRefs.current['DEAD'] = tmpRef;
              }}
              //prevActionKey={prevActionKey}
              //callbackLoopComplete={callbackLoopComplete}
              //原本 Spritesheet 的參數
              //ref={(ref)=>{ssRefs.current[e.key] = ref}} //ref搬到component內
              //key={`SS${e.key}`}
              className={`my-element__class--style ${styles.spritesheet}`}
              image={`${characterData.image_prefix}c7.png`}
              widthFrame={props.zoneData.width}
              heightFrame={props.zoneData.height}
              //startAt={1}
              //endAt={4}
              steps={props.zoneData.frame_count['c7']}
              //steps={e.frame_count}
              fps={props.zoneData.fps}
              autoplay={false}
              loop={false}
              getInstance={spritesheet => {
                //setSpritesheet(spritesheet);
              }}
              onInit={spritesheet => {
                setSsRefs_readyNum(preState => {
                  return preState + 1;
                });
              }}
              onPause={spritesheet => {
                console.log('[Character] DEAD onPause', characterData.id);

                aniApi_fade.start({
                  loop: false,
                  to: [{ opacity: 0 }, { width: `0vw` }],
                  config: {
                    duration: 100,
                  },
                  onRest: () => {
                    console.log('[Character] DEAD fade');

                    props.characterActionFinished(characterData);
                    //setAction("STAND");
                  },
                });
              }}
              onLoopComplete={spritesheet => {
                //console.log('[Character] ATTACK onLoopComplete');
              }}
              onEachFrame={spritesheet => {}}
              onEnterFrame={[
                {
                  frame: 1,
                  callback: () => {},
                },
              ]}
            />
          </div>
        </div>

        {/* 已死亡 */}
        <div style={{ opacity: action == 'AFTERDEAD' ? 1 : 0 }} className={styles.spritesheetBox}>
          <div className={styles.flipbox} style={flipX_style}>
            <Ispritesheet
              //加帶給 Ispritesheet 的參數
              styles={styles}
              //e={e}
              //ssRefs={ssRefs}
              getRefCallback={tmpRef => {
                ssRefs.current['AFTERDEAD'] = tmpRef;
              }}
              //prevActionKey={prevActionKey}
              //callbackLoopComplete={callbackLoopComplete}
              //原本 Spritesheet 的參數
              //ref={(ref)=>{ssRefs.current[e.key] = ref}} //ref搬到component內
              //key={`SS${e.key}`}
              className={`my-element__class--style ${styles.spritesheet}`}
              image={`${characterData.image_prefix}a2.png`}
              widthFrame={props.zoneData.width}
              heightFrame={props.zoneData.height}
              //startAt={1}
              //endAt={4}
              steps={props.zoneData.frame_count['a2']}
              //steps={e.frame_count}
              fps={props.zoneData.fps}
              autoplay={props.zoneData.frame_count['a2'] == 1 ? false : true}
              loop={props.zoneData.frame_count['a2'] == 1 ? false : true}
              getInstance={spritesheet => {
                //setSpritesheet(spritesheet);
              }}
              onInit={spritesheet => {
                setSsRefs_readyNum(preState => {
                  return preState + 1;
                });
              }}
              onLoopComplete={spritesheet => {}}
              onEachFrame={spritesheet => {}}
              onEnterFrame={[
                {
                  frame: 1,
                  callback: () => {},
                },
              ]}
            />
          </div>
        </div>
      </div>

      <div className={styles.nameBar}>
        <div className={styles.sealIconBox}>
          <Iimg
            className={styles.sealIcon}
            src={characterData.icon}
            transition={false}
            onReady={() => {}}
          />
        </div>
        <div className={styles.playerName}>{characterData.name}</div>
      </div>

      <div className={styles.bloodbarBox}>
        <div className={styles.bloodbarSide}></div>
        <div className={styles.bloodbar}>
          <div
            className={styles.bloodbarFill}
            style={{
              width: `${(characterData.power_last / characterData.power) * 100}%`,
              backgroundColor: props.positionSide == 'L' ? '#ff5866' : '#59bcff',
            }}
          />
        </div>
        <div className={`${styles.bloodbarSide} ${styles.abbr}`}></div>
      </div>
      {/* {collectedProps.canDrop && (<div>V</div>)} */}
    </animated.div>
  ) : (
    <></>
  );
};

