import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import styles from './UnionMedals.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
//
import { Medals } from 'component/Medals';

export const UnionMedals = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    //據點戰結算牌位
    if (location.state?.getPreviousRecord == 'after_nation_battle') {
      DCContext.playMusic(iConfig.battleMusic);
    }

    //console.log('[UnionMedals] mount');

    //
    DCContext.clearOverlay();
  }, []);

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${background})` }}>
      <div className={styles.mainBox}>
        {/* <div style={{position: "absolute", left:0, top:0, backgroundColor: "pink"}}> */}
        <Medals
          catKey={location.state?.catKey}
          getPreviousRecord={location.state?.getPreviousRecord}
          callback_close={
            location.state?.returnUrl
              ? () => {
                  navigate(location.state?.returnUrl, {
                    state: { ...location.state?.returnState },
                  });
                }
              : undefined
          }
        />
        {/* </div> */}
      </div>
      {/* <Navigator></Navigator> */}
    </div>
  );
};
