import React, { useContext, useState, useEffect } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import { find as lodash_find, orderBy as lodash_orderBy } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import { FitText } from 'lib/FitText';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { ClickEffect } from 'componentx/ClickEffect';
import styles from './Unioninfo.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import actor_halfbody_bg from 'assets/img2/playerinfo/actor_halfbody_bg.png';
import actor_halfbody_fg from 'assets/img2/playerinfo/actor_halfbody_fg.png';
import actor_head_bg from 'assets/img2/playerinfo/actor_head_bg.png';
import actor_head_fg from 'assets/img2/playerinfo/actor_head_fg.png';
import iconChange from 'assets/img/iconChange.png';
import icon_copy from 'assets/img2/playerinfo/icon_copy.png';

//
import gold_circle_check from 'assets/img/nation/gold_circle_check.png';
import icon_circle_check_green from 'assets/img2/icon_circle_check_green.png';
import goldmedal from 'assets/img/teams/goldmedal.png';

import icon_unionJoin from 'assets/img2/icon_unionJoin.png';
import icon_unionQuit from 'assets/img2/icon_unionQuit.png';
import icon_unionChannel from 'assets/img2/icon_unionChannel.png';
import icon_mail from 'assets/img2/icon_mail.png';
import icon_unionFire from 'assets/img2/icon_unionFire.png';
import icon_pen from 'assets/img2/icon_pen_grey.png';

export const Unioninfo = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [union, setUnion] = useState();
  //const [btnUnionQuit_clicked, setBtnUnionQuit_clicked] = useState(false);
  //const [btnUnionDissolve_clicked, setBtnUnionDissolve_clicked] = useState(false);
  const [unionChief, setUnionChief] = useState();
  const [unionNation, setUnionNation] = useState();

  useEffect(() => {
    return () => {};
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Unions] channel player 未連線');
      return;
    }

    console.log('[Unions] channel player 已連線');
    ///DCContext.getUnions();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.unions || !DCContext.showUnion_id) {
      return;
    }

    console.log('[Unioninfo] showUnion_id', DCContext.showUnion_id);

    const tmpUnion = DCContext.unions.find((el, idx) => {
      return el.id == DCContext.showUnion_id;
    });

    console.log('[Unioninfo] tmpUnion', DCContext.showUnion_id, tmpUnion);

    setUnion(tmpUnion);
  }, [DCContext.unions, DCContext.showUnion_id]);

  const clickShowPlayerInfo = user_id => {
    console.log('[Unioninfo] clickShowPlayerInfo', user_id);
    DCContext.showPlayerinfoModal(user_id);
  };

  const clickShowUnionCity = () => {
    console.log('[Unioninfo] clickShowUnionCity', union.city.id);

    navigate('/attacks/attackmap', {
      state: {
        focus_city_id: union.city.id,
      },
    });

    props.callbackModal();
  };

  /* 隨機推薦本國聯盟 */

  const doRecommendUnion = () => {
    let tmpUnions = DCContext.getRecommendUnions({ quantity: 1 });
    console.log('[Unioninfo] doRecommendUnions', tmpUnions);

    if (tmpUnions.length > 0) {
      setUnion(tmpUnions[0]);
    }
  };

  useEffect(() => {
    if (!union) {
      return;
    }

    let tmpNation = lodash_find(DCContext.nations, ['id', union?.nation.id]);
    setUnionNation(tmpNation);

    let tmpChief = DCContext.getChiefByUnionId(union?.id);
    //如果聯盟領袖當選該陣營總指揮，不顯示 總指揮預設部門頭銜“秘書長” 而顯示該陣營總指揮頭銜，例如盟主
    // if (tmpChief.user_id == tmpNation.commander?.user_id){
    //   tmpChief.title = tmpNation.commander?.title;
    // }
    setUnionChief(tmpChief);

    console.log('[Unioninfo] tmpChief tmpNation', tmpChief, tmpNation);
  }, [union, DCContext.nations]);

  /* 申請加入聯盟 */

  const doApplyForJoin = () => {
    DCContext.unionApplyJoin({
      union_id: union.id,
    });
  };

  //join_union 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},join_union`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //console.log(`[Unioninfo] ${_key}`, {..._res});

    if (_res.status == 'ok') {
      showModal_confirm({
        confirm: {
          //已申請加入。
          message: { i18nKey: `union_join_applied`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });
    } else {
      //todo error處理
      console.log(`[Unioninfo] [錯誤] ${_key}`, { ..._res });
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},join_union`]?.uuid]);

  /* 解散聯盟 */

  const doUnionDissolve = () => {
    showModal_confirm({
      confirm: {
        //原先受本聯盟影響的城鎮。其影響者將由本國NPC替補。聯盟提供給加盟成員的各類補助也將停止。確定要解散 ${union.name} ？ (加上24小時猶豫期說明)
        message: {
          i18nKey: `union_alert_disbandment`,
          values: { union_name: union.name },
          options: null,
        },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({ code: 'unionDissolve' });
            },
          },
        ],
      },
    });
  };

  /* 取消解散聯盟 */

  const doUnionDissolveUndo = () => {
    DCContext.unionDissolveUndo();
  };

  /* 確認/取消解散聯盟 */

  const doUnionDissolveConfirm = () => {
    console.log('[Unioninfo] doUnionDissolveConfirm');

    showModal_confirm({
      confirm: {
        //確定解散或取消解散聯盟？
        message: {
          i18nKey: `union_alert_disbandment_confirm`,
          values: { union_name: union.name },
          options: null,
        },
        buttons: [
          {
            text: { i18nKey: `union_disbandment_yes` },
            callback: () => {
              callbackConfirm({ code: 'confirm_dissolve_union' });
            },
          },
          {
            text: { i18nKey: `union_disbandment_no` },
            callback: () => {
              callbackConfirm({ code: 'undo_dissolve_union' });
            },
          },
        ],
      },
    });
  };

  /* 退出聯盟 */

  const doUnionQuit = () => {
    // if (btnUnionQuit_clicked){
    //   //
    //   DCContext.unionQuit();
    //   return;
    // }

    // setBtnUnionQuit_clicked(true);

    showModal_confirm({
      confirm: {
        //確定退出 ${union.name} ？
        message: {
          i18nKey: `union_confirm_leave`,
          values: null,
          options: { keySuffix: false, unionId: union?.id },
        },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({ code: 'unionQuit' });
            },
          },
        ],
      },
    });
  };

  //leave_union 結果
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},leave_union`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[Unioninfo] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
    } else {
      console.log(`[Unioninfo] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},leave_union`]?.uuid]);

  //confirm_dissolve_union 結果
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},confirm_dissolve_union`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[Unioninfo] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //關閉 modal
      props.callbackModal();
    } else {
      console.log(`[Unioninfo] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},confirm_dissolve_union`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Unioninfo] callbackConfirm', returnParams);

    //
    callbackModal_confirm(null, null);

    //
    switch (returnParams.code) {
      case 'unionDissolve': //解散聯盟
        DCContext.unionDissolve();
        break;
      case 'unionQuit': //退出聯盟
        DCContext.unionQuit();
        break;
      case 'confirm_dissolve_union': //確定解散聯盟
        DCContext.unionDissolveConfirm();
        break;
      case 'undo_dissolve_union': //取消解散聯盟
        DCContext.unionDissolveUndo();
        break;
    }
  };

  return (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      <ClickEffect
        enabled={true}
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={e => {
          clickShowPlayerInfo(unionChief?.user_id);
        }}
      >
        {/* <div className={styles.leftBox} style={{backgroundImage: `url(${actor_halfbody_bg})`}}>
          <Iimg className={styles.userOutfit} src={unionChief?.image} transition={false} onReady={()=>{}} />
          <div className={styles.leftBoxFg} style={{backgroundImage: `url(${actor_halfbody_fg})`}}></div>
        </div> */}

        <div className={styles.leftBox} style={{ backgroundImage: `url(${actor_halfbody_bg})` }}>
          <div className={styles.userOutfitBox}>
            <Iimg
              className={styles.userOutfit}
              src={unionChief?.image}
              transition={false}
              onReady={() => {}}
            />
          </div>
          <div
            className={styles.leftBoxFg}
            style={{ backgroundImage: `url(${actor_halfbody_fg})` }}
          ></div>

          <div className={styles.userInfo}>
            <div
              className={styles.userTitle}
              dangerouslySetInnerHTML={{ __html: unionChief?.title.replace(' ', '<br/>') }}
            ></div>
            <FitText className={styles.userName}>{unionChief?.name}</FitText>
          </div>
        </div>
      </ClickEffect>

      <div className={styles.rightBox}>
        <div className={styles.dataBox}>
          <div className={styles.nationBox}>
            <Iimg
              className={styles.nationSeal}
              src={union?.seal_image}
              transition={false}
              onReady={() => {}}
            />
            {union?.name}
          </div>

          <Row align="bottom" className={styles.colContentBox}>
            <Col span={24}>
              <Row wrap={false} align="middle" style={{}}>
                <Col span={7} className={styles.colTitle} style={{}}>
                  {tt(`leader`)}
                  {/* 領袖 */}
                </Col>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickShowPlayerInfo(unionChief?.user_id);
                  }}
                >
                  <Col span={2} className={styles.colCircleCheck}>
                    <img src={icon_circle_check_green} className={styles.circle_check} />
                  </Col>
                </ClickEffect>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickShowPlayerInfo(unionChief?.user_id);
                  }}
                >
                  <Col flex="auto" className={`${styles.colContent} ${styles.unionChief}`}>
                    {unionChief?.name}
                    <div className={styles.localeText}>
                      {iConfig.locales[unionChief?.locale]?.short}
                    </div>
                  </Col>
                </ClickEffect>
              </Row>
              <Row wrap={false} align="middle">
                <Col span={7} className={styles.colTitle}>
                  {tt(`union_id`, {}, { keySuffix: true, unionId: union?.id })}
                  {/* 聯盟ID||派系ID */}
                </Col>
                <Col span={2}>&nbsp;</Col>
                <Col flex="auto" className={`${styles.colContent} font_figures`}>
                  {union?.id}
                  <ClickEffect
                    enabled={true}
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={e => {
                      navigator.clipboard.writeText(union?.id);
                    }}
                  >
                    <img className={styles.icon_copy} src={icon_copy} />
                  </ClickEffect>
                </Col>
              </Row>
              <Row wrap={false} align="middle">
                <Col span={7} className={styles.colTitle}>
                  {tt(`location_main_force`)}
                  {/* 主力所在地 */}
                </Col>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickShowUnionCity();
                  }}
                >
                  <Col span={2} className={styles.colCircleCheck}>
                    <img src={icon_circle_check_green} className={styles.circle_check} />
                  </Col>
                </ClickEffect>
                <Col flex="auto" className={`${styles.colContent}`}>
                  <ClickEffect
                    enabled={true}
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={e => {
                      clickShowUnionCity();
                    }}
                  >
                    <div className={styles.cityName}>{DCContext.cityNames?.[union?.city.id]}</div>
                  </ClickEffect>
                </Col>
              </Row>
              <Row wrap={false} align="middle">
                <Col span={7} className={styles.colTitle}>
                  {tt(`control_cities`)}
                  {/* 勢力範圍 */}
                </Col>
                <Col span={2}></Col>
                <Col flex="auto" className={`${styles.colContent} font_figures`}>
                  {union?.control_cities}
                </Col>
              </Row>
              <Row wrap={false} align="middle">
                <Col span={7} className={styles.colTitle}>
                  {tt(`members`)}
                  {/* 成員 */}
                </Col>
                <Col span={2}></Col>
                <Col
                  flex="auto"
                  className={`${styles.colContent} font_figures`}
                >{`${union?.member_count}/${union?.member_cap}`}</Col>
              </Row>
            </Col>
          </Row>
        </div>

        <div className={styles.actorsBox}>
          {[...Array(6)].map((x, idx) => {
            let tmpActor = union?.officers[idx + 1];

            if (tmpActor?.authority == 1) {
              //盟主
              return false;
            }

            return (
              <div key={tmpActor ? tmpActor.id : `idx_${idx}`} className={styles.actorBox}>
                <ClickEffect
                  enabled={tmpActor ? true : false}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickShowPlayerInfo(tmpActor?.user_id);
                  }}
                >
                  <div
                    className={styles.actorThumbnail}
                    style={{ backgroundImage: `url(${actor_head_bg})` }}
                  >
                    {tmpActor && (
                      <Iimg
                        className={null}
                        src={tmpActor?.image}
                        transition={false}
                        onReady={() => {}}
                      />
                    )}
                    <div
                      className={styles.actorThumbnailFg}
                      style={{ backgroundImage: `url(${actor_head_fg})` }}
                    ></div>

                    <div className={styles.userInfo}>
                      <div
                        className={styles.officerTitle}
                        dangerouslySetInnerHTML={{ __html: tmpActor?.title?.replace(' ', '<br/>') }}
                      ></div>
                      <FitText className={styles.officerName}>{tmpActor?.name}</FitText>
                    </div>
                  </div>
                </ClickEffect>
              </div>
            );
          })}
        </div>
      </div>

      <ClickEffect
        enabled={true}
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={e => {
          DCContext.clearOverlay(); //可能由排行榜點開後再導回牌位
          //
          navigate(`/unionmedals`, {
            state: {
              catKey: 'Union', //聯盟牌位
            },
          });
          //關閉 modal
          props.callbackModal();
        }}
      >
        <div className={styles.goldmedalBox}>
          <Iimg
            className={styles.goldmedal}
            src={union?.medal?.image}
            transition={false}
            onReady={() => {}}
          />
          <div className={styles.goldmedalText}>{union?.medal?.name}</div>
        </div>
      </ClickEffect>

      {/* modal 外部按鈕 */}
      <div className={styles.outBoxTop}>
        <div className={styles.outBtnL}>
          {/* <img src={icon_unionQuit} className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}/>
          test */}
        </div>
        <div className={styles.outBtnR}>
          {union?.random_pick && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doRecommendUnion();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={styles.outBtnText}>
                  {tt(`recommend_unions`, {}, { keySuffix: true })} {/* 隨機推薦本國聯盟 */}
                </div>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={iconChange}
                    className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}
                  />
                </div>
              </div>
            </ClickEffect>
          )}
        </div>
      </div>

      <div className={styles.outBoxBottom}>
        <div className={styles.outBtnL}>
          {union?.joinable && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doApplyForJoin();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_mail}
                    className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                  />
                </div>
                <div className={styles.outBtnText}>
                  {tt(`union_join_apply`)} {/* 申請加入 */}
                </div>
              </div>
            </ClickEffect>
          )}

          {union?.dissolvable && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doUnionDissolve();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_unionFire}
                    className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                  />
                </div>
                <div className={styles.outBtnText}>
                  {tt(`union_dissolve`, null, { keySuffix: false, unionId: union?.id })}{' '}
                  {/* 解散聯盟 */}
                </div>
              </div>
            </ClickEffect>
          )}

          {union?.confirm_dissolvable ? (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doUnionDissolveConfirm();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_unionFire}
                    className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                  />
                </div>
                <div className={styles.outBtnText}>
                  {tt(`union_confirm_dissolvable`, null, { keySuffix: false, unionId: union?.id })}{' '}
                  {/* 再次確認解散聯盟 */}
                </div>
              </div>
            </ClickEffect>
          ) : union?.undo_dissolvable ? (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doUnionDissolveUndo();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_unionFire}
                    className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                  />
                </div>
                <div className={styles.outBtnText}>
                  {tt(`union_undo_dissolvable`, null, { keySuffix: false, unionId: union?.id })}{' '}
                  {/* 請於提出申請後24小時再次確認 */}
                </div>
              </div>
            </ClickEffect>
          ) : (
            <></>
          )}

          {union?.leavable && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                doUnionQuit();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_unionQuit}
                    className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                  />
                </div>
                <div className={styles.outBtnText}>
                  {tt(`union_leave`, null, { keySuffix: false, unionId: union?.id })}{' '}
                  {/* 退出聯盟 */}
                </div>
              </div>
            </ClickEffect>
          )}
        </div>

        <div className={styles.outBtnR}>
          {union?.show_union_channel && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                navigate('/user/unions');
                props.callbackModal();
              }}
            >
              <div className={styles.outBtnGroup}>
                <div className={styles.outBtnText}>
                  {tt(`union_channel`, null, { keySuffix: false, unionId: union?.id })}{' '}
                  {/* 聯盟頻道 */}
                </div>
                <div className={`${styles.outBtnIconBox}`}>
                  <img
                    src={icon_unionChannel}
                    className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}
                  />
                </div>
              </div>
            </ClickEffect>
          )}
        </div>
      </div>

      {/* 修改聯盟按鈕 */}
      {union?.editable && (
        <img
          className={styles.iconEdit}
          src={icon_pen}
          onClick={() => {
            DCContext.showUnionFormModal({ union_id: union?.id });
          }}
        />
      )}

      {/* modal confirm */}
      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
