import React, { useEffect, useState, useRef } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useParams,
  useNavigate,
  useLocation,
} from 'react-router-dom';
import { matchPath } from 'react-router';
//
import { SocketProvider, useSocketContext } from 'lib/Phoenix/SocketContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useUserContext } from 'lib/UserContext';
//
import { Button, message, Card, Row, Col } from 'antd';

export function ChannelPlayer() {
  const { ...SocketContext } = useSocketContext();
  const ChannelContext = useChannelContext();
  const { ...UserContext } = useUserContext();
  //
  let navigate = useNavigate();
  const location = useLocation();
  const DCContext = useDCContext();

  const joinTimes = useRef(0);

  //若 socket 連線，自動加入 channel: player
  useEffect(() => {
    if (SocketContext.socketStatus?.status !== 'ok' || !DCContext.playerChannelTopic) {
      return;
    }

    console.log('[ChannelPlayer] SocketContext.socket.channels', {
      ...SocketContext.socket.channels,
    });
    console.log('[ChannelPlayer] DCContext.playerChannelTopic', DCContext.playerChannelTopic);

    const tmpChannel = SocketContext.socket?.channels.find(
      element => element.topic == DCContext.playerChannelTopic,
    );
    console.log('[ChannelPlayer] tmpChannel', { ...tmpChannel });

    //socket 首次連線，channel 不存在 => 手動 join
    //socket 斷線重連，channel 已存在 => Phoenix 會自動 join，不要手動 join
    if (!tmpChannel) {
      handleClick_join(null);
    }
  }, [SocketContext.socketStatus?.status, DCContext.playerChannelTopic]);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (ChannelContext.channels?.[DCContext.playerChannelTopic]?.state != 'joined') {
      console.log('[ChannelPlayer] channel 未連線');
      return;
    }

    console.log('[ChannelPlayer] channel 已連線');

    //
    DCContext.getProfile(true);
    DCContext.getNations(true);
    DCContext.getCities(true);
    DCContext.getElection(true);
    DCContext.getDemos(true);
    DCContext.getWeapon_prototypes(true);
    DCContext.getUnions(true);
  }, [ChannelContext.channels?.[DCContext.playerChannelTopic]?.state]);

  /*  */

  //加入 channel
  const handleClick_join = e => {
    //join 前先 leave，避免萬一前一個連線還存在
    //handleClick_leave(); //=>跟下面的join發生時間似乎會有混亂，導致join後又發生leave

    //
    console.log('[ChannelPlayer] join channel: ', DCContext.playerChannelTopic);
    //setDoJoin(true);
    // ChannelContext.setJoin({
    // 	topic: DCContext.playerChannelTopic,
    // 	params: {fake: "1"}
    // });

    joinTimes.current += 1;

    ChannelContext.joinChannel({
      topic: DCContext.playerChannelTopic,
      params: {
        fake: 'ChannelPlayer',
        fake2: joinTimes.current,
      },
    });
  };

  const handleClick_leave = e => {
    //console.log("client: leave channel");
    // ChannelContext.setLeave({
    // 	topic: DCContext.playerChannelTopic
    // });

    ChannelContext.leaveChannel({
      topic: DCContext.playerChannelTopic,
      params: { fake: 'ChannelPlayer' },
    });
  };

  //檢查是否已完成會員基本設定(陣營 玩家名稱 組織名稱)
  //ChannelPlayer, ProtectedRoute, Routes 相關
  const verifyProfileUpdated = () => {
    if (!DCContext.userProfile) {
      return;
    }

    /*
		2個檢查點
		ProtectedRoute: 網址變更時
		ChannelPlayer: userProfile 變更時
		*/
    //未設定過所屬國家
    if (
      !DCContext.userProfile?.nation?.id &&
      // login 頁自行處理，不在此處理 (提示App升級)
      !matchPath('/users/log_in', location.pathname) &&
      //
      !matchPath('/settings/nation/*', location.pathname) &&
      !matchPath('/settings/streetimage', location.pathname) &&
      !matchPath('/settings/sealimage', location.pathname)
      //&& !matchPath("/users/register", location.pathname)
    ) {
      console.log('[ChannelPlayer] 未設定過所屬國家, 導向設定');
      navigate('/settings/nation');
      return;
    }

    // 改由 Nation.js 自行處理
    //已設定過所屬國家
    // let match2 = matchPath("/settings/nation/*", location.pathname);
    // console.log('[ChannelPlayer] pathname', location.pathname, match2);

    // if (match2){
    // 	console.log('[ChannelPlayer] /nation 已設定過所屬國家, 導向劇情', location.pathname);
    // 	navigate('/story/story_nation/fakeCityId');
    // 	return;
    // }
  };

  //每次 user profile 更新就檢查是否完成基本設定
  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    verifyProfileUpdated();
  }, [DCContext.userProfile]);

  return (
    <>
      {/* <div className="chat-messages" style={{marginTop: 20}}>
				<Row gutter={16}>
					<Col span={5}>
						<Card title="1. join channel: player">
							<Button type="primary" onClick={handleClick_join}>join</Button>
							<Button type="primary" onClick={handleClick_leave}>leave</Button>
						</Card>
					</Col>
				</Row>
			</div> */}
    </>
  );
}
