import React, { useContext, useState, useEffect, useRef } from 'react';
import { useDrag } from 'react-dnd';
import { useSpring, useSpringRef, useChain, animated, easings } from '@react-spring/web';
//
import iConfig from 'iConfig';
import styles from './BtnGrey.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
//
import popup_btn_bg from 'assets/img2/popup_btn_bg.png';

export const BtnGrey = props => {
  const btnClick = () => {
    if (props.callback) {
      props.callback();
    }
  };

  return (
    <ClickEffect
      enabled={props.enabled === false ? false : true}
      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
      onClick={e => {
        btnClick();
      }}
    >
      <div
        className={styles.formBtn}
        style={{ ...props.style, backgroundImage: `url(${popup_btn_bg})` }}
      >
        <div className={styles.btnText}>{props.text}</div>
      </div>
    </ClickEffect>
  );
};
