import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Row.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
//
import avatarTB02 from 'assets/img/tmp/avatar/avatarTB02.png';
import minicoa06UG from 'assets/img/tmp/nationSeal_c/minicoa06UG.png';
//
import icon_unionAnnouncements from 'assets/img2/icon_unionAnnouncements.png';
import icon_unionChannel from 'assets/img2/icon_unionChannel.png';
import icon_dialog from 'assets/img2/icon_dialog.png';
import icon_more from 'assets/img2/icon_more.png';

export const RowContact = props => {
  /* i18n */
  const { tt } = useI18n();
  const { i18n, ready } = useTranslation();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  //console.log("[RowContact] props.data", {...props.data});
  const [roomInfo, setRoomInfo] = useState();
  const roomTopic = useRef(props.data.room_id ? `room:${props.data.room_id}` : null);
  const [showBtns, setShowBtns] = useState(false);

  useEffect(() => {
    console.log('[RowContact] props._type', props._type);

    return () => {};
  }, []);

  useEffect(() => {
    if (!props) {
      return;
    }

    setRoomInfo(props.data);
  }, [props]);

  //拒絕申請(加盟)
  const doRejectMember = () => {
    DCContext.rejectUnionMember({ user_id: roomInfo.id });
  };

  //同意申請(加盟)
  const doApproveMember = () => {
    DCContext.approveUnionMember({ user_id: roomInfo.id });
  };

  //邀請(聯絡人)
  const doRequest = () => {
    //DCContext.request_contact({
    //  friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id //search_user 沒有 friend_id
    //});

    DCContext.setShowContactRequestForm({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //撤回邀請(聯絡人)
  const doWithdraw = () => {
    DCContext.withdraw_contact({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //拒絕邀請(聯絡人)
  const doReject = () => {
    DCContext.reject_contact({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //同意邀請(聯絡人)
  const doAccept = () => {
    DCContext.accept_contact({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //封鎖(聯絡人)
  const doBlock = () => {
    DCContext.block_contact({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //封鎖解除(聯絡人)
  const doUnblock = () => {
    DCContext.unblock_contact({
      friend_id: roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id, //search_user 沒有 friend_id
    });
  };

  //刪除全部訊息
  const doDelMessages = room_id => {
    console.log('[RowContact] doDelMessages, room_id', room_id);

    showModal_confirm({
      confirm: {
        //刪除全部訊息
        message: { i18nKey: `contacts_delete_messages_confirm`, values: null, options: null },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({});
              //
              DCContext.delete_messages({
                room_id: room_id,
              });
            },
          },
        ],
      },
    });
  };

  //點擊聯絡人文字部分
  const clickContact = () => {
    //console.log("[RowContact] clickContact, room_id", roomInfo.room_id, roomTopic.current);
    props.clickContactCallback(roomInfo);
  };

  //委任副手/領袖換手
  //authority 1:盟主 2:副手
  const doAppoint = authority => {
    DCContext.appoint_officer({
      authority: authority,
      user_id: roomInfo.friend_id,
    });
  };

  //解任副手
  const doFire = () => {
    DCContext.fire_officer({
      user_id: roomInfo.friend_id,
    });
  };

  //踢出聯盟
  const doExpel = () => {
    DCContext.expelUnionMember({
      user_id: roomInfo.friend_id,
    });
  };

  const aniStyles_btns = useSpring({
    loop: false,
    from: { x: '0%' },
    to: { x: showBtns ? '-100%' : '0%' },
    config: {
      //duration: 3000,
    },
  });

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[RowContact] callbackConfirm', returnParams);

    //
    callbackModal_confirm(null, null);

    //
  };

  return !roomInfo ? (
    <></>
  ) : (
    <>
      <div className={styles.chatGroup} wrap={false} align="middle" justify="center">
        <ClickEffect
          enabled={roomInfo.id && roomInfo.can_show_detail ? true : false}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            DCContext.showPlayerinfoModal(roomInfo.friend_id ? roomInfo.friend_id : roomInfo.id);
          }}
        >
          <div span={2} className={styles.avatarBox}>
            <>
              {/* 聯盟公告 */}
              {roomInfo.roomType == 'announcements' && (
                <IbgDiv
                  className={styles.avatarCircle}
                  src={icon_unionAnnouncements}
                  transition={false}
                  onReady={() => {}}
                ></IbgDiv>
              )}

              {/* 聯盟頻道 */}
              {roomInfo.roomType == 'unionChannel' && (
                <IbgDiv
                  className={styles.avatarCircle}
                  src={icon_unionChannel}
                  transition={false}
                  onReady={() => {}}
                >
                  <div className={styles.nationSealCircle}>
                    <Iimg
                      className={styles.nationSeal}
                      src={roomInfo.seal_image}
                      transition={false}
                      onReady={() => {}}
                    />
                  </div>
                </IbgDiv>
              )}

              {/* 聯絡人邀請清單: 只顯示一個對話 icon */}
              {roomInfo.roomType == 'contactRequestInfo' && (
                <Iimg
                  className={styles.avatarFitWidth}
                  src={icon_dialog}
                  transition={false}
                  onReady={() => {}}
                />
              )}

              {roomInfo.id && (
                <IbgDiv
                  className={styles.avatarCircle}
                  src={roomInfo.image}
                  transition={false}
                  onReady={() => {}}
                >
                  <div className={styles.nationSealCircle}>
                    {/* <Iimg className={styles.nationSeal} src={roomInfo.nation_icon} transition={false} onReady={()=>{}} /> */}
                    <Iimg
                      className={styles.nationSeal}
                      src={roomInfo.seal_image}
                      transition={false}
                      onReady={() => {}}
                    />
                  </div>
                </IbgDiv>
              )}
            </>
          </div>
        </ClickEffect>

        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            clickContact();
          }}
        >
          <div
            className={styles.chatTextBox}
            flex="auto"
            style={roomInfo.can_unblock ? { color: '#747474' } : {}}
          >
            <div className={styles.playerNameBox}>
              <span className={styles.playerName}>{roomInfo.name}</span>
              <span className={styles.playerOrg}>{roomInfo.organization}</span>
            </div>
            <div className={styles.msgText}>
              {roomInfo.can_unblock ? (
                tt(`contact_blocked`) /* 已封鎖 */
              ) : roomInfo.roomType == 'contactRequestInfo' /* 聯絡人邀請清單 */ ? (
                roomInfo.description
              ) : roomInfo.room_id /* 有 room_id 是聯絡人 */ ? (
                <>
                  {roomInfo.last_message?.recalled
                    ? tt(`message_recalled_by_player`, {
                        name: roomInfo.last_message?.name,
                      }) /*${} 已收回訊息*/
                    : roomInfo.last_message?.content.replace(/(<([^>]+)>)/gi, '')}
                </>
              ) : roomInfo.last_message?.content /* 非聯絡人有訊息 => 聯絡邀請 */ ? (
                roomInfo.last_message?.content.replace(/(<([^>]+)>)/gi, '')
              ) : (
                <>ID: {roomInfo.friend_id || roomInfo.id}</>
              )}
            </div>
          </div>
        </ClickEffect>
        <div className={styles.msgQuantityBox}>
          {roomInfo.unread_messages > 0 && (
            <div className={styles.msgQuantityText}>{roomInfo.unread_messages}</div>
          )}
        </div>

        <div>
          <div className={styles.rowBtnBox}>
            <animated.div className={styles.btnsBox1} style={{ ...aniStyles_btns }}>
              {/* 聯絡人類別 */}
              {props._type == 'contacts' && (
                <>
                  {/* 聯絡請求 */}
                  {roomInfo.can_request && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doRequest();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`contact`) /* 聯絡 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 撤回聯絡請求 */}
                  {roomInfo.can_withdraw && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doWithdraw();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`withdraw`) /* 撤回 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 拒絕聯絡請求 */}
                  {roomInfo.can_reject && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doReject();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`reject`) /* 拒絕 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 同意聯絡請求 */}
                  {roomInfo.can_accept && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doAccept();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`agree`) /* 同意 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 封鎖聯絡人 */}
                  {roomInfo.can_block && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doBlock();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`block`) /* 封鎖 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 解除封鎖 */}
                  {roomInfo.can_unblock && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doUnblock();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`unblock`) /* 解封 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 刪除 (全部訊息) */}
                  {roomInfo.can_delete_messages && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doDelMessages(roomInfo.room_id);
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`contacts_delete_messages`) /* 刪除 */}
                      </div>
                    </ClickEffect>
                  )}
                </>
              )}

              {/* 聯盟成員類別 */}
              {props._type == 'union_contacts' && (
                <>
                  {/* 交接(領袖換手) */}
                  {roomInfo.can_promote_to_chief && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doAppoint(1);
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`handover`) /* 換手 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 委任副手 */}
                  {roomInfo.can_appoint && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doAppoint(2);
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`appoint_2`) /* 委任 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 解任副手 */}
                  {roomInfo.can_fire && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doFire();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`dismissal`) /* 解任 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 踢出聯盟 */}
                  {roomInfo.can_expel && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doExpel();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`union_expel`) /* 踢出 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 封鎖聯絡人 */}
                  {roomInfo.can_block && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doBlock();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                        {tt(`block`) /* 封鎖 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 解除封鎖 */}
                  {roomInfo.can_unblock && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doUnblock();
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`unblock`) /* 解封 */}
                      </div>
                    </ClickEffect>
                  )}

                  {/* 刪除 (全部訊息) */}
                  {roomInfo.can_delete_messages && (
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        doDelMessages(roomInfo.room_id);
                      }}
                    >
                      <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                        {tt(`contacts_delete_messages`) /* 刪除 */}
                      </div>
                    </ClickEffect>
                  )}
                </>
              )}

              {/* 加盟申請類別 */}
              {props._type == 'union_applicants' && (
                <>
                  {/* 拒絕加盟申請 */}
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={() => {
                      doRejectMember();
                    }}
                  >
                    <div className={`${styles.rowBtn} ${styles.rowBtnGrey}`}>
                      {tt(`reject`) /* 拒絕 */}
                    </div>
                  </ClickEffect>
                  {/* 同意加盟申請 */}
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={() => {
                      doApproveMember();
                    }}
                  >
                    <div className={`${styles.rowBtn} ${styles.rowBtnGolden}`}>
                      {tt(`agree`) /* 同意 */}
                    </div>
                  </ClickEffect>
                </>
              )}
            </animated.div>

            <div className={styles.btnsBox2}>
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={() => {
                  setShowBtns(!showBtns);
                }}
              >
                <div className={styles.rowBtn_more}>
                  <img src={icon_more} />
                </div>
              </ClickEffect>
            </div>
          </div>
        </div>

        {/* modal confirm */}
        <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
          <Confirm {...modalProps_confirm.confirm} />
        </Imodal>
      </div>
    </>
  );
};
