import React, { useContext, useState, useEffect, useRef } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal, Popover } from 'antd';
import { animated, useSpring } from '@react-spring/web';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
//moment
import moment from 'moment';
import 'moment-timezone';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import { Imodal } from 'componentx/Imodal';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Announcements.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
//
import bgItemGray from 'assets/img2/bgItemGray.png';
import bgItemGreen from 'assets/img2/actor_pools/bgItemGreen.png';
import iconBack_gray from 'assets/img2/navigator/iconBack_gray.png';
import popup_btn_bg from 'assets/img2/popup_btn_bg.png';
import bgSelectedItem from 'assets/img2/bgSelectedItem.png';
import icon_circleCheck from 'assets/img2/icon_circleCheck.png';
import btnRight_active from 'assets/img2/actor_pools/btnRight_active.png';
import bgSkillInfo from 'assets/img2/bgSkillInfo.png';

export const Announcements = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [contentId, setContentId] = useState();
  const [content, setContent] = useState();
  const [bundleQuantity, setBundleQuantity] = useState(0); //有多少 bundle 需要領
  const [unCollectedBundles, setUnCollectedBundles] = useState(0); //有多少 bundle 未領

  useEffect(() => {
    //console.log("[Announcement] amount");

    /* debug - modal bundle received */
    // let tmpItems = [
    //   {image: "/images/player/fund.png", quantity: 10000 },
    //   {image: "/images/player/media.png", quantity: 10000 },
    //   {image: "/images/player/IT09.png", quantity: 10000 }
    // ];

    // showModal_BRA({
    //   params:{
    //     showBg: true,
    //     bundleItems: tmpItems,
    //     callback: ()=>{callbackModal_BRA(null, null)}
    //   }
    // });
    /* /debug - modal bundle received */

    return () => {
      //console.log("[Announcement] unamount");

      //清除所有公告(規則：讀取過一次，不論是否開啟，視做已讀，已讀公告不再顯示)
      console.log('[Announcement] 清除所有公告 setAnnouncements null');
      //      DCContext.setAnnouncements(null);

      //未讀公告數歸零
      //      DCContext.setUserProfile((prevState)=>{
      //        prevState.unread_announcements = 0;
      //        return prevState;
      //      });
    };
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Announcement] channel player 未連線');
      return;
    }

    console.log('[Announcement] channel player 已連線');
    DCContext.getAnnouncements();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.announcements) {
      return;
    }

    console.log('[Announcement] announcements', DCContext.announcements);

    let tmpUnReceived = 0;
    let tmpBundleQuantity = 0;
    for (let i = 0; i < DCContext.announcements.length; i++) {
      let el = DCContext.announcements[i];
      //console.log("[Announcement] setUnCollectedBundles", {...el});

      if (el.bundle) {
        tmpBundleQuantity += 1;
        if (!el.collected) {
          tmpUnReceived += 1;
        }
      }
    }

    console.log('[Announcement] tmpBundleQuantity', tmpBundleQuantity, tmpUnReceived);

    setBundleQuantity(tmpBundleQuantity);
    setUnCollectedBundles(tmpUnReceived);

    //
    if (contentId !== undefined && contentId !== null) {
      let tmp = lodash_find(DCContext.announcements, ['id', contentId]);
      setContent(tmp);
    }
  }, [DCContext.announcements, contentId]);

  //設為已讀
  useEffect(() => {
    if (!content) {
      return;
    }

    DCContext.mark_announcement_read({
      announcement_id: content.id,
    });
  }, [content]);

  const showContent = data => {
    console.log('[Announcement] showContent', data);
    setContentId(data.id);
  };

  const hideContent = () => {
    setContentId(null);
    setContent(null);
  };

  /* 單則公告領取道具 */

  const doCollectBundle = () => {
    showModal_processing(); //顯示“處理中”

    DCContext.collectBundle({
      reference_type: 'Announcement',
      reference_id: content.id,
    });
  };

  //collect_bundle 結果
  useEffect(() => {
    callbackModal_processing(); //隱藏“處理中”

    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Announcement] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* 領取全部公告道具 */
  const doCollectBundles = () => {
    let ids = [];
    DCContext.announcements.map((el, idx) => {
      if (!el.collected && el.bundle) {
        ids.push(el.id);
      }
    });

    if (!ids.length) {
      return;
    }

    showModal_processing(); //顯示“處理中”
    console.log('[Announcement] doCollectBundles', ids);

    DCContext.collectBundles({
      reference_type: 'Announcement',
      reference_ids: ids,
    });
  };

  /* API collect_bundles 結果 */
  useEffect(() => {
    callbackModal_processing(); //隱藏“處理中”

    let _key = `${DCContext.playerChannelTopic},collect_bundles`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Announcement] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundles`]?.uuid]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[Announcement] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* modal processing */

  const [modalProps_processing, setModalProps_processing] = useState({
    destroyOnClose: true,
    ratio: 0.7,
    //fullscreen: false,
    //opacityBg: true,
    //shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_processing = exProps => {
    setModalProps_processing(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_processing = (type, e) => {
    console.log('[Announcement] callbackPlayerModal', type, e);

    setModalProps_processing(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const aniStyles_moveup = useSpring(iConfig.aniStyles_moveup);

  return DCContext.announcements ? (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      <animated.div
        className={styles.listBox}
        style={content ? { opacity: 0 } : { ...aniStyles_moveup }}
      >
        {/* <animated.div className={styles.aniUpBox} style={{...aniStyles_moveup}}> */}
        {DCContext.announcements.map((el, idx) => {
          return (
            <div
              key={el.id}
              onClick={() => {
                showContent(el);
              }}
              className={styles.itemRow}
              style={{ backgroundImage: `url(${el.read ? bgItemGray : bgItemGreen})` }}
            >
              <div className={styles.subjectText}>{el.subject}</div>
              <div className={styles.dateText}>
                {moment.utc(el.published_at).local().format('YYYY.M.D')}
              </div>
            </div>
          );
        })}
        {/* </animated.div> */}
      </animated.div>

      {!content && bundleQuantity > 0 && (
        <ClickEffect
          enabled={unCollectedBundles > 0 ? true : false}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            doCollectBundles();
          }}
        >
          <div className={`${styles.rightBtnBox} ${styles.active}`}>
            <img className={styles.btnImg} src={btnRight_active} />
            <div className={styles.rightBtnText}>
              {
                unCollectedBundles > 0
                  ? tt(`claim_all`) /* 全部領取 */
                  : tt(`collected_all`) /* 全部已領取 */
              }
            </div>
          </div>
        </ClickEffect>
      )}

      {content && (
        <>
          <div className={styles.contBox}>
            <div className={styles.contentSubjectRow}>
              <div className={styles.subjectText}>{content.subject}</div>
              <div className={styles.dateText}>
                {moment.utc(content.published_at).local().format('YYYY.M.D')}
              </div>
            </div>

            {content?.bundle && (
              <div className={styles.bundleItemsBox}>
                <img className={styles.bgSkillInfo} src={bgSkillInfo} />
                <div className={styles.itemsBox}>
                  {content.bundle.map((tmpItem, idx) => {
                    const descriptionPop = (
                      <div
                        className={`popover-description`}
                        dangerouslySetInnerHTML={{ __html: tmpItem.description }}
                      ></div>
                    );

                    return (
                      <div className={styles.itemBox}>
                        <Popover
                          overlayInnerStyle={{ backgroundColor: 'unset' }}
                          content={descriptionPop}
                          title={tmpItem.name}
                          placement="rightTop"
                          trigger="click"
                          overlayClassName={styles.popOver}
                        >
                          <div className={styles.selectedItemBox}>
                            <Iimg
                              className={styles.selectedPieceImg}
                              src={tmpItem.image}
                              transition={false}
                              onReady={() => {}}
                            />
                            {content.collected && (
                              <img className={styles.icon_circleCheck} src={icon_circleCheck} />
                            )}
                            <div
                              className={styles.selectedItemQuantity}
                              style={{ color: content.collected ? '#5b5b5b' : 'white' }}
                            >
                              {tmpItem.quantity}
                            </div>
                          </div>
                        </Popover>
                        {/* <div className={styles.selectedItemName}>{tmpItem.name}</div> */}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            <div
              className={styles.contentBox}
              dangerouslySetInnerHTML={{
                __html: content.content?.replace(/(\r\n|\r|\n)/g, '<br/>'),
              }}
            >
              {/* {content.content} */}
            </div>
          </div>

          {content?.bundle && (
            <ClickEffect
              enabled={!content?.collected}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                doCollectBundle();
              }}
            >
              <div className={`${styles.rightBtnBox} ${styles.active}`}>
                <img className={styles.btnImg} src={btnRight_active} />
                <div className={styles.rightBtnText}>
                  {content?.collected ? tt(`claimed`) /* 已領取 */ : tt(`collect`) /* 領取 */}
                </div>
              </div>
            </ClickEffect>
          )}

          <img
            className={styles.iconBack}
            src={iconBack_gray}
            onClick={e => {
              hideContent();
            }}
          />
        </>
      )}

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>

      <Imodal {...modalProps_processing} callback={callbackModal_processing}>
        <div
          className={`${styles.processingLayer} modalDescriptionFont`}
          style={{ backgroundImage: `url(${bgRF})` }}
        >
          {tt(`processing`)}...
        </div>
      </Imodal>
    </div>
  ) : (
    <></>
  );
};
