import React, { useContext, useState, useEffect, useRef } from 'react';
import Spritesheet from 'react-responsive-spritesheet';
import { useSpring, animated } from '@react-spring/web';
import iConfig from 'iConfig';
import useValidSrc from 'componentx/useValidSrc';

export const Ispritesheet = ({
  image,
  styles,
  e,
  ssRefs,
  prevActionKey,
  callbackLoopComplete,
  ...props
}) => {
  const { setTargetSrc, validSrc } = useValidSrc();
  const wrapRef = useRef(null);
  const instRef = useRef(null);

  useEffect(() => {
    if (!image) {
      return;
    }

    setTargetSrc(image);
  }, [image]);

  useEffect(() => {
    if (!validSrc) {
      return;
    }

    //console.log("[Ispritesheet] validSrc", validSrc);
  }, [validSrc]);

  /* react-responsive-spritesheet 2.4.5 已改寫為 function component，ref 經由
     useImperativeHandle 只暴露 play / pause / goToAndPlay / goToAndPause /
     setStartAt / setEndAt / setFps / setDirection / getInfo —— 舊版 class component
     才有的 spriteEl (sprite 根 DOM 節點) 不再存在。

     但呼叫端 (Character.js) 仍以 spriteEl.style.display 控制顯示：.spritesheet 的 CSS
     預設是 display:none，要靠 onInit 打開。少了 spriteEl 就會在 onInit 拋
     "Cannot read properties of undefined (reading 'style')"，sprite 永遠停在
     display:none → 戰鬥畫面看不到角色 (回報：排名戰與任務戰鬥沒有角色)。

     這裡把實際渲染出來的根節點補回 instance，維持既有呼叫端不必改動。
     用 effect 而非 ref callback 指派：React 的 ref 是由子到父依序附加，
     在 Spritesheet 的 ref callback 執行時外層 wrapRef 可能還是 null。
     onInit 是圖片 onload 時才觸發，必定晚於 mount effect，時序安全。 */
  useEffect(() => {
    if (instRef.current && wrapRef.current && !instRef.current.spriteEl) {
      instRef.current.spriteEl = wrapRef.current.firstElementChild;
    }
  });

  return !validSrc ? (
    <></>
  ) : (
    // display:contents → 這層不產生 box，不影響 .spritesheet 的絕對定位與既有版面
    <div ref={wrapRef} style={{ display: 'contents' }}>
      <Spritesheet
        ref={ref => {
          //ssRefs.current[e.key] = ref;
          instRef.current = ref;
          if (props.getRefCallback) {
            props.getRefCallback(ref);
          }
        }}
        image={validSrc}
        {...props}
      />
    </div>
  );
};
