export const RewardCollectAll = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  const iZIndex = useRef(highestZindex({ _level: 'low' }));
  //
  let navigate = useNavigate();

  //
  const [title, setTitle] = useState();
  const [description, setDescription] = useState();
  //
  const [collected_items_set, setCollected_items_set] = useState();

  useEffect(() => {
    if (!DCContext.showRewardCollectAll) {
      return;
    }

    console.log(
      `[RewardCollectALL] DCContext.showRewardCollectAll`,
      DCContext.showRewardCollectAll,
    );

    DCContext.setShowProcessingModal(true); //顯示“處理中”

    //領取全部援助
    DCContext.collectBundle({
      reference_type: 'Minister and Control Union',
      //test: true
    });
  }, [DCContext.showRewardCollectAll]);

  //collect_bundle 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //debug
    //_res = debugData['collect_bundle_1'];

    console.log(`[RewardCollectALL] ${_key}`, { ..._res });

    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    if (_res.status == 'error') {
      DCContext.setShowConfirmModal({
        confirm: {
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                //console.log('xxxxx');
                DCContext.setShowConfirmModal();
                DCContext.setShowRewardCollectAll();
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      setCollected_items_set(_res.payload.collected_items_set);
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  useEffect(() => {
    if (!collected_items_set || !collected_items_set?.length) {
      return;
    }

    console.log(`[RewardCollectALL] collected_items_set`, collected_items_set);

    let tmp_items_set = collected_items_set[0];

    if (tmp_items_set) {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: '', //tt(`bundle_receive_congratulations`)/* 恭喜獲得 */,
          bundleItems: tmp_items_set.collected_items,
          backgroundColor: 'rgb(0,0,0,0)',
          disableFirstSound: false, //獎勵第一頁不播放音效，此畫面要播放勝利或失敗音效
          callback: () => {
            console.log(`[RewardCollectALL] showModal_BRA callback`);

            //callbackModal_BRA(null, null);

            //移除第一組
            let tmp = lodash_cloneDeep(collected_items_set);
            tmp.shift();
            console.log(`[RewardCollectALL] shift`, tmp);

            if (!tmp || !tmp.length) {
              DCContext.setShowRewardCollectAll();
            } else {
              setCollected_items_set(tmp);
            }
          },
        },
      });

      setDescription(tmp_items_set.description);
      setTitle(tmp_items_set.title);
    }
  }, [collected_items_set]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[RewardCollectALL] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return (
    <IbgDiv
      className={styles.contentBox}
      src={null}
      transition={false}
      onReady={() => {}}
      style={{
        zIndex: iZIndex.current,
      }}
    >
      {modalProps_BRA.params && (
        <>
          <div className={styles.bodyBox}>
            <div className={styles.leftBox}>
              <Iimg
                className={styles.leftFlag}
                src={DCContext.myUnionNation?.flag}
                transition={false}
                onReady={() => {}}
              />
            </div>

            <div className={styles.middleBox}>
              <div className={styles.titleBox}>{title}</div>
              <div className={styles.descriptionBox}>{description}</div>
            </div>

            <div className={styles.rightBox}>
              <Iimg
                className={styles.rightFlag}
                src={DCContext.myUnionNation?.flag}
                transition={false}
                onReady={() => {}}
              />
            </div>
          </div>

          <div className={styles.page}>
            <BundleReceivedAlert {...modalProps_BRA.params} />
          </div>
        </>
      )}

      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE3.mp3` }}
        onClick={() => {
          DCContext.setShowRewardCollectAll();
        }}
      >
        <div className={styles.skipText}>{tt('skip') /* 跳過 */}</div>
      </ClickEffect>

      {/* <Navigator navi={{
        navigator: {
          show: false,
        },
        back: {
          callback: ()=>{
            console.log('[RewardCollectALL] click back');
            DCContext.setShowRewardCollectAll();
          }
        }
      }}/> */}
    </IbgDiv>
  );
};

