import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import styles from './Accountbind.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';

export const Accountbind = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    const data = {
      email: values.email,
      password: values.password,
    };
    //console.log("[Accountbind] form data", data);
    //return;

    handleClick_edit_profile(data);
  };

  const submitForm = () => {
    form.submit();
    //console.log("submitForm");
  };

  //
  const handleClick_edit_profile = tmp => {
    console.log('[Accountbind] handleClick_edit_profile', tmp);
    DCContext.updateProfile(tmp);
  };

  //edit_profile 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},edit_profile`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Accountbind] ${_key}`, { ..._res });

    //error處理
    if (_res.status == 'error' && _res.error.validation_error) {
      //console.log("[Accountbind] player,edit_profile error", {..._res.error.validation_error});

      let tmp = [];
      for (var fieldName in _res.error.validation_error) {
        tmp.push({
          name: fieldName,
          errors: _res.error.validation_error[fieldName],
        });
      }
      //console.log("[Accountbind] player,edit_profile error", tmp);
      form.setFields(tmp);
    } else if (_res.status == 'error' && _res.error.message) {
      showModal_confirm({
        confirm: {
          /*錯誤，例如帳號重複*/
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                //if (props.callback){ props.callback() }
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      showModal_confirm({
        confirm: {
          /*綁定完成*/
          message: { i18nKey: `p_account_binded`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                if (props.callback) {
                  props.callback();
                }
              },
            },
          ],
        },
      });
    } else {
      console.log('edit_profile error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},edit_profile`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });
  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };
  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };
  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <Form
            action=""
            form={form}
            name="control-hooks"
            onFinish={onFinish}
            initialValues={{ email: '', password: '' }}
            labelCol={{ span: 8, className: styles.colTitle }}
            wrapperCol={{ span: 16, className: styles.colContent }}
            colon={false}
          >
            <Form.Item
              name="email"
              required={false}
              label={<div className={styles.colTitle}>{tt(`p_account_enter`) /* 輸入帳號 */}</div>}
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`p_account`) }), //帳號為必填
                },
              ]}
            >
              <Input bordered={true} className={styles.inputBox} />
            </Form.Item>

            <Form.Item
              name="password"
              required={false}
              label={<div className={styles.colTitle}>{tt(`p_password_enter`) /* 輸入密碼 */}</div>}
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`p_password`) }), //密碼為必填
                },
              ]}
            >
              <Input.Password bordered={true} className={styles.inputBox} />
            </Form.Item>
          </Form>

          <FitText className={`${styles.descriptionBox} modalDescriptionFont`}>
            {tt(`p_account_bild_confirm_description`) /* 綁定可以增加此帳號的安全性... */}
          </FitText>

          <div>
            <BtnGrey text={tt(`bild`) /* 綁定 */} callback={submitForm} />
          </div>
        </div>
      </div>

      {/* modal confirm */}

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
