export const Nationbattle_result = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  //
  let navigate = useNavigate();
  const [battleResult, setBattleResult] = useState();
  const [victoryStatusData, setVictoryStatusData] = useState();
  const [hasBundle, setHasBundle] = useState(false);

  //
  const VictoryStatusCfg = {
    0: {
      text: tt(`close_defeat`) /*惜敗*/,
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain,
    },
    1: {
      text: tt(`victory`) /*勝利*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
    },
  };

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionChannelTopic]) {
      console.log('[Nationbattle_result] channel union:x 未連線');
      return;
    }

    console.log('[Nationbattle_result] channel union:x 已連線');
    DCContext.getLast_nation_battle_result();
  }, [ChannelContext.channels[DCContext.unionChannelTopic]]);

  // last_nation_battle 結果
  useEffect(() => {
    //debug
    //setBattleResult(debugData['last_nation_battle']['lose'].response);
    //return;

    let _key = `${DCContext.unionChannelTopic},last_nation_battle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Nationbattle_result] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      navigate('/home');
    } else if (_res.status == 'ok') {
      console.log(`[Nationbattle_result] ${_key} ok`);
      setBattleResult(_res.payload);
    } else {
      console.log(`[Nationbattle_result] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},last_nation_battle`]?.uuid]);

  useEffect(() => {
    if (!battleResult) {
      return;
    }

    console.log(`[Nationbattle_result] battleResult`, { ...battleResult });

    if (battleResult.win) {
      setVictoryStatusData(VictoryStatusCfg[1]);
    } else {
      setVictoryStatusData(VictoryStatusCfg[0]);
    }

    //是否有獎勵
    if (
      battleResult.collected_items?.items?.length ||
      battleResult.collected_items?.actors?.length
    ) {
      setHasBundle(true);
    }

    //勝利或失敗音效
    if (battleResult.sound_effect) {
      //console.log("[Nationbattle_result] DCContext.playSound", battleResult.sound_effect);
      DCContext.pauseMusic();
      DCContext.playSound(battleResult.sound_effect, () => {
        //DCContext.playMusic(`${DCContext.userProfile.music}`);
        DCContext.playMusic(iConfig.battleMusic);
      });
    }
  }, [battleResult]);

  useEffect(() => {
    if (!hasBundle || !victoryStatusData) {
      return;
    }

    showModal_BRA({
      params: {
        title: victoryStatusData.text,
        bundleItems: battleResult.collected_items,
        backgroundColor: 'rgb(0,0,0,0)',
        disableFirstSound: true, //獎勵第一頁不播放音效，此畫面要播放勝利或失敗音效
      },
    });
  }, [hasBundle, victoryStatusData]);

  useEffect(() => {
    //console.log("[Nationbattle_result] hasBundle", hasBundle);
  }, [hasBundle]);

  const goNext = () => {
    // navigate("/nationbattlemap", {
    //   state: {
    //     focus_city_id: battleResult.city_id
    //   }
    // });

    //
    navigate(`/unionmedals`, {
      state: {
        catKey: 'Union', //聯盟牌位
        getPreviousRecord: 'after_nation_battle', //聯盟牌位 取上次資料做比對
        returnUrl: `/nationbattlemap`,
        returnState: {
          focus_city_id: battleResult.city_id,
        },
      },
    });
  };

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[ChatBundle] callbackPlayerModal', type, e);

    goNext();

    // setModalProps_BRA((prevState)=>({
    // 	...prevState,
    // 	visible: false
    // }));
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox} style={{}}>
        <div className={styles.bgBox}>
          <img className={styles.bgImg} src={victoryStatusData?.bgImg} />
          <img className={styles.bgImg_chain} src={victoryStatusData?.fgImg} />
        </div>

        {hasBundle && (
          <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
        )}

        {!hasBundle && (
          <div
            className={styles.clickSensorBox}
            onClick={() => {
              goNext();
            }}
          >
            <div className={`${styles.resultTitleBox} ${styles.middle}`}>
              {hasBundle}
              {victoryStatusData?.text}
            </div>
          </div>
        )}
      </div>

      <Navigator
        navi={{
          back: {
            callback: () => {
              goNext();
            },
          },
        }}
      />
    </div>
  );
};

