const SelectedProps = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  const location = useLocation();
  //
  const [tmpSelectedPropsAry, setTmpSelectedPropsAry] = useState([]);

  useEffect(() => {
    if (!DCContext.tmpSelectedProps) {
      setTmpSelectedPropsAry([]);
    }

    setTmpSelectedPropsAry(DCContext.tmpSelectedProps);
  }, [DCContext.tmpSelectedProps]);

  useEffect(() => {
    console.log('[ActorProps] tmpSelectedPropsAry', tmpSelectedPropsAry);
  }, [tmpSelectedPropsAry]);

  //點擊減少已選擇素材數量
  const itemClick = _itemData => {
    console.log('[ActorProps] itemClick itemData', _itemData);

    let tmpIdx = DCContext.tmpSelectedProps.findIndex(el => {
      return el.id == _itemData.id;
    });
    console.log('[ActorProps] itemClick tmpIdx', tmpIdx);

    //
    let tmpQuantity = DCContext.tmpSelectedProps[tmpIdx].usedQuantity - 1;

    if (tmpQuantity <= 0) {
      let copy = [...DCContext.tmpSelectedProps];
      copy.splice(tmpIdx, 1);
      DCContext.setTmpSelectedProps(copy);
    } else {
      DCContext.setTmpSelectedProps(prevState => {
        let copy = [...prevState];
        copy[tmpIdx].usedQuantity--;
        return copy;
      });
    }
  };

  return (
    <div className={styles.skillBox2}>
      {[...Array(5)].map((tmp, idx) => {
        return (
          <div className={styles.selectedItemBox}>
            <img className={styles.bgSelectedItem} src={bgSelectedItem} />
            {tmpSelectedPropsAry && tmpSelectedPropsAry[idx] && (
              <>
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    itemClick(tmpSelectedPropsAry[idx]);
                  }}
                >
                  <Iimg
                    className={styles.selectedPieceImg}
                    src={tmpSelectedPropsAry[idx].prop_prototype.image}
                    transition={false}
                    onReady={() => {}}
                  />
                </ClickEffect>
                <div className={styles.selectedItemQuantity}>
                  {tmpSelectedPropsAry[idx].usedQuantity}
                </div>
              </>
            )}
          </div>
        );
      })}
    </div>
  );
};

export const ActorProps = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  //
  let navigate = useNavigate();
  const location = useLocation();
  //
  const [actor, setActor] = useState();
  const prevActor = useRef();
  //
  const mode = props.mode;
  //
  const [upgradeActorCacuResult, setUpgradeActorCacuResult] = useState();
  const [actorExpData, setActorExpData] = useState(); //幹部強化 畫面顯示經驗值相關部分
  //
  const [upgradeWeaponCacuResult, setUpgradeWeaponCacuResult] = useState();
  const [weaponUpgradeExpData, setWeaponUpgradeExpData] = useState(); //符文升級 畫面顯示經驗值相關部分
  //
  const [weaponEquipExpData, setWeaponEquipExpData] = useState(); //符文裝備 畫面顯示經驗值相關部分
  //
  const [weaponPrototype, setWeaponPrototype] = useState(); //符文 prototype 用來計算 符文裝備 符文升級 HP ATK 數值變化
  //
  const CountUp_delaySec = 1;
  const CountUp_timer = useRef();

  useEffect(() => {
    return () => {
      clearTimeout(CountUp_timer.current);
    };
  }, []);

  useEffect(() => {
    if (!props.actorData) {
      return;
    }

    if (JSON.stringify(actor) === JSON.stringify(props.actorData)) {
      return;
    }

    console.log('[ActorProps] props.actorData', props.actorData);

    //把目前的 actor 保留供下次比對
    // if (!prevActor.current || prevActor.current.id != props.actorData.id){
    //   prevActor.current = lodash_cloneDeep(props.actorData);
    // }
    prevActor.current = lodash_cloneDeep(actor);

    //更新 actor
    setActor(props.actorData);

    //大約升級數字跳動結束後(非精準)
    CountUp_timer.current = setTimeout(() => {
      prevActor.current = lodash_cloneDeep(props.actorData);
    }, 4000);
  }, [props.actorData]);

  useEffect(() => {
    if (!actor) {
      return;
    }

    //console.log('[ActorProps] actor.skill', prevActor.current?.skill, actor.skill);
  }, [actor]);

  useEffect(() => {
    if (!actor) {
      return;
    }

    console.log('[ActorProps] mode', mode);

    switch (mode) {
      case 'actorUpgrade':
        if (!DCContext.tmpSelectedProps.length) {
          setUpgradeActorCacuResult(null);
        } else {
          let tmpResult = DCContext.cacuActorUpgradeExp(actor);
          setUpgradeActorCacuResult(tmpResult);
        }
        break;
      case 'weaponUpgrade':
        if (!DCContext.tmpSelectedProps.length) {
          setUpgradeWeaponCacuResult(null);
        } else {
          let tmpResult = DCContext.cacuWeaponUpgradeExp(actor.weapon);
          console.log('[ActorProps] cacuWeaponUpgradeExp', tmpResult);
          setUpgradeWeaponCacuResult(tmpResult);
        }
        break;
    }
  }, [DCContext.tmpSelectedProps]);

  //強化 計算幹部屬性變化
  useEffect(() => {
    if (!actor) {
      return;
    }

    let tmpData = {
      lvCap: '', //上限等級，用來計算顯示的資訊
      lvPlus: '', //等級旁的+號
      expPlus: '', //經驗值旁的+號
      expMax: '', //經驗值分母
      hpPlus: '', //血量旁的+號
      atkPlus: '', //攻擊力旁的+號
      barPercent: 0, //經驗值bar長度的比例
    };

    if (!upgradeActorCacuResult) {
      let tmpLvCap = Math.min(actor.level + 1, actor.level_cap);
      tmpData.lvCap = tmpLvCap;
      tmpData.expMax = tmpLvCap * tmpLvCap * 1000;
      //
      let barPercent = Math.round((actor.skill / tmpData.expMax) * 100);
      if (barPercent > 100) {
        barPercent = 100;
      }
      tmpData.barPercent = `${barPercent}%`;
    } else {
      let tmpLvCap = Math.min(upgradeActorCacuResult.finalLevel + 1, actor.level_cap);
      tmpData.lvCap = tmpLvCap;
      tmpData.expMax = tmpLvCap * tmpLvCap * 1000;
      //
      let tmpLvPlus = Math.min(upgradeActorCacuResult.finalLevel, actor.level_cap);
      tmpData.lvPlus = tmpLvPlus - actor.level;
      tmpData.expPlus = upgradeActorCacuResult.propsExp;
      //
      let barPercent = Math.round(
        (upgradeActorCacuResult.finalLevel_overExp / tmpData.expMax) * 100,
      );
      if (barPercent > 100) {
        barPercent = 100;
      }
      tmpData.barPercent = `${barPercent}%`;
      //
      tmpData.hpPlus = tmpData.lvPlus * actor.actor_prototype.blood_elevation_value;
      tmpData.atkPlus = tmpData.lvPlus * actor.actor_prototype.offense_elevation_value;
    }

    console.log('[ActorProps] setActorExpData', mode, tmpData);
    setActorExpData(tmpData);
  }, [actor, upgradeActorCacuResult]);

  //裝備符文 計算幹部屬性變化
  useEffect(() => {
    if (mode != 'weaponEquip' || !actor) {
      return;
    }

    let tmpData = {
      hpPlus: '', //血量旁的+號
      atkPlus: '', //攻擊力旁的+號
    };

    if (weaponPrototype) {
      tmpData = {
        hpPlus:
          weaponPrototype?.blood_base_value +
          weaponPrototype?.blood_elevation_value * (DCContext?.tmpSelectedWeapon.level - 1),
        atkPlus:
          weaponPrototype?.offense_base_value +
          weaponPrototype?.offense_elevation_value * (DCContext?.tmpSelectedWeapon.level - 1),
      };
    }

    console.log('[ActorProps] setWeaponEquipExpData', mode, tmpData);
    setWeaponEquipExpData(tmpData);
  }, [mode, actor, weaponPrototype]);

  useEffect(() => {
    if (mode != 'weaponUpgrade' || !actor) {
      return;
    }

    console.log(
      '[ActorProps] weaponUpgrade upgradeWeaponCacuResult',
      mode,
      upgradeWeaponCacuResult,
      weaponPrototype,
      actor,
    );

    let tmpData = {
      hpPlus: '', //血量旁的+號
      atkPlus: '', //攻擊力旁的+號
    };

    if (upgradeWeaponCacuResult) {
      tmpData = {
        hpPlus:
          weaponPrototype?.blood_elevation_value *
          (upgradeWeaponCacuResult.finalLevel - actor.weapon.level),
        atkPlus:
          weaponPrototype?.offense_elevation_value *
          (upgradeWeaponCacuResult.finalLevel - actor.weapon.level),
      };
    }
    console.log('[ActorProps] weaponUpgrade tmpData', tmpData, weaponPrototype);

    setWeaponUpgradeExpData(tmpData);
  }, [mode, actor, upgradeWeaponCacuResult, DCContext?.tmpSelectedWeapon]);

  const goEvolute = () => {
    navigate(`/user/actorevolute/${actor.id}`, {
      state: {
        returnUrl: location.pathname,
      },
    });
  };

  //裝備武器(符文): 準備 weaponPrototype
  useEffect(() => {
    if (mode != 'weaponEquip' || !actor) {
      return;
    }

    if (!DCContext?.tmpSelectedWeapon) {
      setWeaponPrototype();
    } else {
      let tmpPrototype = lodash_find(DCContext.weapon_prototypes, {
        id: DCContext?.tmpSelectedWeapon?.weapon_prototype_id,
      });
      console.log(
        '[ActorProps] actor weaponEquip',
        actor,
        DCContext?.tmpSelectedWeapon,
        DCContext.weapon_prototypes,
        tmpPrototype,
      );

      setWeaponPrototype(tmpPrototype);
    }
  }, [mode, actor, DCContext?.tmpSelectedWeapon]);

  //符文升級: 準備 weaponPrototype
  useEffect(() => {
    if (mode != 'weaponUpgrade' || !actor) {
      return;
    }

    if (!actor.weapon?.weapon_prototype_id) {
      setWeaponPrototype();
    } else {
      let tmpPrototype = lodash_find(DCContext.weapon_prototypes, {
        id: actor.weapon?.weapon_prototype_id,
      });
      console.log('[ActorProps] weaponUpgrade', actor, DCContext.weapon_prototypes, tmpPrototype);

      setWeaponPrototype(tmpPrototype);
    }
  }, [mode, actor]);

  /* modal */

  const [modalProps_ActorSkills, setModalProps_ActorSkills] = useState({
    ratio: 0.82,
    visible: false,
  });

  const showModal_ActorSkills = () => {
    setModalProps_ActorSkills(prevState => ({
      ...prevState,
      visible: true,
      destroyOnClose: true,
    }));
  };

  const callbackModal_ActorSkills = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_ActorSkills(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return actor ? (
    <div className={`${styles.rootContainer}`}>
      <img className={`bgTunl`} src={bgTunl} />
      <Iimg className={`bg_scarcity_image`} src={actor?.scarcity_image} />

      <div className={styles.contentBox}>
        <div className={styles.lvBox}>
          <div className={styles.lvBoxLeft}>
            <div className={styles.lvText}>Lv</div>
            <div className={styles.lvNum}>
              {actor.id == prevActor.current?.id && actor?.level != prevActor.current?.level ? (
                <CountUp
                  prefix=""
                  preserveValue={true}
                  start={prevActor.current?.level}
                  end={actor?.level}
                  delay={CountUp_delaySec}
                />
              ) : (
                actor?.level.toLocaleString('en-US')
              )}
            </div>
            {actorExpData?.lvPlus > 0 && (
              <div className={`${styles.upLevelCount} colorGolden`}>
                {`+${actorExpData?.lvPlus}`}
                {/* <CountUp prefix="+" preserveValue={true} end={actorExpData?.lvPlus} /> */}
              </div>
            )}
            <div className={styles.lvSlash}>/</div>
            <div className={styles.lvCap}>
              {(() => {
                const relationLevelCap = actor?.actor_prototype?.relation_level_cap ?? 1;
                const relationLevel = actor?.relation_level ?? 1;
                let previewRelationLevel = relationLevel;

                if (relationLevelCap > 1) {
                  const relationExps =
                    (actor?.relation_exps ?? 0) +
                    previewRelationAdd(
                      DCContext.tmpSelectedProps,
                      actor?.actor_prototype_id ?? actor?.actor_prototype?.id,
                    );
                  while (previewRelationLevel < relationLevelCap) {
                    const threshold = (2 ** previewRelationLevel - 1) * 40000;
                    if (relationExps < threshold) break;
                    previewRelationLevel += 1;
                  }
                }

                const previewExtraCap =
                  extraLevelCapFromRelation(previewRelationLevel) -
                  extraLevelCapFromRelation(relationLevel);

                if (mode == 'actorEvolute' && DCContext.tmpSelectedPiece) {
                  return (
                    <span className="colorGolden">
                      {actor.level_cap + iConfig.evolute.level_interval[actor?.scarcity]}
                    </span>
                  );
                }
                if (previewExtraCap > 0) {
                  // 桃色 #ae7272：與 UwActorTopBlock 的關係等級/經驗值預覽同一個色
                  return (
                    <span style={{ color: '#ae7272' }}>
                      {(actor.level_cap + previewExtraCap).toLocaleString('en-US')}
                    </span>
                  );
                }
                if (
                  actor.id == prevActor.current?.id &&
                  actor?.level_cap != prevActor.current?.level_cap
                ) {
                  return (
                    <CountUp
                      prefix=""
                      preserveValue={true}
                      start={prevActor.current?.level_cap}
                      end={actor?.level_cap}
                      delay={CountUp_delaySec}
                    />
                  );
                }
                return actor.level_cap.toLocaleString('en-US');
              })()}
            </div>
            <div className={styles.lvCap}>
              {mode != 'actorEvolute' && actor.can_evolute && (
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE11.mp3` }}
                  onClick={e => {
                    goEvolute();
                  }}
                >
                  <img className={styles.iconUpgrade} src={icon_upgrade} />
                </ClickEffect>
              )}
            </div>
          </div>
          {/* <div className={styles.lvBox5}></div> */}

          <div className={styles.nationBox}>
            <div className={styles.actorNation}>
              {
                tt(`actor_from_nation`, {
                  nation_name: DCContext.nationNames[actor?.nation_id],
                }) /* {actor?.nation}出身 */
              }
            </div>
            <div
              className={styles.actorCat}
              style={{ color: actor?.actor_prototype.actor_category.font_color }}
            >
              {actor?.actor_prototype.actor_category.name}
            </div>
          </div>
        </div>
        <div className={styles.propsBox}>
          <div className={styles.propRT}>
            {/* {`(${actor.id}, ${prevActor.current?.id}, ${actor?.skill}, ${prevActor.current?.skill})  `} */}
            {actor.id == prevActor.current?.id && actor?.skill != prevActor.current?.skill ? (
              <CountUp
                prefix={``}
                preserveValue={true}
                start={prevActor.current?.skill}
                end={actor?.skill}
                delay={CountUp_delaySec}
              />
            ) : (
              actor?.skill.toLocaleString('en-US')
            )}
            {actorExpData?.expPlus && (
              <span className={`colorGolden`}>
                {`+${actorExpData?.expPlus.toLocaleString('en-US')}`}
                {/* <CountUp prefix="+" preserveValue={true} end={actorExpData?.expPlus} /> */}
              </span>
            )}
            &nbsp;/&nbsp;
            {actorExpData?.expMax.toLocaleString('en-US')}
          </div>
          <div className={styles.propRB}>
            ATK
            {actor.id == prevActor.current?.id && actor?.offense != prevActor.current?.offense ? (
              <CountUp
                prefix=""
                preserveValue={true}
                start={prevActor.current?.offense}
                end={actor?.offense}
                delay={CountUp_delaySec}
              />
            ) : (
              actor?.offense.toLocaleString('en-US')
            )}
            <span className={`colorGolden`}>
              {mode == 'actorUpgrade' && actorExpData?.atkPlus > 0 ? ( //強化
                `+${actorExpData?.atkPlus.toLocaleString('en-US')}`
              ) : mode == 'weaponEquip' && weaponEquipExpData?.atkPlus > 0 ? ( //裝備符文
                `+${weaponEquipExpData?.atkPlus.toLocaleString('en-US')}`
              ) : mode == 'weaponUpgrade' && weaponUpgradeExpData?.atkPlus > 0 ? ( //符文升級
                `+${weaponUpgradeExpData?.atkPlus.toLocaleString('en-US')}`
              ) : (
                <></>
              )}
            </span>
          </div>
          <div className={styles.propLB}>
            HP
            {actor.id == prevActor.current?.id && actor?.blood != prevActor.current?.blood ? (
              <CountUp
                prefix=""
                preserveValue={true}
                start={prevActor.current?.blood}
                end={actor?.blood}
                delay={CountUp_delaySec}
              />
            ) : (
              actor?.blood.toLocaleString('en-US')
            )}
            <span className={`colorGolden`}>
              {mode == 'actorUpgrade' && actorExpData?.hpPlus > 0 ? ( //強化
                `+${actorExpData?.hpPlus.toLocaleString('en-US')}`
              ) : mode == 'weaponEquip' && weaponEquipExpData?.hpPlus > 0 ? ( //裝備符文
                `+${weaponEquipExpData?.hpPlus.toLocaleString('en-US')}`
              ) : mode == 'weaponUpgrade' && weaponUpgradeExpData?.hpPlus > 0 ? ( //符文升級
                `+${weaponUpgradeExpData?.hpPlus.toLocaleString('en-US')}`
              ) : (
                <></>
              )}
            </span>
          </div>
          <div className={styles.propBar}>
            <div className={styles.propBarBg}></div>
            <div className={styles.propBarFill} style={{ width: actorExpData?.barPercent }}></div>
          </div>
        </div>

        {mode == 'actorEvolute' ? (
          <div className={styles.skillBox2}>
            <div className={styles.selectedItemBox}>
              <img className={styles.bgSelectedItem} src={bgSelectedItem} />
              {DCContext.tmpSelectedPiece && (
                <Iimg
                  className={styles.selectedPieceImg}
                  src={DCContext.tmpSelectedPiece.image}
                  transition={false}
                  onReady={() => {}}
                />
              )}
            </div>
          </div>
        ) : mode == 'actorUpgrade' || mode == 'weaponUpgrade' ? (
          <SelectedProps />
        ) : (
          <div className={styles.skillBox}>
            <div className={styles.skillBoxLeft}>
              <div className={styles.skillBoxBar} style={{ backgroundImage: `url(${bgTitle_s})` }}>
                {tt(`actor_talent`) /* 天賦 */}
              </div>
              <div
                className={styles.skillBoxText}
                dangerouslySetInnerHTML={{
                  __html: `${actor?.actor_prototype.talent_1}<br/>${actor?.actor_prototype.talent_2}`,
                }}
              ></div>
            </div>

            <div className={styles.skillBoxRight}>
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={e => {
                  showModal_ActorSkills();
                }}
              >
                <div className={styles.skillTreeBox}>
                  <div>
                    <img className={styles.skillTree} src={icon_skilltree} />
                  </div>
                  <div className={styles.skillTreeText}>{tt(`actor_talent_tree`) /* 天賦樹 */}</div>
                </div>
              </ClickEffect>
            </div>
          </div>
        )}

        <div className={styles.weaponBox}>
          <div className={styles.weapons}>
            <div className={styles.weapon}>
              <EquipWeapon actor={actor} mode={mode} />
            </div>
            {upgradeWeaponCacuResult && (
              <>
                <div className={styles.icon_arrow2_right}>
                  <img className={null} src={icon_arrow2_right} />
                </div>
                <div className={styles.weapon}>
                  <EquipWeapon
                    actor={actor}
                    mode={mode}
                    upgradeWeaponCacuResult={upgradeWeaponCacuResult}
                  />
                </div>
              </>
            )}

            {mode != 'weaponUpgrade' && (
              <div className={styles.weapon}>
                <EquipSkill
                  actor={actor}
                  skillData={actor?.active_skill}
                  active_skills={actor?.actor_prototype.active_skills}
                />
              </div>
            )}
          </div>
        </div>

        {mode == 'actorEvolute' && DCContext.tmpSelectedPiece && (
          <div className={styles.mediaCostBox}>
            <img className={styles.iconPublicity} src={iconPublicity} />
            <div className={styles.mediaCostText}>
              -{iConfig.evolute.media_cost[actor.scarcity]}
            </div>
          </div>
        )}

        {mode == 'actorUpgrade' && upgradeActorCacuResult && (
          <div className={styles.mediaCostBox}>
            <img className={styles.iconPublicity} src={iconPublicity} />
            <div className={styles.mediaCostText}>
              -{upgradeActorCacuResult?.finalLevel_needMedia.toLocaleString('en-US')}
              {/* <CountUp prefix="-" preserveValue={true} end={upgradeActorCacuResult?.propsExp} /> */}
            </div>
          </div>
        )}

        {mode == 'weaponUpgrade' && upgradeWeaponCacuResult && (
          <div className={styles.mediaCostBox}>
            <img className={styles.iconPublicity} src={iconPublicity} />
            <div className={styles.mediaCostText}>
              -{upgradeWeaponCacuResult?.finalLevel_needMedia.toLocaleString('en-US')}
              {/* -{upgradeWeaponCacuResult?.propsExp} */}
            </div>
          </div>
        )}
      </div>

      {/* 天賦樹 */}
      <Imodal {...modalProps_ActorSkills} callback={callbackModal_ActorSkills}>
        <ActorSkills actor={actor} />
      </Imodal>
    </div>
  ) : (
    <></>
  );
};
