import React, { useContext, useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useRoutes, useNavigate } from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
  Popover,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { FitText } from 'lib/FitText';
//
import styles from './Actorcard.module.scss';
//
import actorBg from 'assets/img2/actorcard/actorBg.png';
import actorFg from 'assets/img2/actorcard/actorFg.png';
import actorFgLight from 'assets/img2/actorcard/actorFgLight.gif';
import actorProPanel_white from 'assets/img2/actorcard/actorProPanel_white.png';
import bgTipsText from 'assets/img2/bgTipsText.png';
import icon_vanguard from 'assets/img2/icon_vanguard.png';
import icon_info from 'assets/img2/icon_info.png';

const positionImgs = {
  1: `/images/team/A.png`,
  2: `/images/team/B.png`,
  3: `/images/team/C.png`,
  4: `/images/team/D.png`,
  5: `/images/team/E.png`,
};

export const Actorcard = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  let navigate = useNavigate();
  /*
  cardType 大小
  dataType 一般 或者 招募 ... 等
  */
  const { actor, cardType, dataType, positonKey } = { ...props };
  //console.log("[Actorcard] actor", actor);

  const [iActor, setIActor] = useState({
    actorImg: '',
    positionImg: positionImgs[positonKey],
    panelImg: actorProPanel_white,
  });

  useEffect(() => {
    if (!actor) {
      return;
    }

    setIActor(preState => {
      let actorImg = cardType == 'M' ? actor.half_image : actor.head_image;
      let positionImg = actor.team ? positionImgs[actor.team.position_in_team] : null;

      return {
        actorImg: actorImg,
        positionImg: positionImg,
        panelImg: actor.actor_category_decor,
      };
    });
  }, [actor]);

  useEffect(
    preState => {
      //console.log("[Actorcard] iActor", iActor);
    },
    [iActor],
  );

  const aniStyles = useSpring({
    from: { opacity: 0 },
    to: { opacity: 1 },
    loop: { reverse: true },
    //reverse: true,
    config: {
      duration: 1500,
    },
  });

  return (
    <div
      className={styles.actorBox}
      style={cardType == 'M' ? { backgroundImage: `url(${actorBg})` } : {}}
    >
      {/* <div className={styles.actor} style={
        iActor.actorImg ? {backgroundImage: `url(${iActor.actorImg})`} : {}
      }></div>	 */}

      <IbgDiv
        className={styles.actor}
        src={iActor.actorImg}
        transition={false}
        onReady={() => {}}
      ></IbgDiv>

      {cardType == 'M' && dataType == 'teams' && (
        <>
          <div className={styles.actorFg} style={{ backgroundImage: `url(${actorFg})` }}></div>
          {actor && (
            <div
              className={styles.actorFg}
              style={{ backgroundImage: `url(${actorFgLight})` }}
            ></div>
          )}
          <IbgDiv
            className={styles.actorFg}
            src={iActor.positionImg}
            transition={false}
            onReady={() => {}}
          ></IbgDiv>
        </>
      )}

      {/* <div className={styles.actorProPanel} style={{backgroundImage: `url(${iActor.panelImg})`}}> */}
      <IbgDiv className={styles.actorProPanel} src={null} transition={false} onReady={() => {}}>
        <Iimg className={styles.actorProPanelImg} src={iActor.panelImg} />

        <div className={styles.actorProPanelProps}>
          <div className={styles.panelProps}>
            {actor?.nation_icon && (
              <Iimg
                className={styles.nation_icon}
                src={actor?.nation_icon}
                transition={false}
                onReady={() => {}}
              />
            )}
            <div className={styles.actorName}>
              <FitText>{actor?.actor_prototype?.name}</FitText>
            </div>
          </div>
          <div className={styles.panelProps2}>
            {dataType == 'recruit' ? (
              <>
                {(actor?.actor_piece || actor?.wild_card_piece) && (
                  <div
                    className={styles.cardPieceText}
                    style={{ backgroundImage: `url(${bgTipsText})` }}
                  >
                    {tt(`secret_scrolls`) /* 祕笈 */}
                  </div>
                )}
                <animated.div
                  className={`${styles.actorLv} ${styles[actor?.scarcity]}`}
                  style={actor?.scarcity == 'SSR' ? { ...aniStyles } : {}}
                >
                  <FitText>{actor?.scarcity}</FitText>
                </animated.div>
              </>
            ) : (
              <>
                {/* <div className={styles.actorTeamNo}>{actor?.team?.team_roman_number}</div> */}
                <div className={styles.actorTeamNo}>
                  <FitText>{actor?.team?.team_roman_number}</FitText>
                </div>
                {/* <div className={styles.actorTeamPos}>{actor?.team?.alphabet_in_team}</div>				 */}
                <div className={styles.actorTeamPos}>
                  <FitText>{actor?.team?.alphabet_in_team}</FitText>
                </div>
                <div className={styles.actorLv}>
                  <FitText>{actor?.level}</FitText>
                </div>
                <div
                  className={styles.actorLvBar}
                  style={{ width: `${actor?.skill_percentage}%` }}
                ></div>
              </>
            )}
          </div>
          <Iimg
            className={styles.scarcity}
            src={actor?.scarcity_icon}
            transition={false}
            onReady={() => {}}
          />

          {/* {actor?.actor_category_icon && (
            <Iimg className={styles.iconActorPro} src={actor?.actor_category_icon} transition={false} onReady={()=>{}} />
          )} */}

          {actor && (
            <div className={styles.iconActorProBox}>
              {dataType == 'recruit' ? (
                <Iimg
                  className={styles.iconActorPro}
                  src={actor?.actor_category_icon}
                  transition={false}
                  onReady={() => {}}
                />
              ) : (
                <>
                  <Iimg
                    className={styles.iconActorPro}
                    src={icon_info}
                    transition={false}
                    onReady={() => {}}
                  />
                  <Popover
                    overlayInnerStyle={{ backgroundColor: 'unset' }}
                    content={
                      <div
                        className={`popover-description`}
                        dangerouslySetInnerHTML={{
                          __html: `
                      <div style='padding-bottom:2.5%; background-color: transparent'>
                        ${actor?.actor_prototype?.actor_category.name}
                        ${
                          actor?.actor_prototype?.vanguard
                            ? `(${tt('actor_category_vanguard')})`
                            : ``
                        }
                      </div>
                      <div style='padding-bottom:2.5%; background-color: transparent'>
                        ${actor?.no_weapon_name}
                      </div> 
                      <div>${tt(`actor_talent`)}：</div>
                      <div>${actor?.actor_prototype?.talent_2}</div> 
                      <div>
                        ${actor?.active_skill?.name}：(${tt(`commands_required`)}${
                            actor?.active_skill?.activate_skill_point
                          })
                      </div> 
                      <div>${actor?.active_skill?.description}</div> 
                    `,
                        }}
                      ></div>
                    }
                    title={null}
                    placement="rightTop"
                    trigger="click"
                    overlayClassName={styles.popOver}
                  >
                    <div className={styles.iconActorProSensor} onClick={e => e.stopPropagation()} />
                  </Popover>
                </>
              )}
            </div>
          )}

          {actor?.actor_prototype?.vanguard && (
            <Iimg
              className={styles.icon_vanguard}
              src={icon_vanguard}
              transition={false}
              onReady={() => {}}
            />
          )}
        </div>
      </IbgDiv>
    </div>
  );
};
