import React, { useContext, useState, useEffect } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import { find as lodash_find, orderBy as lodash_orderBy } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import { Imodal } from 'componentx/Imodal';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { ClickEffect } from 'componentx/ClickEffect';
import styles from './Playerinfo.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
//
import actor_halfbody_bg from 'assets/img2/playerinfo/actor_halfbody_bg.png';
import actor_halfbody_fg from 'assets/img2/playerinfo/actor_halfbody_fg.png';
import actor_head_bg from 'assets/img2/playerinfo/actor_head_bg.png';
import actor_head_fg from 'assets/img2/playerinfo/actor_head_fg.png';
import iconChange from 'assets/img/iconChange.png';
import iconTrash from 'assets/img/iconTrash.png';
//
import gold_circle_check from 'assets/img/nation/gold_circle_check.png';
import icon_circle_check_green from 'assets/img2/icon_circle_check_green.png';
import goldmedal from 'assets/img/teams/goldmedal.png';

import icon_unionQuit from 'assets/img2/icon_unionQuit.png';
import icon_unionChannel from 'assets/img2/icon_unionChannel.png';
import icon_pen from 'assets/img2/icon_pen.png';
import icon_copy from 'assets/img2/playerinfo/icon_copy.png';
import icon_clover from 'assets/img2/icon_clover.png';
import icon_dialog from 'assets/img2/icon_dialog.png';
import icon_unionFire from 'assets/img2/icon_unionFire.png';
import bgMedalShadow from 'assets/img2/bgMedalShadow.png';

//
import { AccountDel } from 'component/modal/AccountDel';
import { Names } from 'pages/settings/Names';
import { UwPlayerLocation, UwWorkstationsButton } from 'features/underworld';

export const Playerinfo = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  const navigate = useNavigate();
  const location = useLocation();

  const [actors, setActors] = useState([]);
  const [delAccountBtnClicks, setDelAccountBtnClicks] = useState(0);
  const [retractContactClicks, setRetractContactClicks] = useState(0);
  const [isSelf, setIsSelf] = useState(false);
  //console.log('Imodal props', props);

  useEffect(() => {
    return () => {
      DCContext.setShowPlayerinfoId();
      DCContext.setPlayerInfo();
    };
  }, []);

  useEffect(() => {
    if (!DCContext.showPlayerinfoId) {
      return;
    }

    console.log('[Playerinfo] showPlayerinfoId', DCContext.showPlayerinfoId);
    DCContext.getPlayerinfo();
  }, [DCContext.showPlayerinfoId]);

  useEffect(() => {
    if (!DCContext.playerInfo || !DCContext.userProfile) {
      return;
    }
    //console.log("[Playerinfo] DCContext.playerInfo", {...DCContext.playerInfo});

    if (DCContext.playerInfo.id === DCContext.userProfile.id) {
      setIsSelf(true);
    }

    let tmpActors = [];
    if (DCContext.playerInfo.first_team?.actors) {
      tmpActors = [...DCContext.playerInfo.first_team?.actors];
      tmpActors.sort((a, b) => (a.team.position_in_team > b.team.position_in_team ? 1 : -1));
    }
    setActors(tmpActors);
  }, [DCContext.playerInfo, DCContext.userProfile]);

  const goChangeUserImage = () => {
    navigate('/user/image_change');

    if (props.callback) {
      props.callback();
    }
  };

  const showUnionInfo = () => {
    DCContext.showUnionModal(DCContext.playerInfo?.union.id);

    if (props.callback) {
      props.callback();
    }
  };

  const delAccountBtnClick = () => {
    if (delAccountBtnClicks > 0) {
      //跳訊息確認刪除
      showModal_AccountDel();
    } else {
      setDelAccountBtnClicks(prevState => {
        return prevState + 1;
      });
    }
  };

  const clickRetractContact = () => {
    if (retractContactClicks > 0) {
      //
      console.log('[Playerinfo] clickRetractContact 解除聯絡人', { ...DCContext.playerInfo });

      DCContext.retract_contact({
        friend_id: DCContext.playerInfo.id,
      });
    } else {
      setRetractContactClicks(prevState => {
        return prevState + 1;
      });
    }
  };

  const clickSendMessage = () => {
    //進入聊天室
    DCContext.enterChatRoom({
      room_id: DCContext.playerInfo.room_id,
    });

    if (props.callback) {
      props.callback();
    }
  };

  //加入聯絡人
  const clickAddContact = () => {
    //都用 request_contact，server 會自動處理兩者之間目前關係
    // DCContext.request_contact({
    //   friend_id: DCContext.playerInfo.id //search_user 沒有 friend_id
    // });

    DCContext.setShowContactRequestForm({
      friend_id: DCContext.playerInfo.id, //search_user 沒有 friend_id
    });
  };

  //retract_contact 解除聯絡人 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},retract_contact`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //console.log(`[Playerinfo] ${_key}`, {..._res});

    if (_res.status == 'ok') {
      //重新取此玩家資料
      DCContext.getPlayerinfo();
    } else {
      //todo error處理
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},retract_contact`]?.uuid]);

  //request_contact 邀請聯絡人 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},request_contact`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //console.log(`[Playerinfo] ${_key}`, {..._res});

    if (_res.status == 'ok') {
      //重新取此玩家資料
      DCContext.getPlayerinfo();
    } else {
      //todo error處理
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},request_contact`]?.uuid]);

  /* modal confirm */

  const [modalProps_AccountDel, setModalProps_AccountDel] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_AccountDel = exProps => {
    setModalProps_AccountDel(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_AccountDel = (type, e) => {
    setModalProps_AccountDel(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  // modal set names
  const [modalProps_names, setModalProps_names] = useState({
    ratio: 0.82,
    visible: false,
  });
  const showModal_names = () => {
    setModalProps_names(prevState => ({
      ...prevState,
      visible: true,
    }));
  };
  const callbackModal_names = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_names(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const [playerUnion, setPlayerUnion] = useState();
  useEffect(() => {
    if (!DCContext.unions || !DCContext.playerInfo?.union?.id) {
      setPlayerUnion();
      return;
    }

    //例如 退出 或 被踢出 聯盟
    if (isSelf && !DCContext.userProfile.union?.id) {
      setPlayerUnion();
      return;
    }

    let tmp = lodash_find(DCContext.unions, ['id', DCContext.playerInfo?.union?.id]);
    console.log('[Playerinfo] playerUnion', tmp);
    setPlayerUnion(tmp);
  }, [DCContext.unions, DCContext.playerInfo?.union?.id, DCContext.userProfile, isSelf]);

  const [playerNation, setPlayerNation] = useState();
  useEffect(() => {
    if (!DCContext.nations || !DCContext.playerInfo?.nation?.id) {
      setPlayerNation();
      return;
    }

    let tmp = lodash_find(DCContext.nations, ['id', DCContext.playerInfo?.nation.id]);
    console.log('[Playerinfo] playerNation', tmp);
    setPlayerNation(tmp);
  }, [DCContext.nations, DCContext.playerInfo?.nation?.id]);

  return (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      {DCContext.playerInfo && DCContext.userProfile && (
        <IbgDiv className={null} src={null} transition={true} onReady={() => {}}>
          <div className={styles.leftBox} style={{ backgroundImage: `url(${actor_halfbody_bg})` }}>
            <div className={styles.userOutfitBox}>
              <Iimg
                className={styles.userOutfit}
                src={DCContext.playerInfo?.outfit?.image}
                transition={false}
                onReady={() => {}}
              />
            </div>
            <div
              className={styles.leftBoxFg}
              style={{ backgroundImage: `url(${actor_halfbody_fg})` }}
            ></div>
          </div>

          <div className={styles.rightBox}>
            <div className={styles.dataBox}>
              <div className={styles.nationBox}>
                <Iimg
                  className={styles.nationSeal}
                  src={DCContext.playerInfo?.nation.icon}
                  transition={false}
                  onReady={() => {}}
                />
                {tt(`nation_faction`, { nation_name: playerNation?.name }, { keySuffix: false })}{' '}
                {/* playerNation?.name 陣營/勢力/Faction */}
              </div>

              <Row align="bottom" className={styles.colContentBox}>
                <Col span={24}>
                  <Row className={styles.dataRow} wrap={false} align="middle">
                    <Col span={6} className={styles.colTitle} style={{}}>
                      {tt(`player_name`) /* 玩家名稱 */}
                    </Col>
                    <Col span={2} className={styles.colCircleCheck}>
                      {DCContext.playerInfo?.contact && (
                        <img src={icon_clover} className={styles.circle_check} />
                      )}
                    </Col>
                    <Col flex="auto" className={styles.colContent}>
                      {isSelf ? (
                        <>
                          <div className={styles.inputBox}>
                            {DCContext.playerInfo?.nickname}
                            <ClickEffect
                              enabled={true}
                              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                              onClick={e => {
                                showModal_names();
                              }}
                            >
                              <img className={styles.editBtnImg} src={icon_pen} />
                            </ClickEffect>
                          </div>
                          <div className={styles.localeText}>
                            {iConfig.locales[DCContext.locale].short}
                          </div>
                        </>
                      ) : (
                        <>
                          {DCContext.playerInfo?.nickname}
                          <div className={styles.localeText}>
                            {iConfig.locales[DCContext.playerInfo?.locale].short}
                          </div>
                        </>
                      )}
                    </Col>
                  </Row>
                  <Row className={styles.dataRow} wrap={false} align="middle">
                    <Col span={6} className={styles.colTitle}>
                      {tt(`cell_name`) /* 組織名稱 */}
                    </Col>
                    <Col span={2}>&nbsp;</Col>
                    <Col flex="auto" className={styles.colContent}>
                      {isSelf ? (
                        <div className={styles.inputBox}>
                          {DCContext.playerInfo?.organization}
                          <ClickEffect
                            enabled={true}
                            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                            onClick={e => {
                              showModal_names();
                            }}
                          >
                            <img className={styles.editBtnImg} src={icon_pen} />
                          </ClickEffect>
                        </div>
                      ) : (
                        DCContext.playerInfo?.organization
                      )}
                    </Col>
                  </Row>
                  <Row wrap={false} align="middle">
                    <Col span={6} className={styles.colTitle}>
                      {tt(`player_id`) /* 玩家ID */}
                    </Col>
                    <Col span={2}>&nbsp;</Col>
                    <Col flex="auto" className={`${styles.colContent} ${styles.playerId}`}>
                      {DCContext.playerInfo?.id}
                      <ClickEffect
                        enabled={true}
                        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                        onClick={e => {
                          navigator.clipboard.writeText(DCContext.playerInfo?.id);
                        }}
                      >
                        <img className={styles.icon_copy} src={icon_copy} />
                      </ClickEffect>
                    </Col>
                  </Row>
                  <Row wrap={false} align="middle">
                    <Col span={6} className={styles.colTitle}>
                      {tt(`level`) /* 等級 */}
                    </Col>
                    <Col span={2}></Col>
                    <Col flex="auto" className={styles.colContent}>
                      <div className={styles.levelBox}>
                        <div className={styles.levelText}>
                          Lv{' '}
                          <div className={styles.levelTextNumber}>
                            {DCContext.playerInfo?.level}
                          </div>
                        </div>
                        <div className={styles.levelBarBox}>
                          <div className={styles.levelBarText}>
                            {DCContext.playerInfo.skill} / {DCContext.playerInfo.skill_required}
                          </div>
                          <div className={styles.levelBarOutline}>
                            <div
                              className={styles.levelBarInline}
                              style={{
                                width: `${
                                  (DCContext.playerInfo.skill /
                                    DCContext.playerInfo.skill_required) *
                                  100
                                }%`,
                              }}
                            ></div>
                          </div>
                        </div>
                      </div>
                    </Col>
                  </Row>
                  <Row wrap={false} align="middle">
                    <Col span={6} className={styles.colTitle}>
                      {
                        tt(
                          `union_type`,
                          {},
                          { keySuffix: true, unionId: DCContext.playerInfo.union?.id },
                        ) /* 聯盟||派系 */
                      }
                    </Col>
                    <ClickEffect
                      enabled={playerUnion ? true : false}
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={e => {
                        showUnionInfo();
                      }}
                    >
                      <Col span={2} className={styles.colCircleCheck}>
                        {playerUnion && (
                          <img src={icon_circle_check_green} className={styles.circle_check} />
                        )}
                      </Col>
                    </ClickEffect>
                    <ClickEffect
                      enabled={playerUnion ? true : false}
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={e => {
                        showUnionInfo();
                      }}
                    >
                      <Col flex="auto" className={`${styles.colContent} ${styles.unionName}`}>
                        {playerUnion?.name}
                      </Col>
                    </ClickEffect>
                  </Row>
                  <UwPlayerLocation />
                </Col>
              </Row>

              <div className={styles.actorTeamTitle}>
                {tt(`frequently_used_formation`) /* 常用編隊 */}
              </div>
            </div>

            <div className={styles.actorsBox}>
              {[...Array(5)].map((x, idx) => {
                //let i = 4-idx;
                let tmpActor = actors[4 - idx];
                //console.log('cccccc', idx, tmpActor);

                return (
                  <div
                    key={tmpActor ? tmpActor.id : idx}
                    className={styles.actorBox}
                    style={{ order: idx }}
                  >
                    <div
                      className={styles.actorThumbnail}
                      style={{ backgroundImage: `url(${actor_head_bg})` }}
                    >
                      {tmpActor && (
                        <Iimg
                          className={null}
                          src={tmpActor?.head_image}
                          transition={false}
                          onReady={() => {}}
                        />
                      )}
                      <div
                        className={styles.actorThumbnailFg}
                        style={{ backgroundImage: `url(${actor_head_fg})` }}
                      ></div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {DCContext.playerInfo?.medal && (
            <>
              {/* 客戶要求不管是誰的玩家資料，點擊牌位都可開啟自己牌位畫面 */}
              <ClickEffect
                enabled={isSelf ? true : true}
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={e => {
                  DCContext.clearOverlay(); //可能由排行榜點開後再導回牌位
                  //
                  navigate(`unionmedals`);
                  props.callback();
                }}
              >
                <div className={styles.goldmedalBox}>
                  {/* <img className={styles.bgMedalShadow} src={bgMedalShadow}/> */}
                  <Iimg
                    className={styles.goldmedal}
                    src={DCContext.playerInfo?.medal.image}
                    transition={false}
                    onReady={() => {}}
                  />
                  <div className={styles.goldmedalText}>{DCContext.playerInfo?.medal.name}</div>
                </div>
              </ClickEffect>
            </>
          )}

          {isSelf && (
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                goChangeUserImage();
              }}
            >
              <img src={iconChange} className={styles.iconChange} />
            </ClickEffect>
          )}

          <UwWorkstationsButton />

          {/* modal 外部按鈕 */}
          {/* <div className={styles.outBoxTop}>
        <div className={styles.outBtnL}>
          <img src={icon_unionQuit} className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}/>
          test
        </div>
        <div className={styles.outBtnR}>
          聯盟頻道
          <img src={icon_unionChannel} className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}/>
        </div>
      </div> */}

          {isSelf && (
            <div className={styles.outBoxBottom}>
              <div className={styles.outBtnL}>
                {/* {DCContext.playerInfo?.union && (
            <>
            <img src={icon_unionQuit} className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`} />
            </>
          )} */}
              </div>
              <div className={styles.outBtnR}>
                {/* 永久刪除帳號 */}
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    delAccountBtnClick();
                  }}
                >
                  <div className={styles.outBtnGroup}>
                    <div className={styles.outBtnText}>
                      {
                        delAccountBtnClicks >= 1
                          ? tt(`p_info_delete_permanent`) /* 永久刪除當前遊戲資料？ */
                          : tt(`delete_account`) //刪除帳號
                      }
                    </div>
                    <div className={`${styles.outBtnIconBox}`}>
                      <img
                        src={iconTrash}
                        className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}
                      />
                    </div>
                  </div>
                </ClickEffect>
              </div>
            </div>
          )}

          {DCContext.playerInfo?.contact && (
            <div className={styles.outBoxBottom}>
              {/* 解除聯絡人 */}
              <div className={styles.outBtnL}>
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickRetractContact();
                  }}
                >
                  <div className={styles.outBtnGroup}>
                    <div className={`${styles.outBtnIconBox}`}>
                      <img
                        src={icon_unionFire}
                        className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
                      />
                    </div>
                    <div className={styles.outBtnText}>
                      {
                        retractContactClicks >= 1 &&
                          tt(`contact_remove_confirm`) /* 希望解除聯絡人？ */
                      }
                    </div>
                  </div>
                </ClickEffect>
              </div>
              {/* 發送訊息 */}
              <div className={styles.outBtnR}>
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickSendMessage();
                  }}
                >
                  <div className={styles.outBtnGroup}>
                    <div className={styles.outBtnText}>{tt(`message_send`) /* 發送訊息 */}</div>
                    <div className={`${styles.outBtnIconBox}`}>
                      <img
                        src={icon_dialog}
                        className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}
                      />
                    </div>
                  </div>
                </ClickEffect>
              </div>
            </div>
          )}

          {!isSelf && DCContext.playerInfo?.can_add_contact && (
            <div className={styles.outBoxBottom}>
              <div className={styles.outBtnL}>
                {/* <ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e)=>{ clickRejectContact() }}>
          <img src={icon_unionFire} className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`} />
          </ClickEffect>
          {retractContactClicks>=1 && (`希望解除聯絡人？`)} */}
              </div>
              <div className={styles.outBtnR}>
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickAddContact();
                  }}
                >
                  <div className={styles.outBtnGroup}>
                    <div className={styles.outBtnText}>{tt(`contact_add`) /* 加入聯絡人 */}</div>
                    <div className={`${styles.outBtnIconBox}`}>
                      <img
                        src={icon_dialog}
                        className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}
                      />
                    </div>
                  </div>
                </ClickEffect>
              </div>
            </div>
          )}

          <Imodal {...modalProps_AccountDel} callback={callbackModal_AccountDel}>
            <AccountDel />
          </Imodal>

          <Imodal {...modalProps_names} callback={callbackModal_names}>
            <Names mode={`EDIT`} callback={callbackModal_names} />
          </Imodal>
        </IbgDiv>
      )}
    </div>
  );
};
