import React, { useEffect, useRef } from 'react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useI18n } from 'lib/useI18n';
import { Teams } from 'component/Teams';
import { IbgDiv } from 'componentx/IbgDiv';
import { Navigator } from 'component/modal/Navigator';
import background from 'assets/img/bgClockSilver.png';
import styles from 'pages/unionbattle/Unionteams.module.scss';

/*
 * UW 選隊派遣介面。沿用實戰選隊的公版 UI (component/Teams，與
 * #/user/teams/nationbattleselect 相同)，依 mode 分派兩種用途：
 *
 *   mode="uwdeploy" — 工作站建造 / 升級 (規格 p.15-16)
 *     點「派遣」→ workstation_deploy {site_id, team_id}，成功後回城內介面
 *     (後端於 workstations 新增資料、原按鍵轉 (2) 狀態)。
 *     動員力不足 / 編隊已派遣 / 已達 20 上限 → 阻擋提示，停留本頁。
 *     進入狀態 (location.state)：{ site_id, city_id, cityName, mediaNeed, siteLevel }
 *
 *   mode="uwplot"   — 副本 Visit / Explore (規格 pp.18-22)
 *     點「派遣」→ uw_start_plot {site_id, team_id}；後端此時才正式扣除
 *     sites.energy_charge 並抽劇情，成功後進劇情畫面 (副本沒有戰鬥，劇情播完
 *     或跳過即結算)。能量不足 → 比照攻城跳「能量不足，是否補充能量？」。
 *     進入狀態 (location.state)：{ site_id, city_id, cityName, siteName, energyCharge }
 *
 * 兩種用途共用背景音樂 cities.uw_music (而非 battleMusic)。
 */
export const UwTeams = props => {
  const { tt } = useI18n();
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  const navigate = useNavigate();
  const location = useLocation();
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;

  const mode = props.mode || 'uwdeploy';
  const isPlot = mode === 'uwplot';
  const event = isPlot ? 'uw_start_plot' : 'workstation_deploy';

  const st = location.state || {};
  const topic = DCContext?.playerChannelTopic;
  const city =
    DCContext?.cities && st.city_id != null ? DCContext.getCityDataById(st.city_id) : null;

  // 回城內介面 (帶回原本 cityId / cityName)。
  const backToCity = () =>
    navigate('/attacks/uwtown', {
      state: { cityId: st.city_id, cityName: st.cityName },
    });

  // 背景音樂：cities.uw_music (規格 p.16)
  useEffect(() => {
    if (city?.uw_music && DCContext?.playMusic) DCContext.playMusic(city.uw_music);
  }, [city?.uw_music]); // eslint-disable-line react-hooks/exhaustive-deps

  // 本次進入選隊畫面後，玩家是否真的按過「派遣」。
  // uwPlotR 存在 localStorage，會一直留著上一次副本抽到的劇情；下面導頁的 effect 在
  // mount 時也會跑一次，沒有這道旗標的話，第二次以後一進選隊畫面就會被舊的 uwPlotR
  // 立刻導去劇情頁 —— 不經選隊、不送 uw_start_plot、不扣能量，而且每次都播同一段劇情
  // (看起來像「機率壞掉、結局固定」)，直到登出清掉 localStorage 才會恢復。
  const startedRef = useRef(false);

  // 派遣 (出戰鍵)
  const clickFightCallback = ({ team_id = 0 } = {}) => {
    if (!topic || !st.site_id || !team_id) return;

    if (isPlot) {
      startedRef.current = true;
      DCContext.uwStartPlot({ site_id: st.site_id, team_id });
      return;
    }

    ChannelContext.sendMessage({
      topic,
      event,
      message: { site_id: st.site_id, team_id },
    });
  };

  // 副本成功：等 DCContext 把抽到的劇情寫進 uwPlotR / slides 之後才進劇情畫面。
  // (不在 sendMessageRes 當下就導頁 —— 子元件的 effect 比 provider 的先跑，劇情頁會
  //  先讀到還沒更新的 uwPlotR，閃出上一次的劇情。)
  useEffect(() => {
    if (!isPlot) return;
    // 只認「本次派遣」抽到的劇情 —— 否則 mount 時會直接吃到 localStorage 裡的舊結果。
    if (!startedRef.current) return;
    if (!DCContext.uwPlotR?.site_plot_id) return;
    if (String(DCContext.uwPlotR.site_id) !== String(st.site_id)) return;

    navigate(`/story/uw_plot/${st.site_id}`);
  }, [DCContext.uwPlotR]); // eslint-disable-line react-hooks/exhaustive-deps

  // 回覆：
  //   uwdeploy ok → 回城內介面
  //   錯誤 → 阻擋提示，停留本頁；能量不足另外導向補充能量視窗。
  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic || r.event !== event) return;

    if (r.res?.status === 'ok') {
      DCContext.getProfile && DCContext.getProfile(true); // 更新 media/energy

      if (!isPlot) {
        backToCity();
      }
      return;
    }

    const p = r.res?.error || r.res?.payload || {};

    if (p.energy_boost_options) {
      // 能量不足：比照攻城 (Attackteams) —— 確認後開補充能量視窗，停留本頁。
      DCContext.setShowConfirmModal({
        confirm: {
          message: { i18nKey: 'replenish_energy_confirm' },
          buttons: [
            {
              text: { i18nKey: 'confirm' },
              callback: () => {
                DCContext.setShowConfirmModal();
                DCContext.showEnergyboostModal();
              },
            },
          ],
        },
      });
      return;
    }

    DCContext.setShowConfirmModal({
      confirm: {
        message: p.message || tt(`uw_deploy_failed`) /* 派遣失敗，請稍後再試。 */,
        buttons: [
          {
            text: { i18nKey: 'confirm' },
            callback: () => DCContext.setShowConfirmModal(),
          },
        ],
      },
    });
  }, [ChannelContext.sendMessageRes]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams
        mode={mode}
        catKey={'Union'}
        showFightBtn={true}
        teamIdx={teamIdx}
        clickFightCallback={clickFightCallback}
      />

      <Navigator navi={{ back: { callback: backToCity } }} />
    </IbgDiv>
  );
};
