import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Actorpoolsrecord.module.scss';
import background from 'assets/img/sv01.jpg';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { ClickEffect } from 'componentx/ClickEffect';

//
import bgClock from 'assets/img2/bgClock.png';
//import left_gold from 'assets/img/icon_left_gold.png';
//import right_gold from 'assets/img/icon_right_gold.png';
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';

//
import bgLight from 'assets/img2/bgLight.gif';

import bg_record_golden from 'assets/img2/actor_pools/bg_record_golden.png';
import bg_record_silver from 'assets/img2/actor_pools/bg_record_silver.png';

export const Actorpoolsrecord = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [showInfoType, setShowInfoType] = useState(2);
  const [records, setRecords] = useState({});

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Actorpoolsrecord] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Actorpoolsrecord] channel player 未連線');
      return;
    }

    console.log('[Actorpoolsrecord] channel player 已連線');
    DCContext.getUsed_recruit_coupons();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.used_recruit_coupons) {
      return;
    }

    console.log(
      '[Actorpoolsrecord] DCContext.used_recruit_coupons',
      DCContext.used_recruit_coupons,
    );

    let tmp = {};
    DCContext.used_recruit_coupons.map((item, idx) => {
      if (!tmp[item.recruit_sequence]) {
        tmp[item.recruit_sequence] = {
          recruit_sequence: item.recruit_sequence,
          updated_at: item.updated_at,
          characters: [],
        };
      }

      tmp[item.recruit_sequence].characters.push(item);
    });

    tmp = lodash_orderBy(tmp, ['updated_at'], ['desc']);
    console.log('[Actorpoolsrecord] DCContext.used_recruit_coupons', tmp);

    setRecords(tmp);
  }, [DCContext.used_recruit_coupons]);

  /* */

  const changeInfoType = t => {
    if (t == 2) {
      navigate(`/actorpools/record`);
    } else {
      navigate(`/actorpools`);
    }
  };

  const aniStyles_moveup = useSpring(iConfig.aniStyles_moveup);

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox} style={{ backgroundImage: `url(${bgClock})` }}>
        <div className={styles.bgLightBox} style={{ backgroundImage: `url(${bgLight})` }}></div>

        <animated.div className={styles.contentOutBox} style={{ ...aniStyles_moveup }}>
          {Object.values(records).map((item, idx) => {
            return item.characters.length > 1 ? (
              <ItemMultiCharacters key={idx} data={item} />
            ) : (
              <ItemSingleCharacter key={idx} data={item} />
            );
          })}
        </animated.div>

        <div className={`tabBar`}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(1);
            }}
          >
            <div className={`tab ${showInfoType == 1 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`recruitment`) /* 招募 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(2);
            }}
          >
            <div className={`tab ${showInfoType == 2 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`recruit_history`) /* 歷程 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 3 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            >
              <div className={`tabText1`}></div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 4 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            ></div>
          </ClickEffect>
        </div>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />
    </IbgDiv>
  );
};

const ItemSingleCharacter = props => {
  /* i18n */
  const { tt } = useI18n();
  const isPiece =
    props.data.characters[0].actor_piece || props.data.characters[0].wild_card_piece ? true : false;

  return (
    <div className={styles.itemOutBox} style={{ backgroundImage: `url(${bg_record_silver})` }}>
      <div className={styles.itemBoxLeft}>
        <div className={styles.itemBoxLeftBody}>
          <div className={`${styles.itemBodyLeft}`}>
            {!isPiece && <div className={styles.shadow}></div>}
            {props.data.characters[0].name}
          </div>
          <div className={styles.characterHalfBody}>
            <IbgDiv
              className={`${styles.characterHalfBodyImg} ${isPiece ? styles.piece : ''}`}
              src={props.data.characters[0].image}
              transition={false}
              onReady={() => {}}
            ></IbgDiv>
          </div>
          <div className={`${styles.itemBodyRight}`}>
            {!isPiece && <div className={styles.shadow}></div>}
            {props.data.characters[0].scarcity}
          </div>
        </div>
      </div>
      <div className={styles.itemBoxRight}>
        <div className={styles.recordType}>{tt(`recruitment`) /* 招募 */}</div>
        <div className={styles.recordDate}>
          {moment.utc(props.data.updated_at).local().format('YYYY.MM.DD HH:mm')}
        </div>
      </div>
    </div>
  );
};

const ItemMultiCharacters = props => {
  /* i18n */
  const { tt } = useI18n();
  //

  return (
    <div className={styles.itemOutBox} style={{ backgroundImage: `url(${bg_record_golden})` }}>
      <div className={styles.itemBoxLeft}>
        <div className={styles.itemBoxLeftBody}>
          {props.data.characters.map((item, idx) => {
            return (
              <div className={styles.characterHead}>
                <IbgDiv
                  className={styles.characterHeadImg}
                  src={item.image}
                  transition={false}
                  onReady={() => {}}
                ></IbgDiv>
              </div>
            );
          })}
        </div>
      </div>
      <div className={styles.itemBoxRight}>
        <div className={styles.recordType}>{tt(`recruit_10_actors`) /* 招募10次 */}</div>{' '}
        {/* {props.data.characters.length} */}
        <div className={styles.recordDate}>
          {moment.utc(props.data.updated_at).local().format('YYYY.MM.DD HH:mm')}
        </div>
      </div>
    </div>
  );
};
