import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  find as lodash_find,
  findIndex as lodash_findIndex,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { ClickEffect } from 'componentx/ClickEffect';

//
import iConfig from 'iConfig';
import styles from './MedalTypeSwitcher.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { IbgDiv } from 'componentx/IbgDiv';
//
import iconChange from 'assets/img/iconChange.png';

export const MedalTypeSwitcher = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [catIdx, setCatIdx] = useState();

  useEffect(() => {
    if (!props.catKey || !DCContext.medalTypes) {
      return;
    }

    let tmpIdx = lodash_findIndex(DCContext.medalTypes, { key: props.catKey });

    if (tmpIdx === -1) {
      tmpIdx = 0;
    }

    console.log('[MedalTypeSwitcher] tmpIdx', props.catKey, tmpIdx);

    setCatIdx(tmpIdx);
  }, [props.catKey, DCContext.medalTypes]);

  useEffect(() => {
    if (catIdx == undefined) {
      return;
    }

    console.log(`[MedalTypeSwitcher] catIdx`, catIdx);
  }, [catIdx]);

  const changeCat = p => {
    let newIdx = catIdx + p;
    if (newIdx >= DCContext.medalTypes.length) {
      newIdx = 0;
    }

    console.log(`[MedalTypeSwitcher] changeCat A`, catIdx, newIdx);
    console.log(`[MedalTypeSwitcher] changeCat B`, DCContext.medalTypes?.[newIdx]?.key);

    if (props.callback_catKey) {
      props.callback_catKey(DCContext.medalTypes?.[newIdx]?.key);
    }
  };

  return catIdx == undefined ? (
    <></>
  ) : (
    <div className={styles.medalTypeSwitcherBox}>
      <div>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            changeCat(1);
          }}
        >
          <img className={styles.medalChangeIcon} src={iconChange} />
        </ClickEffect>
      </div>

      <IbgDiv
        className={styles.medalTypeIconBox}
        src={DCContext.medalTypes?.[catIdx]?.icon}
        transition={false}
        onReady={() => {}}
      ></IbgDiv>
    </div>
  );
};
