/*
i18nKey: recommend_unions_U || recommend_unions_R
<Itrans i18nKey={`recommend_unions`} keySuffix={true} values={{}}/>

欄位必填
<Itrans i18nKey={`form_field_required`} values={{field_name: tt(`your_character_name`)}}/> //角色名稱為必填
*/

import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
//
import { useDCContext } from 'lib/DCContext';

export const useI18n = () => {
  /* i18n */
  const { t, i18n, ready } = useTranslation();
  //
  const DCContext = useDCContext();

  //keySuffix: 紅軍/非紅軍陣營 兩邊詞句差異大而分開成兩個詞句的情況
  const tt = (i18nKey = '', values = {}, options = { keySuffix: false, unionId: undefined }) => {
    if (!values) {
      values = {};
    }

    // if (!options){
    //   options = {
    //     keySuffix: false,
    //     unionTypeBy: {
    //       type: undefined, //nation || union
    //       id: undefined //nation.id || union.id
    //     }
    //   };
    // }

    //判別陣營
    let theNationId;
    if (options?.unionId) {
      //指定陣營
      let union = lodash_find(DCContext.unions, { id: options.unionId });
      //console.log("[useI18n] [tt] union", union);
      theNationId = union?.nation?.id;
      //console.log(`[useI18n] [tt] <${i18nKey}> nation A`, theNationId);
    } else if (DCContext.userProfile?.union?.nation?.id) {
      //玩家所屬聯盟所屬陣營
      theNationId = DCContext.userProfile?.union?.nation?.id;
      //console.log(`[useI18n] [tt] <${i18nKey}> nation B`, theNationId);
    } else if (DCContext.userProfile?.nation?.id) {
      //玩家所屬陣營
      theNationId = DCContext.userProfile?.nation?.id;
      //console.log(`[useI18n] [tt] <${i18nKey}> nation C`, theNationId);
    }

    //詞句 key
    let newI18nKey = i18nKey;
    //紅軍/非紅軍陣營 分成兩個詞句 key
    if (options?.keySuffix) {
      if (!theNationId) {
        return;
      }
      newI18nKey = `${i18nKey}_${theNationId == 1 ? 'R' : 'U'}`;
      //console.log(`[useI18n] [tt] <${i18nKey}> [keySuffix]`, i18nKey, newI18nKey);
    }

    //替換詞中主動加入 union_type: 聯盟||派系，只要語詞 key 中帶有 union_type 一律置換
    let newValues = values;
    if (theNationId) {
      newValues.union_type = t(`union_type_${theNationId == 1 ? 'R' : 'U'}`);
      //console.log(`[useI18n] [tt] <${i18nKey}> newValues`, newValues);
    }

    const result = t(newI18nKey, newValues);
    //console.log(`[useI18n] [tt] <${i18nKey}> result`, newI18nKey, result);

    return result;
  };

  const ttValue = (value = '') => {
    if (typeof value === 'object' && value !== null) {
      return value[DCContext.locale];
    }

    return value;
  };

  return { tt, ttValue };
};

export const Itrans = ({ i18nKey, keySuffix, values, ...props }) => {
  const DCContext = useDCContext();
  /* i18n */
  const { tt } = useI18n();

  const newI18nKey = keySuffix ? `${i18nKey}_${DCContext.localeKeys.faction}` : i18nKey;

  const newValues = {
    union_type: tt(DCContext.localeKeys.union_type),
    ...values,
  };

  //console.log(`[useI18n] [Itrans]`, newI18nKey, newValues);

  return (
    <Trans
      i18nKey={newI18nKey}
      {...props}
      //i18nKey={`p_h_new_contact_requests`}
      //defaults="hello <italic>beautiful</italic> <bold>{{what}}</bold>" // optional defaultValue
      values={newValues}
      //components={{ italic: <i />, bold: <strong /> }}
    />
  );
};
