import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
//import { useGameDataContext } from "lib/GameDataContext";
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './PvpResult.module.scss';
import { Imodal } from 'componentx/Imodal';
//
import { Navigator } from 'component/modal/Navigator';
import { Medals } from 'component/Medals';
//
import bgMissionBigVictory from 'assets/img2/bgMissionBigVictory.png';
import bgMissionTinyVictory from 'assets/img2/bgMissionTinyVictory.png';
import bgMissionFail from 'assets/img2/bgMissionFail.png';
import bgMissionFailChain from 'assets/img2/bgMissionFailChain.png';

export const PvpResult = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  //
  let navigate = useNavigate();
  const location = useLocation();
  //
  let { battle_type } = useParams();
  battle_type = battle_type || '1v1';
  //console.log("[PvpResult] battle_type", battle_type);

  const [victoryStatusData, setVictoryStatusData] = useState();
  const [showMedals, setShowMedals] = useState(true);

  //
  const VictoryStatusCfg = {
    /* 攻擊結果不會有 -1 的狀況
    "-1": {
      text: "未攻擊過",
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain
    },
    */
    0: {
      text: tt(`close_defeat`) /*惜敗*/,
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain,
      win: false,
    },
    1: {
      text: tt(`close_victory`) /*險勝*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
      win: true,
    },
    2: {
      text: tt(`victory`) /*勝利*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
      win: true,
    },
    3: {
      text: tt(`total_victory`) /*大獲全勝*/,
      bgImg: bgMissionBigVictory,
      fgImg: null,
      win: true,
    },
  };

  useEffect(() => {
    console.log(`[PvpResult] location.state`, location.state);
  }, []);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[PvpResult] channel player 未連線');
      return;
    }

    console.log('[PvpResult] channel player 已連線 battle_type', battle_type);

    //DCContext.getMedals({previous_record: battle_type}); // '1v1' || '3v3'
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.medals) {
      return;
    }

    console.log('[PvpResult] DCContext.medals', DCContext.medals);

    if (DCContext.medals.previous_record[battle_type]) {
      let score = DCContext.medals[battle_type].score;
      let preScore = DCContext.medals.previous_record[battle_type].score;
      let diffScore = parseInt(score - preScore);

      console.log('[PvpResult] scores', score, preScore, diffScore);

      if (diffScore > 100) {
        setVictoryStatusData(VictoryStatusCfg[3]); //大獲全勝
      } else if (diffScore > 0) {
        setVictoryStatusData(VictoryStatusCfg[2]); //勝利
      } else {
        setVictoryStatusData(VictoryStatusCfg[0]); //惜敗
      }
    }

    //勝利或失敗音效
    // if (DCContext.attackResult.sound_effect){
    //   //console.log("[PvpResult] DCContext.playSound", DCContext.attackResult.sound_effect);
    //   DCContext.playSound(DCContext.attackResult.sound_effect);
    // }
  }, [DCContext.medals]);

  useEffect(() => {
    if (!victoryStatusData) {
      return;
    }

    console.log('[PvpResult] victoryStatusData, location.state', victoryStatusData, location.state);

    //勝利或失敗音效
    DCContext.pauseMusic();
    if (victoryStatusData.win) {
      DCContext.playSound(location.state.pvpChannelStatus.sound_effect.win, () => {
        DCContext.playMusic(`${DCContext.userProfile.music}`);
      });
    } else {
      DCContext.playSound(location.state.pvpChannelStatus.sound_effect.lose, () => {
        DCContext.playMusic(`${DCContext.userProfile.music}`);
      });
    }
  }, [victoryStatusData?.text]);

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox} style={{}}>
        {/* <div className={styles.pageBox}>
          <div className={styles.bgBox}>
            <img className={styles.bgImg} src={victoryStatusData?.bgImg}/>
            <img className={styles.bgImg_chain} src={victoryStatusData?.fgImg}/>
          </div>

          <div className={styles.clickSensorBox} onClick={()=>{ setShowMedals(true) }}>
            <div className={`${styles.resultTitleBox} ${styles.middle}`}>{victoryStatusData?.text}</div>
          </div>
        </div> */}

        {showMedals && (
          <div className={styles.pageBox} style={{ zIndex: 30 }}>
            <Medals
              catKey={battle_type == '3v3' ? '3v3' : '1v1'}
              getPreviousRecord={battle_type == '3v3' ? 'after_3v3' : 'after_1v1'}
              style={{ zIndex: 30 }}
            />
          </div>
        )}
      </div>

      {/* <Navigator navi={{
        back: {
          spot: "home",
          show: false
        }
      }}/> */}
    </div>
  );
};
