import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal, Popover } from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import { Imodal } from 'componentx/Imodal';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Attackcondition.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnRing } from 'component/BtnRing';
//
import bgMissionStatus_fail from 'assets/img/tmp/bgMissionStatus/bgMissionStatus_fail.png';
import bgMissionStatus_chain from 'assets/img/tmp/bgMissionStatus/bgMissionStatus_chain.png';
//
import iconEnergyPlus from 'assets/img/iconEnergyPlus.png';
import bgMissionUnlock from 'assets/img/attacks/bgMissionUnlock.png';
import bgChapter from 'assets/img/attacks/bgChapter.png';
import circleGolden from 'assets/img/circleGolden.png';
import bgPrizesBar from 'assets/img/tmp/bgMissionStatus/bgPrizesBar.png';
import bgPropsHole_w from 'assets/img/bgPropsHole_w.png';
import bgPropsHole from 'assets/img/bgPropsHole.png';
//
import wsv01 from 'assets/img/tmp/wsv01.png';
import mattest01 from 'assets/img/props/mattest01.png';
//
import { Navigator } from 'component/modal/Navigator';
//
import bgMissionBigVictory from 'assets/img2/bgMissionBigVictory.png';
import bgMissionTinyVictory from 'assets/img2/bgMissionTinyVictory.png';
import bgMissionFail from 'assets/img2/bgMissionFail.png';
import bgMissionFailChain from 'assets/img2/bgMissionFailChain.png';
//
import icon_seal_achieved from 'assets/img2/icon_seal_achieved.png';

export const Attackcondition = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [city, setCity] = useState();
  const [victoryStatusData, setVictoryStatusData] = useState();
  const [spoils, setSpoils] = useState(); //合併組合包後戰利品

  //
  let { actionId } = useParams();
  actionId = parseInt(actionId) || 0;
  console.log('[Attackcondition] useParams: ', actionId);

  //city.spoil_reference 會維持最大值，險勝後再打失敗不會降為 0
  const VictoryStatusCfg = {
    // "-2": { //尚不能攻打城鎮，目前用不到
    //   text:  '',
    //   bgImg: '',
    //   fgImg: ''
    // },
    '-1': {
      //可攻打未攻打過
      text: tt(`not_yet_finished`) /*未完成*/,
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain,
    },
    0: {
      //攻打過但尚未成功
      text: tt(`not_yet_finished`) /*未完成*/,
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain,
    },
    1: {
      text: tt(`close_victory`) /*險勝*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
    },
    2: {
      text: tt(`victory`) /*勝利*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
    },
    3: {
      text: tt(`total_victory`) /*大獲全勝*/,
      bgImg: bgMissionBigVictory,
      fgImg: null,
    },
  };

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Attackcondition] playMusic');
    //DCContext.playMusic(`${DCContext.userProfile.music}`);
    DCContext.playMusic(iConfig.battleMusic);
  }, [DCContext.userProfile]);

  // Sweep (new_attack with battle: false) resolves immediately without entering
  // the normal team/round flow. Forward its result to the shared result page.
  useEffect(() => {
    const response = DCContext.msgRes?.[`${DCContext.playerChannelTopic},new_attack`]?.res;
    if (!response) return;

    DCContext.setMsgRes(previous => {
      const next = { ...previous };
      delete next[`${DCContext.playerChannelTopic},new_attack`];
      return next;
    });

    // 只有掃蕩會回「attack 物件」；一般戰鬥的 round_to_map 也有 attack 這個 key，
    // 但值是 attack_id (整數)，不能拿來當掃蕩結果 (見 DCContext new_attack 的說明)。
    const attackPayload = response.payload?.attack;
    if (response.status === 'ok' && attackPayload && typeof attackPayload === 'object') {
      DCContext.setAttackResult({ ...attackPayload, sweep: true });
      // replace：掃蕩的結果頁不留在 history。本頁的 <Navigator /> 用預設的 back = -1
      // (瀏覽器上一頁)，若這裡 push，結算完回到本頁後按返回會退回結果頁而顯示戰敗版面
      // (回報)。Attackresult.goNext 導回本頁時同樣用 replace，兩邊要一致。
      navigate('/attacks/attackresult', { replace: true });
    } else if (response.status === 'error') {
      DCContext.setShowConfirmModal({
        confirm: {
          message: response.error?.message || response.message || tt('error'),
          buttons: [
            { text: { i18nKey: 'confirm' }, callback: () => DCContext.setShowConfirmModal() },
          ],
        },
      });
    }
  }, [DCContext.msgRes?.[`${DCContext.playerChannelTopic},new_attack`]?.uuid]);

  // 註：這裡原本還有一個「看到 attackResult.sweep 就 navigate 到結果頁」的 effect，已移除。
  // attackResult 是 useLocalStorage，掃蕩完不會自己消失，那個 effect 於是在「任何城鎮」的
  // 任務頁掛載時都會命中舊值，把玩家彈到掃蕩獎勵頁 (回報：所有城的任務鍵都跳掃蕩獎勵)。
  // 上面那個 effect 已經在收到 new_attack 回覆的當下就導頁，不需要再靠共用 state 觸發。

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Attackcondition] channel player 斷線');
      return;
    }

    console.log('[Attackcondition] channel player 已連線');
    ///DCContext.getCities();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.cities) {
      return;
    }

    let tmp = DCContext.getCityDataById(actionId);
    console.log('[Attackcondition] city', tmp);

    setCity(tmp);
    setVictoryStatusData(VictoryStatusCfg[tmp.spoil_reference]);

    //合併戰利品
    //更改格式，不需合併
    // let tmpSpoils = DCContext.combineCityspoils(tmp.city_spoils);
    // console.log("[Attackcondition] tmpSpoils", tmpSpoils);
    // setSpoils(tmpSpoils);

    console.log('[Attackcondition] city_spoils', tmp.city_spoils);
    setSpoils(tmp.city_spoils);
  }, [DCContext.cities]);

  const showEnergyboost = () => {
    DCContext.showEnergyboostModal();
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox} style={{}}>
        <div className={styles.bgBox}>
          <img className={styles.bgImg} src={victoryStatusData?.bgImg} />
          <img className={styles.bgImg_chain} src={victoryStatusData?.fgImg} />
        </div>

        <div className={styles.leftBox}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={e => {
              showEnergyboost();
            }}
          >
            <div className={styles.foundsBox}>
              <img className={styles.itemIcon} src={iconEnergyPlus} />
              <div className={styles.itemText}>
                {/* {city?.energy_charge}/{DCContext.userProfile?.energy} */}
                {DCContext.userProfile?.energy}{' '}
                <span style={{ color: '#60c0bd' }}>(-{city?.energy_charge})</span> /{' '}
                {DCContext.getUser_maxEnergyByLevel()}
              </div>
            </div>
          </ClickEffect>

          <div className={styles.statusText}>{victoryStatusData?.text}</div>
          <div className={styles.missionDescription}>{city?.description}</div>
          <div className={styles.winCondition}>
            {tt(`total_victory_conditions`) /* 大獲全勝條件 */}
            <br />- {tt(`total_victory_condition_1`) /* 戰鬥開始後3分鐘內獲勝。 */}
            <br />- {tt(`total_victory_condition_2`) /*沒有任何幹部倒下。*/}
            <br />- {tt(`total_victory_condition_3`) /*單一幹部擊倒至少5名敵人。*/}
          </div>
        </div>

        <div className={styles.rightBox}>
          <div className={styles.cityTitle}>
            <div className={styles.cityName}>{city?.name}</div>
          </div>

          <div className={styles.city_point_description}>{/*city?.point_description*/}</div>
          <Iimg
            className={styles.cityImg}
            src={city?.window_view_image}
            transition={false}
            onReady={() => {}}
          />

          <div className={styles.missionNameBox}>
            <img src={bgMissionUnlock} />
            <div className={styles.missionName}>{city?.title}</div>
            <div className={styles.missionNoL}>{city?.chapter.number}</div>
            <div className={styles.missionNoR}>{city?.chapter.serial}</div>
          </div>
          <div className={styles.chapterNameBox}>
            <img src={bgChapter} />
            <div className={styles.chapterName}>{city?.chapter.name}</div>
          </div>
        </div>

        <div className={styles.btnCircleBox}>
          <BtnRing
            color="golden"
            text={tt(`start`) /* 開始 */}
            callback={() => {
              navigate(`/user/teams/attacksselect`, { state: { cityId: actionId } });
            }}
          />
        </div>

        {Number(city?.spoil_reference) === 3 && (
          <div className={styles.btnCircleBox2}>
            <BtnRing
              color="silver"
              text={tt('mission_sweep')}
              callback={() => {
                // battle: false is the server-supported no-battle/sweep path.
                DCContext.newAttack({ city_id: city.id, battle: false });
              }}
            />
          </div>
        )}

        <div className={styles.winPrizesBar} style={{ backgroundImage: `url(${bgPrizesBar})` }}>
          {/* 原本使用合併的格式 */}
          {/* {spoils?.Others && Object.keys(spoils?.Others).map((key)=>{
            let el = spoils?.Others[key];
            return (
              <div key={key} className={styles.prizeItem}>
                <img className={styles.bgPrizeItem} src={bgPropsHole_w}/>
                <Iimg className={styles.prizeImg} src={el.image} transition={false} onReady={()=>{}} />
                <div className={styles.prizeQuantity}>{el.quantity}</div>
              </div>
            );
          })} */}

          {spoils &&
            spoils.map((theSpoil, idx_0) => {
              //是否已領過且不能再領
              const collected =
                theSpoil.random == false && theSpoil.reference <= city.spoil_reference
                  ? true
                  : false;

              return theSpoil.items.map((item, idx_1) => {
                const descriptionPop = (
                  <div
                    className={`popover-description`}
                    dangerouslySetInnerHTML={{ __html: item.description }}
                  ></div>
                );

                //console.log("[Attackcondition] theSpoil.item", item);

                return (
                  <div key={`${idx_0},${idx_1}`} className={styles.prizeItem}>
                    <img
                      className={styles.bgPrizeItem}
                      src={theSpoil.random ? bgPropsHole : bgPropsHole_w}
                    />
                    <Popover
                      overlayInnerStyle={{ backgroundColor: 'unset' }}
                      content={descriptionPop}
                      title={item.name}
                      placement="rightTop"
                      trigger="click"
                      overlayClassName={styles.popOver}
                    >
                      <Iimg
                        className={styles.prizeImg}
                        src={item.image}
                        transition={false}
                        onReady={() => {}}
                      />
                    </Popover>
                    {collected && (
                      <img className={styles.icon_seal_achieved} src={icon_seal_achieved} />
                    )}
                    <div className={styles.firstTimeText}>
                      {!theSpoil.random ? tt('reward_first_time') /*首次*/ : ''}
                    </div>
                    <div className={styles.prizeQuantity}>{item.quantity}</div>
                  </div>
                );
              });
            })}
        </div>
      </div>

      {/* 返回鍵固定回大地圖，不用 Navigator 預設的 back = -1 (瀏覽器上一頁)。
          預設值會讓行為取決於「玩家怎麼走到這一頁」—— 掃蕩來回一趟就會退到結果頁而
          顯示戰敗版面 (回報)。本頁實際上只有一個入口 (Attackmap 點城鎮)，
          掃蕩返回那條已改用 replace，所以固定導向大地圖與所有既有路徑一致。
          順帶把 focus_city_id 帶回去，返回後鏡頭仍停在原本那座城。 */}
      <Navigator
        navi={{
          back: {
            url: '/attacks/attackmap',
            urlState: { focus_city_id: actionId },
          },
        }}
      />
    </div>
  );
};
