import React, { useContext, useState, useEffect, useRef } from 'react';
import { useDrag } from 'react-dnd';
import { useSpring, useSpringRef, useChain, animated, easings } from '@react-spring/web';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './SkillBall.module.scss';

export const SkillBall = props => {
  //const [ballData, setBallData] = useState(props.ballData);
  const itemRef = useRef(null);

  let elId = `skillball_${props.idx}`;

  useEffect(() => {
    //console.log("[SkillBall] mount", props.ballData.id);

    return () => {};
  }, []);

  /* dnd */

  //第一個值是 collect 返回的物件
  const [{ opacity, ...collectedProps }, dragRef] = useDrag(
    () => {
      //console.log(`[SkillBall] useDrag`, props.ballData.id);

      return {
        type: 'skill_ball', //對應 useDrop: accept
        item: {
          ballData: props.ballData, //給 preview 顯示拖動時被拖的元件
          elId: elId, //給 preview 顯示拖動時被拖的元件（用來取得寬高）
          //idx: props.idx
        },
        //收集狀態，返回陣列的第一個值
        collect: monitor => ({
          opacity: monitor.isDragging() ? 0 : 1, //被拖曳時，原位置的物件變透明
          isDragging: monitor.isDragging(),
        }),
        canDrag: monitor => {
          //console.log("[Skillball] canDrag, autoPlay", props.autoPlay);
          return !props.autoPlay;
        },
      };
    },
    [props.autoPlay, props.ballData.id], //dependency
  );
  dragRef(itemRef); //這個寫法讓我們可以同時使用 react ref 和 useDrag

  /* animation */

  const [aniStyles, aniApi] = useSpring(() => ({
    loop: false,
    from: { y: 0, opacity: 1, scale: 1 },
    to: { y: 0, opacity: 1, scale: 1 },
    config: {
      duration: 200,
    },
  }));

  //能量球資料換新時，還原 style
  useEffect(() => {
    if (!props.ballData.id) {
      return;
    }

    //console.log(`[SkillBall] ani1 ${props.idx}`, props.ballData.id);
    aniApi.start({
      to: [{ opacity: 1, scale: 1, y: 0 }],
    });
  }, [props.ballData.id]);

  useEffect(() => {
    if (!props.autoAssignBalls || !props.autoAssignBalls[props.ballData.id]) {
      return;
    }

    //console.log(`[SkillBall] ani2 ${props.idx}`, props.ballData.id);
    aniApi.start({
      to: [
        { opacity: 1, scale: 0.4, y: 0 },
        { opacity: 0.5, scale: 0.4, y: 0 },
        { opacity: 1, scale: 0.4, y: 0 },
        { opacity: 0.5, scale: 0.4, y: 0 },
        { opacity: 1, scale: 0.4, y: 0 },
        { opacity: 0, scale: 0.4, y: -900 },
      ],
    });
  }, [props.autoAssignBalls, props.ballData.id]);

  useEffect(() => {
    if (!props.ballData) {
      return;
    }

    //console.log("ballData", ballData);
  }, [props.ballData]);

  return (
    // <div id={refElemId} ref={preview} style={{ opacity: opacity }} className={styles.skillBall}>
    <div id={elId} ref={itemRef} className={styles.skillBall} style={{ opacity: opacity }}>
      {/* <div style={{color:"white"}}>{props.idx}, {props.ballData.id}</div> */}
      <Iimg
        className={styles.skillBallImg}
        style={{ ...aniStyles }}
        src={props.ballData.image}
        transition={false}
        onReady={() => {}}
      />
      {props.colorblindAssist && <div className={styles.skillBallAbbr}>{props.ballData.abbr}</div>}
      {/* <div style={{height: "20px"}}>
					{collectedProps.isDragging ? 'Dragging' : ''}
				</div> */}
    </div>
    // </div>
  );
};
