import React, { useContext, useState, useEffect, useMemo } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { ClickEffect } from 'componentx/ClickEffect';
//
import iConfig from 'iConfig';
import styles from './PortalMap.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { PopupMessagesIcon } from 'component/modal/PopupMessagesIcon';
import { UwPortalCollectButton } from 'features/underworld';
//
import portalmap from 'assets/img2/portalmap.png';
import highlightCircle from 'assets/img2/highlightCircle.png';
import icon_2swords from 'assets/img2/icon_2swords.png';
import icon_frontSight from 'assets/img2/icon_frontSight.png';
import icon_unionFlag from 'assets/img2/icon_unionFlag.png';
import icon_ingots from 'assets/img2/icon_ingots.png';

export const PortalMap = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  const navigate = useNavigate();
  const location = useLocation();
  //
  const [nationsObject, setNationsObject] = useState();
  const [citiesObject, setCitiesObject] = useState({});
  const [relatedCities, setRelatedCities] = useState();

  useEffect(() => {
    DCContext.playMusic(iConfig.battleMusic);

    return () => {};
  }, []);

  useEffect(() => {
    if (!DCContext.rawNations) {
      return;
    }

    let tmp = {};
    DCContext.rawNations.map((o, idx) => {
      tmp[o.id] = o;
    });
    console.log('[PortalMap] tmp nations', tmp);

    setNationsObject(tmp);
  }, [DCContext.rawNations]); //包含自由勢力城鎮也要顯示顏色

  useEffect(() => {
    if (!DCContext.cities) {
      return;
    }

    let tmp = {};
    DCContext.cities.map((o, idx) => {
      tmp[o.id] = o;
    });

    setCitiesObject(tmp);

    //相關城市
    setRelatedCities({
      //任務的下個城鎮
      FrontSight: lodash_find(DCContext.cities, ['focus', true]),
      //聯盟主力所在地
      Flag: lodash_find(DCContext.cities, ['id', DCContext.myUnion?.city.id]),
    });
  }, [DCContext.cities]);

  useEffect(() => {
    //console.log("[PortalMap] citiesObject", citiesObject);
    //debug
    // let hasSwordCities = [];
    // Object.entries(citiesObject).map(([id, o])=>{
    //   //
    //   if (o.sword){
    //     hasSwordCities.push(o);
    //   }
    // });
    // console.log("[PortalMap] hasSwordCities", hasSwordCities);
  }, [citiesObject]);

  //領取全部援助
  const clickCollectRewards = () => {
    //尚未領援助的城市
    let tmpCities = lodash_filter(DCContext.cities, { reward: true, reward_collected: false });
    console.log('[PortalMap] [RewardCollectALL] clickCollectRewards tmpCities', tmpCities);

    //debug
    //return;

    if (!tmpCities.length) {
      //已全數領取完畢
      DCContext.setShowConfirmModal({
        confirm: {
          message: tt(`all_rewards_collected`), //已全數領取完畢
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                //console.log('xxxxx');
                DCContext.setShowConfirmModal();
              },
            },
          ],
        },
      });
    } else {
      //有未領的城市援助
      DCContext.setShowRewardCollectAll(true);
    }
  };

  const SCity = ({ city_id }) => {
    return (
      <>
        <div className={`${styles.sRing} ${styles[`ring_${city_id}`]}`}>
          <img className={`rotation_highlightCircle`} src={highlightCircle} />
        </div>

        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate('/attacks/attackmap', {
              state: {
                focus_city_id: city_id,
                returnUrl: location.pathname,
                returnState: location.state,
              },
            });
          }}
        >
          <div className={`${styles.sCityBox} ${styles[`city_${city_id}`]}`}>
            <div className={styles.sCityIcon}>
              <Iimg
                className={styles.sCityIconImg}
                src={nationsObject?.[citiesObject?.[city_id]?.control_nation.id]?.color_icon}
              />
            </div>
            <div className={styles.sCityName}>{citiesObject?.[city_id]?.name}</div>
          </div>
        </ClickEffect>
      </>
    );
  };

  let sCities = {};
  sCities[502] = useMemo(
    () => <SCity city_id={502} />,
    [
      nationsObject?.[citiesObject?.[502]?.control_nation.id]?.color_icon,
      citiesObject?.[502]?.name,
    ],
  );
  sCities[507] = useMemo(
    () => <SCity city_id={507} />,
    [
      nationsObject?.[citiesObject?.[507]?.control_nation.id]?.color_icon,
      citiesObject?.[507]?.name,
    ],
  );
  sCities[540] = useMemo(
    () => <SCity city_id={540} />,
    [
      nationsObject?.[citiesObject?.[540]?.control_nation.id]?.color_icon,
      citiesObject?.[540]?.name,
    ],
  );
  sCities[27] = useMemo(
    () => <SCity city_id={27} />,
    [nationsObject?.[citiesObject?.[27]?.control_nation.id]?.color_icon, citiesObject?.[27]?.name],
  );
  sCities[37] = useMemo(
    () => <SCity city_id={37} />,
    [nationsObject?.[citiesObject?.[37]?.control_nation.id]?.color_icon, citiesObject?.[37]?.name],
  );
  sCities[1] = useMemo(
    () => <SCity city_id={1} />,
    [nationsObject?.[citiesObject?.[1]?.control_nation.id]?.color_icon, citiesObject?.[1]?.name],
  );
  sCities[293] = useMemo(
    () => <SCity city_id={293} />,
    [
      nationsObject?.[citiesObject?.[293]?.control_nation.id]?.color_icon,
      citiesObject?.[293]?.name,
    ],
  );
  sCities[75] = useMemo(
    () => <SCity city_id={75} />,
    [nationsObject?.[citiesObject?.[75]?.control_nation.id]?.color_icon, citiesObject?.[75]?.name],
  );
  sCities[110] = useMemo(
    () => <SCity city_id={110} />,
    [
      nationsObject?.[citiesObject?.[110]?.control_nation.id]?.color_icon,
      citiesObject?.[110]?.name,
    ],
  );

  const aniStyles = useSpring({
    loop: true,
    from: { _x: 0 },
    to: { _x: 4 },
    config: {
      duration: 4000,
    },
  });

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <div className={styles.leftBox}></div>

          <div className={styles.mapArea}>
            <img className={styles.fakeMapImg} src={portalmap} />

            <div className={styles.mapBox}>
              <img className={styles.mapImg} src={portalmap} />
              {Object.entries(citiesObject).map(([id, o]) => {
                //if (o.name == "烏蘭巴托"){
                //  console.log("xxxxxxx", o);
                //}

                return (
                  <div
                    key={`${o.id},${o.sword ? 1 : 0}`}
                    className={o.capital ? styles.markerCapital : styles.marker}
                    style={{
                      left: `calc(${o.x_position}/11036 * 100%)`,
                      top: `calc(${o.y_position}/7505 * 100%)`,
                      backgroundColor: `#${nationsObject?.[o.control_nation?.id]?.city_color}`,
                      zIndex: o.sword ? 4 : 3,
                      //backgroundColor: 'red'
                    }}
                  >
                    <ClickEffect
                      enabled={true}
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={e => {
                        navigate('/attacks/attackmap', {
                          state: {
                            focus_city_id: o.id,
                            returnUrl: location.pathname,
                            returnState: location.state,
                          },
                        });
                      }}
                    >
                      {o.sword && (
                        <animated.img
                          key={`ring_${o.id}`}
                          className={styles.marker2swords}
                          src={icon_2swords}
                          style={{
                            //left: `calc(${o.x_position}/11036 * 100%)`,
                            //top: `calc(${o.y_position}/7505 * 100%)`,
                            transform: aniStyles._x
                              .to({
                                range: [0, 3, 3.5, 4],
                                output: [0.7, 0.7, 1, 0.7],
                              })
                              .to(value => {
                                return `translate(-50%, -50%) scale(${value})`;
                              }),
                          }}
                        />
                      )}
                    </ClickEffect>
                  </div>
                );
              })}
              {sCities?.[502]} {/* 阿拉木圖 */}
              {sCities?.[507]} {/* 伊斯坦堡 */}
              {sCities?.[540]} {/* 達蘭薩拉 */}
              {sCities?.[27]} {/* 曼谷 */}
              {sCities?.[37]} {/* 維多利亞城 */}
              {sCities?.[1]} {/* 臺北 */}
              {sCities?.[293]} {/* 北京 */}
              {sCities?.[75]} {/* 海參崴 */}
              {sCities?.[110]} {/* 烏蘭巴托 */}
            </div>
          </div>

          <div className={styles.rightBox}></div>
        </div>

        <div className={styles.rightPanel}>
          {relatedCities?.FrontSight && (
            <div className={styles.panelItemBox}>
              <div className={styles.panelItemIcon}>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    navigate('/attacks/attackmap', {
                      state: {
                        focus_city_id: DCContext.userProfile?.city_id,
                        returnUrl: location.pathname,
                        returnState: location.state,
                      },
                    });
                  }}
                >
                  <img className={styles.layerBtnImg} src={icon_frontSight} />
                </ClickEffect>
              </div>
              <div className={styles.panelItemText}>{tt(`mission_progress`) /* 任務進度 */}</div>
            </div>
          )}

          {relatedCities?.Flag && (
            <div className={styles.panelItemBox}>
              <div className={styles.panelItemIcon}>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    navigate('/nationbattlemap', {
                      state: {
                        focus_city_id: relatedCities.Flag.id,
                        returnUrl: location.pathname,
                        returnState: location.state,
                      },
                    });
                  }}
                >
                  <img className={styles.layerBtnImg} src={icon_unionFlag} />
                </ClickEffect>
              </div>
              <div className={styles.panelItemText}>{tt(`union_main_force`) /* 聯盟主力 */}</div>
            </div>
          )}

          {DCContext.myUnion && (
            <div className={styles.panelItemBox}>
              <div className={styles.panelItemIcon}>
                <ClickEffect
                  enabled={true}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickCollectRewards();
                  }}
                >
                  <img
                    className={`${styles.layerBtnImg} ${styles.icon_ingots}`}
                    src={icon_ingots}
                  />
                </ClickEffect>
              </div>
              <div className={styles.panelItemText}>{tt(`collect_all_rewards`) /* 全部援助 */}</div>
            </div>
          )}
        </div>
      </div>

      <UwPortalCollectButton />

      <PopupMessagesIcon category={2} />

      <Navigator
        navi={{
          back: { spot: 'home' },
        }}
      />
    </IbgDiv>
  );
};
