export const BundleReceivedAlert = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();

  const [itemPages, setItemPages] = useState();
  const [pageIdx, setPageIdx] = useState(0);

  useEffect(() => {
    if (!props.bundleItems) {
      return;
    }
    console.log('[BundleReceivedAlert] props.bundleItems', props.bundleItems);

    let tmp = reStract(props.bundleItems);

    //debug
    //tmp = reStract(debugData.bundleItems);

    setItemPages(tmp);
  }, [props.bundleItems]);

  const reStract = data => {
    let tmp = [];
    //
    if (data?.items) {
      data.items.map((o, idx) => {
        tmp.push({
          data: o,
          sound: data?.sound_effect?.items,
          type: 'item',
        });
      });
    }
    //
    if (data?.actors) {
      data.actors.map((o, idx) => {
        tmp.push({
          data: o,
          sound: data?.sound_effect?.actors,
          type: 'actor',
        });
      });
    }
    console.log(`[BundleReceivedAlert] reStract`, tmp);

    return tmp.length ? tmp : null;
  };

  useEffect(() => {
    if (!props.bundleItems) {
      return;
    }
  }, [props.bundleItems]);

  const clickNextPage = () => {
    //console.log(`[BundleReceivedAlert] clickNextPage`, pageIdx, itemPages);

    let nextIdx = pageIdx + 1;
    if (itemPages[nextIdx]) {
      //console.log(`[BundleReceivedAlert] clickNextPage nextIdx`, nextIdx, itemPages[nextIdx]);
      setPageIdx(nextIdx);
    } else {
      //獎勵內容顯示結束
      //console.log(`[BundleReceivedAlert] clickNextPage END`);
      props.callback();
    }
  };

  useEffect(() => {
    if (!itemPages) {
      return;
    }

    if (props.disableFirstSound && pageIdx == 0) {
      //第一頁不播放音效 (任務結果頁播放勝利或失敗音效)
    } else if (itemPages?.[pageIdx]?.sound) {
      console.log(`[BundleReceivedAlert] playSound`, itemPages?.[pageIdx]?.sound);
      DCContext.playSound(itemPages?.[pageIdx]?.sound);
    }
  }, [pageIdx, itemPages]);

  return itemPages?.[pageIdx]?.type == 'item' ? (
    <ItemView
      key={pageIdx}
      title={props.title}
      showBg={props.showBg}
      items={itemPages[pageIdx].data}
      clickNextPage={clickNextPage}
      backgroundColor={props.backgroundColor}
    />
  ) : itemPages?.[pageIdx]?.type == 'actor' ? (
    <ActorView
      key={pageIdx}
      title={props.title}
      actor={itemPages[pageIdx].data}
      clickNextPage={clickNextPage}
      backgroundColor={props.backgroundColor}
    />
  ) : (
    <></>
  );
};

const ItemView = ({ title, showBg, items, clickNextPage, backgroundColor }) => {
  /* i18n */
  const { tt } = useI18n();

  return (
    <IbgDiv
      className={styles.rootContainer}
      src={showBg ? bgClockGold : null}
      transition={false}
      onReady={() => {}}
      style={{ backgroundColor: backgroundColor }}
    >
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3`, flash: false }}
        onClick={() => {
          clickNextPage();
        }}
      >
        <div className={styles.mainBox}>
          <div className={`${styles.resultTitleBox}`}>{title}</div>

          {items && (
            <div className={styles.winPrizesBar} style={{ backgroundImage: `url(${bgPrizesBar})` }}>
              {items.map((el, idx) => {
                return (
                  <div key={idx} className={styles.prizeItem}>
                    <img className={styles.bgPrizeItem} src={bgPropsHole_w} />
                    <Iimg
                      className={styles.prizeImg}
                      src={el.image}
                      transition={false}
                      onReady={() => {}}
                    />
                    <div className={styles.firstTimeText}>
                      {el.first_time ? tt('reward_first_time') /*首次*/ : ''}
                    </div>
                    <div className={styles.prizeQuantity}>{el.quantity}</div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </ClickEffect>
    </IbgDiv>
  );
};

const ActorView = ({ title, actor, clickNextPage, backgroundColor }) => {
  return (
    <IbgDiv
      className={styles.rootContainer}
      src={actor.scarcity_image}
      transition={false}
      onReady={() => {}}
      style={{ backgroundColor: backgroundColor }}
    >
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE3.mp3`, flash: false }}
        onClick={() => {
          clickNextPage();
        }}
      >
        <div className={styles.mainBox}>
          <div className={styles.oneEgg_Box}>
            <div className={styles.oneEgg_nameBox}>
              <FitText className={styles.oneEgg_nameText}>{actor.actor_prototype?.name}</FitText>
            </div>
            <div className={`${styles.oneEgg_actorBox} noClick`}>
              <Actorcard actor={actor} cardType="M" dataType="recruit" />
            </div>
            <div className={styles.oneEgg_nameBox}></div>
          </div>
        </div>
      </ClickEffect>
    </IbgDiv>
  );
};

