export const ShortMessage = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  const [iZIndex, setIZIndex] = useState();
  //
  const [message, setMessage] = useState();
  const displayTime = 10 * 1000;
  const timer = useRef();

  useEffect(() => {
    //debug
    // setTimeout(() => {
    //   ChannelContext.setMessages(debugData.notification_message);
    // }, 7000);

    //debug
    // setTimeout(() => {
    //   ChannelContext.setMessages(debugData.notification_messages);
    // }, 3000);

    //console.log("[ShortMessage] locale", DCContext.locale);

    return () => {
      clearTimeout(timer.current);
      setMessage();
    };
  }, []);

  // useEffect(()=>{
  //   console.log('[ShortMessage] DCContext.showShortMessage', DCContext.showShortMessage);

  // }, [DCContext.showShortMessage]);

  //Server主動發送 message
  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[DCContext] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //模擬戰（channel: all_players）
      case `all_players,union_battle_status`:
      case `${DCContext.localeChannelTopic},union_battle_status`:
        //console.log('[ShortMessage] server broadcast', _key, ChannelContext.messages?.res?.payload);

        //模擬戰集結開始，待領袖發起後即刻開戰
        if (ChannelContext.messages?.res?.payload.status == 'initiate') {
          setMessage(ChannelContext.messages?.res?.payload);

          clearTimeout(timer.current);
          timer.current = setTimeout(() => {
            setMessage();
          }, displayTime);
        }
        break;

      //模擬戰（channel: union:x）
      case `${DCContext.unionChannelTopic},union_battle_status`:
        //console.log('[ShortMessage] server broadcast', _key, ChannelContext.messages?.res?.payload);

        //領袖已發起模擬戰，請盡速前往支援
        if (ChannelContext.messages?.res?.payload.status == 'roll call') {
          setMessage(ChannelContext.messages?.res?.payload);

          clearTimeout(timer.current);
          timer.current = setTimeout(() => {
            setMessage();
          }, displayTime);
        }
        break;

      // case `all_players,notification`:
      // case `${DCContext.localeChannelTopic},notification`:
      //   //console.log('[ShortMessage] server broadcast', _key, ChannelContext.messages?.res?.payload);

      //   setMessage({
      //     message: ChannelContext.messages?.res?.payload[DCContext.locale]
      //   });

      //   clearTimeout(timer.current);
      //   timer.current = setTimeout(() => {
      //     setMessage();
      //   }, displayTime);
      // break;

      //
      case `${DCContext.localeChannelTopic},notification`:
        console.log('[ShortMessage] server broadcast', _key, ChannelContext.messages?.res?.payload);

        if (ChannelContext.messages?.res?.payload.message) {
          //一般單則訊息
          setMessage({
            message: ChannelContext.messages?.res?.payload.message,
          });
        } else if (ChannelContext.messages?.res?.payload.messages) {
          //通知選舉開始
          let tmp = lodash_find(ChannelContext.messages?.res?.payload.messages, {
            nation_id: DCContext.myUnionNation?.id,
          });
          console.log('[ShortMessage] tmp', tmp);

          if (!tmp) {
            return;
          }

          setMessage({
            message: tmp.message,
          });
        }

        clearTimeout(timer.current);
        timer.current = setTimeout(() => {
          setMessage();
        }, displayTime);
        break;
    }
  }, [ChannelContext.messages]);

  useEffect(() => {
    if (!message) {
      return;
    }

    let tmp = highestZindex({ _level: 'low', _elType: 'ShortMessage' });
    console.log('[ShortMessage] highestZindex', tmp, DCContext.showShortMessage, message);
    setIZIndex(tmp);

    DCContext.playSound2(`/audio/sound_effect/SE147.mp3`);
  }, [message]);

  const clickMessage = () => {
    console.log('[ShortMessage] clickMessage', message.goto);
    if (props.callback_click) {
      props.callback_click(message.goto);
    }
  };

  return !DCContext.showShortMessage || !message ? (
    <></>
  ) : (
    <div className={styles.shortMessageBox} /*style={{zIndex: iZIndex}}*/>
      <ClickEffect
        enabled={message?.goto ? true : false}
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          clickMessage();
        }}
      >
        <div className={styles.messageText}>{message?.message}</div>
      </ClickEffect>
    </div>
  );
};

