import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import history from 'lib/history';
//
import iConfig from 'iConfig';
import styles from './PvpBattle.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { AniDoor } from 'pages/unionbattle/AniDoor';
import { V3assignTeam } from 'pages/pvp/V3assignTeam';
import { BattleStage } from 'component/BattleStage';

export const PvpBattle = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [pvpBattleStatus, setPvpBattleStatus] = useState();
  const [pvpChannelStatus, setPvpChannelStatus] = useState();
  //
  const [matchData, setMatchData] = useState();
  //
  const [doorClosed, setDoorClosed] = useState(false);
  const [doorShowed, setDoorShowed] = useState(false);

  //BattleStage
  //const [roundData, setRoundData] = useState();
  const [ready2Play, setReady2Play] = useState(true); //淡入過場結束，避免過場與角色動畫同時，造成 webview crash

  //
  //const quitChannelName = useRef();

  useEffect(() => {
    return () => {
      //console.log(`[PvpBattle] leaveChannel`, quitChannelName.current);
      // ChannelContext.leaveChannel({
      //   topic: quitChannelName.current,
      //   params: {},
      //   callback: (res)=>{
      //     console.log(`[PvpBattle] channel ${quitChannelName.current} leave res`, res);
      //     //if (res.res.status == 'ok'){
      //       DCContext.setPvpChannelTopic();
      //     //}
      //   }
      // });
    };
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log(`[PvpBattle] channel player 未連線`);
      return;
    }

    console.log(`[PvpBattle] channel player 已連線`);

    //step 1
    DCContext.getPvp_battle_status();

    //debug 測試開關門
    // setMatchData({
    //   LEFT:{
    //     flag: "/images/home/flag/bigflag01CM.png",
    //     medal_image: "/images/medal/rank01.png",
    //     title1: "勁共勁共",
    //     title2: "嗶呠呠"
    //   },
    //   RIGHT:{
    //     flag: "/images/home/flag/bigflag06UG.png",
    //     medal_image: "/images/medal/rank01.png",
    //     title1: "東突信仰者聯盟",
    //     title2: "Ayup Arslan"
    //   }
    // });
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  //API pvp_battle_status 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},pvp_battle_status`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[PvpBattle] [pvp_battle_status 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //step 2
      setPvpBattleStatus(_res.payload);
    } else {
      console.log('pvp_battle_status error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},pvp_battle_status`]?.uuid]);

  useEffect(() => {
    if (!pvpBattleStatus) {
      return;
    }

    console.log(`[PvpBattle] pvpBattleStatus`, pvpBattleStatus);

    switch (pvpBattleStatus.status) {
      case `can_join`: //可參加排名戰
        goUrl.current = `/home`;
        setNaviBlock(false);
        break;

      case `matching`: //已參加，等待對手中
        break;

      case `matched`:
        break;

      case `in_progress`: //已參加，戰鬥中
        //step 3
        //console.log(`[PvpBattle] pvpBattleStatus in_progress`, pvpBattleStatus.channel);
        //DCContext.setPvpChannelTopic(pvpBattleStatus.channel);

        break;
    }
  }, [pvpBattleStatus]);

  // useEffect(()=>{
  //   if (!DCContext.pvpChannelTopic){
  //     return;
  //   }

  //   //step 4
  //   //join channel pvp_battle:x
  //   ChannelContext.joinChannel({
  //     topic: DCContext.pvpChannelTopic,
  //     params: {},
  //     callback: (res)=>{
  //       console.log(`[PvpBattle] channel ${DCContext.pvpChannelTopic} join res`, res);
  //       if (res.res.status == 'ok'){
  //         //step 5
  //         DCContext.getPvp_channel_status();

  //         //debug
  //         //DCContext.pvp_surrender();
  //       }
  //     }
  //   });

  //   //
  //   quitChannelName.current = DCContext.pvpChannelTopic;

  // }, [DCContext.pvpChannelTopic]);

  //監測特定 channel 連線變化狀態

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.pvpChannelTopic]) {
      console.log('[PvpBattle] channel pvp_battle:x 未連線');
      return;
    }

    console.log('[PvpBattle] channel pvp_battle:x 已連線');

    //step 5
    DCContext.getPvp_channel_status();

    //debug
    //DCContext.pvp_surrender();
  }, [ChannelContext.channels[DCContext.pvpChannelTopic]]);

  //pvp_battle:x API status 結果
  useEffect(() => {
    let _key = `${DCContext.pvpChannelTopic},status`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[PvpBattle] [getPvp_channel_status 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //step 6

      //更新 pvpBattleStatus
      setPvpChannelStatus(preState => {
        //去掉 round 免得前後回合戰鬥資料合併在一起
        let preData = preState ? lodash_cloneDeep(preState) : {};
        delete preData?.round;

        let tmp = lodash_merge(preData, _res.payload);
        //console.log("[DCContext] _updateData medals 222 ===========", tmp);

        if (tmp.offender?.user_id) {
          if (tmp.offender.user_id == DCContext.userProfile.id) {
            //
            tmp._player1 = {
              ...tmp.offender,
              _defender: false,
            };
            //
            tmp._player2 = {
              ...tmp.defender,
              _defender: true,
            };
            //
            tmp._iamDefender = false;
          } else {
            //
            tmp._player1 = {
              ...tmp.defender,
              _defender: true,
            };
            //
            tmp._player2 = {
              ...tmp.offender,
              _defender: false,
            };
            //
            tmp._iamDefender = true;
          }

          //tmp._player1 = (tmp.offender.user_id == DCContext.userProfile.id) ? tmp.offender : tmp.defender;
          //tmp._player2 = (tmp.offender.user_id == DCContext.userProfile.id) ? tmp.defender : tmp.offender;
          //
          //tmp._iamDefender = (tmp.offender.user_id == DCContext.userProfile.id) ? false : true;
        }

        //
        tmp._updatedBy = 'api';

        return tmp;
      });
    } else {
      console.log('getPvp_channel_status error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.pvpChannelTopic},status`]?.uuid]);

  //pvpChannelStatus 主要控制流程

  useEffect(() => {
    if (!pvpChannelStatus) {
      return;
    }

    console.log(`[PvpBattle] pvpChannelStatus`, pvpChannelStatus.next_action, {
      ...pvpChannelStatus,
    });

    switch (pvpChannelStatus.next_action) {
      case `battle`: //出戰後，戰鬥尚未開始
        //step 7
        DCContext.pvp_ready({ to: 'battle' }); //之後會收到 broadcast 要開關門轉場
        break;

      case `confirm_team`: //開關門轉場，轉場後開始指派隊伍
        //step 8
        //3v3 關門開門
        if (pvpChannelStatus.battle_type == '3v3') {
          setMatchData({
            LEFT: {
              flag: pvpChannelStatus._player1.flag,
              medal_image: pvpChannelStatus._player1.medal,
              title1: pvpChannelStatus._player1.organization,
              title2: pvpChannelStatus._player1.name,
            },
            RIGHT: {
              flag: pvpChannelStatus._player2.flag,
              medal_image: pvpChannelStatus._player2.medal,
              title1: pvpChannelStatus._player2.organization,
              title2: pvpChannelStatus._player2.name,
            },
          });

          //關閉 搜尋對手中 modal
          DCContext.setShowMatchingModal();

          //切換音樂
          if (pvpChannelStatus.music) {
            DCContext.playMusic(`${pvpChannelStatus.music}`);
          }
        }

        break;

      case `enter_round`: //此時：雙方都完成指派隊伍後 || 演完前回合通知 server end_round 後。之後：收到 broadcast 第一回合戰鬥資料，進入戰鬥場景
        //1v1 關門開門
        if (pvpChannelStatus.battle_type == '1v1') {
          setMatchData({
            LEFT: {
              flag: pvpChannelStatus._player1.flag,
              medal_image: pvpChannelStatus._player1.medal,
              title1: pvpChannelStatus._player1.organization,
              title2: pvpChannelStatus._player1.name,
            },
            RIGHT: {
              flag: pvpChannelStatus._player2.flag,
              medal_image: pvpChannelStatus._player2.medal,
              title1: pvpChannelStatus._player2.organization,
              title2: pvpChannelStatus._player2.name,
            },
          });

          //關閉 搜尋對手中 modal
          DCContext.setShowMatchingModal();

          //切換音樂
          if (pvpChannelStatus.music) {
            DCContext.playMusic(`${pvpChannelStatus.music}`);
          }
        }

        //3v3 此時會標示此回合雙方最終各選哪一隊
        //資料中 defender 或 offender.teams[n].sent_to_battle 會有此回合的數字

        DCContext.pvp_ready({ to: 'enter_round' });

        break;

      case `end_round`:
        if (pvpChannelStatus._updatedBy == 'api') {
          //pvp_battle:x API status 拿到 next_action:'end_round'，不會有 round 資料也無法演出戰鬥
          //直接通知 server ready to end_round (不需帶能量球資料)，等待 server broadcast 下一個動作
          DCContext.pvp_ready({
            to: 'end_round',
          });

          //todo 顯示等待處理中
        } else {
          //此時：此回合演完。之後：收到 broadcast 下回合戰鬥資料，繼續演
          //setRoundData(pvpChannelStatus.round);
        }
        break;

      case `select_team`:
        if (pvpChannelStatus._updatedBy == 'api') {
          //呼叫 pvp_battle:x status response
          //此時要選隊伍，沒有 round 資料
          //通知 server 準備好選隊伍
          DCContext.pvp_ready({
            to: 'select_team',
          });
        } else {
          //此時：收到本隊戰鬥最後一回合資料。之後：收到 broadcast 開始選下一隊
          //setRoundData(pvpChannelStatus.round);
        }
        break;

      case `medals`:
        //有一方投降
        if (pvpChannelStatus.surrender_user_id) {
          if (pvpChannelStatus.surrender_user_id == DCContext.userProfile.id) {
            //我方投降 直接轉向結果頁
            goUrl.current = `/pvpresult/${pvpChannelStatus.battle_type}`;
            setNaviBlock(false);
          } else {
            //對方投降
            showModal_confirm({
              confirm: {
                /*對手已投降*/
                message: { i18nKey: `pvp_surrender_alert`, values: null, options: null },
                buttons: [
                  {
                    text: { i18nKey: `confirm` },
                    callback: () => {
                      //轉向結果頁
                      goUrl.current = `/pvpresult/${pvpChannelStatus.battle_type}`;
                      setNaviBlock(false);
                      //
                      callbackConfirm({});
                    },
                  },
                ],
              },
            });
          }
        }
        break;
    }
  }, [pvpChannelStatus]);

  //Server broadcast pvp_battle:x

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[PvpBattle] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //pvp_battle:x
      case `${DCContext.pvpChannelTopic},pvp_battle`:
        //console.log('[PvpBattle] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpData = ChannelContext.messages?.res?.payload;
        console.log('[PvpBattle] broadcast pvp_battle', tmpData);

        //
        setPvpChannelStatus(preState => {
          //去掉 round 免得前後回合戰鬥資料合併在一起
          let preData = preState ? lodash_cloneDeep(preState) : {};
          delete preData?.round;

          let tmp = lodash_merge(preData, tmpData);

          if (tmp.offender?.user_id) {
            if (tmp.offender.user_id == DCContext.userProfile.id) {
              //
              tmp._player1 = {
                ...tmp.offender,
                _defender: false,
              };
              //
              tmp._player2 = {
                ...tmp.defender,
                _defender: true,
              };
              //
              tmp._iamDefender = false;
            } else {
              //
              tmp._player1 = {
                ...tmp.defender,
                _defender: true,
              };
              //
              tmp._player2 = {
                ...tmp.offender,
                _defender: false,
              };
              //
              tmp._iamDefender = true;
            }

            //tmp._player1 = (tmp.offender.user_id == DCContext.userProfile.id) ? tmp.offender : tmp.defender;
            //tmp._player2 = (tmp.offender.user_id == DCContext.userProfile.id) ? tmp.defender : tmp.offender;
            //
            //tmp._iamDefender = (tmp.offender.user_id == DCContext.userProfile.id) ? false : true;
          }

          //
          tmp._updatedBy = 'broadcast';

          return tmp;
        });
        break;
    }
  }, [ChannelContext.messages]);

  //step 9 開關門轉場完

  //已關門
  const doorClose_callback = () => {
    console.log('[PvpBattle] doorClose_callback', pvpChannelStatus);
    setDoorClosed(true);
  };

  //已開門 (3v3 停在此等待指派隊伍)
  const doorOpen_callback = () => {
    console.log('[PvpBattle] doorOpen_callback', pvpChannelStatus);
    setDoorShowed(true);
  };

  //BattleStage 此回合演完時呼叫
  const getAttackEndRound = p => {
    //debug 暫停下一個 round
    console.log(
      '[PvpBattle] round end ============================================================',
      pvpChannelStatus,
      p,
    );

    switch (pvpChannelStatus.next_action) {
      case `battle`:
        break;

      case `confirm_team`:
        break;

      case `enter_round`:
        break;

      case `end_round`:
        //通知 server 此回合演完
        DCContext.pvp_ready({
          to: 'end_round',
          round: p, //能量球資料
        });
        break;

      case `select_team`:
        //通知 server 此回合演完，本隊戰鬥結束，準備好選下一隊
        DCContext.pvp_ready({
          to: 'select_team',
        });
        break;

      case `medals`:
        //戰鬥結束導向結果頁
        //navigate(`/pvpresult/${pvpChannelStatus.battle_type}`);

        goUrl.current = `/pvpresult/${pvpChannelStatus.battle_type}`;
        setNaviBlock(false);
        break;
    }
  };

  /* block page when leave */

  const [naviBlock, setNaviBlock] = useState(true);
  const unblockNavi = useRef(() => {});
  const goUrl = useRef();

  useEffect(() => {
    //確保有 DCContext.pvpChannelTopic ，否則 modal confirm callback 時 DCContext.pvpChannelTopic => undefined
    //if (!DCContext.pvpChannelTopic){
    //  return;
    //}

    let unblock;
    if (naviBlock) {
      // Block navigation and register a callback that
      // fires when a navigation attempt is blocked.
      unblock = history.block(tx => {
        // Navigation was blocked! Let's show a confirmation dialog
        // so the user can decide if they actually want to navigate
        // away and discard changes they've made in the current page.
        let url = tx.location.pathname;

        // if (window.confirm(`Are you sure you want to go to "${url}"?`)) {
        //   // Unblock the navigation.
        //   unblock();

        //   // Retry the transition.
        //   tx.retry();
        // }

        unblockNavi.current = () => {
          console.log('[PvpBattle] unblockCallback()');

          // Unblock the navigation.
          unblock();

          // Retry the transition.
          tx.retry();
        };

        showModal_confirm({
          confirm: {
            /*確定要投降？*/
            message: { i18nKey: `pvp_surrender_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: () => {
                  DCContext.pvp_surrender();
                  callbackConfirm({});
                },
              },
            ],
          },
        });
      });
    } else if (goUrl.current) {
      //
      if (goUrl.current.startsWith('/pvpresult')) {
        navigate(goUrl.current, {
          state: {
            pvpChannelStatus: pvpChannelStatus,
          },
        });
      } else {
        navigate(goUrl.current);
      }
    }

    return () => {
      if (typeof unblock === 'function') {
        unblock();
      }
    };
  }, [naviBlock, DCContext.pvpChannelTopic]);

  //pvp_battle:x API surrender 結果
  useEffect(() => {
    let _key = `${DCContext.pvpChannelTopic},surrender`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[PvpBattle] [surrender 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      //戰鬥不存在(已結束)
      if (_res.error == 'no_such_pvp_battle') {
        navigate('/home');
        return;
      }
    } else if (_res.status == 'ok') {
    } else {
      console.log('surrender error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.pvpChannelTopic},surrender`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox}>
        {/* 戰鬥舞台 */}
        {pvpChannelStatus?.round && doorClosed && (
          <div className={styles.pageBox} style={{ zIndex: 1 }}>
            {' '}
            {/* zIndex:1 避免遮住主選單 */}
            <BattleStage
              mode="pvp"
              background={pvpChannelStatus.background_image}
              iamDefender={pvpChannelStatus._iamDefender}
              roundData={pvpChannelStatus.round}
              getAttackEndRound={getAttackEndRound}
            />
          </div>
        )}

        {/* 指派隊伍 */}
        {pvpChannelStatus?.battle_type == '3v3' && !pvpChannelStatus?.round && doorClosed && (
          <V3assignTeam doorShowed={doorShowed} pvpChannelStatus={pvpChannelStatus} />
        )}

        {/* 開關門過場 */}
        {matchData && !doorShowed && (
          <div className={styles.pageBox} style={{ zIndex: 40 }}>
            <AniDoor
              sound={
                `/audio/sound_effect/SE146.mp3` /*pvpChannelStatus?.closing_door_sound_effect*/
              }
              matchData={matchData}
              doorClose_callback={doorClose_callback}
              doorOpen_callback={doorOpen_callback}
              style={{ zIndex: 40 }}
            />
          </div>
        )}
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};

