import React, { useEffect, useState } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useParams,
  useNavigate,
  useLocation,
} from 'react-router-dom';
import { matchPath } from 'react-router';
//
import { SocketProvider, useSocketContext } from 'lib/Phoenix/SocketContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useUserContext } from 'lib/UserContext';
//
import { Button, message, Card, Row, Col } from 'antd';
//
import iConfig from 'iConfig';

export function ChannelLocale() {
  const { ...SocketContext } = useSocketContext();
  const ChannelContext = useChannelContext();
  const { ...UserContext } = useUserContext();
  //
  let navigate = useNavigate();
  const location = useLocation();
  const DCContext = useDCContext();

  //若 socket 連線，自動加入 channel
  useEffect(() => {
    if (SocketContext.socketStatus?.status !== 'ok' || !DCContext.localeChannelTopic) {
      return;
    }

    console.log('[ChannelLocale] DCContext.localeChannelTopic', DCContext.localeChannelTopic);

    //比對已存在的 channel
    const origChannel = SocketContext.socket?.channels.find(element =>
      element.topic.startsWith('locale:'),
    );
    console.log('[ChannelLocale] origChannel', { ...origChannel });
    if (origChannel && origChannel?.topic != DCContext.localeChannelTopic) {
      console.log('[ChannelLocale] xxxxxxxxxx', { ...origChannel });

      //退出 channel
      ChannelContext.leaveChannel({
        topic: origChannel.topic,
        params: { fake: 'locale' },
      });
    }

    //socket 首次連線，channel 不存在 => 手動 join
    //socket 斷線重連，channel 已存在 => Phoenix 會自動 join，不要手動 join
    if (!origChannel || origChannel?.topic != DCContext.localeChannelTopic) {
      handleClick_join(null);
    }
  }, [SocketContext.socketStatus?.status, DCContext.localeChannelTopic]);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (ChannelContext.channels?.[DCContext.localeChannelTopic]?.state != 'joined') {
      console.log('[ChannelLocale] channel 未連線');
      return;
    }

    console.log('[ChannelLocale] channel 已連線');
  }, [ChannelContext.channels?.[DCContext.localeChannelTopic]?.state]);

  /*  */

  //加入 channel
  const handleClick_join = e => {
    //
    console.log('[ChannelLocale] join channel: ', DCContext.localeChannelTopic);

    ChannelContext.joinChannel({
      topic: DCContext.localeChannelTopic,
      params: { fake: 'locale' },
    });
  };

  const handleClick_leave = e => {
    //console.log("client: leave channel");

    ChannelContext.leaveChannel({
      topic: DCContext.localeChannelTopic,
      params: { fake: 'locale' },
    });
  };

  return (
    <>
      {/* <div className="chat-messages" style={{marginTop: 20}}>
				<Row gutter={16}>
					<Col span={5}>
						<Card title="1. join channel: player">
							<Button type="primary" onClick={handleClick_join}>join</Button>
							<Button type="primary" onClick={handleClick_leave}>leave</Button>
						</Card>
					</Col>
				</Row>
			</div> */}
    </>
  );
}
