import { BattleStage } from 'pages/unionbattle/BattleStage';
import { Medals } from 'component/Medals';

export const Unionbattle = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [battleData, setBattleData] = useState();
  const [fightData, setFightData] = useState();
  const [zonesData, setZonesData] = useState();
  const [matchData, setMatchData] = useState();
  //
  let timer_commanderOnline;
  const [commanderOnline, setCommanderOnline] = useState(); // YES / NO
  const [doorShowed, setDoorShowed] = useState(false);
  const [showMedals, setShowMedals] = useState(false);
  //
  const _mode = 'unionBattle';

  useEffect(() => {
    return () => {
      clearTimeout(timer_commanderOnline);
    };
  }, []);

  //監測特定 channel 連線變化狀態

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionChannelTopic]) {
      console.log('[Unionbattle] channel union:x 未連線');
      return;
    }

    console.log('[Unionbattle] channel union:x 已連線');
    DCContext.getUnion_battle_status();

    //debug
    //setFightData(debugStatusR_broadcast["roll_call"]);
  }, [ChannelContext.channels[DCContext.unionChannelTopic]]);

  //API union_battle status 結果

  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`]) {
      return;
    }

    console.log('[Unionbattle] union_battle_status', {
      ...DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res,
    });

    if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.status == 'error'
    ) {
    } else if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.status == 'ok'
    ) {
      /* 模擬戰
			{"not_started"}					開始時間未到							 停在本部跳訊息通知
      {"initiate"}						開始時間已到，尚未發起			 選隊伍
      {"roll_call"}						已發起
        data.player_joined  	false => 未參戰             選隊伍
                            	true  => 已參戰，未開戰      等待開戰頁
			{"manuver"}				 			已開戰，開始選擇戰區					聊天室 選戰區
      {"battle"}	 						已開戰，開始交戰 							交戰頁
      {"concluded"}						已分勝負 									結果頁
      {"no_battle"}  					本聯盟今天沒有參戰					停在本部跳訊息通知
			*/

      let tmpData =
        DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.payload;

      //debug
      //tmpData = debugStatusR["concluded"];
      //console.log('[Unionbattle] union_battle_status', tmpData);

      //各階段資料
      switch (tmpData.status) {
        case 'no_battle':
        case 'not_started':
        case 'initiate':
          navigate('/home');
          break;

        case 'roll_call':
        case 'maneuver':
          setBattleData(tmpData);
          break;

        case 'battle':
        case 'concluded':
          setFightData(tmpData);
          break;
      }
    } else {
      console.log('union_battle_status error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.unionChannelTopic},union_battle_status`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`]?.uuid]);

  //Server broadcast

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[DCContext] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //模擬戰
      case `${DCContext.unionChannelTopic},union_battle_status`:
        //console.log('[Unionbattle] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpData = ChannelContext.messages?.res?.payload;
        console.log('[Unionbattle] broadcast union_battle_status', tmpData);

        switch (tmpData.status) {
          case 'roll_call': //有人參賽時，戰力數值變動
            setBattleData(tmpData);
            break;

          case 'maneuver':
            if (tmpData.round == 1) {
              console.log('[Unionbattle] broadcast maneuver 第一次', tmpData);
              //取 union_battle_status 完整資料 (broadcast maneuver 沒有 battle_zone_position)
              DCContext.getUnion_battle_status();
            } else {
              console.log('[Unionbattle] broadcast maneuver 合併原資料', tmpData);
              setBattleData(prevState => {
                return merge(prevState, tmpData);
              });
            }
            break;

          case 'battle':
            // if (!battleData){
            //   //取 maneuver 資料
            // 	DCContext.getUnion_battle_status({params:{maneuver:true}});
            // }

            setFightData(tmpData);
            break;
        }
        break;

      //更換戰區後 || 間諜偵察後 || 指揮官分配戰區後 => 更新 power
      case `${DCContext.unionChannelTopic},union_battle_power`:
        let tmpPower = ChannelContext.messages?.res?.payload;
        console.log('[Unionbattle] broadcast union_battle_power', tmpPower);

        setBattleData(prevState => {
          let tmp = merge(prevState, { data: tmpPower });
          //console.log('[Unionbattle] broadcast union_battle_power 2', tmp);
          return tmp;
        });
        break;

      //指揮官就位
      case `${DCContext.unionChannelTopic},Commander on deck`:
        setCommanderOnline('YES');

        DCContext.playSound(`/audio/sound_effect/SE144.mp3`);

        clearTimeout(timer_commanderOnline);
        setTimeout(() => {
          setCommanderOnline();
        }, 3000);
        break;
    }
  }, [ChannelContext.messages]);

  /* 基本資料 */

  useEffect(() => {
    if (!battleData) {
      return;
    }

    let tmpData = battleData;

    console.log('[Unionbattle] tmpData', tmpData);

    //基本資料 zones
    if (tmpData.zones) {
      setZonesData(tmpData.zones);
    }

    //基本資料 match
    if (tmpData.match) {
      let tmpMatch = tmpData.match;

      setMatchData({
        LEFT: {
          flag: tmpMatch.offender_union.flag,
          medal_image: tmpMatch.offender_union.medal_image,
          title1: DCContext.cityNames[tmpMatch.offender_union.city_id],
          title2: tmpMatch.offender_union.name,
        },
        RIGHT: {
          flag: tmpMatch.defender_union.flag,
          medal_image: tmpMatch.defender_union.medal_image,
          title1: DCContext.cityNames[tmpMatch.defender_union.city_id],
          title2: tmpMatch.defender_union.name,
        },
      });
    }
  }, [battleData]);

  useEffect(() => {
    if (!fightData) {
      return;
    }

    let tmpData = fightData;

    console.log('[Unionbattle] tmpData', tmpData);

    //基本資料 zones
    if (tmpData.zones) {
      setZonesData(tmpData.zones);
    }

    //基本資料 match
    if (tmpData.match) {
      let tmpMatch = tmpData.match;

      setMatchData({
        LEFT: {
          flag: tmpMatch.offender_union.flag,
          medal_image: tmpMatch.offender_union.medal_image,
          title1: DCContext.cityNames[tmpMatch.offender_union.city_id],
          title2: tmpMatch.offender_union.name,
        },
        RIGHT: {
          flag: tmpMatch.defender_union.flag,
          medal_image: tmpMatch.defender_union.medal_image,
          title1: DCContext.cityNames[tmpMatch.defender_union.city_id],
          title2: tmpMatch.defender_union.name,
        },
      });
    }
  }, [fightData]);

  //API maneuver 更換戰區 結果

  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`]) {
      return;
    }

    console.log('[Unionbattle] maneuver', {
      ...DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`].res,
    });

    if (DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`].res.status == 'error') {
    } else if (DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`].res.status == 'ok') {
      let tmpData = DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`].res.payload;

      console.log('[Unionbattle] maneuver', tmpData);

      switch (tmpData.status) {
        case 'maneuver':
          //setBattleData(tmpData);

          //回傳資料不全，只更新戰區位置 (data.power 由 server broadcast "nation_battle_power" 更新)
          setBattleData(preState => {
            return {
              ...preState,
              battle_zone_position: tmpData.battle_zone_position, //只更新戰區位置
            };
          });
          break;

        case 'battle': //回合戰鬥結束後，提早回到 maneuver 選戰區，但表定時間還是 battle
          //回傳資料不全，只更新戰區位置 (data.power 由 server broadcast "nation_battle_power" 更新)
          setBattleData(preState => {
            return {
              ...preState,
              battle_zone_position: tmpData.battle_zone_position, //只更新戰區位置
            };
          });
          break;
      }
    } else {
      console.log('maneuver error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.unionChannelTopic},maneuver`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},maneuver`]?.uuid]);

  const doorOpen_callback = () => {
    console.log('[Unionbattle] doorOpen_callback');
    setDoorShowed(true);
  };

  //callback 戰鬥舞台回合結束
  const roundEnd_callback = () => {
    console.log('[Unionbattle] 本回合戰鬥結束', { ...fightData });

    if (fightData.good_game) {
      console.log('[Unionbattle] 模擬戰結束，顯示結果');
      setShowMedals(true);
    } else {
      console.log('[Unionbattle] 等待下回合');

      //取下回合 maneuver 資料
      DCContext.getUnion_battle_status({ params: { maneuver: true } });
      //清除 battle 資料，關閉戰鬥舞台
      setFightData();
    }
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox}>
        <div className={styles.pageBox} style={{ zIndex: 10 }}>
          <BattleRoom
            _mode={_mode}
            zonesData={zonesData}
            battleData={battleData}
            commanderOnline={commanderOnline}
          />
        </div>

        {doorShowed && fightData && (
          <div className={styles.pageBox} style={{ zIndex: 20 }}>
            <BattleStage
              zonesData={zonesData}
              fightData={fightData}
              roundEnd_callback={roundEnd_callback}
            />
          </div>
        )}

        {showMedals && (
          <div className={styles.pageBox} style={{ zIndex: 30 }}>
            <Medals
              catKey={`Union`}
              getPreviousRecord={`after_union_battle`}
              style={{ zIndex: 30 }}
            />
          </div>
        )}

        {matchData && !doorShowed && (
          <div className={styles.pageBox} style={{ zIndex: 40 }}>
            <AniDoor
              matchData={matchData}
              doorOpen_callback={doorOpen_callback}
              style={{ zIndex: 40 }}
            />
          </div>
        )}
      </div>

      {/* <div style={{color:"white", textAlign:"left"}}>
				DoorShowed: {doorShowed?1:0}, fightData: {fightData?1:0}
			</div> */}
    </div>
  );
};

