import icon_fund from 'assets/img2/store/icon_fund.png';
import icon_fund2 from 'assets/img2/store/icon_fund2.png';

export const MonthlyCard = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [bundles, setBundles] = useState();
  const [products, setProducts] = useState();
  const [product, setProduct] = useState();
  const [selectedProduct, setSelectedProduct] = useState();
  const catIdx = 1;

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[MonthlyCard] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[MonthlyCard] channel player 未連線');
      return;
    }

    console.log('[MonthlyCard] channel player 已連線');
    DCContext.getBundles(false); //錢莊 true 就可以
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.bundle_categories || !DCContext.bundles) {
      return;
    }

    let tmp = [];
    DCContext.bundles.map((item, idx) => {
      if (item.bundle_category_id == DCContext.bundle_categories[catIdx].id) {
        tmp.push(item);
      }
    });

    console.log('[MonthlyCard] bundles', tmp);

    setBundles(tmp);
  }, [DCContext.bundle_categories, DCContext.bundles]);

  useEffect(() => {
    console.log('[MonthlyCard] DCContext.bundles', DCContext.bundles);

    if (!bundles) {
      return;
    }

    if (!DCContext.iapProducts) {
      DCContext.getIapProducts();
      return;
    }

    console.log('[MonthlyCard] DCContext.iapProducts', DCContext.iapProducts);

    let tmp;
    let matchIapItem = DCContext.iapProducts.find(iapItem => {
      if (iapItem.productId == DCContext.bundle_categories[catIdx].product_id) {
        return true;
      }
    });
    console.log(
      '[MonthlyCard] matchIapItem',
      DCContext.bundle_categories[catIdx].product_id,
      matchIapItem,
    );

    if (matchIapItem) {
      tmp = {
        ...DCContext.bundle_categories[catIdx],
        iapData: matchIapItem,
      };
    }

    console.log('[MonthlyCard] merged products', tmp);

    setProduct(tmp);
    setSelectedProduct(tmp);
  }, [bundles, DCContext.iapProducts]);

  const clickBuyBtn = () => {
    //debug
    //collectProduct();
    //return;

    if (selectedProduct.can_buy) {
      buyProduct();
    } else if (selectedProduct.can_collect) {
      collectProduct();
    }
  };

  /* IAP 購買 */

  const buyProduct = () => {
    if (!selectedProduct) {
      return;
    }

    console.log('[MonthlyCard] buyProduct selectedProduct', selectedProduct);

    //購買鍵縮放效果
    aniApi.start({
      from: { _x: 0 },
      to: { _x: 1 },
      config: {
        duration: 1000,
      },
      onRest: () => {
        console.log('[MonthlyCard] shop button scale complete');

        //顯示購買物品內容
        DCContext.setShowStoreShopConfirm({
          data: {
            cost: `${product?.iapData.currency} ${
              product?.iapData?.localizedPrice.startsWith('$')
                ? product?.iapData?.localizedPrice.substr(1)
                : product?.iapData?.localizedPrice
            }`,
            productName: product.name,
          },
          callback: () => {
            //確定購買
            //console.log('xxxxx');

            DCContext.setShowProcessingModal(true); //顯示“處理中”
            //
            DCContext.buyIapProduct(selectedProduct.iapData.productId);
            //
            DCContext.setShowStoreShopConfirm();
          },
        });
      },
    });
  };

  useEffect(() => {
    if (!DCContext.iapPhase1) {
      return;
    }

    //iapPhase1 => OK 或 ERROR 都關閉“處理中” modal
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    DCContext.setIapPhase1(null);
  }, [DCContext.iapPhase1]);

  //in_app_purchase_receipt 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},in_app_purchase_receipt`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[MonthlyCard] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //購買月卡後，立即獲得的獎勵，馬上顯示在畫面上
      if (_res.payload?.collected_items) {
        //顯示已領取狀態 & popup
        showModal_BRA({
          params: {
            title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
            bundleItems: _res.payload.collected_items,
            callback: () => {
              callbackModal_BRA(null, null);
            },
          },
        });
      }
    } else {
      console.log('in_app_purchase_receipt error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},in_app_purchase_receipt`]?.uuid]);

  /* 領取 */

  const collectProduct = () => {
    console.log('[MonthlyCard] collectProduct', selectedProduct);

    DCContext.collectBundle({
      reference_type: 'Monthly Pass',
    });
  };

  //collect_bundle 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[MonthlyCard] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  // //領取結果
  // useEffect(()=>{
  // 	if (!DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]){
  // 		return;
  // 	}

  // 	console.log("[MonthlyCard] player,collect_bundle", {...DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res});

  // 	//todo error處理
  //   if (DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res.status == "error"){
  //     console.log("[MonthlyCard] player,collect_bundle error", {...DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res});
  //     return;
  //   }

  //   //顯示已領取狀態 & popup
  //   let returnParams = DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res.payload;

  //   if (returnParams.reference_type == "Monthly Pass"){
  //     //popup
  //     showModal_confirm({
  //       confirm: {
  //         /* 領取完成 */
  //         message: {i18nKey:`bundle_collected`, values:null, options:null},
  //         buttons: [
  //           {
  //             text: {i18nKey:`confirm`},
  //             callback: ()=>{
  //               callbackConfirm();
  //             }
  //           }
  //         ]
  //       }
  //     });
  //   }

  // 	//清除本次 send message 結果
  // 	DCContext.setMsgRes((prevState)=>{
  // 		delete prevState[`${DCContext.playerChannelTopic},collect_bundle`];
  // 		return {...prevState};
  // 	});

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    maskClosable: false,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[ChatBundle] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  //購買鍵縮放效果
  const [aniStyles, aniApi] = useSpring(() => ({
    from: { _x: 0 },
    to: { _x: 1 },
    onRest: () => {},
  }));

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <IbgDiv className={styles.mainBox} src={bgMonthlyCard} transition={false} onReady={() => {}}>
        <div className={styles.bodyBox}>
          <div className={styles.contBox}>
            <div className={styles.leftBox}>
              <div className={styles.sectionBox}>
                <div className={styles.titleText}>
                  {tt(`monthly_pass_bestow_immediately`) /* 立即贈送 */}
                </div>
                <div className={`${styles.passItemBox}`}>
                  <img className={styles.bgPassItem} src={bgPropsHole} />
                  <Iimg
                    className={`${styles.passItemImg}`}
                    src={icon_fund2}
                    transition={false}
                    onReady={() => {}}
                  />
                  <div className={styles.passItemQuantity}>{bundles?.[0].first_day_fund}</div>
                </div>
              </div>

              <div className={styles.sectionBox}>
                <div className={styles.titleText}>
                  {tt(`monthly_pass_daily_bundle`) /* 每日登入領取 */}
                </div>
                <div className={`${styles.passItemBox}`}>
                  <img className={styles.bgPassItem} src={bgPropsHole} />
                  <Iimg
                    className={`${styles.passItemImg}`}
                    src={icon_fund}
                    transition={false}
                    onReady={() => {}}
                  />
                  <div className={styles.passItemQuantity}>{bundles?.[0].regular_fund}</div>
                </div>
              </div>
            </div>
          </div>

          <div className={styles.infoBox}></div>

          <div className={styles.md_price}>
            {`${product?.iapData.currency} ${
              product?.iapData?.localizedPrice.startsWith('$')
                ? product?.iapData?.localizedPrice.substr(1)
                : product?.iapData?.localizedPrice
            }`}
          </div>

          <ClickEffect
            enabled={product?.can_buy || product?.can_collect ? true : false}
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              clickBuyBtn();
            }}
          >
            <animated.div
              className={styles.shopBtn}
              style={{
                ...aniStyles,
                transform: aniStyles._x
                  .to({
                    range: [0, 0.5, 1],
                    output: [1, 1.1, 1],
                  })
                  .to(value => {
                    return `translate(0, 0) scale(${value})`;
                  }),
              }}
            >
              <img className={styles.shopBtnImg} src={shopBtn} />
              <div className={styles.shopBtnText}>
                {
                  product?.can_buy
                    ? tt(`trade`) /* 交易 */
                    : product?.can_collect
                    ? tt(`collect`) /* 領取 */
                    : tt(`monthly_pass_daily_collected`) /* 今日已領取 */
                }
              </div>
              {product?.can_collect && <div className={`coinRedSpot`}></div>}
            </animated.div>
          </ClickEffect>
        </div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/user/backpack`);
          }}
        >
          <div className={styles.linkProps}>
            <img className={`rotation_1`} src={iconPropsWhite} />
            <span>{tt(`to_treasury`) /* 往庫房 */}</span>
          </div>
        </ClickEffect>
      </IbgDiv>

      <div className={`tabBar ${styles.tabBar_shadow}`}>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundleorders');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`bank`) /* 錢莊 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/monthlycard');
          }}
        >
          <div className={`tab active`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`monthly_card`) /* 月卡 */}</div>
            {DCContext.bundle_categories?.[1].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlepass');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`activity_pass`) /* 通行證 */}</div>
            {DCContext.bundle_categories?.[2].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlegift');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`gift_pack`) /* 禮包 */}</div>
          </div>
        </ClickEffect>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </IbgDiv>
  );
};
