import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { v4 as uuidv4 } from 'uuid';
import { useSwipeable } from 'react-swipeable';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { Col, Row, Modal } from 'antd';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import Carousel from 'react-spring-3d-carousel';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnRing } from 'component/BtnRing';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Sealimage.module.scss';
import background from 'assets/img/bgClockGold.png';
//import left_gold from 'assets/img/icon_left_gold.png';
//import right_gray from 'assets/img/icon_right_gray.png';
//import right_gold from 'assets/img/icon_right_gold.png';
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';

export const Sealimage = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const location = useLocation();
  let navigate = useNavigate();
  //
  const [slides, setSlides] = useState([]);
  const [slideIdxs, setSlideIdxs] = useState(); //各 catgories 目前切換到哪一個 slide index
  const [slideCatIdx, setSlideCatIdx] = useState(0);

  //
  const [imagesData, setImagesData] = useState();
  const [imageData, setImageData] = useState();
  //
  const _mode = props.mode;

  //swipe
  const swipeConfig = {
    delta: 50, // min distance(px) before a swipe starts. *See Notes*
    preventScrollOnSwipe: false, // prevents scroll during swipe (*See Details*)
    trackTouch: true, // track touch input
    trackMouse: true, // track mouse input
    rotationAngle: 0, // set a rotation angle
    swipeDuration: 800, //Infinity,               // allowable duration of a swipe (ms). *See Notes*
    touchEventOptions: { passive: true }, // options for touch listeners (*See Details*)
  };

  const swipeHandlers = useSwipeable({
    ...swipeConfig,
    //onSwiped: (eventData) => {console.log("User Swiped!", eventData)},
    onSwipedLeft: eventData => {
      //console.log("User onSwipedLeft!", eventData);
      changeSlide(null, 1);
    },
    onSwipedRight: eventData => {
      //console.log("User onSwipedRight!", eventData);
      changeSlide(null, -1);
    },
  });

  useEffect(() => {
    console.log('[Sealimage] location.state', location.state);

    if (DCContext.userProfile?.music) {
      DCContext.playMusic(`${DCContext.userProfile.music}`);
    } else {
      DCContext.playMusic(`/audio/music/BGM10.mp3`);
    }
  }, []);

  useEffect(() => {
    if (!DCContext.nations) {
      return;
    }

    console.log('[Sealimage] location.state.nation', location.state.nation);
    setImagesData(location.state.nation.seal_categories);
  }, [DCContext.nations]);

  /* */
  useEffect(() => {
    if (!imagesData || slideCatIdx === undefined) {
      return;
    }

    let tmp = imagesData[slideCatIdx].seals.map((e, i) => {
      return {
        key: uuidv4(),
        content: <Iimg className={null} src={e.image_url} transition={false} onReady={() => {}} />,
      };
    });
    //console.log(tmp);
    setSlides(tmp);

    //
    setSlideIdxs(prevState => {
      let tmp = prevState ? { ...prevState } : {};
      tmp[slideCatIdx] = tmp[slideCatIdx] ? tmp[slideCatIdx] : 0;
      return tmp;
    });

    //changeSlide(null, 1);
  }, [imagesData, slideCatIdx]);

  useEffect(() => {
    if (!slideIdxs) {
      return;
    }

    console.log('[Sealimage] slideIdxs', slideCatIdx, slideIdxs);
    setImageData(imagesData[slideCatIdx].seals[slideIdxs[slideCatIdx]]);
  }, [slideIdxs]);

  const changeSlide = (e, p) => {
    let newIdx = slideIdxs[slideCatIdx] + p;
    if (newIdx >= slides.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = slides.length - 1;
    }
    //console.log("newIdx", newIdx);

    setSlideIdxs(prevState => {
      let tmp = { ...prevState };
      tmp[slideCatIdx] = newIdx;
      return tmp;
    });
  };

  const pickSeal = () => {
    console.log('[Sealimage] pickSeal', imageData, location.state.returnUrl);

    switch (_mode) {
      case 'sealimage':
        //新玩家選陣營時挑選紋章
        DCContext.setPickedSeal(imageData);
        navigate(location.state.returnUrl);
        break;

      case 'sealimage_change':
        //玩家修改個人紋章
        DCContext.updateProfile({
          seal_id: imageData.id,
        });
        break;

      case 'sealimage_change_nation':
        DCContext.change_nation_flag({
          seal_id: imageData.id,
        });
        break;
    }
  };

  //edit_profile 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},edit_profile`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[Sealimage] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //success
      navigate(location.state.returnUrl);
    } else {
      console.log(`[Sealimage] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},edit_profile`]?.uuid]);

  //change_nation_flag 結果
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},change_nation_flag`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[Sealimage] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //success
      navigate(location.state.returnUrl);
    } else {
      console.log(`[Sealimage] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},change_nation_flag`]?.uuid]);

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div>
          <div className={styles.titleBox}>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeSlide(e, -1);
              }}
            >
              <div className={styles.arrowL}>
                <img src={arrowL} className={styles.arrow} />
              </div>
            </ClickEffect>
            <div className={styles.title}>{imageData?.name}</div>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeSlide(e, 1);
              }}
            >
              <div className={styles.arrowR}>
                <img src={arrowR} className={styles.arrow} />
              </div>
            </ClickEffect>
          </div>
        </div>

        <div {...swipeHandlers} className={styles.streetImgBox}>
          {/* <div className={styles.streetImgL}><img src={Rcoaw99} className={styles.streetImg}/></div>
          <div className={styles.streetImgR}><img src={Rcoaw98} className={styles.streetImg}/></div>
          <div className={styles.streetImgC}><img src={Rcoaw01} className={styles.streetImg}/></div> */}

          {slides && slideIdxs && (
            <Carousel
              slides={slides}
              goToSlide={slideIdxs[slideCatIdx]}
              offsetRadius={2}
              goToSlideDelay={0}
            />
          )}
        </div>

        <div className={styles.tipsBox}>
          <div className={styles.tipsText}>
            {
              _mode == 'sealimage_change_nation'
                ? tt(`may_change_nation_flag`, {
                    headquarters: DCContext.myUnionNation?.headquarters,
                    commander: DCContext.myUnionNation?.commander?.title,
                  })
                : tt(
                    `nation_rebel_alliance_rule_change_seal_streetview_in_game`,
                  ) /* 反賊聯盟玩家在遊戲中隨時可以更換紋章 */
            }
          </div>
        </div>
      </div>

      <div className={styles.tabBar}>
        {imagesData &&
          imagesData.map((e, i) => {
            return (
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={() => {
                  setSlideCatIdx(i);
                }}
              >
                <div
                  key={i}
                  className={`tab ${i == slideCatIdx ? 'active' : ''}`}
                  style={{ width: '23%' }}
                >
                  <div className={`tabText1`}>{e.name}</div>
                </div>
              </ClickEffect>
            );
          })}
      </div>

      <BtnRing
        color="golden"
        text={tt(`confirm`)}
        callback={() => {
          pickSeal();
        }}
      />

      <Navigator
        navi={{
          navigator: {
            show: false,
          },
        }}
      />
    </IbgDiv>
  );
};
