export const CityBonuses = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [items, setItems] = useState();

  useEffect(() => {
    return () => {};
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[CityBonuses] channel player 未連線');
      return;
    }

    console.log('[CityBonuses] channel player 已連線');
    DCContext.getCityBonuses();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  //room city_bonuses 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},city_bonuses`;
    let _res = DCContext.msgRes[_key]?.res;

    //debug
    //setItems(_debugData.city_bonuses);

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[CityBonuses] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      setItems(_res.payload.city_bonuses);
    } else {
      console.log('city_bonuses error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},city_bonuses`]?.uuid]);

  return (
    <div className={styles.mainBox} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.listBox} style={{}}>
        {items &&
          items.map((el, idx) => {
            return (
              <ClickEffect
                key={idx}
                enabled={true}
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={e => {
                  if (DCContext.showCityBonuses.callback_clickItem) {
                    DCContext.showCityBonuses.callback_clickItem(el.city.id);
                  }
                }}
              >
                <div
                  key={idx}
                  onClick={() => {}}
                  className={styles.itemRow}
                  style={{ backgroundImage: `url(${bgItemGreen})` }}
                >
                  <div className={styles.cityNameText}>{el.city.name}</div>
                  <div className={styles.percentageText}>{el.percentage}%</div>
                  <div className={styles.nationNameText}>{el.nation.name}</div>
                </div>
              </ClickEffect>
            );
          })}
      </div>
    </div>
  );
};

