import React, { useContext, useState, useEffect, useRef } from 'react';
//moment
import moment from 'moment';
import 'moment-timezone';
//
import iConfig from 'iConfig';
import { validImageSrc } from 'lib/funcs';

export default function useValidSrc() {
  const [targetSrc, setTargetSrc] = useState();
  const [validSrc, setValidSrc] = useState();

  useEffect(() => {
    if (!targetSrc) {
      return;
    }
    //console.log('[useValidSrc] targetSrc', targetSrc);

    //react包內的圖檔 || http開頭路徑
    if (targetSrc.startsWith('data:')) {
      setValidSrc(targetSrc);
      return;
    } else if (
      targetSrc.startsWith('/static/') ||
      targetSrc.startsWith('./static/') ||
      targetSrc.startsWith('http')
    ) {
      setValidSrc(targetSrc + `?t=${moment().format('MMDDHH')}`);
      return;
    }

    (async () => {
      const tmpImg = await validImageSrc(targetSrc);
      console.log('[useValidSrc] tmpImg', targetSrc, tmpImg);

      setValidSrc(tmpImg + `?t=${moment().format('MMDDHH')}`);
    })();

    return;

    let preloadImages = [`${iConfig.Media.builtinAssets}${targetSrc}`];
    if (window.deviceInfo?.assetsDL_path) {
      preloadImages.push(`${window.deviceInfo?.assetsDL_path}${targetSrc}`);
    }

    /*async*/ function effect() {
      //console.log('[useValidSrc] PRELOAD', preloadImages);

      const imagesPromiseList = [];
      for (const i of preloadImages) {
        imagesPromiseList.push(
          loadImage(i),
          //fetchUri(i)
        );
      }

      //any => 任一個 promise resolve
      //await 先等待處理結果
      /*await*/ Promise.any(imagesPromiseList)
        .then(value => {
          //console.log("[useValidSrc] resolve", value);
          setValidSrc(value + `?t=${moment().format('MMDDHH')}`);
        })
        .catch(err => {
          //console.log("[useValidSrc] err", err);
          setValidSrc(
            `${iConfig.Media.remoteAssets}${targetSrc}` + `?t=${moment().format('MMDDHH')}`,
          );
        });
    }

    effect();
  }, [targetSrc]);

  useEffect(() => {
    if (!validSrc) {
      return;
    }

    //console.log("[useValidSrc] validSrc", validSrc);
  }, [validSrc]);

  // fetch local file 永遠 response.ok => false
  const fetchUri = src => {
    return fetch(src, { method: 'HEAD' })
      .then(response => {
        //console.log("[useValidSrc] fetchUri success", src, response);
        if (response.ok) {
          return src;
        }
      })
      .catch(error => {
        //console.log("[useValidSrc] fetchUri error", src, error);
      });
  };

  const loadImage = src => {
    return new Promise((resolve, reject) => {
      const img = new Image();

      img.onload = function () {
        //console.log("[useValidSrc] img onload", src);
        resolve(src);
      };
      img.onerror = img.onabort = function () {
        //console.log("[useValidSrc] img onerror", src);
        reject(src);
      };
      img.src = src;
    });
  };

  return { setTargetSrc, validSrc };
}

export function useValidVideoSrc() {
  const [targetSrc, setTargetSrc] = useState();
  const [validSrc, setValidSrc] = useState();

  useEffect(() => {
    if (!targetSrc) {
      setValidSrc(undefined);
      return;
    }
    console.log('[useValidVideoSrc] targetSrc', targetSrc);

    // Imported webpack media and absolute URLs are already complete. Prefixing
    // these with passionfruit creates an invalid file:// URL in the WebView.
    if (
      targetSrc.startsWith('data:') ||
      targetSrc.startsWith('blob:') ||
      targetSrc.startsWith('/static/') ||
      targetSrc.startsWith('./static/') ||
      targetSrc.startsWith('http://') ||
      targetSrc.startsWith('https://') ||
      targetSrc.startsWith('file://')
    ) {
      setValidSrc(targetSrc);
      return;
    }

    let cancelled = false;

    let preloadImages = [`${iConfig.Media.builtinAssets}${targetSrc}`];
    if (window.deviceInfo?.assetsDL_path) {
      preloadImages.push(`${window.deviceInfo?.assetsDL_path}${targetSrc}`);
    }

    /*async*/ function effect() {
      console.log('[useValidVideoSrc] PRELOAD', preloadImages);

      const imagesPromiseList = [];
      for (const i of preloadImages) {
        imagesPromiseList.push(loadVideo(i));
      }

      //any => 任一個 promise resolve
      //await 先等待處理結果
      /*await*/ Promise.any(imagesPromiseList)
        .then(value => {
          console.log('[useValidVideoSrc] resolve', value);
          if (!cancelled) setValidSrc(value);
        })
        .catch(err => {
          console.log('[useValidVideoSrc] err', err);
          if (!cancelled) setValidSrc(`${iConfig.Media.remoteAssets}${targetSrc}`);
        });
    }

    effect();

    return () => {
      cancelled = true;
    };
  }, [targetSrc]);

  useEffect(() => {
    if (!validSrc) {
      return;
    }

    //console.log("[useValidVideoSrc] validSrc", validSrc);
  }, [validSrc]);

  const loadVideo = src => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.onloadstart = function () {
        //console.log("[useValidVideoSrc] onloadstart", src);
        //resolve(src);
        //destoryVideo(video);
      };
      //onloadedmetadata 才能代表該檔案存在
      video.onloadedmetadata = function () {
        console.log('[useValidVideoSrc] onloadedmetadata', src);
        resolve(src);
        destoryVideo(video);
      };
      video.onerror = video.onabort = function () {
        console.log('[useValidVideoSrc] onerror', src);
        reject(src);
        destoryVideo(video);
      };
      video.src = src;
    });
  };

  const destoryVideo = media => {
    //console.log("[useValidVideoSrc] destoryVideo", media.src);
    media.onloadstart = null;
    media.onloadedmetadata = null;
    media.onerror = null;
    media.pause();
    // `src = null` loads a literal URL named "null" and produces Chromium's
    // "no supported source" message. Removing the attribute is enough here.
    media.removeAttribute('src');
  };

  return { setTargetSrc, validSrc };
}
