export const Demos = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  let navigate = useNavigate();
  //
  const [preloadKey, setPreloadKey] = useState(); //ex. demos,3
  const [slides, setSlides] = useState();

  //組 slides
  useEffect(() => {
    if (!DCContext.userProfile || !DCContext.demos) {
      return;
    }

    //slides 組好後，不要因為 profile completed_demo_section 更新發生變動
    if (slides) {
      return;
    }

    //console.log("[Demos] sectionKey", sectionKey, DCContext.demos);

    let tmp = [];
    let tmpSlideIdx = -1;
    props.sectionKeys.map((_key, idx) => {
      if (
        !DCContext.userProfile?.completed_demo_section ||
        _key > DCContext.userProfile?.completed_demo_section
      ) {
        console.log('[Demos] sectionKeys', _key, DCContext.userProfile?.completed_demo_section);
        DCContext.demos?.[_key]?.images?.map((data, idx2) => {
          tmpSlideIdx += 1;

          tmp.push({
            _slideIdx: tmpSlideIdx,
            _type: 'image',
            _sectionKey: _key,
            _sectionFirstRow: idx2 == 0 ? true : false,
            _sectionLastRow: idx2 == DCContext.demos?.[_key]?.images.length - 1 ? true : false,
            _sno: `${idx2 + 1}/${DCContext.demos?.[_key]?.images.length}`,
            _url: data.image,
            ...data,
          });
        });

        DCContext.demos?.[_key]?.videos?.map((data, idx2) => {
          tmpSlideIdx += 1;

          tmp.push({
            _slideIdx: tmpSlideIdx,
            _type: 'video',
            _sectionKey: _key,
            _sectionFirstRow: idx2 == 0 ? true : false,
            _sectionLastRow: idx2 == DCContext.demos?.[_key]?.videos.length - 1 ? true : false,
            _sno: `${idx2 + 1}/${DCContext.demos?.[_key]?.videos.length}`,
            _url: data.path,
            ...data,
          });
        });
      }
    });

    console.log('[Demos] slides', tmp);

    //debug
    //tmp = debugData.slides_3;
    //tmp = debugData.slides;

    setSlides(tmp);
  }, [DCContext.userProfile?.completed_demo_section, DCContext.demos]);

  /* 預載 */

  const { setPreloadImages, imagesPreloaded, preloadedRatio, preloaderReset } = useImagePreloader({
    preloadMode: 'browser', //即使裝置也使用 browser 下載模式
  });
  //const preloadKey = "profile";

  useEffect(() => {
    if (!DCContext.preloads?.[preloadKey]) {
      return;
    }

    console.log('[Demos] [preload] setPreloadImages', DCContext.preloads?.[preloadKey]);

    setPreloadImages(DCContext.preloads?.[preloadKey]);
  }, [DCContext.preloads?.[preloadKey]]);

  useEffect(() => {
    console.log('[Demos] [preload] imagesPreloaded', imagesPreloaded, { ...DCContext.preloads });

    //清空本次該預載的
    if (imagesPreloaded && DCContext.preloads?.[preloadKey]) {
      DCContext.setPreloads(preState => {
        let tmp = { ...preState };
        tmp[preloadKey] = null;
        delete tmp[preloadKey];

        return tmp;
      });
    }
  }, [imagesPreloaded]);

  const ckeckPreloads = _preloadKey => {
    console.log('[Demos] [preload] ckeckPreloads', _preloadKey);

    preloaderReset();
    setPreloadKey(_preloadKey);
  };

  //為了先準備好 slides，避免 useTransition 時 slides 是空的
  return (
    <>
      {!slides ||
        !DCContext.preloads ||
        (DCContext.preloads?.[preloadKey] && <Loading preloadedRatio={preloadedRatio} />)}
      {slides && <_Slides slides={slides} callback_ckeckPreloads={ckeckPreloads} {...props} />}
    </>
  );
};

export const _Slides = ({ slides, ...props }) => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  //const [slides, setSlides] = useState();
  const [slideIdx, setSlideIdx] = useState(0);

  useEffect(() => {
    console.log('[Demos] props', props);
  }, []);

  useEffect(() => {
    if (!slides) {
      return;
    }

    console.log(`[Demos] slideIdx`, slideIdx, slides?.length, slides?.[slideIdx]);
  }, [slideIdx, slides]);

  const nextSlide = () => {
    const newSlideIdx = slideIdx + 1;

    console.log('[Demos] nextSlide()', slideIdx, newSlideIdx);

    //檢查 是否全部結束
    if (newSlideIdx >= slides.length) {
      console.log('[demos] [Slide] slides 全部結束');
      return;
    }

    //下一頁
    setSlideIdx(newSlideIdx);
  };

  /* 轉場特效 */

  const aniPhase = useRef('out'); //in || out

  const [aniStyles, aniApi] = useSpring(() => ({
    // from: { _x: 0},
    // to: { _x: 1 },
  }));

  const nextAni = () => {
    console.log('[Demos] nextAni aniPhase prev', aniPhase.current);
    aniPhase.current = aniPhase.current == 'out' ? 'in' : 'out';
    console.log('[Demos] nextAni aniPhase new', aniPhase.current);

    // in
    let aniProps = {
      from: { _x: 0, opacity: slides[slideIdx].fade_in ? 0 : 1 }, //_x 避免 opacity 相等時不觸發 onRest
      to: { _x: 1, opacity: 1 },
      config: {
        duration: slides[slideIdx].fade_in ? 500 : 1,
      },
      onRest: () => {
        console.log(`[Demos] nextAni (IN) onRest`, slideIdx, aniPhase.current);
      },
    };

    // out
    if (aniPhase.current == 'out') {
      aniProps = {
        from: { _x: 0, opacity: 1 },
        to: { _x: 1, opacity: slides[slideIdx].fade_out ? 0 : 1 },
        config: {
          duration: slides[slideIdx].fade_out ? 500 : 1,
        },
        onRest: () => {
          console.log(`[Demos] nextAni (OUT) onRest`, slideIdx, aniPhase.current);

          //更新教學已讀進度 (在 out.onRest 實行避免最後一個 slide 一出現就因為教學完成被移除)
          if (slides[slideIdx]._sectionLastRow) {
            console.log('[demos] nextAni 更新教學已讀進度', slides[slideIdx]._sectionKey);
            //debug
            DCContext.complete_demo({
              section: `${slides[slideIdx]._sectionKey}`,
            });
          }

          nextSlide();
        },
      };
    }

    aniApi.start(aniProps);
  };

  useEffect(() => {
    console.log(
      '[Demos] slideIdx',
      slideIdx,
      `(${slides[slideIdx]._sno}) (${slideIdx + 1}/${slides?.length})`,
      slides[slideIdx]._sectionLastRow,
    );

    //檢查 preloads
    if (slides[slideIdx]._sectionFirstRow) {
      props.callback_ckeckPreloads(`demos,${slides?.[slideIdx]?._sectionKey}`);
    }

    //
    nextAni();
  }, [slideIdx]);

  const skip = () => {
    console.log('[demos] skip', props?.skipSectionKey);

    if (!props?.skipSectionKey) {
      return;
    }

    showModal_confirm({
      confirm: {
        //確定要跳過新手教學
        message: { i18nKey: `demos_skip_confirm` },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm();

              //
              DCContext.complete_demo({
                section: `${props?.skipSectionKey}`,
              });
            },
          },
        ],
      },
    });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Home] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  // return (
  //   <div  className={styles.rootContainer}>
  //     <div className={styles.mainBox}>

  //     <Slide slide={slides[slideIdx]} nextSlide={nextSlide}/>

  // 		</div>
  // 	</div>
  // )

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <animated.div className={styles.slideBox} style={{ ...aniStyles }}>
          <Slide slide={slides[slideIdx]} nextAni={nextAni} />
        </animated.div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE3.mp3` }}
          onClick={() => {
            skip();
          }}
        >
          <div className={styles.skipText}>{tt('skip') /* 跳過 */}</div>
        </ClickEffect>

        {/* //debug */}
        {/* <div style={{position: 'absolute', left: '0', top: '0', color: 'white'}}>
          {slideIdx}
        </div> */}

        <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
          <Confirm {...modalProps_confirm.confirm} />
        </Imodal>
      </div>
    </IbgDiv>
  );
};

const Slide = ({ slide, nextAni, ...props }) => {
  const DCContext = useDCContext();
  const videoRef = useRef();
  //
  const clickSensorStyle = slide.click_area
    ? {
        left: `${slide.click_area[0].x}%`,
        top: `${slide.click_area[0].y}%`,
        width: `${slide.click_area[1].x - slide.click_area[0].x}%`,
        height: `${slide.click_area[1].y - slide.click_area[0].y}%`,
      }
    : {};

  useEffect(() => {
    console.log('[demos] [Slide] slide', slide);

    return () => {
      console.log('[demos] [Slide] unmount', slide);
    };
  }, []);

  useEffect(() => {
    DCContext.playMusic(slide?.music);
  }, [slide?.music]);

  return (
    <>
      {slide?._type == 'image' ? (
        <>
          <Iimg
            className={styles.guideImg}
            src={slide._url}
            transition={false}
            onReady={() => {}}
          />
          <ClickEffect
            effect={{ flash: false, sound: slide.click_sound_effect }}
            onClick={() => {
              nextAni();
            }}
          >
            <div className={styles.clickSensor} style={clickSensorStyle}>
              {slide.click_area && (
                <div className={styles.clickSensorImgBox}>
                  <img
                    className={`${styles.clickSensorImg} rotation_highlightCircle`}
                    style={{}}
                    src={highlightCircle}
                  />
                </div>
              )}
            </div>
          </ClickEffect>
        </>
      ) : slide?._type == 'video' ? (
        <Ivideo
          key={slide._url}
          innerRef={videoRef}
          src={slide._url}
          //
          className={styles.videoFit}
          preload="auto"
          autoPlay="autoPlay"
          playsInline="playsInline"
          onCanPlay={() => {
            console.log('[Demos] videoRef onCanPlay', slide._url);
            void safePlayMedia(videoRef.current);
          }}
          onCanPlayThrough={() => {}}
          onEnded={() => {
            console.log('[Demos] videoRef onEnded', slide._url);
            //
            nextAni();
          }}
          onError={() => {
            console.log('[Demos] videoRef onError', slide._url);
            //
            nextAni();
          }}
          //onClick={() => {videoRef.current.play();}}
        />
      ) : (
        <></>
      )}
    </>
  );
};

