import React, { useContext, useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useRoutes, useNavigate } from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
import { filter } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Contacts.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ChatRooms } from 'component/Chat/ChatRooms';
import { ClickEffect } from 'componentx/ClickEffect';
//
import iconMsg from 'assets/img/icons/iconMsg.png';
import iconSearch from 'assets/img/iconSearch.png';
import iconBack from 'assets/img2/navigator/iconBack.png';

export const Applicants = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [contacts, setContacts] = useState();
  const [searchedUsers, setSearchedUsers] = useState();
  const [mode, setMode] = useState();

  useEffect(() => {}, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Applicants] channel player 未連線');
      return;
    }

    console.log('[Applicants] channel player 已連線');
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionChannelTopic]) {
      console.log('[Applicants] channel union 未連線');
      return;
    }

    console.log('[Applicants] channel union 已連線');
    DCContext.getUnionApplicants(true);
  }, [ChannelContext.channels[DCContext.unionChannelTopic]]);

  useEffect(() => {
    if (!DCContext.unionApplicants) {
      return;
    }

    //console.log("[Applicants] DCContext.unionApplicants", DCContext.unionApplicants);
    setContacts(DCContext.unionApplicants);
  }, [DCContext.unionApplicants]);

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    //關閉鍵盤
    document.activeElement.blur();

    const data = {
      keyword: values.keyword.trim(),
    };

    if (!data.keyword) {
      console.log('[Applicants] input no value');
      return;
    }

    console.log('[Applicants] search keyword', data.keyword);

    let tmp = filter(contacts, o => {
      return o.id == data.keyword || o.name.includes(data.keyword);
    });

    console.log('[Applicants] search result', tmp);

    setSearchedUsers(tmp);
  };

  //
  const goBack = () => {
    if (searchedUsers) {
      setSearchedUsers(null);
    } else {
      navigate('/user/unions');
    }
  };

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div className={styles.titleBarBox}>
          <div className={`${styles.titleBar} ${styles.titleBarActive} ${styles.titleBar_search}`}>
            {
              searchedUsers
                ? tt(`search_result`) /* 搜尋結果 */
                : tt(`union_join_applies`) /* 加盟申請 */
            }
          </div>
        </div>

        <div className={styles.searchbarBox}>
          <img className={styles.iconSearch} src={iconSearch} />
          <div className={styles.searchInputBox}>
            <Form
              action=""
              form={form}
              name="search_form"
              onFinish={onFinish}
              initialValues={{}}
              // labelCol={{ span: 8, className: styles.colTitle }}
              // wrapperCol={{ span: 16, className: styles.colContent }}
              colon={false}
            >
              <Form.Item
                required={false} //不顯示必填星號
                noStyle
                name="keyword"
                // label={<div className={styles.colTitle}>聯盟名稱</div>}
                // rules={[{
                //   required: true, message: `請填寫聯盟名稱`
                // },]}
              >
                <Input
                  type="search"
                  bordered={true}
                  className={`opacity0 ${styles.inputBox}`}
                  placeholder={tt(`search_applicant`) /* 搜尋申請者 */}
                />
              </Form.Item>
            </Form>
          </div>
        </div>

        <ChatRooms _type="union_applicants" rooms={searchedUsers || contacts} />
      </div>

      <Navigator
        navi={{
          navigator: {
            show: false,
          },
          back: {
            callback: goBack,
            //position: 'LEFT',
            show: true,
          },
        }}
      />
    </IbgDiv>
  );
};
