  useEffect(() => {
    // console.log("[Character] actorsSkillpoints", props.actorsSkillpoints, props.characterData);

    // actorsSkillpoints 更新比 characterData 早，導致 id 比對不到，
    // 因為 actorsSkillpoints 的 id 是新一回合的，characterData 的 id 是上一回合的，
    // 因此，若比對不到則不處理，等下 characterData 更新時再整理一遍

    let tmpPoints = props.characterData.skill_point;
    if (props.actorsSkillpoints[props.characterData.id]) {
      tmpPoints = tmpPoints + props.actorsSkillpoints[props.characterData.id].skill_point;
    }
    setSkillPoints(tmpPoints);
  }, [props.characterData, props.actorsSkillpoints]);

