    if (!props.characterData) {
      return;
    }

    aniApi_bloodNum.start({
      delay: 200,
      from: { transform: `translate(-50%, 0%)`, opacity: 1 },
      to: [
        { transform: `translate(-50%, -50%)`, opacity: 1 },
        { transform: `translate(-50%, -50%)`, opacity: 0 },
      ],
    });
