import React, { useState, useEffect } from 'react';
import { Row, Col } from 'antd';
import { useNavigate } from 'react-router-dom';
import { ClickEffect } from 'componentx/ClickEffect';
import { useDCContext } from 'lib/DCContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useI18n } from 'lib/useI18n';
// 遊戲公版彈窗：Imodal (提供尺寸/遮罩/右上關閉鍵/音效) + bgRF.png 白色底圖，
// 與 ItemQuantity / Playerinfo / Announcements 等既有視窗同一套。
import { Imodal } from 'componentx/Imodal';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import bgRF from 'assets/img/modal/bgRF.png';
// 右下「收取 / 本日已收取」按鍵底圖 (規格 p.31-32)：與 actor_pools 其他場景共用的緞帶按鍵。
//   可收取 → btnRight_active.png (亮白)；已收取 → btnRight.png (灰)。
import icon_circle_check_green from 'assets/img2/icon_circle_check_green.png';
import btnRight from 'assets/img2/actor_pools/btnRight.png';
import btnRightActive from 'assets/img2/actor_pools/btnRight_active.png';
import iConfig from 'iConfig';
import { kmb } from '../utils/format';
import { UwFitText } from './UwFitText';
import { uwImage } from '../assets/uwImages';
import styles from './UwPlayerinfoExtras.module.scss';

// uw05.png (工作站) / uw06.png (王) — 玩家資訊視窗左下按鍵底圖 (規格 p.30)。
// 改由 bundle 出貨 (見 assets/uwImages)。
const uwImg = uwImage;

/*
 * UW (Under World) — 玩家資訊視窗追加項目。
 * 規格書第 30–32 頁，資料來自 profile 與 uw_player_info 後端事件。
 *
 * 三個對外元件 (均供 Playerinfo.js 注入)：
 *   1. <UwPlayerLocation/>           — 派系下方「玩家位置」一列 (users.city_id → cities.name)
 *   2. <UwWorkstationsButton/>       — 視窗偏左下角「工作站」/「{城}王」(uw05.png / uw06.png)
 *   3. <UwWorkstationsPopup/>        — 由 (2) 內部觸發；本檔輸出時不需要外部使用
 *
 * 接後端時：
 *   - uw05.png / uw06.png 由 remoteAssets 載入；右下收取鍵用 actor_pools/btnRight[_active].png。
 *   - 工作站清單視窗使用遊戲公版彈窗 (Imodal + bgRF.png)，收取結果用公版 BundleReceivedAlert。
 */

const SE1 = '/audio/sound_effect/SE1.mp3';
// 同 UwPortalCollectButton：BundleReceivedAlert 沒拿到 sound_effect 就整頁靜音。
const SE_COLLECT_ITEM = '/audio/sound_effect/collect_item.mp3';

/* ── (1) 派系下方「玩家位置」(規格 p.30) ──
 * 取被檢視玩家的 users.city_id → cities.name 翻譯 (後端 profile.city_name)。
 * 顯示與點擊跳轉同源 (city_id)，修正「顯示台北卻跳曼谷」的來源不一致。
 * 規格：不需即時刷新 — 開窗時 (本元件 mount) 讀一次快照即可。 */
export const UwPlayerLocation = () => {
  const { tt } = useI18n();
  const navigate = useNavigate();
  const DCContext = useDCContext();
  const player = DCContext?.playerInfo;
  // 開窗時的一次性快照 (useState 初始化只執行一次)。
  const [snapshot] = useState(() => ({
    cityId: player?.city_id ?? null,
    cityName: player?.city_name ?? null,
  }));

  if (snapshot.cityId == null) return null; // 無所在城鎮 → 不顯示此列

  const onClick = () => {
    // 跳轉到「此」城鎮 (與顯示同一 city_id)，focus 到地圖對應城。
    navigate('/attacks/attackmap', {
      state: { focus_city_id: snapshot.cityId },
    });
  };
  return (
    <Row wrap={false} align="middle" className={styles.locationRow}>
      <Col span={6} className={styles.locTitle}>
        {tt(`uw_player_location`) /* 玩家位置 */}
      </Col>
      {/* 地名左側圓形按鍵 — 與「派系」左側同一顆，點擊效果同直接點文字 */}
      <ClickEffect effect={{ sound: SE1 }} onClick={onClick}>
        <Col span={2} className={styles.locCircle}>
          <img src={icon_circle_check_green} className={styles.locIcon} alt="" />
        </Col>
      </ClickEffect>
      <Col flex="auto">
        <ClickEffect effect={{ sound: SE1 }} onClick={onClick}>
          <span className={styles.locContent}>{snapshot.cityName}</span>
        </ClickEffect>
      </Col>
    </Row>
  );
};

/* ── (2) 視窗偏左下角「工作站」/「{城}王」按鍵 + popup 觸發 (規格 p.30-31) ──
 * 底圖：非王 uw05.png、王 uw06.png。開窗時向後端取一次 uw_player_info
 * (該玩家的王號 / 每日產量 / 各城工作站)，王號取 points 加總較高的城；無則「工作站」。 */
export const UwWorkstationsButton = () => {
  const { tt } = useI18n();
  const [open, setOpen] = useState(false);
  const [info, setInfo] = useState(null); // uw_player_info payload
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const topic = DCContext?.playerChannelTopic;
  const playerId = DCContext?.playerInfo?.id;

  // 開窗 (本元件 mount) 時取一次該玩家的工作站資料 (規格：不需即時刷新)。
  useEffect(() => {
    if (!topic || playerId == null) return;
    ChannelContext.sendMessage({
      topic,
      event: 'uw_player_info',
      message: { user_id: playerId },
    });
  }, [topic, playerId]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic || r.event !== 'uw_player_info') return;
    if (r.res?.status === 'ok' && r.res.payload?.user_id === playerId) {
      setInfo(r.res.payload);
    }
  }, [ChannelContext.sendMessageRes]); // eslint-disable-line react-hooks/exhaustive-deps

  const kingCityName = info?.king_city_name || null;
  const isKing = !!kingCityName;
  // i18n：王 uw_king_title「{{city_name}}王」/ 非王 uw_workstations_label「工作站」
  const label = isKing
    ? tt(`uw_king_title`, { city_name: kingCityName })
    : tt(`uw_workstations_label`);

  return (
    <>
      <div className={styles.btnRow}>
        <ClickEffect effect={{ sound: SE1 }} onClick={() => setOpen(true)}>
          <div className={styles.workstationButton}>
            <div
              className={styles.workstationButtonImage}
              style={{
                backgroundImage: `url(${uwImg(isKing ? 'uw06.png' : 'uw05.png')})`,
              }}
            ></div>
            {/* 王號 (例：九龍城王) 長度隨城名變動，過長時等比縮小而不折行 (回報)。
                這一列是靠左對齊，故 origin 用 left。 */}
            <UwFitText className={styles.workstationButtonText} origin="left">
              {label}
            </UwFitText>
          </div>
        </ClickEffect>
      </div>
      {open && <UwWorkstationsPopup info={info} onBack={() => setOpen(false)} />}
    </>
  );
};

/* link 樣式的城鎮連結 (規格 p.31-32)：Noto Sans Bold #9caaaa。
   點擊跳轉至對應城鎮介面；cities.hidden = TRUE 時點擊無反應 (且不給 pointer)。 */
const CityLink = ({ city, onCityClick, children }) => {
  if (city?.hidden) {
    return <span className={`${styles.link} ${styles.linkDisabled}`}>{children}</span>;
  }
  return (
    <ClickEffect effect={{ sound: SE1 }} onClick={() => onCityClick(city)}>
      <span className={styles.link}>{children}</span>
    </ClickEffect>
  );
};

/* ── (3) 工作站清單 popup (規格 p.31-32) — 真實資料版 ── */
const UwWorkstationsPopup = ({ info, onBack }) => {
  const { tt } = useI18n();
  const navigate = useNavigate();
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const topic = DCContext?.playerChannelTopic;

  const cities = info?.cities || []; // 後端已依 points desc / inserted_at asc 排序
  const organization = info?.organization || '';
  const playerName = info?.player_name || '';
  // 稱號來源改用 cities 內 is_king 者 (而非 king_titles 字串)，才有 city_id / hidden 可供連結跳轉。
  const kingCities = cities.filter(c => c.is_king);
  const dailyOutputs = info?.org_daily_output || []; // [{prop_name, quantity}]

  // 收取僅在檢視自己且本日尚可收取時可點 (規格 p.32)。
  const [collectedLocal, setCollectedLocal] = useState(false);
  const canCollect = !!info?.is_self && !!info?.can_collect_all && !collectedLocal;

  // 收取結果改用遊戲公版「恭喜獲得」視窗 (BundleReceivedAlert)，與每日禮包/公告同一套。
  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });
  const showModal_BRA = exProps =>
    setModalProps_BRA(prev => ({ ...prev, ...exProps, visible: true }));
  const callbackModal_BRA = () => setModalProps_BRA(prev => ({ ...prev, visible: false }));

  const onCityClick = c => {
    if (c.hidden) return; // 隱藏城 → 點擊無反應
    onBack();
    navigate('/attacks/attackmap', { state: { focus_city_id: c.city_id } });
  };

  const onCollect = () => {
    if (!canCollect || !topic) return;
    ChannelContext.sendMessage({ topic, event: 'uw_collect_all', message: {} });
  };

  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic || r.event !== 'uw_collect_all') return;
    if (r.res?.status === 'ok') {
      const rewards = r.res.payload?.rewards || [];
      setCollectedLocal(true);
      DCContext.getProfile && DCContext.getProfile(true);
      // 有產出才跳「恭喜獲得」；無產出不彈窗 (按鍵已轉為本日已收取)。
      if (rewards.length > 0) {
        showModal_BRA({
          params: {
            title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
            showBg: true,
            bundleItems: {
              items: [rewards],
              sound_effect: {
                items: r.res.payload?.sound_effect?.items || SE_COLLECT_ITEM,
              },
            },
          },
        });
      }
    }
  }, [ChannelContext.sendMessageRes]); // eslint-disable-line react-hooks/exhaustive-deps

  const collected = !!info?.is_self && (!info?.can_collect_all || collectedLocal);

  return (
    <>
      {/* 遊戲公版彈窗 (Imodal + bgRF 白底)：Imodal 提供尺寸/遮罩/右上關閉鍵/SE1 音效，
        關閉 (callback) = 返回此玩家資訊視窗，而非關掉整個玩家資訊 (規格 p.32)。 */}
      <Imodal
        visible={true}
        destroyOnClose={true}
        /* 尺寸與玩家資訊視窗 (Playerinfo) 一致 (index.js modalProps_playerInfo) */
        ratio={0.82}
        callback={onBack}
      >
        <div className={styles.popupFrame} style={{ backgroundImage: `url(${bgRF})` }}>
          <div className={styles.popupScroll}>
            {/* (a) 擁有稱號 — 僅在有稱號時整段顯示。
                 稱號為同一行、以空白分隔的 link (點擊跳該城；hidden 無反應)。
                 由 cities 內 is_king 者推導，才能取得 city_id / hidden 供跳轉判斷。 */}
            {kingCities.length > 0 && (
              <>
                <div className={styles.text}>
                  {tt(`uw_player_titles_header`, { player_name: playerName })}
                </div>
                <div className={styles.text}>
                  {kingCities.map((c, i) => (
                    <React.Fragment key={c.city_id}>
                      {i > 0 && ' '}
                      <CityLink city={c} onCityClick={onCityClick}>
                        {tt(`uw_king_title`, { city_name: c.city_name })}
                      </CityLink>
                    </React.Fragment>
                  ))}
                </div>
              </>
            )}

            {/* (b) 每日產量 — 同一行、空白分隔，格式 {數量KMB}{資源名} */}
            <div className={styles.text}>{tt(`uw_org_daily_output_header`, { organization })}</div>
            <div className={styles.text}>
              {dailyOutputs.map(o => `${kmb(o.quantity)}${o.prop_name}`).join(' ')}
            </div>

            {/* (c) 工作站 — 每城一行：<link>城鎮</link>：Lv{等級} {工作站} 空白分隔 */}
            <div className={styles.text}>{tt(`uw_org_workstations_header`, { organization })}</div>
            {cities.map(c => (
              <div key={c.city_id} className={styles.text}>
                <CityLink city={c} onCityClick={onCityClick}>
                  {c.city_name}
                </CityLink>
                ：{(c.workstations || []).map(w => `Lv${w.level} ${w.ws_name}`).join(' ')}
              </div>
            ))}
          </div>

          {/* 右下固定按鍵 (規格 p.31-32)：收取 (檢視自己時顯示) — 可收 / 已收 (50% 透明度)。
            底圖用 actor_pools 共用緞帶按鍵；文案走 i18n：
            uw_collect_all「收取」/ uw_collected_all「本日已收取」。 */}
          {info?.is_self && (
            <ClickEffect effect={{ sound: SE1 }} onClick={onCollect}>
              <div className={`${styles.popupCollect} ${collected ? styles.popupCollectDone : ''}`}>
                <img
                  className={styles.popupCollectImg}
                  src={collected ? btnRight : btnRightActive}
                  alt=""
                />
                <div className={styles.popupCollectText}>
                  {collected ? tt('uw_collected_all') : tt('uw_collect_all')}
                </div>
              </div>
            </ClickEffect>
          )}
        </div>
      </Imodal>

      {/* 收取結果：遊戲公版「恭喜獲得」視窗 */}
      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </>
  );
};
