import React, { useContext, useState, useEffect, useRef } from 'react';
import { useSpring, animated } from '@react-spring/web';
import iConfig from 'iConfig';
import { useValidVideoSrc } from 'componentx/useValidSrc';

export const Ivideo = ({ innerRef, src, ...props }) => {
  const { setTargetSrc, validSrc } = useValidVideoSrc();

  useEffect(() => {
    console.log('[Ivideo] props', props);
  }, []);

  useEffect(() => {
    if (!src) {
      return;
    }

    setTargetSrc(src);
  }, [src]);

  useEffect(() => {
    if (!validSrc) {
      return;
    }

    console.log('[Ivideo] validSrc', validSrc);
  }, [validSrc]);

  return !validSrc ? <></> : <video key={validSrc} ref={innerRef} {...props} src={validSrc} />;
};
