import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Teams } from 'component/Teams';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Attackteams.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { PopupMessagesIcon } from 'component/modal/PopupMessagesIcon';

export const Attackteams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  const [teams, setTeams] = useState([]);
  const [actors, setActors] = useState([]);
  const team_id = useRef();

  let mode = props.mode;
  //
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;
  //
  const cityId = location.state.cityId;

  useEffect(() => {
    console.log('[Attackteams] useParams: ', mode, teamIdx, location, cityId);
  }, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    //todo
    if (!cityId) {
      console.log('[Attackteams] error, no cityId');
      return;
    }

    //
    console.log('[Attackteams] playMusic');
    //DCContext.playMusic(`${DCContext.userProfile.music}`);
    DCContext.playMusic(iConfig.battleMusic);
  }, [DCContext.userProfile, teamIdx]);

  //new_attack 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`]) {
      return;
    }

    console.log('[Attackteams] player,new_attack', {
      ...DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`].res,
    });

    if (
      DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`].res.status == 'error' &&
      DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`].res.error.energy_boost_options
    ) {
      //能量不足
      let energy_boost_options =
        DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`].res.error
          .energy_boost_options;
      console.log('[Attackteams] energy_boost_options', energy_boost_options);

      showModal_confirm({
        confirm: {
          /*能量不足，立即補充能量?*/
          message: { i18nKey: `replenish_energy_confirm`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                DCContext.showEnergyboostModal();
              },
            },
            // {
            // 	text: {i18nKey:`...`},
            // 	callback: ()=>{ console.log("2"); callbackConfirm({}) }
            // },
          ],
        },
      });
    } else if (DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`].res.status == 'ok') {
      //new_attack 成功
      console.log('player,new_attack ok');
      navigate(`/story/before_attack/${cityId}`);

      // let url = `/story/before_attack/${cityId}`;
      // let go_url = `./transporter.html?go_url=${url}`;
      // console.log('[Attackteams] go_url', go_url);
      // window.location.assign(go_url);
    } else {
      console.log('player,new_attack error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},new_attack`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},new_attack`]?.uuid]);

  /* */

  const clickFightCallback = ({ team_id = 0 } = {}) => {
    console.log('[Attackteams] clickFightCallback', team_id);

    DCContext.newAttack({
      city_id: cityId,
      team_id: team_id,
    });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams
        mode={mode}
        showFightBtn={true}
        teamIdx={teamIdx}
        clickFightCallback={clickFightCallback}
      />

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </IbgDiv>
  );
};
