export const Unions = () => {
  /* i18n */
  const { tt } = useI18n();
  const { i18n, ready } = useTranslation();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [unions, setUnions] = useState();
  const [searchedUnions, setSearchedUnions] = useState();
  const [unionContacts, setUnionContacts] = useState();
  const [searchedUnionContacts, setSearchedUnionContacts] = useState();
  //
  const quitChannelName = useRef();

  useEffect(() => {
    return () => {
      console.log(`[Unions] quitChannelName.current`, quitChannelName.current);

      ChannelContext.leaveChannel({
        topic: quitChannelName.current,
        params: { fake: 'Unions' },
      });
    };
  }, []);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Unions] channel player 未連線');
      return;
    }

    console.log('[Unions] channel player 已連線');

    //
    DCContext.getUnions(true);
    DCContext.getUnionApplicants(true);
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.unionContactsChannelTopic) {
      return;
    }

    //加入 channel unioncontacts 讓 server 知道玩家目前在”聯盟“畫面
    ChannelContext.joinChannel({
      topic: DCContext.unionContactsChannelTopic,
      params: { fake: '1' },
      callback: res => {
        console.log(`[Unions] channel ${DCContext.unionContactsChannelTopic} join res`, res);
      },
    });

    quitChannelName.current = DCContext.unionContactsChannelTopic;
  }, [DCContext.unionContactsChannelTopic]);

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionContactsChannelTopic]) {
      console.log(`[Contacts] channel ${DCContext.unionContactsChannelTopic} 未連線`);
      return;
    }

    //協議：每次進到畫面重取，避免在其他畫面某聯絡人被解除聯絡人導致資料變更
    DCContext.getUnionContacts(true);
  }, [ChannelContext.channels[DCContext.unionContactsChannelTopic]]);

  useEffect(() => {
    if (!DCContext.unions) {
      return;
    }

    console.log('[Unions] DCContext.unions', DCContext.unions);
    setUnions(DCContext.unions);
  }, [DCContext.unions]);

  useEffect(() => {
    if (!DCContext.unionContacts) {
      return;
    }

    console.log('[Unions] DCContext.unionContacts', DCContext.unionContacts);

    //排序：聯盟公告 聯盟頻道 最新發言聯天室
    let tmp2 = lodash_orderBy(
      DCContext.unionContacts,
      [
        'roomType',
        o => {
          return o.last_message?.inserted_at || '';
        },
      ],
      ['asc', 'desc'],
    );
    console.log('[Unions] tmp2', tmp2);
    setUnionContacts(tmp2);
  }, [DCContext.unionContacts]);

  const doRecommendUnion = () => {
    // showModal_confirm({
    //   confirm: {
    //     message: tt('disabled_function_this_phase') /*'本階段未開放此功能'*/,
    //     buttons: [
    //       {
    //         text: {i18nKey:`confirm`},
    //         callback: ()=>{
    //           callbackConfirm({});
    //         }
    //       },
    //     ]
    //   }
    // });

    // return;

    let tmpUnions = DCContext.getRecommendUnions({ quantity: 5 });
    console.log('[Unions] doRecommendUnions', tmpUnions);
    setSearchedUnions(tmpUnions);
  };

  const joinUnionSwitch = () => {
    DCContext.unionEdit({ free_join: !DCContext.myUnion?.free_join });
  };

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    //關閉鍵盤
    document.activeElement.blur();

    const data = {
      keyword: values.keyword.trim(),
    };

    if (!data.keyword) {
      console.log('[Unions] input no value');
      return;
    }

    setSearchedUnions();
    setSearchedUnionContacts();

    if (isNaN(data.keyword)) {
      //console.log("[Unions] is not Integer", data);

      let tmp = lodash_filter(unionContacts, o => {
        return o.name?.includes(data.keyword);
      });

      console.log('[Unions] search result', tmp);

      setSearchedUnionContacts(tmp);
    } else {
      //console.log("[Unions] isInteger", data);

      let tmp = lodash_filter(unions, o => {
        return o.id == data.keyword;
      });

      console.log('[Unions] search result', tmp);

      setSearchedUnions(tmp);
    }
  };

  /* 這一段 聯絡人 聯盟 相同 */

  //request_contact 聯絡人邀請 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},request_contact`;
    let _res = DCContext.msgRes[_key]?.res;

    //被邀方會收到 broadcast
    //邀請方通常是在搜尋玩家結果頁，沒有 update_data 的對象，所以要自己更新資料
    //(不是 contacts union_contacts contact_requests 之一)
    afterContactsApi(_key, _res);
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},request_contact`]?.uuid]);

  //withdraw_contact 聯絡人邀請撤回 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},withdraw_contact`;
    let _res = DCContext.msgRes[_key]?.res;

    //被撤回方會收到 broadcast
    //撤回方通常是在搜尋玩家結果頁，沒有 update_data 的對象，所以要自己更新資料
    //(不是 contacts union_contacts contact_requests 之一)
    afterContactsApi(_key, _res);
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},withdraw_contact`]?.uuid]);

  //改成 API response update_data
  //reject_contact 聯絡人邀請拒絕 結果
  // useEffect(()=>{
  // 	let _key = `${DCContext.playerChannelTopic},reject_contact`;
  //   let _res = DCContext.msgRes[_key]?.res;

  //   afterContactsApi(_key, _res);

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},reject_contact`]?.uuid]);

  //改成 API response update_data
  //accept_contact 聯絡人邀請接受 結果
  // useEffect(()=>{
  // 	let _key = `${DCContext.playerChannelTopic},accept_contact`;
  //   let _res = DCContext.msgRes[_key]?.res;

  //   afterContactsApi(_key, _res);

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},accept_contact`]?.uuid]);

  //改成 API response update_data
  //block_contact 聯絡人封鎖 結果
  // useEffect(()=>{
  // 	let _key = `${DCContext.playerChannelTopic},block_contact`;
  //   let _res = DCContext.msgRes[_key]?.res;

  //   afterContactsApi(_key, _res);

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},block_contact`]?.uuid]);

  //改成 API response update_data
  //unblock_contact 聯絡人封鎖解除 結果
  // useEffect(()=>{
  // 	let _key = `${DCContext.playerChannelTopic},unblock_contact`;
  //   let _res = DCContext.msgRes[_key]?.res;

  //   afterContactsApi(_key, _res);

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},unblock_contact`]?.uuid]);

  /* 這一段 聯絡人 聯盟 處理不同 */
  const afterContactsApi = (_key, _res) => {
    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Contacts] ${_key}`, { ..._res });

    if (_res.status == 'ok') {
      if (searchedUnionContacts) {
        //搜尋模式，重新執行搜尋
        form.submit();
      }

      DCContext.getUnionContacts(true);
    } else {
      //todo error處理
    }
  };

  //2024-02-22 改為 player:x broadcast update_data 更新 union_contacts
  //收到對方訊息
  // useEffect(()=>{
  // 	console.log("[Unions] receivedRoomMessages", {...DCContext.receivedRoomMessages});

  //   if (!DCContext.receivedRoomMessages){
  //     return;
  //   }

  //   if (DCContext.myUnion){
  //     DCContext.getUnionContacts(true);
  //   }

  //   //清空最新留言
  //   DCContext.setReceivedRoomMessages(null);

  // }, [DCContext.receivedRoomMessages]);

  //2024-02-22 改為 player:x broadcast update_data 更新 union_contacts
  //收到對方收回訊息
  // useEffect(()=>{
  // 	console.log("[Unions] recalledRoomMessages", {...DCContext.recalledRoomMessages});

  //   if (!DCContext.recalledRoomMessages){
  //     return;
  //   }

  //   if (DCContext.myUnion){
  //     DCContext.getUnionContacts(true);
  //   }

  //   //清空最新收回留言
  //   DCContext.setRecalledRoomMessages(null);

  // }, [DCContext.recalledRoomMessages]);

  //點擊聯絡人文字部分
  const clickContactCallback = roomInfo => {
    console.log('[Unions] clickContactCallback', roomInfo);

    if (roomInfo.room_id) {
      //進入聊天室
      // DCContext.enterChatRoom({
      //   room_id: roomInfo.room_id,
      //   callback: (res)=>{
      //     console.log("[Contacts] enterChatRoom res", res);
      //     if (res.res.status == "ok"){
      //       navigate(`/chatroom/${roomInfo.room_id}`);
      //     }
      //   }
      // });

      //改直接進入
      navigate(`/chatroom/${roomInfo.room_id}`, {
        state: {
          exRoomInfo: roomInfo,
        },
      });
    }
  };

  //從搜尋頁 => 回上一頁
  const goBackFromSearch = () => {
    setSearchedUnionContacts();
    setSearchedUnions();
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });
  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };
  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };
  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  //debug
  //DCContext.setMyUnion(null);

  return !DCContext.userProfile ? (
    <></>
  ) : (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div className={styles.titleBarBox}>
          {searchedUnions || searchedUnionContacts ? (
            <div
              className={`${styles.titleBar} ${styles.titleBarActive} ${styles.titleBar_search}`}
            >
              {tt(`search_result`) /* 搜尋結果 */}
            </div>
          ) : (
            <>
              <div
                className={`${styles.titleBar} ${styles.titleBarUnActive}`}
                onClick={() => {
                  navigate('/user/contacts');
                }}
              >
                {tt(`contacts`) /* 聯絡人 */}
              </div>
              <div className={`${styles.titleBar} ${styles.titleBarActive} ${styles.right}`}>
                {tt(`union_type`, {}, { keySuffix: true }) /* 聯盟 */}
              </div>
            </>
          )}
        </div>

        {/* <div className={styles.searchbarBox}>
          <img className={styles.iconSearch} src={iconSearch}/>
          <div className={styles.searchInputHolder}>以ID搜尋任意聯盟或派系</div>
        </div> */}

        <div className={styles.searchbarBox}>
          <img className={styles.iconSearch} src={iconSearch} />

          <div className={styles.searchInputBox}>
            <Form
              action=""
              form={form}
              name="search_form"
              onFinish={onFinish}
              initialValues={{}}
              // labelCol={{ span: 8, className: styles.colTitle }}
              // wrapperCol={{ span: 16, className: styles.colContent }}
              colon={false}
            >
              <Form.Item
                required={false} //不顯示必填星號
                noStyle
                name="keyword"
                // label={<div className={styles.colTitle}>聯盟名稱</div>}
                // rules={[{
                //   required: true, message: `請填寫聯盟名稱`
                // },]}
              >
                <Input
                  type="search"
                  bordered={true}
                  className={`opacity0 ${styles.inputBox}`}
                  placeholder={
                    tt(`union_search_placeholder`) /* 搜尋成員/或以ID搜尋任意聯盟或派系 */
                  }
                />
              </Form.Item>
            </Form>
          </div>
        </div>

        {DCContext.isMyUnionOfficer && (
          <div className={styles.permissionBar}>
            <div className={styles.permissionBar_L}></div>
            {DCContext.isMyUnionChief && (
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={() => {
                  joinUnionSwitch();
                }}
              >
                {DCContext.myUnion?.free_join ? (
                  <div className={`${styles.permissionBar_M} ${styles.permission_active}`}>
                    {tt(`open_recruitment`) /* 公開招募 */}
                  </div>
                ) : (
                  <div className={`${styles.permissionBar_M}`}>
                    {tt(`pause_recruitment`) /* 暫停公開招募 */}
                  </div>
                )}
              </ClickEffect>
            )}
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                navigate('/user/union_applicants');
              }}
            >
              <div className={styles.permissionBar_R}>
                {tt(`union_join_applies`) /* 加盟申請 */}
                {DCContext.unionApplicants?.length > 0 && `(${DCContext.unionApplicants?.length})`}
              </div>
            </ClickEffect>
          </div>
        )}

        {searchedUnions ? (
          <div className={styles.chatGroupBox}>
            {searchedUnions.map((el, idx) => {
              return <RowUnion key={el.id} union={el} />;
            })}
          </div>
        ) : searchedUnionContacts ? (
          <ChatRooms
            _type="union_contacts"
            rooms={searchedUnionContacts}
            clickContactCallback={clickContactCallback}
          />
        ) : DCContext.myUnion ? (
          <ChatRooms
            _type="union_contacts"
            rooms={unionContacts}
            clickContactCallback={clickContactCallback}
          />
        ) : (
          <NoJoinedUnion doRecommendUnion={doRecommendUnion} />
        )}
      </div>

      <Navigator
        navi={{
          navigator: {
            show: false,
          },
          back:
            searchedUnions || searchedUnionContacts
              ? {
                  callback: goBackFromSearch,
                  //position: 'LEFT',
                  show: true,
                }
              : {
                  spot: 'home',
                  //position: 'LEFT',
                  show: true,
                },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </IbgDiv>
  );
};
