//先檢查 preloads 完成後再顯示劇情，避免劇情背景音樂在預載階段就播放
export const Story = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const _mode = props.mode; //after_attack...
  //
  let { cityId, _slideIdx } = useParams();
  cityId = parseInt(cityId) || 0;

  useEffect(() => {
    return () => {
      //清空 slides，攻城劇情前段保留，後段不用重取
      //if (_mode == "story_nation" || _mode == "after_attack"){
      //	DCContext.setSlides();
      //}

      //清空劇情避免劇情頁開始時判斷是否 loading 錯誤
      DCContext.setSlides();
    };
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic] || !DCContext.locale) {
      console.log('[Story] channel player 斷線');
      return;
    }

    console.log('[Story] channel player 已連線');

    if (_mode == 'story_nation') {
      DCContext.getNationSlides();
    } else if (_mode == 'uw_plot') {
      if (!DCContext.slides && DCContext.uwPlotR?.slides) {
        DCContext.setSlides(DCContext.uwPlotR.slides);
      }
    } else {
      DCContext.getSlides({
        city_id: cityId,
      });
    }
  }, [ChannelContext.channels[DCContext.playerChannelTopic], DCContext.locale]);

  /* 預載 */

  const { setPreloadImages, imagesPreloaded, preloadedRatio } = useImagePreloader();
  const preloadKey = 'slides';

  useEffect(() => {
    if (!DCContext.preloads?.[preloadKey]) {
      return;
    }

    console.log('[Story] [preload] setPreloadImages', DCContext.preloads?.[preloadKey]);

    setPreloadImages(DCContext.preloads?.[preloadKey]);
  }, [DCContext.preloads?.[preloadKey]]);

  useEffect(() => {
    console.log('[Story] [preload] imagesPreloaded', imagesPreloaded, DCContext.preloads);

    //清空本次該預載的
    if (imagesPreloaded && DCContext.preloads?.[preloadKey]) {
      DCContext.setPreloads(preState => {
        let tmp = { ...preState };
        tmp[preloadKey] = null;
        delete tmp[preloadKey];

        return tmp;
      });
    }
  }, [imagesPreloaded]);

  //debug
  // let r1, r2, r3;
  // if (!DCContext.slides || (DCContext.preloads?.[preloadKey] && !imagesPreloaded)){
  // 	r1 = DCContext.slides ? 'y' : 'n';
  // 	r2 = DCContext.preloads?.[preloadKey] ? 'y' : 'n';
  // 	r3 = imagesPreloaded ? 'y' : 'n';

  // 	console.log('[Story] qqqqq 1', r1, r2, r3);
  // } else {
  // 	r1 = DCContext.slides ? 'y' : 'n';
  // 	r2 = DCContext.preloads?.[preloadKey] ? 'y' : 'n';
  // 	r3 = imagesPreloaded ? 'y' : 'n';

  // 	console.log('[Story] qqqqq 2', r1, r2, r3, {...DCContext.slides});
  // }

  return (
    <>
      {!DCContext.slides ||
      !DCContext.preloads ||
      (DCContext.preloads?.[preloadKey] && !imagesPreloaded) ? (
        <Loading preloadedRatio={preloadedRatio}></Loading>
      ) : (
        <_Story {...props} />
      )}
    </>
  );
};

export const _Story = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [slide, setSlide] = useState();
  const [slideIdx, setSlideIdx] = useState();
  //
  const [autoPlay, setAutoPlay] = useState(false); //自動播放
  const autoPlay_timer = useRef(-1);
  const [showLog, setShowLog] = useState(false);
  const messagesEndRef = useRef(); //LOG開啟時捲動至最下方
  //
  const _mode = props.mode;
  //
  let { cityId, _slideIdx } = useParams();
  //cityId = parseInt(cityId) || 0;
  //_slideIdx = parseInt(_slideIdx) || 0;
  const [dialogueComplete, setDialogueComplete] = useState(false);
  const [clickScreenRand, setClickScreenRand] = useState();

  useEffect(() => {
    console.log('[Story] [x] in');

    return () => {
      console.log('[Story] [x] out');
      clearTimeout(autoPlay_timer.current);
    };
  }, []);

  useEffect(() => {
    if (!DCContext.slides) {
      return;
    }

    console.log('[Story] _mode', _mode, cityId, _slideIdx);

    if (_slideIdx != undefined) {
      _slideIdx = parseInt(_slideIdx);
    } else if (_mode == 'story_nation' && _slideIdx == undefined) {
      _slideIdx = 0;
    } else if (_mode == 'before_attack' && _slideIdx == undefined) {
      _slideIdx = 0;
    } else if (_mode == 'uw_plot' && _slideIdx == undefined) {
      _slideIdx = 0;
    } else if (_mode == 'after_attack' && _slideIdx == undefined) {
      for (let i = 0; i < DCContext.slides.length; i++) {
        if (!DCContext.slides[i].before_attack) {
          _slideIdx = i;
          break;
        }
      }
    }

    console.log('[Story] _slideIdx', _slideIdx);

    setSlideIdx(_slideIdx);
  }, [_slideIdx, DCContext.slides]);

  useEffect(() => {
    if (!DCContext.slides || slideIdx == undefined) {
      return;
    }

    console.log('[Story] slideIdx', slideIdx);

    let tmpSlide = DCContext.slides[slideIdx];

    //debug
    //tmpSlide = debugData.slide[1];
    //tmpSlide = debugData.slides_horizontal_shift[slideIdx];

    // 取不到這一張投影片就直接收手，不要往下讀它的欄位。
    // 原本只擋 !DCContext.slides，但空陣列 [] 是 truthy —— 後台若把某個劇情設為 active
    // 卻沒編任何 site_slides，後端會回傳 slides: []，這裡 slides[0] 就是 undefined，
    // 讀 .fade_in 直接整頁崩掉 (回報：TypeError reading 'fade_in')。
    if (!tmpSlide) {
      console.warn('[Story] 找不到投影片，slideIdx =', slideIdx, '總數 =', DCContext.slides.length);
      return;
    }

    if (tmpSlide.fade_in && tmpSlide.fade_out) {
      tmpSlide.iStyle = 'fadeinout';
    } else if (tmpSlide.fade_in) {
      tmpSlide.iStyle = 'fadein';
    } else if (tmpSlide.fade_out) {
      tmpSlide.iStyle = 'fadeout';
    } else {
      tmpSlide.iStyle = '';
    }

    setDialogueComplete(false);
    setSlide(tmpSlide);
  }, [DCContext.slides, slideIdx]);

  /* */

  useEffect(() => {
    if (!slide) {
      return;
    }

    console.log('[Story] slide', slide);

    if (slide.music) {
      DCContext.playMusic(`${slide.music}`);
    } else {
      DCContext.playMusic(false);
    }

    if (slide.sound_effect) {
      DCContext.playSound(`${slide.sound_effect}`);
    }

    if (slide.duration) {
      //有強制停留秒數
      clearTimeout(autoPlay_timer.current);
      autoPlay_timer.current = setTimeout(() => {
        console.log('[Story] 到達強制停留秒數', slide.id);
        goNext();
      }, slide.duration * 1000);
    } else if (autoPlay) {
      //自動播放預設停留 3 秒
      clearTimeout(autoPlay_timer.current);
      autoPlay_timer.current = setTimeout(() => {
        goNext();
      }, 3000);
    } else {
      //手動播放
      clearTimeout(autoPlay_timer.current);
    }

    //
    scrollToBottom();

    //
    // localStorage.setItem('storySlide', JSON.stringify({
    // 	cityId: cityId,
    // 	slideIdx: slideIdx
    // }))
  }, [slide]);

  useEffect(() => {
    if (!showLog) {
      return;
    }

    scrollToBottom();
  }, [showLog]);

  const goNext = () => {
    const tmpSlideIdx = slideIdx + 1;
    console.log('[Story] [goNext] tmpSlideIdx', tmpSlideIdx, DCContext.slides.length);

    let tmpSlide = DCContext.slides[tmpSlideIdx];

    //console.log('tmpSlideIdx', id, tmpSlide.before_attack);

    //劇情已播完
    switch (_mode) {
      case 'story_nation':
        if (tmpSlideIdx >= DCContext.slides.length) {
          //前往本部
          navigate('/home');
          return;
        }
        break;

      case 'after_attack':
        if (tmpSlideIdx >= DCContext.slides.length) {
          //返回地圖
          navigate('/attacks/attackmap');
          return;
        }
        break;

      case 'before_attack':
        if (!tmpSlide.before_attack) {
          //戰鬥前劇情已播完
          //進入戰鬥
          let url = `/attacks/attack`;
          unblockList.current[url] = 1;
          navigate(url);

          //
          //goAttack.current = true;
          //setNaviBlock(false);

          return;
        }
        break;

      case 'uw_plot':
        if (tmpSlideIdx >= DCContext.slides.length) {
          goPlotResult();
          return;
        }
        break;
    }

    //
    if (tmpSlideIdx < DCContext.slides.length) {
      let url = `/story/${_mode}/${cityId}/${tmpSlideIdx}`;
      unblockList.current[url] = 1;
      navigate(url);
    }
  };

  const goPlotResult = () => {
    const plot = DCContext.uwPlotR;
    if (plot?.site_id && plot?.site_plot_id) {
      DCContext.uwFinishPlot({
        site_id: plot.site_id,
        site_plot_id: plot.site_plot_id,
        team_id: plot.team_id,
      });
    }

    const url = '/attacks/uwplotresult';
    unblockList.current[url] = 1;
    navigate(url);
  };

  const goSkip = () => {
    console.log('[Story] goSkip _mode', _mode);

    switch (_mode) {
      case 'story_nation':
        showModal_confirm({
          confirm: {
            /*確定要跳過劇情？*/
            message: { i18nKey: `story_skip_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: () => {
                  navigate('/home');
                },
              },
            ],
          },
        });
        break;

      case 'after_attack':
        showModal_confirm({
          confirm: {
            /*確定要跳過劇情？*/
            message: { i18nKey: `story_skip_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: () => {
                  //返回地圖
                  navigate('/attacks/attackmap');
                },
              },
            ],
          },
        });
        break;

      case 'uw_plot':
        showModal_confirm({
          confirm: {
            message: { i18nKey: `story_skip_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: goPlotResult,
              },
            ],
          },
        });
        break;

      case 'before_attack':
        showModal_confirm({
          confirm: {
            /*確定要跳過劇情？*/
            message: { i18nKey: `story_skip_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: () => {
                  //進入戰鬥
                  let url = `/attacks/attack`;
                  unblockList.current[url] = 1;
                  navigate(url);

                  //
                  //goAttack.current = true;
                  //setNaviBlock(false);
                },
              },
            ],
          },
        });
        break;
    }
  };

  const autoPlaySwitch = () => {
    setAutoPlay(preState => {
      if (preState) {
        clearTimeout(autoPlay_timer.current);
      } else if (slide) {
        autoPlay_timer.current = setTimeout(() => {
          goNext();
        }, 1000);
      }

      return !preState;
    });
  };

  useEffect(() => {
    if (!clickScreenRand) {
      return;
    }

    clickScreen();
  }, [clickScreenRand]);

  const clickScreen = () => {
    //console.log("[Story] clickScreen", slide.duration, dialogueComplete, slide);

    if (slide.duration) {
      //有強制停留秒數
      //console.log("[Story] clickScreen 有強制停留秒數", slide.duration);
      //
      setDialogueComplete(true);
      return;
    }

    if (dialogueComplete) {
      goNext();
    } else {
      //console.log("[Story] clickScreen setDialogueComplete true");
      setDialogueComplete(true);
    }
  };

  //
  const goAttack = useRef(false);

  const transportToAttack = () => {
    let url = `/attacks/attack`;
    let go_url = `./transporter.html?go_url=${url}`;
    console.log('[Story] go_url', go_url);
    window.location.assign(go_url);
  };

  /* block page when leave */

  //只有戰鬥前劇情才需要確認是否放棄戰鬥
  const [naviBlock, setNaviBlock] = useState(_mode == 'before_attack' ? true : false);
  const unblockList = useRef({}); //不阻擋白名單
  const unblockNavi = useRef(() => {});

  useEffect(() => {
    let unblock;
    if (naviBlock) {
      // Block navigation and register a callback that
      // fires when a navigation attempt is blocked.
      unblock = history.block(tx => {
        // Navigation was blocked! Let's show a confirmation dialog
        // so the user can decide if they actually want to navigate
        // away and discard changes they've made in the current page.
        let url = tx.location.pathname;

        console.log('[Story] history.block tx', tx);

        // if (window.confirm(`Are you sure you want to go to "${url}"?`)) {
        //   // Unblock the navigation.
        //   unblock();

        //   // Retry the transition.
        //   tx.retry();
        // }

        //白名單
        //if (url.startsWith(`/story/`)){
        if (unblockList.current[url]) {
          console.log('[Story] unblockList.current', unblockList.current, url);
          unblock();
          tx.retry();
          return;
        }

        //保留到 dropAttack 完成後執行
        unblockNavi.current = () => {
          console.log('[Attack] unblockCallback()');

          // Unblock the navigation.
          unblock();

          // Retry the transition.
          tx.retry();
        };

        //避免影響到 dropAttack 後的導向
        setAutoPlay(false);
        clearTimeout(autoPlay_timer.current);

        showModal_confirm({
          confirm: {
            /*確定要放棄任務？*/
            message: { i18nKey: `mission_abandon_confirm`, values: null, options: null },
            buttons: [
              {
                text: { i18nKey: `confirm` },
                callback: () => {
                  DCContext.dropAttack();
                  callbackConfirm({});
                },
              },
            ],
          },
        });
      });
    } else if (goAttack.current) {
      transportToAttack();
    }

    return () => {
      if (typeof unblock === 'function') {
        console.log('[Story] unblock()');
        unblock();
      }
    };
  }, [naviBlock, slideIdx]);
  //每次白名單換頁都會 unblock() 導致 block 移除，所以每個 slide 都要再重新 history.block

  //drop_attack 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},drop_attack`]) {
      return;
    }

    console.log('[Attack] player,drop_attack', {
      ...DCContext.msgRes[`${DCContext.playerChannelTopic},drop_attack`].res,
    });

    if (DCContext.msgRes[`${DCContext.playerChannelTopic},drop_attack`].res.status == 'error') {
    } else if (DCContext.msgRes[`${DCContext.playerChannelTopic},drop_attack`].res.status == 'ok') {
      //drop_attack 成功
      console.log('[Attack] player,drop_attack ok');
      unblockNavi.current();
    } else {
      console.log('[Attack] player,drop_attack error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},drop_attack`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},drop_attack`]?.uuid]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* story bg */

  const { setTargetSrc, validSrc } = useValidSrc();
  const nodeRef = useRef(null);

  useEffect(() => {
    if (!slide?.background) {
      return;
    }

    setTargetSrc(slide?.background);
  }, [slide?.background]);

  useEffect(() => {
    if (!validSrc) {
      return;
    }

    console.log('[Story] validSrc', validSrc);
  }, [validSrc]);

  const clickBack = () => {};

  return (
    <>
      <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
        <div className={styles.mainBox}>
          <SwitchTransition>
            <CSSTransition
              //key={slideIdx} //debug 每slide都作用
              key={slide?.background} //換圖才作用
              nodeRef={nodeRef}
              in={true}
              //延後 react mount/unmount，留給動畫呈現時間 (fadeout 時才需要，需搭配 fadeout 秒數)
              timeout={slide?.iStyle == 'fadeout' ? 1000 : 100}
              //classNames="fadein" //debug
              classNames={slide?.iStyle}
              //unmountOnExit
            >
              {/* debug */}
              {/* <div ref={nodeRef} style={{left:slideIdx%2 == 1 ? "50%" : "0", width:"50%", backgroundImage:`url(${validSrc})`}} className={`${styles.bgBox}`} >
							{slide?.iStyle}
						</div> */}

              <div
                ref={nodeRef}
                style={{ backgroundImage: `url(${validSrc})` }}
                className={`${styles.bgBox}`}
              >
                {/* {slideIdx} : {slide?.duration} */}
              </div>
            </CSSTransition>
          </SwitchTransition>

          {slide &&
            Object.keys(slide.placement).map((key, index) => {
              let tmpData = slide.placement[key];

              return !tmpData.figure ? null : (
                <Character key={tmpData.figure} data={{ key: key, ...tmpData }} />
              );
            })}

          {/* Panel UI */}
          {1 == 2 && (
            <div className={styles.panelBox} style={{ backgroundImage: `url(${bgBattle})` }}>
              <div className={styles.panelBar}>
                <AttackUIBar />
                <div className={styles.actorName}>{slide?.speaker}</div>
              </div>
              <div className={styles.panelCont}>
                {/* <div className={`${styles.dialogueText} ${slide?.dialogue_color ? styles.dialogue_color : ""}`} dangerouslySetInnerHTML={{__html: slide?.dialogue}}></div> */}
                <_Dialogue key={slide?.id} slide={slide} />
              </div>
            </div>
          )}

          <div className={styles.panelBox}>
            <img className={styles.bgStoryPanel} src={bgStoryPanel} />

            <div className={styles.panelBar}>
              <div className={styles.actorName}>{slide?.speaker}</div>
            </div>

            <div className={styles.panelCont}>
              {/* <div className={`${styles.dialogueText} ${slide?.dialogue_color ? styles.dialogue_color : ""}`} dangerouslySetInnerHTML={{__html: slide?.dialogue}}></div> */}
              {dialogueComplete ? (
                <div
                  className={`${styles.dialogueText} ${
                    slide?.dialogue_color ? styles.dialogue_color : ''
                  }`}
                  dangerouslySetInnerHTML={{ __html: slide.dialogue }}
                ></div>
              ) : (
                <_Dialogue
                  key={slide?.id}
                  slide={slide}
                  callback_complete={() => {
                    setDialogueComplete(true);
                  }}
                />
              )}
            </div>
          </div>

          <div className={styles.animatedRing}>
            <img className={`rotation_highlightCircle`} src={highlightCircle} />
          </div>

          <ClickEffect
            effect={{ sound: null }}
            onClick={() => {
              setClickScreenRand(uuidv4());
            }}
          >
            <div className={styles.clickNextSlideSensor}></div>
          </ClickEffect>

          <div className={styles.lefttopPanelBox}>
            <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={autoPlaySwitch}>
              <div className={styles.iconAutoBox} style={{ opacity: autoPlay ? '100%' : '70%' }}>
                <img className={styles.iconAuto} src={iconAuto} />
              </div>
            </ClickEffect>

            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                setShowLog(preState => {
                  return !preState;
                });
              }}
            >
              <div className={styles.iconLogBox} style={{ opacity: showLog ? '100%' : '70%' }}>
                <img className={styles.iconLog} src={iconLog} />
              </div>
            </ClickEffect>
          </div>

          {_mode != 'story_nation' && ( //陣營劇情不可跳過
            <ClickEffect
              effect={{ sound: null }}
              onClick={() => {
                goSkip();
              }}
            >
              <div className={styles.iconSkip}>
                <img className={styles.iconSkipall} src={iconSkipall} />
              </div>
            </ClickEffect>
          )}

          {/* <ClickEffect effect={{sound: null}} onClick={()=>{goNext()}}>
        <div className={styles.iconNext}>
          <img className={styles.iconsL} src={icon_right_gold}/>
        </div>
				</ClickEffect> */}

          {showLog && (
            <div className={styles.logBox}>
              <div className={styles.logCont}>
                {DCContext.slides?.map((el, idx) => {
                  return el?.dialogue?.length > 0 && idx <= slideIdx ? (
                    <div key={idx} className={styles.logRow}>
                      <div className={styles.logSpeaker}>{el.speaker}</div>
                      <div
                        className={styles.logDialogue}
                        dangerouslySetInnerHTML={{ __html: el?.dialogue }}
                      ></div>
                    </div>
                  ) : null;
                })}
              </div>
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {showLog ? (
          <Navigator
            key={0}
            navi={{
              back: {
                callback: () => {
                  setShowLog(false);
                },
              }, //客戶要求顯示對話時，返回鍵變關閉顯示對話
            }}
          />
        ) : (
          <Navigator
            key={1}
            navi={{
              back:
                _mode == 'story_nation'
                  ? { show: false }
                  : _mode == 'after_attack' || _mode == 'uw_plot'
                  ? {
                      callback: () => {
                        goSkip();
                      },
                    } //客戶要求戰鬥後劇情“返回鍵”同“跳過劇情鍵”
                  : { spot: 'home' },
            }}
          />
        )}

        <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
          <Confirm {...modalProps_confirm.confirm} />
        </Imodal>
      </IbgDiv>
    </>
  );
};

const _Character = _props => {
  const data = _props.data;
  //console.log("[Story, Character] data", data);

  //震動參數
  const shakeXStart = 10;
  const shakeXEnd = -10;
  const shakeYStart = 0;
  const shakeYEnd = 0;

  //存放 spring styles
  const aniStyles = {
    out: null,
    in: null,
  };

  //存放基本 styles
  const baseStyles = {
    out: null,
    in: null,
  };

  useEffect(() => {
    //console.log("[Story, Character] data", data.figure);
  }, [_props.data]);

  //debug
  //data.effect = "horizontal_shift";
  //data.shift_to = "c";
  //
  //data.effect = "motion";

  switch (data.effect) {
    case 'fade_in': //緩現: 2 秒，從隱藏淡入到出現
      baseStyles.in = {
        from: { opacity: 0 },
        to: { opacity: 1 },
        config: {
          duration: 2000,
        },
      };
      break;
    case 'swift_in': //迅速進入: 0.5 秒，從隱藏淡入到出現
      baseStyles.in = {
        from: { opacity: 0 },
        to: { opacity: 1 },
        config: {
          duration: 500,
        },
      };
      break;
    case 'half_transparent': //淡化: 一秒鐘透明度從 100% 變到 30%
      baseStyles.in = {
        from: { opacity: 0.7 },
        to: { opacity: 0.7 },
        config: {
          duration: 1000,
        },
      };
      break;
    case 'motion': //震動
      baseStyles.in = {
        from: { x: 0, y: 0, opacity: 1 }, //加上 opacity: 1 避免上ㄧ slide 若是 half_transparent，影響到這一 slide
        to: { x: 1, y: 1, opacity: 1 },
      };
      break;
    case 'horizontal_shift': //平移
      baseStyles.out = {
        from: { ...avatarPoss[data.key], opacity: 1 }, //加上 opacity: 1 避免上ㄧ slide 若是 half_transparent，影響到這一 slide
        to: { ...avatarPoss[data.shift_to], opacity: 1 },
        config: {
          //	duration: 5000
        },
      };
      break;
    default:
      break;
  }

  aniStyles.in = useSpring(baseStyles.in);
  aniStyles.out = useSpring(baseStyles.out);

  //震動效果二次處理(Interpolate 插值或轉換)
  if (data.effect == 'motion') {
    const xInterpolate = aniStyles.in.x.to(
      [0, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 1],
      [
        shakeXStart,
        shakeXEnd,
        shakeXStart,
        shakeXEnd,
        shakeXStart,
        shakeXEnd,
        shakeXStart,
        shakeXEnd,
      ],
    );

    const yInterpolate = aniStyles.in.y.to(
      [0, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 1],
      [
        shakeYStart,
        shakeYEnd,
        shakeYStart,
        shakeYEnd,
        shakeYStart,
        shakeYEnd,
        shakeYStart,
        shakeYEnd,
      ],
    );

    aniStyles.in = {
      x: xInterpolate,
      y: yInterpolate,
    };
  }

  //顏色濾鏡
  let colorFilter = data.color_filter ? `filter_${data.color_filter}` : null;
  //debug
  //colorFilter = "filter_red";

  //console.log("[Story, Character] aniStyles", aniStyles);

  //debug
  //data.figure = "/images/actor/gif/tachieRB02.gif";

  //立繪gif 和 原先故事角色圖 構圖不同，套用不同 css
  let isGif = data.figure.toLowerCase().endsWith('gif');

  return (
    <animated.div style={{ ...avatarPoss[data.key], ...aniStyles.out }} className={styles.posBox}>
      <div className={`${styles.actorImgBox} ${isGif ? styles.gif : ''}`}>
        <Iimg
          className={`${styles.actorImg} ${isGif ? styles.gif : ''} ${colorFilter}`}
          style={aniStyles.in}
          src={data.figure}
          transition={false}
          onReady={() => {}}
        />
      </div>
    </animated.div>
  );
};

const isEqual = (prevProps, nextProps) => {
  return JSON.stringify(nextProps.data) === JSON.stringify(prevProps.data);
};

const _Dialogue = props => {
  const DCContext = useDCContext();
  //
  const slide = props.slide;
  const el = React.useRef(null);
  const typed = React.useRef(null);

  useEffect(() => {
    return () => {
      typed?.current?.destroy();
    };
  }, []);

  useEffect(() => {
    if (!slide) {
      return;
    }

    typed.current = new Typed(el.current, {
      strings: [slide?.dialogue || ''],
      typeSpeed: 1,
      fadeOut: true,
      cursorChar: '',
      onComplete: self => {
        props.callback_complete();
      },
    });
  }, [slide]);

  return (
    // <div className={`${styles.dialogueText} ${slide?.dialogue_color ? styles.dialogue_color : ""}`} dangerouslySetInnerHTML={{__html: slide?.dialogue}}></div>
    <div className={`${styles.dialogueText} ${slide?.dialogue_color ? styles.dialogue_color : ''}`}>
      <span ref={el} />
    </div>
  );
};

