export const propOutput = level => (level < 10 ? 2 ** level : 1024 * (level - 9));
export const upgradeMinutes = (level, teamPower) =>
  (level < 10 ? 2 ** level * 10 : 10240) * ((7000 - Math.min(teamPower, 7000)) / 7000);
export const upgradeMedia = (level, sameNation) => {
  const base = level < 10 ? 2 ** level * 100000 : 102400000;
  return Math.floor(sameNation ? base * 0.8 : base);
};

/* 倒數計時的顯示格式：只顯示「有值的最大單位以下」，不要補一堆 0 (回報)。
     1h25m32s → 01:25:32
        32m54s →    32:54
            9s →       09s   (只剩秒數時補上單位，避免單獨一個數字看不出是什麼)
   原本一律輸出 HHH:MM:SS，剩幾秒也顯示成 000:06:14。
   小時不設上限、但至少補到 2 位 (超過 99 小時就照實顯示，不截斷)。 */
const hhhmmss = totalSec => {
  const s = Math.max(0, Math.floor(totalSec));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const p2 = n => String(n).padStart(2, '0');

  if (h > 0) return `${p2(h)}:${p2(m)}:${p2(sec)}`;
  if (m > 0) return `${p2(m)}:${p2(sec)}`;
  return `${p2(sec)}s`;
};

