// 圓餅圖的陣營排列 (規格 p.26)。注意這是「排序」用的清單，不是白名單。
const DOMINANCE_ORDER = [1, 2, 3, 8, 4, 6, 5, 7, 10];

const buildDominanceSlices = (uw, colorOf) => {
  const map = uw && typeof uw === 'object' && !Array.isArray(uw) ? uw : {};
  // DOMINANCE_ORDER 漏了 nation 9 (自由勢力)。原本直接 map 這份清單，等於把不在清單內的
  // 陣營整段丟掉；而 pieGradient / topDominanceLabels 又是以「留下來的 slice 總和」當分母，
  // 於是被丟掉的占比會被偷偷分攤給其他陣營 —— 例如後端算出 40/25/35(自由勢力)，
  // 畫出來會變成 61.5/38.5，比例失真且畫面上看不出有東西不見。
  // 故補上「map 裡有、清單沒有」的陣營 (依 id 接在後面)，日後新增陣營也不會再漏。
  const extra = Object.keys(map)
    .map(Number)
    .filter(n => Number.isFinite(n) && !DOMINANCE_ORDER.includes(n))
    .sort((a, b) => a - b);

  return [...DOMINANCE_ORDER, ...extra]
    .map(nid => ({
      nation: nid,
      pct: Number(map[nid] ?? map[String(nid)] ?? 0) || 0,
      color: colorOf(nid),
    }))
    .filter(s => s.pct > 0);
};

const pieGradient = slices => {
  const total = slices.reduce((a, s) => a + s.pct, 0) || 100;
  let acc = 0;
  const stops = slices.map(s => {
    const from = (acc / total) * 100;
    acc += s.pct;
    return `${s.color || '#666'} ${from}% ${(acc / total) * 100}%`;
  });
  return `conic-gradient(from 0deg, ${stops.join(', ')})`;
};

const topDominanceLabels = slices => {
  const total = slices.reduce((a, s) => a + s.pct, 0) || 100;
  let acc = 0;
  const withMid = slices.map(s => {
    const start = (acc / total) * 360;
    acc += s.pct;
    const mid = (start + (acc / total) * 360) / 2;
    const rad = (mid * Math.PI) / 180;
    return { ...s, x: 50 + 30 * Math.sin(rad), y: 50 - 30 * Math.cos(rad) };
  });
  return [...withMid].sort((a, b) => b.pct - a.pct).slice(0, 3);
};

