export const UwTown = () => {
  const { tt } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();

  const topic = DCContext?.playerChannelTopic;
  const userProfile = DCContext?.userProfile;
  const userCityId = userProfile?.city_id ?? null;

  const cityId = location.state?.cityId ?? userCityId ?? null;
  const city = DCContext?.cities && cityId != null ? DCContext.getCityDataById(cityId) : null;
  const cityName = city?.name || location.state?.cityName || '';

  const inCity = userCityId != null && cityId != null && String(userCityId) === String(cityId);

  const energy = userProfile?.energy ?? 0;
  const media = userProfile?.media ?? 0;

  const [sites, setSites] = useState([]);
  const [wsCount, setWsCount] = useState(0);
  const [kings, setKings] = useState([]);
  const [dominance, setDominance] = useState(null);
  const [, forceTick] = useState(0);
  const [notice, setNotice] = useState(null);
  const [teamSelect, setTeamSelect] = useState(null);
  const [selectedTeamId, setSelectedTeamId] = useState(null);
  const [uwConfirm, setUwConfirm] = useState(null);
  const [canCollect, setCanCollect] = useState(false);
  const [collectResult, setCollectResult] = useState(null);
  // Access 進入目標城鎮時的黑幕淡入 (視同切換畫面)。UwTown 是同一個 route，
  // 用 Access 換城不會 remount、也就沒有換頁轉場，故自己補一層。
  //   'hold' = 全黑撐住 (等新城的 city_sites 回來)
  //   'out'  = 淡出露出新城
  // 不用固定秒數直接淡出 —— city_sites 是非同步的，回覆比動畫慢就會先露出舊城清單再跳成新城。
  const [fadeState, setFadeState] = useState(null);
  const fadeHoldTimer = useRef(-1);

  // 黑幕收尾：資料到了就淡出。保險計時器避免回覆失敗時永遠黑屏。
  const endFadeHold = useCallback(() => {
    clearTimeout(fadeHoldTimer.current);
    setFadeState(st => (st === 'hold' ? 'out' : st));
  }, []);

  useEffect(() => () => clearTimeout(fadeHoldTimer.current), []);

  useEffect(() => {
    const t = setInterval(() => forceTick(n => n + 1), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const times = (sites || [])
      .map(s => s.workstation?.completed_at)
      .filter(Boolean)
      .map(t => new Date(t).getTime())
      .filter(t => !isNaN(t) && t > Date.now());
    if (!times.length) return;
    const delay = Math.max(0, Math.min(...times) - Date.now()) + 800;
    const refresh = () => {
      fetchSites();
      DCContext.getProfile && DCContext.getProfile(true);
      DCContext.getActors && DCContext.getActors(true);
      DCContext.getCities && DCContext.getCities(true);
    };
    const t1 = setTimeout(refresh, delay);
    const t2 = setTimeout(refresh, delay + 3000);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [sites]);

  useEffect(() => {
    if (DCContext?.getActors) DCContext.getActors();
  }, []);

  // 進城 (或用 Access 換城) 時強制重抓 cities。
  // uw_king_id / uw_dominance 由伺服器在工作站落成時即時重算 (Cities.recompute_city_uw!)，
  // 但 DCContext.cities 抓過一次就快取住；上面那個 refresh 只有在「本頁還有工作站正要落成」
  // 時才會排定時器重抓 —— 進來時工作站若早已蓋好，整個 session 都不會再抓，王位/圓餅圖
  // 就一直停在舊值，直到重開 app (回報：100% 影響力但王頭貼空白)。
  useEffect(() => {
    if (DCContext?.getCities) DCContext.getCities(true);
  }, [cityId]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (city?.uw_music && DCContext?.playMusic) DCContext.playMusic(city.uw_music);
  }, [city?.uw_music]);

  const fetchSites = useCallback(() => {
    if (!topic || cityId == null) return;
    ChannelContext.sendMessage({
      topic,
      event: 'city_sites',
      message: { city_id: cityId },
    });
  }, [topic, cityId]);

  useEffect(() => {
    fetchSites();
  }, [fetchSites]);

  useEffect(() => {
    if (!topic || cityId == null) return;
    const t = setInterval(() => fetchSites(), 30000);
    return () => clearInterval(t);
  }, [topic, cityId, fetchSites]);

  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic) return;
    if (r.event === 'city_sites' && r.res?.status === 'ok') {
      setSites(r.res.payload?.sites || []);
      endFadeHold(); // 新城資料到齊 → 黑幕淡出
      setWsCount(r.res.payload?.workstation_count ?? 0);
      setKings(r.res.payload?.kings || []);
      setCanCollect(!!r.res.payload?.can_collect_all);
      if (r.res.payload?.uw_dominance !== undefined) setDominance(r.res.payload.uw_dominance);
    }
    // Access (規格 p.18)：成功 → 直接切到目標城的城內介面 (本頁以 cityId 重新載入)。
    if (r.event === 'uw_access_city') {
      if (r.res?.status === 'ok') {
        DCContext.getProfile && DCContext.getProfile(true); // 能量 + 可能變動的 city_id
        // 黑幕先全黑撐住，等新城 city_sites 回來才淡出 (見 endFadeHold)
        setFadeState('hold');
        clearTimeout(fadeHoldTimer.current);
        fadeHoldTimer.current = setTimeout(endFadeHold, 3000);
        navigate('/attacks/uwtown', {
          state: {
            cityId: r.res.payload?.city_id,
            cityName: r.res.payload?.city_name,
          },
        });
      } else {
        const p = r.res?.error || r.res?.payload || {};
        if (p.energy_boost_options) {
          DCContext.setShowConfirmModal({
            confirm: {
              message: { i18nKey: 'replenish_energy_confirm' },
              buttons: [
                {
                  text: { i18nKey: 'confirm' },
                  callback: () => {
                    DCContext.setShowConfirmModal();
                    DCContext.showEnergyboostModal();
                  },
                },
              ],
            },
          });
        } else {
          setNotice({
            title: tt(`uw_access_failed`) /* 前往失敗 */,
            body: p.message || tt(`uw_try_again_later`) /* 請稍後再試。 */,
          });
        }
      }
    }
    if (r.event === 'uw_collect_all') {
      if (r.res?.status === 'ok') {
        setCollectResult({
          rewards: r.res.payload?.rewards || [],
          // server 若有帶 sound_effect 就用它，沒帶則由 overlay 用預設收取音效
          sound: r.res.payload?.sound_effect?.items,
        });
        setCanCollect(false);
        fetchSites();
        DCContext.getProfile && DCContext.getProfile();
      } else {
        const p = r.res?.error || r.res?.payload || {};
        setNotice({
          title: p.status || tt(`uw_collect_failed`) /* 收取失敗 */,
          body: p.message || tt(`uw_try_again_later`) /* 請稍後再試。 */,
        });
      }
    }
    if (['workstation_deploy', 'workstation_cancel', 'workstation_destroy'].includes(r.event)) {
      setTeamSelect(null);
      if (r.res?.status === 'ok') {
        fetchSites();
        // 這三個動作都會改變該城的王位與滲透占比 (後端已即時 recompute)，
        // 連帶影響王號 +200 的編隊戰力。全部強制重抓，否則 client 端快取不會更新：
        //   getProfile() 不帶 true 會直接吃快取；actors 帶著戰力數值、原本完全沒重抓
        //   → 拆除工作站失去王號後，戰力仍顯示含 +200 (回報)。
        DCContext.getProfile && DCContext.getProfile(true);
        DCContext.getActors && DCContext.getActors(true);
        DCContext.getCities && DCContext.getCities(true);
      } else {
        const p = r.res?.error || r.res?.payload || {};
        setNotice({
          title: p.status || tt(`uw_action_failed`) /* 操作失敗 */,
          body: p.message || tt(`uw_try_again_later`) /* 請稍後再試。 */,
        });
      }
    }
  }, [ChannelContext.sendMessageRes]);

  const activeWsSites = sites.filter(s => s.reference_type === 'Workstation' && s.workstation);
  const myPoints = activeWsSites.reduce((sum, s) => sum + (s.workstation?.points || 0), 0);

  const onBack = () => {
    navigate('/attacks/attackmap', { state: { focus_city_id: userCityId } });
  };

  const onCollectAll = () => {
    if (!canCollect || !topic) return;
    ChannelContext.sendMessage({ topic, event: 'uw_collect_all', message: {} });
  };

  const openTeamSelect = (siteId, mediaNeed, siteLevel) => {
    navigate('/user/teams/uwdeploy', {
      state: {
        site_id: siteId,
        mediaNeed,
        siteLevel,
        city_id: cityId,
        cityName,
      },
    });
  };

  // 副本 (Visit/Explore, 規格 pp.18-22)：確認後進選隊畫面，於該頁按「派遣」才扣能量。
  const openPlotTeamSelect = s => {
    navigate('/user/teams/uwplot', {
      state: {
        site_id: s.id,
        siteName: s.name,
        energyCharge: s.energy_charge || 0,
        city_id: cityId,
        cityName,
      },
    });
  };

  const onBuildClick = s => {
    // 已達上限 (20 座)：走城內介面共用確認視窗公版 (內文 + 單一[確定])，
    // 與建造/升級/拆除同一套 UI；只提示、不進選隊。
    if (wsCount >= MAX_WORKSTATIONS) {
      setUwConfirm({
        content: tt(`uw_workstation_already_20`),
        onConfirm: () => setUwConfirm(null),
      });
      return;
    }
    setUwConfirm({
      content: tt(`uw_build_workstation_confirm`, { city_name: cityName, ws_name: s.ws_name }),
      onConfirm: () => {
        setUwConfirm(null);
        openTeamSelect(s.id, upgradeMedia(0, s.same_nation), 0);
      },
    });
  };

  const onUpgradeClick = s => {
    const level = s.workstation?.level ?? 0;
    setUwConfirm({
      content: tt(`uw_upgrade_workstation_confirm`, {
        city_name: cityName,
        ws_name: s.ws_name,
        level: level + 1,
        time: Math.ceil(upgradeMinutes(level, 0)),
      }),
      onConfirm: () => {
        setUwConfirm(null);
        openTeamSelect(s.id, upgradeMedia(level, s.same_nation), level);
      },
    });
  };

  // 取消「建造中」的工作站 (workstation_cancel)，與下方的拆除 (workstation_destroy) 是
  // 兩個不同的功能鍵。兩句詞句的中文內容當初一模一樣，曾被誤判為重複而讓這裡共用了
  // uw_build_workstation_destroy；2026-09-03 確認是兩個功能後導回各自的 key。
  const onCancelClick = s => {
    setUwConfirm({
      content: tt(`uw_build_workstation_cancel`),
      onConfirm: () => {
        setUwConfirm(null);
        ChannelContext.sendMessage({
          topic,
          event: 'workstation_cancel',
          message: { site_id: s.id },
        });
      },
    });
  };

  const onDestroyClick = s => {
    setUwConfirm({
      content: tt(`uw_build_workstation_destroy`),
      onConfirm: () => {
        setUwConfirm(null);
        ChannelContext.sendMessage({
          topic,
          event: 'workstation_destroy',
          message: { site_id: s.id },
        });
      },
    });
  };

  const onSiteActionClick = s => {
    const act = actionOf(tt, s.reference_type);
    if (!act) return;
    // Access (規格 p.18)：不進副本劇情、也不用選隊。確認後扣能量並直接開啟目標城的
    // 城內介面；目標城非隱藏城時後端會同時把 users.city_id 改過去。
    if (s.reference_type === 'Access') {
      setUwConfirm({
        content: tt(`uw_access_confirm`, {
          action: act.verb,
          site_name: s.access_city_name || s.name || '',
        }),
        // 規格 p.18：Access/Visit/Explore 確認視窗左上要顯示能量消耗
        energy: s.energy_charge || 0,
        onConfirm: () => {
          setUwConfirm(null);
          if (!topic) return;
          ChannelContext.sendMessage({
            topic,
            event: 'uw_access_city',
            message: { site_id: s.id },
          });
        },
      });
      return;
    }
    // Visit / Explore (規格 p.22)：確認 → 選隊 → 派遣 (扣能量) → 劇情 → 結算
    setUwConfirm({
      content: tt(`uw_visit_confirm`, { action: act.verb, site_name: s.name || '' }),
      // 規格 p.18：Visit/Explore 確認視窗左上要顯示能量消耗 (蓋工作站不花能量，故不帶)
      energy: s.energy_charge || 0,
      onConfirm: () => {
        setUwConfirm(null);
        openPlotTeamSelect(s);
      },
    });
  };

  const conditionText = (cond, verb, energy) => {
    /* {{action}}需 {{energy}} 能量 */
    const need = tt(`uw_site_energy_need`, { action: verb, energy: energy || 0 });
    if (!cond) return need;
    const name = cond.reference_name || '';
    const lv = cond.level ?? 0;
    switch (cond.type) {
      case 'Actor':
        /* 需擁有{{name}} {{need}} */
        return tt(`uw_site_cond_actor`, { name, need });
      case 'ActorLevel':
        /* {{name}}達 Lv {{level}} 可進行{{site_level}}{{action}} {{need}} */
        return tt(`uw_site_cond_actor_level`, {
          name,
          level: cond.condition_level,
          site_level: lv,
          action: verb,
          need,
        });
      case 'ActorRelationLevel':
        /* 與{{name}}關係已達 {{level}} 級 {{need}} */
        return tt(`uw_site_cond_relation_level`, { name, level: cond.condition_level, need });
      case 'Prop':
        /* 需交付{{name}}×{{quantity}} {{need}} */
        return tt(`uw_site_cond_prop`, { name, quantity: cond.condition_quantity, need });
      case 'SitePlot':
        /* 需完成{{name}}{{level}} {{need}} */
        return tt(`uw_site_cond_site_plot`, { name, level: cond.ref_level ?? lv, need });
      default:
        return need;
    }
  };

  const renderSite = s => {
    const st = s.state;
    const clickable = st !== 4;

    let top = '';
    let big = '';
    let side = '';

    if (s.reference_type === 'Workstation') {
      const level = s.workstation?.level ?? 0;
      // 宗教工作站的 side_label 由後端給 (religions.name，前端拿不到)；
      // 一般工作站後端回 nil，改用詞句，否則各語系都會看到寫死的中文「工作站」。
      side = s.side_label || tt(`uw_workstation_side_label`);
      if (st === 1) {
        /* {{prop_name}}×0／日 滲透值 0 進一步滲透需 {{media}} 動員力 */
        top = tt(`uw_ws_status_unbuilt`, {
          prop_name: s.prop_name,
          media: kmb(upgradeMedia(0, s.same_nation)),
        });
        big = `Lv 0 ${s.ws_name}`;
      } else if (st === 2) {
        const etaSec = s.workstation?.completed_at
          ? Math.max(0, (new Date(s.workstation.completed_at).getTime() - Date.now()) / 1000)
          : 0;
        /* {{prop_name}}×{{output}}→{{next_output}}／日 {{time}} 後滲透完畢 */
        top = tt(`uw_ws_status_upgrading`, {
          prop_name: s.prop_name,
          output: kmb(propOutput(level)),
          next_output: kmb(propOutput(level + 1)),
          time: hhhmmss(etaSec),
        });
        big = `Lv ${level}→${level + 1} ${s.ws_name}`;
      } else {
        /* {{prop_name}}×{{output}}／日 滲透值 {{points}} 進一步滲透需 {{media}} 動員力 */
        top = tt(`uw_ws_status_active`, {
          prop_name: s.prop_name,
          output: kmb(propOutput(level)),
          points: kmb(s.workstation?.points || propOutput(level)),
          media: kmb(upgradeMedia(level, s.same_nation)),
        });
        big = `Lv ${level} ${s.ws_name}`;
      }
    } else {
      const act = actionOf(tt, s.reference_type) || { verb: '', side: '' };
      side = act.side;
      if (s.reference_type === 'Access') {
        // 後台若有為此 Access 設條件 (例：需某幹部達 Lv300)，比照 Visit/Explore 一併顯示，
        // 否則按鍵被擋住卻只寫「前往需 N 能量」，玩家看不出為什麼不能點。
        // 沒設條件時 s.condition 為 null → conditionText 只回能量那段，與原本相同。
        top = conditionText(s.condition, act.verb, s.energy_charge);
        big = s.access_city_name || '';
      } else {
        top = conditionText(s.condition, act.verb, s.energy_charge);
        big = `${s.name || ''}（${s.cur_level ?? 0}/${s.max_level ?? 0}）`;
      }
    }

    const onClick = () => {
      if (!inCity || !clickable) return;
      if (s.reference_type === 'Workstation') {
        if (st === 1) return onBuildClick(s);
        if (st === 2) return;
        if (st === 3) return onUpgradeClick(s);
      } else {
        return onSiteActionClick(s);
      }
    };

    return (
      <div key={s.id} className={styles.siteRow}>
        <div className={styles.siteSide}>{side}</div>
        <ClickEffect effect={{ sound: SE1 }} onClick={onClick}>
          <div
            className={`${styles.site} ${clickable ? '' : styles.siteDisabled}`}
            style={skinStyle(st)}
          >
            {(st === 2 || st === 3) && (
              <span
                className={styles.siteClose}
                title={
                  st === 2
                    ? tt(`uw_cancel_upgrade`) /* 取消升級 */
                    : tt(`uw_destroy_workstation`) /* 拆除工作站 */
                }
                onClick={e => {
                  e.stopPropagation();
                  if (!inCity) return;
                  st === 2 ? onCancelClick(s) : onDestroyClick(s);
                }}
              >
                ×
              </span>
            )}
            {/* 紋章只出現在「已蓋好 (3) 或正在蓋／升級中 (2)」的工作站。
                未建造的工作站格 (1) 與 Visit/Explore/Access 都不顯示。 */}
            {s.reference_type === 'Workstation' && (st === 2 || st === 3) && s.emblem && (
              <span
                className={styles.siteEmblem}
                style={{ backgroundImage: `url(${mediaUrl(s.emblem)})` }}
              />
            )}
            <div className={styles.siteText}>
              <FitText className={styles.siteTop}>{top}</FitText>
              <FitText className={styles.siteBig}>{big}</FitText>
            </div>
          </div>
        </ClickEffect>
      </div>
    );
  };

  const nationColor = nid => {
    const n = DCContext?.nations?.find(x => String(x.id) === String(nid));
    return n?.city_color ? `#${n.city_color}` : '#666';
  };
  const domSlices = buildDominanceSlices(dominance ?? city?.uw_dominance, nationColor);
  const pieBg = domSlices.length ? pieGradient(domSlices) : null;
  const domLabels = topDominanceLabels(domSlices);
  const king = kings[0] || null;
  const runnerUps = kings.slice(1, 3);

  const sortedSites = [...sites].sort((a, b) => (a.position || 0) - (b.position || 0));

  return (
    <IbgDiv className={styles.pageContainer} src={null} transition={true} onReady={() => {}}>
      {/* 背景圖層 + 右半部面板共用同一個「鎖定比例的 stage」。
          stage 以 uwbg.png 的比例 (5445x2516) 做 cover 置中，面板的百分比座標因此
          與底圖同一組基準 —— 縮放時一起放大縮小、不會分家也不變形。 */}
      <div className={styles.stage}>
        <div
          className={styles.bgStreetImage}
          style={{
            backgroundImage: `url(${mediaUrl(
              city?.uw_street_image,
            )}), radial-gradient(circle at 50% 30%, #2a3550 0%, #11131d 70%, #07090f 100%)`,
          }}
        />
        <div
          className={styles.bgCityImage}
          style={{
            backgroundImage: `url(${uwUrl(
              'uwbg.png',
            )}), linear-gradient(180deg, rgba(0,0,0,0.55) 0%, transparent 30%, transparent 70%, rgba(0,0,0,0.75) 100%)`,
          }}
        />
        <div className={styles.cityNameWatermark}>
          {city?.name || location.state?.cityName || ''}
        </div>

        {/* 左側 Site 列表 (在 stage 內 → 與底圖同基準、置中對齊) */}
        <div className={styles.leftPane}>
          <div className={styles.siteList}>{sortedSites.map(renderSite)}</div>
        </div>

        {/* City Panel 右側三大區塊 */}
        <div className={styles.cityPanelGroup}>
          {/* 1. 左欄：數據文字 */}
          <div className={styles.leftCityPanel}>
            <div className={styles.rText}>
              {tt(`uw_organization_workstations`, {
                organization: userProfile?.organization || '',
              })}
            </div>
            <div className={styles.rNum}>
              {wsCount}/{MAX_WORKSTATIONS}
            </div>
            {city?.control_union?.name && (
              <ClickEffect
                effect={{ sound: SE1 }}
                onClick={() => DCContext.showUnionModal(city.control_union.id)}
              >
                <div className={styles.rText}>{city.control_union.name}</div>
              </ClickEffect>
            )}
            {/* 「現正影響{城}」要在三角旗「上面」(回報)，故排在旗子之前。
                有控制聯盟時再往上收一點，與聯盟名稱貼近 (回報)。 */}
            <div
              className={`${styles.rText} ${city?.control_union?.name ? styles.rTextTightTop : ''}`}
            >
              {tt(`uw_currently_affecting`, { city_name: cityName })}
            </div>
            {/* 這面旗代表「現正影響此城的一方」，不是檢視者自己 (回報：以 L2 進上海，
                看到的卻是 L2 自己的旗，而非上海影響者 KDJ.C 的夜字旗)。
                原本讀 userProfile.triangle_flag，那是玩家自身的旗，於是每個人進同一座城
                看到的旗都不一樣。改用 city.control_triangle_flag —— 後端
                Cities.control_triangle_flag/1 已處理好「有控制聯盟取聯盟旗、否則取控制陣營旗」，
                大地圖 (Attackmap) 用的也是同一個欄位，兩邊因此一致。 */}
            {city?.control_triangle_flag && (
              <ClickEffect
                effect={{ sound: SE1 }}
                onClick={() =>
                  city?.control_union?.id && DCContext.showUnionModal(city.control_union.id)
                }
              >
                <img
                  className={styles.triangleFlag}
                  src={mediaUrl(city.control_triangle_flag)}
                  alt=""
                />
              </ClickEffect>
            )}
            <div className={styles.rTextSmall}>{withBr(tt(`uw_dominance_bonus_hint`))}</div>
            <div className={styles.seventhRow}>
              <span className={styles.rText}>
                {tt(`uw_my_dominance_points`, { nickname: userProfile?.nickname || '' })}
              </span>
              <span className={styles.rNum}>{kmb(myPoints)}</span>
            </div>
          </div>

          {/* 2. 中欄：人物柱、uw04 飾板、圓餅圖、名次 */}
          <div className={styles.centerCityPanel}>
            {/* 肖像 (置於上半部) */}
            {king?.avatar && (
              <div
                className={styles.portrait}
                style={{ backgroundImage: `url(${mediaUrl(king.avatar)})` }}
              />
            )}

            {/* 飾板框架：鎖定 806:2040 比例貼齊底部 */}
            <div className={styles.uw04Frame}>
              <img className={styles.uw04img} src={uwUrl('uw04.png')} alt="" />

              {/* 第一名 (王) */}
              {king && (
                <ClickEffect
                  effect={{ sound: SE1 }}
                  onClick={() => king.id && DCContext.showPlayerinfoModal(king.id)}
                >
                  <div className={styles.rank1}>
                    {king.emblem && (
                      <img className={styles.kingEmblem} src={mediaUrl(king.emblem)} alt="" />
                    )}
                    <div className={styles.kingTitle}>
                      {tt(`uw_king_title`, { city_name: cityName })}
                    </div>
                    <div className={styles.kingName}>{king.nickname}</div>
                    <div className={styles.kingPoints}>{kmb(king.points)}</div>
                    <div className={styles.rankBuff}>{tt(`uw_king_bonus_text`)}</div>
                  </div>
                </ClickEffect>
              )}

              {/* 圓餅圖 */}
              {pieBg && (
                <div className={styles.pieWrap}>
                  <div className={styles.pie} style={{ background: pieBg }} />
                  {domLabels.map(s => (
                    <span
                      key={s.nation}
                      className={styles.pieLabel}
                      style={{ left: `${s.x}%`, top: `${s.y}%` }}
                    >
                      {s.pct}%
                    </span>
                  ))}
                </div>
              )}

              {/* 第二、三名 */}
              {runnerUps.length > 0 && (
                <div className={styles.rankRunners}>
                  {runnerUps.map(r => (
                    <ClickEffect
                      key={r.id}
                      effect={{ sound: SE1 }}
                      onClick={() => r.id && DCContext.showPlayerinfoModal(r.id)}
                    >
                      {/* 規格：名次的羅馬數字要獨立一行、置於玩家資訊「上方」，
                          三行依序為 <羅馬數字> / <玩家> / <戰力>。
                          原本把羅馬數字與暱稱放在同一個 div 內，會排成
                          「<羅馬數字> <玩家>」同一行 (回報)。 */}
                      <div className={styles.runnerCol}>
                        <div className={styles.runnerRank}>{ROMAN[r.rank]}</div>
                        <div className={styles.runnerName}>{r.nickname}</div>
                        <div className={styles.runnerPoints}>{kmb(r.points)}</div>
                      </div>
                    </ClickEffect>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* 3. 右欄：收取按鈕與說明 */}
          <div className={styles.rightCityPanel}>
            {canCollect ? (
              <ClickEffect effect={{ sound: SE1 }} onClick={onCollectAll}>
                <div className={styles.collectBtn}>
                  <img className={styles.collectHighlight} src={highlightCircle} alt="" />
                  <span className={styles.collectText}>{tt(`uw_collect_all`)}</span>
                </div>
              </ClickEffect>
            ) : (
              /* 已收取狀態沿用同一個按鍵結構與旋轉光圈，只差在文字色與不可點 ——
                 原本只有一行純文字、沒有動畫，兩種狀態的位置與視覺也對不齊。 */
              <div className={`${styles.collectBtn} ${styles.collectBtnDone}`}>
                <img className={styles.collectHighlight} src={highlightCircle} alt="" />
                <span className={styles.collectedText}>{tt(`uw_collected_all`)}</span>
              </div>
            )}
            <div className={styles.rightCityPanelNote}>
              <div className={styles.rightCityPanelNoteText}>
                {withBr(tt(`uw_dominance_combat_buff`))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 左上三數值。點擊行為比照主畫面 (pages/Home.js) 的同一排：
          能量 → 補充能量視窗、資金 → 商城；動員力不可點。 */}
      <div className={styles.topValues}>
        <ClickEffect
          effect={{ sound: SE1 }}
          onClick={() => DCContext.showEnergyboostModal && DCContext.showEnergyboostModal()}
        >
          <div className={styles.hudItem}>
            <img className={styles.hudIcon} src={iconEnergyPlus} alt="" />
            <span className={styles.hudText}>
              {energy} /{' '}
              {DCContext?.getUser_maxEnergyByLevel ? DCContext.getUser_maxEnergyByLevel() : ''}
            </span>
          </div>
        </ClickEffect>
        <ClickEffect effect={{ sound: SE1 }} onClick={() => navigate('/store/bundleorders')}>
          <div className={styles.hudItem}>
            <img className={styles.hudIcon} src={iconFundsPlus} alt="" />
            <span className={styles.hudText}>{iNumify(userProfile?.fund ?? 0)}</span>
          </div>
        </ClickEffect>
        <div className={styles.hudItem}>
          <img className={styles.hudIcon} src={iconPublicity} alt="" />
          <span className={styles.hudText}>{iNumify(media)}</span>
        </div>
      </div>

      {/* 右上角 Navigator */}
      <Navigator navi={{ back: { callback: onBack } }} />

      {/* Modals & Overlays */}
      {/* Access 換城的黑幕淡入：先全黑蓋住，再淡出露出新城 (視同切換畫面)。
          動畫結束後移除，避免擋住點擊。 */}
      {fadeState && (
        <div
          className={`${styles.screenFade} ${fadeState === 'out' ? styles.screenFadeOut : ''}`}
          onAnimationEnd={() => setFadeState(null)}
        />
      )}

      {uwConfirm && (
        <Imodal visible={true} maskClosable={true} callback={() => setUwConfirm(null)}>
          <UwBuildConfirm
            content={uwConfirm.content}
            energy={uwConfirm.energy}
            onConfirm={uwConfirm.onConfirm}
          />
        </Imodal>
      )}
      {notice && (
        <NoticeModal title={notice.title} body={notice.body} onClose={() => setNotice(null)} />
      )}
      {collectResult && (
        <CollectResultOverlay
          rewards={collectResult.rewards}
          soundEffect={collectResult.sound}
          onClose={() => {
            setCollectResult(null);
            if (city?.uw_music && DCContext?.playMusic) DCContext.playMusic(city.uw_music);
          }}
        />
      )}
    </IbgDiv>
  );
};
