import icon_right_gray from 'assets/img/icon_right_gray.png';
import icon_messageRecall from 'assets/img2/icon_messageRecall.png';
import icon_messageDelete from 'assets/img2/icon_messageDelete.png';
//
import ChatRoom from 'component/Chat/ChatRoom';

export const Chatroom = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const location = useLocation();
  //
  let navigate = useNavigate();
  //
  const { room_id } = useParams();

  useEffect(() => {
    //console.log("[Chatroom] room_id", room_id);

    return () => {};
  }, []);

  useEffect(() => {
    if (!location.state?.exRoomInfo || !DCContext.userProfile) {
      return;
    }

    console.log('[Chatroom] location.state?.exRoomInfo', location.state?.exRoomInfo);

    //聯盟公告 || 聯盟頻道 被解散聯盟須退出
    if (
      !DCContext.userProfile?.union &&
      (location.state?.exRoomInfo.roomType == 'announcements' ||
        location.state?.exRoomInfo.roomType == 'unionChannel')
    ) {
      navigate('/user/unions');
    }
  }, [DCContext.userProfile?.union, location.state?.exRoomInfo]);

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <ChatRoom room_id={room_id} />
      </div>

      <Navigator
        navi={{
          navigator: {
            show: false,
          },
          back: {
            show: true,
          },
        }}
      />
    </IbgDiv>
  );
};
