import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
//
import styles from './GiveawayForm.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';

export const GiveawayForm = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      //console.log("[GiveawayForm] channel player 斷線");
      return;
    }

    //console.log("[GiveawayForm] channel player 已連線");

    DCContext.getGiveaway_categories(true);
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.giveaway_categories) {
      return;
    }
    //console.log("[GiveawayForm] DCContext.giveaway_categories", DCContext.giveaway_categories);
  }, [DCContext.giveaway_categories]);

  /* form */
  const [form] = Form.useForm();
  const onFinish = values => {
    //console.log("[GiveawayForm] form values", values);

    const data = {
      giveaway_category_id: values.giveaway_category_id,
      code: values.code,
    };
    //console.log("[GiveawayForm] form data", data);
    //return;

    DCContext.setShowProcessingModal(true); //顯示“處理中”

    DCContext.collectBundle({
      reference_type: 'Giveaway',
      giveaway_category_id: values.giveaway_category_id,
      code: values.code,
    });
  };

  const submitForm = () => {
    form.submit();
    //console.log("submitForm");
  };

  //collect_bundle 結果
  useEffect(() => {
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[GiveawayForm] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      showModal_confirm({
        confirm: {
          /*錯誤，例如 序號錯誤 序號已被使用*/
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                //if (props.callback){ props.callback() }
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[Announcement] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));

    //關閉序號 modal 自己
    props.callback();
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });
  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };
  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };
  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <Form
            action=""
            form={form}
            name="control-hooks"
            onFinish={onFinish}
            initialValues={{ email: '', password: '' }}
            labelCol={{ span: 8, className: styles.colTitle }}
            wrapperCol={{ span: 16, className: styles.colContent }}
            colon={false}
          >
            <Form.Item
              name="giveaway_category_id"
              required={false}
              label={
                <div className={styles.colTitle}>{tt(`serial_number_category`) /* 序號類別 */}</div>
              }
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`serial_number_category`) }), //序號類別為必填
                },
              ]}
            >
              <Select
                className={styles.selectBox}
                placeholder=""
                onChange={() => {}}
                //allowClear
              >
                {DCContext.giveaway_categories?.map((o, idx) => {
                  return (
                    <Select.Option key={o.id} value={o.id}>
                      {o.name}
                    </Select.Option>
                  );
                })}
              </Select>
            </Form.Item>

            <Form.Item
              name="code"
              required={false}
              label={
                <div className={styles.colTitle}>{tt(`serial_number_input`) /* 輸入序號 */}</div>
              }
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`serial_number`) }), //序號為必填
                },
              ]}
            >
              <Input bordered={true} className={styles.inputBox} />
            </Form.Item>
          </Form>

          <FitText className={styles.descriptionBox}>
            {
              tt(
                `serial_number_description`,
              ) /* 輸入您所擁有的逆統戰手遊虛寶兌換序號，或許會得到意想不到的驚喜？ */
            }
          </FitText>

          <div>
            <BtnGrey text={tt(`confirm`) /* 確定 */} callback={submitForm} />
          </div>
        </div>
      </div>

      {/* modal confirm */}

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </div>
  );
};
