import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ClickEffect } from 'componentx/ClickEffect';
import { useDCContext } from 'lib/DCContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useI18n } from 'lib/useI18n';
import iConfig from 'iConfig';
import { Imodal } from 'componentx/Imodal';
import { UwMoveConfirm } from './UwMoveConfirm';
import { uwImage } from '../assets/uwImages';
import styles from './UwTownButtons.module.scss';

/*
 * UW (Under World) — 城鎮地圖 (#/attacks/attackmap) 的羅盤 (uw01.png) + 王肖像框。
 *
 * 羅盤 (規格書 p.4)：
 *   - 顯示與否：cities.visitable (admin/cities/<id>/edit；default TRUE)。FALSE → 不顯示、不可點。
 *   - 4 狀態 (以 users.city_id / move_to_city_id / move_to_city_at 對此城 city_id 推導)：
 *       (1) city_id != 此城 且 move_to_city_id == null → 「前往」(uw_move_to)   → uw_move_confirm
 *       (2) city_id == 此城 且 move_to_city_id == null → 「造訪」(uw_enter_city) → 進城內介面 UwTown
 *       (3) city_id != 此城 且 move_to_city_id != null → 「正前往<目的城>」(uw_moving) → uw_move_cancel
 *       (4) city_id == 此城 且 move_to_city_id != null → 倒數 MM:SS → uw_move_cancel
 *
 * 對話框一律使用提示視窗公版 (DCContext.setShowConfirmModal)：
 *   - uw_move_confirm (規格 p.11 第一個圖)：內文 + [取消][確定]。內文帶 energy / city_name /
 *     time (分鐘取小數點後 1 位、四捨五入)；成本由後端 "uw_move_cost" 算 (自 users.city_id 出發)。
 *   - uw_move_cancel (規格 p.12 第二個圖)：只有內文 + [確定]。
 *
 * 王肖像框 (規格 p.5)：真實 cities.uw_king。uw01/uw02.png 美術未交付 → CSS 佔位 fallback。
 */

const SE1 = '/audio/sound_effect/SE1.mp3';
const mediaUrl = p => (p ? `${iConfig.Media.remoteAssets}${p}` : null);
// 羅盤 uw01 / 肖像框 uw02 改由 bundle 出貨 (見 assets/uwImages)，避免每次進地圖等網路。
const uwUrl = uwImage;

export const UwTownButtons = ({ thisCityId }) => {
  const navigate = useNavigate();
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const { tt } = useI18n();

  const topic = DCContext?.playerChannelTopic;
  const [, forceTick] = useState(0);
  const [pendingMove, setPendingMove] = useState(null); // { cityId, cityName } 等 uw_move_cost 回覆
  const [moveConfirm, setMoveConfirm] = useState(null); // { cityId, cityName, energy, minutes }

  // ── 真實資料 ──
  const userProfile = DCContext?.userProfile;
  const userCityId = userProfile?.city_id ?? null;
  const moveToCityId = userProfile?.move_to_city_id ?? null;
  const moveToAt = userProfile?.move_to_city_at ?? null; // ISO string | null

  const city =
    DCContext?.cities && thisCityId != null ? DCContext.getCityDataById(thisCityId) : null;
  const cityName = city?.name || '';
  const moveToCity =
    DCContext?.cities && moveToCityId != null ? DCContext.getCityDataById(moveToCityId) : null;
  const moveToName = moveToCity?.name || '';

  // 王肖像只在 city.uw_king_id 確實存在且與 uw_king 物件 id 一致時顯示。
  // 防止前端 cities 快取被 _mergeData 淺合併 (partial city push) 後殘留舊 uw_king 物件、
  // 或 uw_king_id 已清空卻仍留著物件 → 造成無王城顯示他人 (含自己) 頭像的 bug。
  const king =
    city?.uw_king && city?.uw_king_id && city.uw_king.id === city.uw_king_id ? city.uw_king : null;

  // 診斷 (issue: 移動中全地圖王位顯示自己頭像)：當某城王位算成「自己」時，記錄該城與
  // uw_king_id / uw_king.id / 自身 id / 是否移動中，供下次測試回報 console 定位真正來源。
  if (king && userProfile && String(king.id) === String(userProfile.id) && moveToCityId != null) {
    // eslint-disable-next-line no-console
    console.log('[UW king-leak diag]', {
      thisCityId,
      cityName,
      uw_king_id: city?.uw_king_id,
      king_id: king.id,
      self_id: userProfile.id,
      moveToCityId,
    });
  }

  // cities.visitable：default TRUE。FALSE → 不顯示羅盤 (規格 p.4)。
  const visitable = city ? city.visitable !== false : true;

  // ── 4 狀態推導 (規格 p.10-12) ──
  // 移動中：city_id 仍停在「出發城」(取消時回出發城、抵達時才改成目的城)，故「倒數城」須以
  // move_to_city_id (目的城) 判定，而非 city_id：
  //   (4) 此城 == 目的城 (move_to_city_id) → 倒數 MM:SS  → 點擊 uw_move_cancel
  //   (3) 移動中且此城 != 目的城 (含出發城/其它城) → 前往[目的城] (uw_moving) → 點擊 uw_move_cancel
  //   (2) 未移動且此城 == 所在城 (city_id) → 造訪
  //   (1) 未移動且此城 != 所在城 → 前往 (可發起移動)
  const atThisCity = userCityId != null && String(userCityId) === String(thisCityId);
  const moving = moveToCityId != null;
  const isDestination = moving && String(moveToCityId) === String(thisCityId);
  const compassState = moving ? (isDestination ? 4 : 3) : atThisCity ? 2 : 1;

  const closeModal = () => DCContext.setShowConfirmModal();

  // state(4) 倒數每秒刷新
  useEffect(() => {
    if (compassState !== 4) return;
    const t = setInterval(() => forceTick(n => n + 1), 1000);
    return () => clearInterval(t);
  }, [compassState]);

  // 抵達結算：倒數結束 (move_to_city_at 到) 時主動刷新 profile，觸發後端 resolve_uw_state
  // 將 city_id 更新為目的城。否則前端會永遠停在倒數 00:00、city_id 不變 → 無法進入目的城。
  // 只由「目的城」的 compass 實例排程 (避免地圖上每個城鎮都重複打 profile)。
  useEffect(() => {
    if (!moving || !moveToAt) return;
    if (String(thisCityId) !== String(moveToCityId)) return;
    const ms = new Date(moveToAt).getTime() - Date.now();
    const t = setTimeout(
      () => DCContext.getProfile && DCContext.getProfile(true),
      Math.max(0, ms) + 800,
    );
    return () => clearTimeout(t);
  }, [moving, moveToAt, thisCityId, moveToCityId]); // eslint-disable-line react-hooks/exhaustive-deps

  // channel 回覆：uw_move_cost → 開 uw_move_confirm 公版；uw_move_to_city / uw_cancel_move → 刷新 profile
  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic) return;

    if (r.event === 'uw_move_cost' && pendingMove) {
      const pm = pendingMove;
      setPendingMove(null);
      if (r.res?.status === 'ok') {
        const { energy, minutes } = r.res.payload || {};
        // uw_move_confirm 專屬公版視窗 (規格 p.11 第一個圖)：行動力 header + 內文 + 只有[確定]
        setMoveConfirm({
          cityId: pm.cityId,
          cityName: pm.cityName,
          energy: energy ?? 0,
          minutes: minutes ?? 0,
        });
      } else {
        // push 錯誤回覆在 res.error (非 res.payload)。
        DCContext.setShowConfirmModal({
          confirm: {
            message:
              r.res?.error?.message ||
              r.res?.payload?.message ||
              tt(`uw_move_cost_failed`) /* 無法取得移動資訊，請稍後再試。 */,
            buttons: [{ text: { i18nKey: 'confirm' }, callback: closeModal }],
          },
        });
      }
    }

    // 移動失敗 (能量不足最常見)。原本只處理 status === 'ok'，錯誤回覆被整個吞掉 ——
    // 確認鍵按下去視窗就關了、什麼都沒跳，看起來像「直接跳掉」。
    if (r.event === 'uw_move_to_city' && r.res && r.res.status !== 'ok') {
      const p = r.res?.error || r.res?.payload || {};

      if (p.energy_boost_options) {
        // 能量不足：比照副本派遣 / 攻城 —— 確認後開補充能量視窗。
        DCContext.setShowConfirmModal({
          confirm: {
            message: { i18nKey: 'replenish_energy_confirm' },
            buttons: [
              {
                text: { i18nKey: 'confirm' },
                callback: () => {
                  closeModal();
                  DCContext.showEnergyboostModal && DCContext.showEnergyboostModal();
                },
              },
            ],
          },
        });
        return;
      }

      DCContext.setShowConfirmModal({
        confirm: {
          message: p.message || tt(`uw_move_cost_failed`) /* 無法取得移動資訊，請稍後再試。 */,
          buttons: [{ text: { i18nKey: 'confirm' }, callback: closeModal }],
        },
      });
      return;
    }

    if (['uw_move_to_city', 'uw_cancel_move'].includes(r.event) && r.res?.status === 'ok') {
      DCContext.getProfile && DCContext.getProfile(true); // 更新 city_id / move_to_city_*
      // 防禦性：同時強制重抓 cities，修正 session 內若殘留舊王位資料 (issue: 移動中王位顯示自己)。
      // 後端 cities 資料已驗證正確 (L1 僅為 4 城之王)，重抓可清掉客戶端任何過期快取。
      DCContext.getCities && DCContext.getCities(true);
    }
  }, [ChannelContext.sendMessageRes]); // eslint-disable-line react-hooks/exhaustive-deps

  const countdownMMSS = () => {
    if (!moveToAt) return '00:00';
    const ms = Math.max(0, new Date(moveToAt).getTime() - Date.now());
    return `${String(Math.floor(ms / 60000)).padStart(2, '0')}:${String(
      Math.floor((ms % 60000) / 1000),
    ).padStart(2, '0')}`;
  };

  const compassText =
    compassState === 1
      ? tt('uw_move_to')
      : compassState === 2
      ? tt('uw_enter_city')
      : compassState === 3
      ? tt('uw_moving', { city_name: moveToName })
      : countdownMMSS();

  // ── 點擊 ──
  const onCompassClick = () => {
    if (!visitable) return;
    if (compassState === 2) {
      navigate('/attacks/uwtown', { state: { cityId: thisCityId, cityName } });
      return;
    }
    if (compassState === 1) {
      // 前往：先向後端取移動成本 (energy/time)，回覆後開 uw_move_confirm 公版。
      setPendingMove({ cityId: thisCityId, cityName });
      ChannelContext.sendMessage({
        topic,
        event: 'uw_move_cost',
        message: { city_id: thisCityId },
      });
      return;
    }
    // state 3 / 4：uw_move_cancel 提示視窗公版 (規格 p.12 第二個圖)：只有內文 + [確定]
    DCContext.setShowConfirmModal({
      confirm: {
        message: { i18nKey: 'uw_move_cancel', values: { city_name: moveToName } },
        buttons: [
          {
            text: { i18nKey: 'confirm' },
            callback: () => {
              ChannelContext.sendMessage({ topic, event: 'uw_cancel_move', message: {} });
              closeModal();
            },
          },
        ],
      },
    });
  };

  const onKingClick = () => {
    if (king?.id) DCContext.showPlayerinfoModal(king.id);
  };

  return (
    <>
      {/* 羅盤 (uw01.png)：cities.visitable=TRUE 才顯示 (規格 p.4) */}
      {visitable && (
        <div className={styles.compassBox}>
          <ClickEffect effect={{ sound: SE1 }} onClick={onCompassClick}>
            <div className={styles.compass}>
              <img className={styles.compassImg} src={uwUrl('uw01.png')} alt="" />
              <div className={styles.compassText}>{compassText}</div>
            </div>
          </ClickEffect>
        </div>
      )}

      {/* 城鎮統治者肖像框 (規格 p.5)：真實 cities.uw_king。顯示條件有兩個：
          1. cities.visitable —— 規格 p.4「visitable 為 TRUE 時顯示以下按鍵，為 FALSE 時
             不顯示」涵蓋到 p.5 的 ❖ 清單，羅盤與肖像框都在其中。
          2. 該城有王 —— **需求變更 (2026-09-03)，刻意與規格 p.5(2) 不同**。
             規格原文是「uw_king_id 若為 null，則只顯示 uw02.png，頭像與紋章皆空白」，
             亦即無王時仍留一個空框；客戶要求改為整個框都不顯示。
             要改回規格行為只需把下面的 `&& king` 拿掉。
          頭像 / 紋章 / 名稱一律以 uw02.png 的百分比座標定位 (見 scss)，故各平台比例一致。
          key = 城鎮 + 王 id：切換城鎮 / 王變動時強制整框 re-mount，避免 ClickEffect 內
          條件式 <img> 殘留上一城的王頭像 (issue: 移動/切城時王位欄顯示上一城/自己的頭像)。 */}
      {visitable && king && (
      <div className={styles.kingBox} key={`king-${thisCityId}-${king?.id ?? 'none'}`}>
        <div className={styles.kingFrame}>
          {king?.avatar && (
            <ClickEffect effect={{ sound: SE1 }} onClick={onKingClick}>
              <img className={styles.kingAvatar} src={mediaUrl(king.avatar)} alt="" />
            </ClickEffect>
          )}
          {/* 層序：頭像 < uw02 框 < 陣營紋章 */}
          <img className={styles.kingFrameImg} src={uwUrl('uw02.png')} alt="" />
          {king?.emblem && <img className={styles.kingEmblem} src={mediaUrl(king.emblem)} alt="" />}
          {king?.nickname && <div className={styles.kingName}>{king.nickname}</div>}
        </div>
      </div>
      )}

      {/* uw_move_confirm 公版視窗 (規格 p.11 第一個圖)：全畫面 Imodal 包住 (比照火車 icon 的
          MoveForceConfirm 用法)，內含行動力 header + 內文 + 只有[確定]。✕/遮罩關閉 = 不移動。 */}
      {moveConfirm && (
        <Imodal visible={true} maskClosable={true} callback={() => setMoveConfirm(null)}>
          <UwMoveConfirm
            cityName={moveConfirm.cityName}
            energy={moveConfirm.energy}
            minutes={moveConfirm.minutes}
            onConfirm={() => {
              ChannelContext.sendMessage({
                topic,
                event: 'uw_move_to_city',
                message: { city_id: moveConfirm.cityId },
              });
              setMoveConfirm(null);
            }}
          />
        </Imodal>
      )}
    </>
  );
};
