import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './BattleStage.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

import { StageZone } from './StageZone';

export const BattleStage = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  //
  const [fightData, setFightData] = useState();
  const [endZones, setEndZones] = useState({});
  const timer_endDelay = useRef();

  useEffect(() => {
    return () => {
      clearTimeout(timer_endDelay.current);
    };
  }, []);

  useEffect(() => {
    if (!props.fightData) {
      return;
    }
    console.log('[BattleStage] fightData', props.fightData);

    setFightData(props.fightData);
  }, [props.fightData]);

  const callbackZoneEnd = idx => {
    console.log('[BattleStage] callbackZoneEnd', idx);

    setEndZones(preState => {
      let tmp = { ...preState };
      tmp[idx] = true;
      return tmp;
    });
  };

  useEffect(() => {
    let endNum = Object.keys(endZones).length;

    if (endNum >= 3) {
      console.log('[BattleStage] 本回合三個 zone 都結束');

      //稍停幾秒
      timer_endDelay.current = setTimeout(() => {
        props.roundEnd_callback();
      }, 2000);
    }
  }, [endZones]);

  return (
    <IbgDiv className={styles.bgBox} src={null} transition={true} onReady={() => {}}>
      <div className={styles.section} style={{ zIndex: 3 }}>
        <IbgDiv
          className={`${styles.sectionBg} ${endZones[0] ? 'filter_black' : ''}`}
          src={props.zonesData[0].image}
          transition={false}
          onReady={() => {}}
        />
        <StageZone
          zoneIdx={0}
          iamDefender={fightData?.defender}
          zoneData={fightData?.data[0]}
          callbackZoneEnd={callbackZoneEnd}
        />
      </div>

      <div className={styles.section} style={{ zIndex: 2 }}>
        <IbgDiv
          className={`${styles.sectionBg} ${endZones[1] ? 'filter_black' : ''}`}
          src={props.zonesData[1].image}
          transition={false}
          onReady={() => {}}
        />
        <StageZone
          zoneIdx={1}
          iamDefender={fightData?.defender}
          zoneData={fightData?.data[1]}
          callbackZoneEnd={callbackZoneEnd}
        />
      </div>

      <div className={styles.section} style={{ zIndex: 1 }}>
        <IbgDiv
          className={`${styles.sectionBg} ${endZones[2] ? 'filter_black' : ''}`}
          src={props.zonesData[2].image}
          transition={false}
          onReady={() => {}}
        />
        <StageZone
          zoneIdx={2}
          iamDefender={fightData?.defender}
          zoneData={fightData?.data[2]}
          callbackZoneEnd={callbackZoneEnd}
        />
      </div>
    </IbgDiv>
  );
};
