/*
<Ifade effect_in={false} effect_out={true} duration={800}>

</Ifade>
*/

import React from 'react';
import { useTransition, animated } from 'react-spring';

const _defaultProps = {
  duration: 1000,
  effect_in: true,
  effect_out: true,
};

export const Ifade = props => {
  const { children, keys, ...otherProps } = props;

  const newProps = {
    ..._defaultProps,
    ...otherProps,
  };

  //console.log(`[Ifade] props`, props, otherProps, newProps);

  // react-spring v9: keys 併入 options 物件；舊的 3 參數 useTransition(items, keys, config)
  // 已移除。沿用舊寫法時第 2 個參數會被當成 options，未帶 keys 就是 undefined，
  // v9 內部解構它 → 進戰鬥畫面直接噴
  // "Cannot destructure property 'reset' of ... as it is undefined" (Character.js 用到)。
  const transitions = useTransition(children, {
    keys,
    from: { opacity: newProps.effect_in ? 0 : 1 },
    enter: { opacity: 1 },
    leave: { opacity: newProps.effect_out ? 0 : 1 },
    config: {
      duration: newProps.duration,
    },
  });

  // v9: transitions 是 render function (style, item) => node，不再是可 .map() 的陣列。
  return transitions((style, item) =>
    item ? <animated.div style={style}>{children || item}</animated.div> : null,
  );
};
