import { Routes, Route, NavLink, Navigate, useNavigate, useLocation } from 'react-router-dom';
import { v4 as uuidv4 } from 'uuid';
import { matchPath } from 'react-router';
import { useDCContext, resetDCContext } from 'lib/DCContext';
import { useUserContext } from 'lib/UserContext';

export const ProtectedRoute = ({ children }) => {
  const DCContext = useDCContext();
  const { ...UserContext } = useUserContext();
  const location = useLocation();

  //console.log("[ProtectedRoute] userProfile", DCContext.userProfile);

  //是否登入
  //console.log('[ProtectedRoute] DCContext.userProfile', DCContext.userProfile);
  //if (!DCContext.userProfile) {

  //console.log('[ProtectedRoute] UserContext.ifLoggedIn()', UserContext.ifLoggedIn());

  if (!UserContext.ifLoggedIn()) {
    console.log('[ProtectedRoute] 未登入, 導向 log_in');

    return <Navigate to="/users/log_in" replace={true} />;

    //暫時改成重導網頁來清掉所有暫存資料 (iOS網址錯誤)
    //window.location.href = `./?r=${uuidv4()}#/users/log_in`;
    //return <></>;
  }

  /*
  2個檢查點
  ProtectedRoute: 網址變更時
  ChannelPlayer: userProfile 變更時
  */
  //檢查是否已完成會員基本設定(陣營 玩家名稱 組織名稱)
  //ChannelPlayer, ProtectedRoute, Routes 相關
  //須等到 DCContext.userProfile 有值時檢查
  if (
    DCContext.userProfile &&
    !DCContext.userProfile.nation?.id &&
    !matchPath('/settings/nation/*', location.pathname) &&
    !matchPath('/settings/streetimage', location.pathname) &&
    !matchPath('/settings/streetimage/*', location.pathname) &&
    !matchPath('/settings/sealimage', location.pathname) &&
    !matchPath('/settings/sealimage/*', location.pathname)
  ) {
    console.log('[ProtectedRoute] 未設定過所屬國家, 導向設定', location.pathname);
    return <Navigate to="/settings/nation" replace />;
  }

  return children;
};
