import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { FitText } from 'lib/FitText';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './EquipWeapon.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { Imodal } from 'componentx/Imodal';
import { EquipSkillSwitch } from 'component/EquipSkillSwitch';
//
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import icon_upgrade from 'assets/img/icon_upgrade.png';

export const EquipWeapon = props => {
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  const [actor, setActor] = useState();
  const [weapon, setWeapon] = useState();

  useEffect(() => {
    if (!props.actor) {
      return;
    }

    setActor(props.actor);
    setWeapon(props.actor.weapon);
  }, [props.actor]);

  //幹部選擇符文後，顯示此符文
  useEffect(() => {
    if (!DCContext.tmpSelectedWeapon) {
      return;
    }

    console.log('[EquipWeapon] DCContext.tmpSelectedWeapon', DCContext.tmpSelectedWeapon);
    setWeapon(DCContext.tmpSelectedWeapon);
  }, [DCContext.tmpSelectedWeapon]);

  const goChangeWeapon = () => {
    //先改成都可進到符文裝備介面
    // if (actor.usable_weapon_ids.length < 1){
    //   console.log("[EquipWeapon] actor.usable_weapon_ids.length", actor.usable_weapon_ids.length);
    //   return;
    // }

    //已經在裝備頁，點擊武器裝備鍵不要再導向一次，搞亂返回的導向
    //console.log(`[EquipWeapon] goChangeWeapon`, location);
    if (location.pathname.startsWith(`/user/actorweapons/`)) {
      return;
    }

    navigate(`/user/actorweapons/${actor.id}`, {
      state: {
        returnUrl: location.pathname,
        returnState: null,
      },
    });
  };

  const goUpgradeWeapon = () => {
    navigate(`/user/weaponupgrade/${actor.id}`);
  };

  return actor ? (
    <>
      <div className={styles.weapon}>
        <div className={styles.weaponCont}>
          {/* 左欄空白 */}
          <div className={styles.weaponAttrBoxOutLine}></div>

          {/* 中欄武器icon */}
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={e => {
              goChangeWeapon();
            }}
          >
            <Iimg
              className={styles.weaponIcon}
              src={weapon ? weapon.weapon_prototype.image : actor.no_weapon_image}
              transition={false}
              onReady={() => {}}
            />
          </ClickEffect>

          {/* 右欄升級按鈕&等級 */}
          <div className={styles.weaponAttrBoxOutLine}>
            {actor.weapon && actor.weapon.id == weapon.id && (
              <div className={styles.weaponAttrBox}>
                {props.mode != 'weaponUpgrade' && (
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={e => {
                      goUpgradeWeapon();
                    }}
                  >
                    <div className={styles.weaponAttr1}>
                      <img className={styles.iconUpgrade} src={icon_upgrade} />
                    </div>
                  </ClickEffect>
                )}
                <div className={styles.weaponAttr2}>
                  {props.upgradeWeaponCacuResult?.finalLevel || weapon?.level}
                </div>
              </div>
            )}
          </div>
        </div>
        {weapon?.id ? (
          //? <div className={styles.weaponName} dangerouslySetInnerHTML={{__html: weapon?.weapon_prototype.name}}></div>
          <FitText className={styles.weaponName}>{weapon?.weapon_prototype.name}</FitText>
        ) : (
          <FitText className={`${styles.weaponName} ${styles.no_weapon_name}`}>
            {actor.no_weapon_name}
          </FitText>
        )}
      </div>
    </>
  ) : (
    <></>
  );
};
