import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
  config,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Teams } from 'component/Teams';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Unionteams.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';

export const Unionteams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  const [teams, setTeams] = useState([]);
  const [actors, setActors] = useState([]);
  const team_id = useRef();

  let mode = props.mode;
  //
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;
  //console.log('[Unionteams] useParams: ', mode, teamIdx, location);
  //
  const [unionBattleStatus, setUnionBattleStatus] = useState();

  useEffect(() => {}, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    //
    console.log('[Unionteams] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile, teamIdx]);

  //監測特定 channel 連線變化狀態

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionChannelTopic]) {
      console.log('[Unionteams] channel union:x 未連線');
      return;
    }

    console.log('[Unionteams] channel union:x 已連線');
    DCContext.getUnion_battle_status();
  }, [ChannelContext.channels[DCContext.unionChannelTopic]]);

  //union_battle status 結果

  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`]) {
      return;
    }

    console.log('[Unionteams] union_battle_status', {
      ...DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res,
    });

    if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.status == 'error'
    ) {
    } else if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.status == 'ok'
    ) {
      /* 模擬戰
			{"not_started"}					開始時間未到							 停在本部跳訊息通知
      {"initiate"}						開始時間已到，尚未發起			 選隊伍
      {"roll_call"}						已發起
        data.player_joined    false => 未參戰             選隊伍
                              true  => 已參戰，未開戰      等待開戰頁
			{"maneuver"}		 			  已開戰，開始選擇戰區					聊天室 選戰區
      {"battle"}	 						已開戰，開始交戰 							交戰頁
      {"concluded"}						已分勝負 									結果頁
      {"no_battle]"}  					本聯盟今天沒有參戰					停在本部跳訊息通知
			*/
      let tmpStatus =
        DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.payload.status;
      let tmpData =
        DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`].res.payload.data;
      console.log('[Unionteams] union_battle_status status: ', tmpStatus, tmpData);

      //debug
      // tmpStatus = "initiate";

      setUnionBattleStatus(tmpStatus);
    } else {
      console.log('union_battle_status error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.unionChannelTopic},union_battle_status`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},union_battle_status`]?.uuid]);

  //Server 主動發送 message

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[DCContext] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //模擬戰
      case `${DCContext.unionChannelTopic},union_battle_status`:
        console.log('[Unionteams] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpStatus = ChannelContext.messages?.res?.payload.status;

        //debug
        // tmpStatus = "initiate";

        setUnionBattleStatus(tmpStatus);
        break;
    }
  }, [ChannelContext.messages]);

  //join_union_battle 結果

  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.unionChannelTopic},join_union_battle`]) {
      return;
    }

    console.log('[Unionteams] player, join_union_battle', {
      ...DCContext.msgRes[`${DCContext.unionChannelTopic},join_union_battle`].res,
    });

    if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},join_union_battle`].res.status == 'error'
    ) {
    } else if (
      DCContext.msgRes[`${DCContext.unionChannelTopic},join_union_battle`].res.status == 'ok'
    ) {
      //join_union_battle 成功
      console.log('[Unionteams] player, join_union_battle ok');
      navigate('/unionbattle');
    } else {
      console.log('[Unionteams] player, join_union_battle error 其他錯誤');
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.unionChannelTopic},join_union_battle`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},join_union_battle`]?.uuid]);

  /* 點擊參戰 */

  const clickFightCallback = ({ team_id = 0 } = {}) => {
    console.log('[Unionteams] clickFightCallback, team_id', team_id);

    showModal_confirm({
      confirm: {
        /* 確定要參與模擬戰？ */
        message: { i18nKey: `mb_join_battle_confirm`, values: null, options: null },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({});
              DCContext.joinUnionBattle({
                team_id: team_id,
              });
            },
          },
        ],
      },
    });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams
        mode={mode}
        showFightBtn={
          DCContext?.isMyUnionOfficer || unionBattleStatus == 'roll_call' ? true : false
        }
        teamIdx={teamIdx}
        clickFightCallback={clickFightCallback}
      />

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </IbgDiv>
  );
};
