import React, { useLayoutEffect, useRef, useState } from 'react';

/*
 * UW 共用「過長自動縮小」文字容器。
 *
 * 用途：名稱之類的動態文字太長時，寧可等比縮小也不要折行或被 ellipsis 截斷 (回報)。
 * 作法：容器 nowrap + overflow hidden，量測內層 scrollWidth 與容器 clientWidth，
 *       超出就用 transform: scale() 等比縮小。用 transform 而不是改 font-size，
 *       是為了避免改字級觸發重排、再回頭影響量測而抖動。
 *
 * 原本這份實作內嵌在 UwTown.js，只有靠左的用法；抽出來共用並補上 origin，
 * 因為置中的文字 (例如 UwActorTopBlock 的城名) 若仍以 left 為縮放原點，縮小後會偏左。
 *
 * Props：
 *   className — 直接套在外層容器上 (沿用呼叫端原本的樣式)
 *   origin    — 'left' | 'center' | 'right'，對應文字的對齊方式，預設 'left'
 */

const MIN_SCALE = 0.25; // 下限；原本 0.4 在極長字串時仍塞不下會被切掉 (回報)

const ORIGIN_MAP = {
  left: 'left center',
  center: 'center center',
  right: 'right center',
};

export const UwFitText = ({ children, className, origin = 'left' }) => {
  const box = useRef(null);
  const inner = useRef(null);
  const [scale, setScale] = useState(1);

  useLayoutEffect(() => {
    const fit = () => {
      const b = box.current;
      const i = inner.current;
      if (!b || !i) return;
      // clientWidth 含 padding，但文字只能用內容框；呼叫端若有左右內距
      // (例：UwPlayerinfoExtras 的 .workstationButtonText 有 padding-right)，
      // 不扣掉就會高估可用寬度，字仍會溢出到內距上。
      const cs = window.getComputedStyle(b);
      const avail =
        b.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
      // 先還原成 1 再量，否則量到的是「已縮小後」的寬度，字變短時不會縮回去
      i.style.transform = 'scale(1)';
      const need = i.scrollWidth;
      setScale(need > avail && need > 0 ? Math.max(MIN_SCALE, avail / need) : 1);
    };
    fit();
    window.addEventListener('resize', fit);
    return () => window.removeEventListener('resize', fit);
  }, [children]);

  return (
    <div ref={box} className={className} style={{ overflow: 'hidden', whiteSpace: 'nowrap' }}>
      <span
        ref={inner}
        style={{
          display: 'inline-block',
          transformOrigin: ORIGIN_MAP[origin] || ORIGIN_MAP.left,
          transform: `scale(${scale})`,
        }}
      >
        {children}
      </span>
    </div>
  );
};
