import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { merge as lodash_merge, cloneDeep as lodash_cloneDeep } from 'lodash';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import styles from './Unionbattle.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

//
import { AniDoor } from 'pages/unionbattle/AniDoor';
import { BattleRoom } from 'pages/unionbattle/BattleRoom';
import { BattleStage } from 'pages/unionbattle/BattleStage';
//import { Medals } from "component/Medals";
import { Nationbattle_result } from './Nationbattle_result';
import { PopupMessagesIcon } from 'component/modal/PopupMessagesIcon';

export const Nationbattle = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [battleData, setBattleData] = useState();
  const [fightData, setFightData] = useState();
  const [zonesData, setZonesData] = useState();
  const [matchData, setMatchData] = useState();
  //
  let timer_commanderOnline;
  const [commanderOnline, setCommanderOnline] = useState(); // YES / NO
  //據點戰不需開關門動畫，都改成 true
  const [doorClosed, setDoorClosed] = useState(true);
  const [doorShowed, setDoorShowed] = useState(true);
  //
  //const [showMedals, setShowMedals] = useState(false);
  //
  const [battleLeavable, setBattleLeavable] = useState(true);
  //
  const _mode = 'nationBattle';

  useEffect(() => {
    //debug: battle
    //setDoorShowed(true);
    //setFightData(debugStatusR_broadcast["battle"]);

    //debug
    //setBattleData(debugStatusR['maneuver']);

    //debug
    //setShowMedals(true);

    //debug
    // DCContext.setShowConfirmModal({
    // 	confirm: {
    // 		message: '123',
    // 		buttons: [
    // 			{
    // 				text: {i18nKey:`confirm`},
    // 				callback: ()=>{
    // 					console.log('xxxxx');
    // 					DCContext.setShowConfirmModal();
    // 				}
    // 			}
    // 		]
    // 	}
    // });

    DCContext.setShowPopupMessages({ category: 0 });

    return () => {
      clearTimeout(timer_commanderOnline);
      //恢復顯示短訊
      DCContext.setShowShortMessage(true);

      //
      // if (DCContext.nationBattleChannelTopic){
      // 	ChannelContext.leaveChannel({
      // 		topic: DCContext.nationBattleChannelTopic,
      // 		params: {fake: "1"}
      // 	});
      // }
    };
  }, []);

  //斷線重連後
  useEffect(() => {
    if (!DCContext.userProfile?.nation_battle) {
      //最後一場戰鬥資料拿到，演出戰鬥前 update_data 仍保留 profile.nation_battle，只是格式不同
      /*
				{
					"profile": {
						"nation_battle": {
							"good_game": true,
							"id": 359
						}
					}
				}
			*/
      //區別
      //profile.nation_battle: null 表示斷線重連後呼叫 API profile 據點戰已結束，導向結果頁
      //profile.nation_battle: 有值，但 nation_battle.channel 被清空，戰鬥還要演完最後一場

      console.log(`[Nationbattle] profile.nation_battle 已清空(斷線重連後)，導向結果頁`);
      navigate('/nationbattleresult');

      return;
    }
  }, [DCContext.userProfile?.nation_battle]);

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.nationBattleChannelTopic]) {
      console.log(`[Nationbattle] channel ${DCContext.nationBattleChannelTopic} 未連線`);
      return;
    }

    console.log(`[Nationbattle] channel ${DCContext.nationBattleChannelTopic} 已連線`);
    DCContext.getNation_battle_status();
  }, [ChannelContext.channels[DCContext.nationBattleChannelTopic]]);

  //API nation_battle_status 結果
  useEffect(() => {
    let _key = `${DCContext.nationBattleChannelTopic},nation_battle_status`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //console.log(`[Nationbattle] [API 結果] ${_key}`, {..._res});

    //
    if (_res.status == 'error') {
      console.log(`[Nationbattle] ${_key} error`);
    } else if (_res.status == 'ok') {
      /* 據點戰
			{"not_started"}					開始時間未到							 停在本部跳訊息通知
      {"initiate"}						開始時間已到，尚未發起			 選隊伍
      {"roll_call"}						已發起
        data.player_joined  	false => 未參戰             選隊伍
                            	true  => 已參戰，未開戰      等待開戰頁
			{"manuver"}				 			已開戰，開始選擇戰區					聊天室 選戰區
      {"battle"}	 						已開戰，開始交戰 							交戰頁
      {"concluded"}						已分勝負 									結果頁
      {"no_battle"}  					本聯盟今天沒有參戰					停在本部跳訊息通知
			*/

      let tmpData = _res.payload;

      //debug
      //tmpData = debugStatusR["concluded"];

      console.log(`[Nationbattle] nation_battle_status [API]`, tmpData.status, tmpData);

      //集結階段才有返回鍵
      setBattleLeavable(tmpData.status == `roll_call` ? true : false);
      //集結階段才顯示短訊
      DCContext.setShowShortMessage(tmpData.status == `roll_call` ? true : false);

      //各階段資料
      switch (tmpData.status) {
        case 'no_battle':
        case 'not_started':
        case 'initiate':
          navigate('/home');
          break;

        case 'roll_call':
        case 'maneuver':
          setBattleData(tmpData);
          break;

        case 'battle':
        case 'concluded':
          //離開再回到據點戰，第一次 getNation_battle_status 結果是 battle 階段，先取得下回合 maneuver 資料
          if (!battleData) {
            //取下回合 maneuver 資料
            DCContext.getNation_battle_status({ params: { maneuver: true } });
          } else {
            //有 battleData 時
            setFightData(tmpData);
          }
          break;
      }
    } else {
      console.log(`[Nationbattle] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.nationBattleChannelTopic},nation_battle_status`]?.uuid]);

  //Server broadcast

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[DCContext] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //據點戰
      case `${DCContext.nationBattleChannelTopic},nation_battle_status`:
        //console.log('[Nationbattle] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpData = ChannelContext.messages?.res?.payload;
        console.log('[Nationbattle] nation_battle_status [broadcast]', tmpData.status, tmpData);

        //集結階段才有返回鍵
        setBattleLeavable(tmpData.status == `roll_call` ? true : false);
        //集結階段才顯示短訊
        DCContext.setShowShortMessage(tmpData.status == `roll_call` ? true : false);

        switch (tmpData.status) {
          case 'roll_call': //有人參賽時，戰力數值變動
            setBattleData(tmpData);
            break;

          case 'maneuver':
            if (tmpData.round == 1) {
              console.log('[Nationbattle] broadcast maneuver 第一次', tmpData);
              //取 nation_battle_status 完整資料 (broadcast maneuver 沒有 battle_zone_position)
              DCContext.getNation_battle_status();
            } else if (battleData) {
              //已經有完整 battleData (API取得) 才合併
              console.log('[Nationbattle] broadcast maneuver 合併原資料', tmpData);
              setBattleData(prevState => {
                return lodash_merge(lodash_cloneDeep(prevState), tmpData);
              });
            }
            break;

          case 'battle':
            // if (!battleData){
            //   //取 maneuver 資料
            // 	DCContext.getNation_battle_status({params:{maneuver:true}});
            // }

            //如果有顯示 “更換戰區時間未開始或已結束” 此時自動關閉
            DCContext.setShowConfirmModal();

            //debug 不進入戰鬥畫面
            setFightData(tmpData);
            break;
        }
        break;

      //更換戰區後 || 間諜偵察後 || 指揮官分配戰區後 => 更新 power
      case `${DCContext.nationBattleChannelTopic},nation_battle_power`:
        let tmpPower = ChannelContext.messages?.res?.payload;
        console.log('[Nationbattle] broadcast nation_battle_power', tmpPower);

        if (battleData) {
          setBattleData(prevState => {
            let tmp = { ...prevState };
            tmp.data.power = tmpPower.power; //只更新 power
            return tmp;
          });
        }
        break;

      //指揮官就位
      case `${DCContext.nationBattleChannelTopic},Commander on deck`:
        setCommanderOnline('YES');

        DCContext.playSound(`/audio/sound_effect/SE144.mp3`);

        clearTimeout(timer_commanderOnline);
        setTimeout(() => {
          setCommanderOnline();
        }, 3000);
        break;
    }
  }, [ChannelContext.messages]);

  /* 基本資料 */

  useEffect(() => {
    if (!battleData) {
      return;
    }

    let tmpData = battleData;

    console.log('[Nationbattle] battleData', { ...battleData });

    //基本資料 zones
    if (tmpData.zones) {
      setZonesData(tmpData.zones);
    }

    //基本資料 match
    if (tmpData.match) {
      let tmpMatch = tmpData.match;

      setMatchData({
        LEFT: {
          flag: tmpMatch.offender_union.flag,
          medal_image: tmpMatch.offender_union.medal_image,
          title1: DCContext.cityNames?.[tmpMatch.offender_union.city_id],
          title2: tmpMatch.offender_union.name,
        },
        RIGHT: {
          flag: tmpMatch.defender_union.flag,
          medal_image: tmpMatch.defender_union.medal_image,
          title1: DCContext.cityNames?.[tmpMatch.defender_union.city_id],
          title2: tmpMatch.defender_union.name,
        },
      });

      //切換音樂
      if (battleData.music) {
        DCContext.playMusic(`${battleData.music}`);
      }
    }
  }, [battleData]);

  useEffect(() => {
    if (!fightData) {
      return;
    }

    let tmpData = fightData;

    //console.log('[Nationbattle] fightData', tmpData);

    //基本資料 zones
    if (tmpData.zones) {
      setZonesData(tmpData.zones);
    }

    //基本資料 match
    if (tmpData.match) {
      let tmpMatch = tmpData.match;

      setMatchData({
        LEFT: {
          flag: tmpMatch.offender_union.flag,
          medal_image: tmpMatch.offender_union.medal_image,
          title1: DCContext.cityNames?.[tmpMatch.offender_union.city_id],
          title2: tmpMatch.offender_union.name,
        },
        RIGHT: {
          flag: tmpMatch.defender_union.flag,
          medal_image: tmpMatch.defender_union.medal_image,
          title1: DCContext.cityNames?.[tmpMatch.defender_union.city_id],
          title2: tmpMatch.defender_union.name,
        },
      });
    }
  }, [fightData]);

  //API maneuver 更換戰區 結果

  useEffect(() => {
    let _key = `${DCContext.nationBattleChannelTopic},maneuver`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Nationbattle] [更換戰區 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      DCContext.setShowConfirmModal({
        confirm: {
          message: { i18nKey: `nation_battle_change_zone_warn` }, //更換戰區時間未開始或已結束
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                //console.log('xxxxx');
                DCContext.setShowConfirmModal();
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      let tmpData = _res.payload;

      //回傳資料不全，只更新戰區位置 (data.power 由 server broadcast "nation_battle_power" 更新)
      if (battleData) {
        setBattleData(preState => {
          return {
            ...preState,
            battle_zone_position: tmpData.battle_zone_position, //只更新戰區位置
          };
        });
      }
    } else {
      console.log('maneuver error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.nationBattleChannelTopic},maneuver`]?.uuid]);

  /* 開關門轉場 */

  //已關門
  const doorClose_callback = () => {
    console.log('[Nationbattle] doorClose_callback');
    setDoorClosed(true);
  };

  const doorOpen_callback = () => {
    console.log('[Nationbattle] doorOpen_callback');
    setDoorShowed(true);
  };

  //callback 戰鬥舞台回合結束
  const roundEnd_callback = () => {
    console.log('[Nationbattle] 本回合戰鬥結束', { ...fightData });

    if (fightData.good_game) {
      console.log('[Nationbattle] 據點戰結束，顯示結果');
      //setShowMedals(true);
      navigate('/nationbattleresult');
    } else {
      console.log('[Nationbattle] 等待下回合');

      //取下回合 maneuver 資料
      if (!battleData) {
        DCContext.getNation_battle_status({ params: { maneuver: true } });
      }

      //清除 battle 資料，關閉戰鬥舞台
      setFightData();
    }
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox}>
        {doorClosed && (
          <div className={styles.pageBox} style={{ zIndex: 10 }}>
            <BattleRoom
              _mode={_mode}
              zonesData={zonesData}
              battleData={battleData}
              commanderOnline={commanderOnline}
            />
          </div>
        )}

        {doorShowed && fightData && zonesData ? (
          <div className={styles.pageBox} style={{ zIndex: 20 }}>
            <BattleStage
              zonesData={zonesData}
              fightData={fightData}
              roundEnd_callback={roundEnd_callback}
            />
          </div>
        ) : (
          //選戰區畫面才顯示，戰鬥畫面不顯示
          // <PopupMessagesIcon category={0}/>
          <></>
        )}

        {/* {showMedals && (
					<div className={styles.pageBox}	style={{zIndex:30}}>
					<Nationbattle_result win={fightData.win} style={{zIndex:30}}/>
					</div>
				)} */}

        {matchData && !doorShowed && (
          <div className={styles.pageBox} style={{ zIndex: 40, backgroundColor: 'unset' }}>
            <AniDoor
              matchData={matchData}
              doorClose_callback={doorClose_callback}
              doorOpen_callback={doorOpen_callback}
              style={{ zIndex: 40 }}
            />
          </div>
        )}
      </div>

      <Navigator
        navi={{
          back: battleLeavable
            ? {
                callback: () => {
                  navigate('/nationbattlemap', {
                    state: {
                      focus_city_id: DCContext.userProfile.nation_battle?.city_id,
                      //returnUrl: location.pathname,
                      //returnState: location.state
                    },
                  });
                },
              }
            : {
                show: false,
              },
        }}
      />

      {/* <div style={{color:"white", textAlign:"left"}}>
				DoorShowed: {doorShowed?1:0}, fightData: {fightData?1:0}
			</div> */}
    </div>
  );
};

