import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Actoroutfits.module.scss';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnRing } from 'component/BtnRing';
import { ActorSwitch } from 'component/ActorSwitch';
//
import background from 'assets/img/bgClockGold.png';
import circleGolden from 'assets/img/circleGolden.png';

export const Actoroutfits = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  let { actionId } = useParams();
  actionId = parseInt(actionId);
  //console.log('actionId: ', actionId);
  //
  const [actor, setActor] = useState();
  const [outfit, setOutfit] = useState();
  const outfitIdx = useRef(0);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Actoroutfits] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('channel player 斷線');
      return;
    }

    console.log('channel player 已連線');
    DCContext.getActors();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.actors) {
      return;
    }

    console.log('[Actoroutfits] DCContext.actors', DCContext.actors);

    let actorData = DCContext.getActorDataById(actionId);
    setActor(actorData);
    console.log('[Actoroutfits] actorData', actorData);
  }, [DCContext.actors, actionId]);

  useEffect(() => {
    if (!actor) {
      return;
    }

    setOutfit(actor.outfits[outfitIdx.current]);
  }, [actor]);

  const changeOutfit = p => {
    let newIdx = outfitIdx.current + p;
    if (newIdx >= actor.outfits.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = actor.outfits.length - 1;
    }
    console.log('[Actoroutfits] newIdx', newIdx);

    outfitIdx.current = newIdx;
    setOutfit(actor.outfits[outfitIdx.current]);
  };

  const pickFitout = () => {
    DCContext.updateActor({
      id: actor.id,
      outfit_id: outfit.id,
    });
  };

  //update_actor 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]) {
      return;
    }

    console.log('[Actoroutfits] player,update_actor', { ...DCContext.msgRes });

    //todo error處理

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},update_actor`];
      return { ...prevState };
    });

    //
    navigate(`/user/actorprofile/${actor.id}`);
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]?.uuid]);

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${background})` }}>
      <div className={styles.mainBox}>
        <Iimg
          className={styles.character}
          src={outfit?.image}
          transition={false}
          onReady={() => {}}
        />
        <Iimg
          className={styles.character_full}
          src={outfit?.image}
          transition={false}
          onReady={() => {}}
        />

        <div className={styles.nameBox}>
          <ActorSwitch actor={outfit?.name} callback_changeActor={changeOutfit} />
        </div>

        <BtnRing
          color="golden"
          text={tt(`confirm`) /* 確定 */}
          callback={e => {
            pickFitout();
          }}
        />
      </div>
      <Navigator></Navigator>
    </div>
  );
};
