const lineColors = ['#cf625f', '#d2e95d', '#6ab3de'];

const Hline = props => {
  const { idx0, gsItems, colQuantity } = props;
  //console.log("Hline props", idx0, {...gsItems}, colQuantity);

  let pointL = 0;
  let pointR = 0;

  if (gsItems[idx0] !== undefined) {
    //此大項裡有選取
    let idxAry = Object.keys(gsItems[idx0]);
    //console.log("Hline idxAry", idxAry);

    if (idxAry.length == 1) {
      //只有一個分支有選取
      //console.log("Hline 一個端點", idxAry[0]);
      let p1 = 50; //一點在正中央
      let p2 = ((parseInt(idxAry[0]) + 0.5) / colQuantity) * 100;
      //console.log("Hline p1 p2", p1, p2);

      pointL = Math.min(p1, p2);
      pointR = Math.max(p1, p2);
      //console.log("Hline pointL pointR", pointL, pointR);
    } else if (idxAry.length >= 2) {
      //兩個以上分支有選取
      let minIdx = Math.min(...idxAry);
      let maxIdx = Math.max(...idxAry);
      //console.log("Hline 兩個端點以上", minIdx, maxIdx);

      let p1 = ((parseInt(minIdx) + 0.5) / colQuantity) * 100;
      let p2 = ((parseInt(maxIdx) + 0.5) / colQuantity) * 100;
      pointL = Math.min(p1, p2);
      pointR = Math.max(p1, p2);

      //console.log("Hline pointL pointR", pointL, pointR);
    }
  }

  let _styleColor = {};
  if (gsItems[idx0] === undefined || pointL == pointR) {
    _styleColor = {
      display: `none`,
    };
  } else {
    _styleColor = {
      backgroundColor: lineColors[idx0],
      left: `calc(${pointL}% - (${styles.lineWidth}/2))`,
      right: `calc(${100 - pointR}% - (${styles.lineWidth}/2))`,
      boxShadow: `${lineShadowSize} ${lineColors[idx0]}`,
    };
  }
  //console.log("[Hline] _styleColor", _styleColor);

  //全長白底背景
  const _styleBg = {
    width: `calc((${colQuantity - 1}/${colQuantity}*100%) + ${styles.lineWidth})`,
  };
  //console.log("[Hline] _style", _style);

  return (
    <>
      <div className={`${styles.lineH} ${styles.bg}`} style={_styleBg}></div>
      <div className={`${styles.lineH}`} style={_styleColor}></div>
    </>
  );
};

const Vline = props => {
  const { section, idx0, idx1, idx2, gsItems } = props;
  //console.log("Vline", idx0, idx1, idx2, gsItems);

  let heightClass = '';
  let style = {
    //backgroundColor: "white",
    //opacity: 0.4
  };

  switch (section) {
    case 'general_head':
      //console.log("Vline", idx0, idx1, idx2, gsItems);
      //樹狀頭
      heightClass = styles.bottom50;
      //
      if (gsItems[idx0] !== undefined) {
        style = {
          backgroundColor: lineColors[idx0],
          opacity: 1,
          boxShadow: `${lineShadowSize} ${lineColors[idx0]}`,
        };
      }
      break;
    case 'general_body':
      //樹狀分支
      if (idx2 == 0) {
        heightClass = styles.top50;
      }

      //樹狀分支
      //比對 undefined 因為值可能為零
      if (gsItems[idx0] === undefined || gsItems[idx0][idx1] === undefined) {
        //該分支全未選取
      } else if (idx2 < gsItems[idx0][idx1]) {
        //該分支有選取 排在被選取物件之前
        style = {
          backgroundColor: lineColors[idx0],
          opacity: 1,
          boxShadow: `${lineShadowSize} ${lineColors[idx0]}`,
        };
      } else if (idx2 == gsItems[idx0][idx1]) {
        //該分支有選取 為被選取物件
        style = {
          backgroundColor: lineColors[idx0],
          opacity: 1,
          boxShadow: `${lineShadowSize} ${lineColors[idx0]}`,
        };
      }
      break;
  }

  return <div className={`${styles.lineV} ${heightClass}`} style={style}></div>;
};

