import React from 'react';
import { useI18n } from 'lib/useI18n';
import { useDCContext } from 'lib/DCContext';
// 沿用主力遷移確認視窗 (train icon) 的公版樣式與行動力 header — 規格 p.11 第一個圖。
import styles from 'component/modal/MoveForceConfirm.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { BtnGrey } from 'component/BtnGrey';
import iconEnergyPlus from 'assets/img/iconEnergyPlus.png';

const round1 = n => Math.round((Number(n) || 0) * 10) / 10; // 小數點後 1 位、四捨五入

/*
 * uw_move_confirm 提示視窗公版 (規格 p.11 第一個圖)。
 * 版型比照 /nationbattlemap 左下火車 icon 的 MoveForceConfirm：
 *   - 左上行動力 header：[icon] 當前能量 (−預計消耗) / 能量上限
 *   - 內文：確定要消耗{{energy}}能量前往{{city_name}}？預計將於{{time}}分鐘後抵達。
 *   - 只有一顆「確定」鍵
 */
export const UwMoveConfirm = ({ cityName, energy, minutes, onConfirm }) => {
  const { tt } = useI18n();
  const DCContext = useDCContext();

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={`${styles.contentBox} modalContentBox`}>
          <div className={`${styles.descriptionBox} modalDescriptionBox`}>
            {tt('uw_move_confirm', { energy, city_name: cityName, time: round1(minutes) })}
          </div>
          <div className={styles.foorBox}>
            <BtnGrey text={tt('confirm')} callback={onConfirm} />
          </div>
        </div>
      </div>

      {/* 左上行動力 header (比照火車 icon 的 MoveForceConfirm) */}
      <div className={styles.outBoxTop}>
        <div className={styles.outBtnL}>
          <img
            src={iconEnergyPlus}
            className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`}
            alt=""
          />
          {DCContext.userProfile?.energy} <span style={{ color: '#60c0bd' }}>(-{energy})</span> /{' '}
          {DCContext.getUser_maxEnergyByLevel && DCContext.getUser_maxEnergyByLevel()}
        </div>
      </div>
    </div>
  );
};
