import React, { useState, useEffect } from 'react';
import { ClickEffect } from 'componentx/ClickEffect';
import { useDCContext } from 'lib/DCContext';
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useI18n } from 'lib/useI18n';
import { Imodal } from 'componentx/Imodal';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import iConfig from 'iConfig';
import { uwImage } from '../assets/uwImages';
import styles from './UwPortalCollectButton.module.scss';

/*
 * UW — 入口地圖右下「工作站收益」按鍵 (規格書第 36 頁，真實資料版)。
 *
 *  - 圖檔：uw08.png (圖文分開、上下置中)。
 *  - 文字 (走 i18n)：可領 uw_collect_all_b「工作站收益」/ 已領 uw_collected_all「本日已收取」
 *    (50% 透明度)。已領文案與城內介面、玩家資訊視窗統一為「本日已收取」。
 *  - 點擊效果同 #/attacks/uwtown 的 uw_collect_all：後端聚合此 user 所有 workstations
 *    本日 output_quantity 並發素材，回傳 rewards。
 *  - 可收取狀態來自 profile.can_collect_all (東八區每日 00:00 重置)。
 *
 *  修正 (回報)：
 *   1. 按鍵狀態同步 — 收取後以 getProfile(true) 強制重抓 (原本 getProfile() 走快取 → can_collect_all
 *      不更新，按鍵仍可點、再點跳「沒有可收取的產量」)。進頁時也重抓一次，確保「當日已領且無新落成工作站」
 *      直接顯示「本日已收取」。收取回傳空 rewards 時不再彈窗，直接讓按鍵轉為已領。
 *   2. 收取結果改用遊戲公版獲得視窗 (BundleReceivedAlert)，取代自製 overlay。
 */

const SE1 = '/audio/sound_effect/SE1.mp3';
// 「恭喜獲得」的收取音效。BundleReceivedAlert 是從 bundleItems.sound_effect 取，
// 沒帶就整頁靜音 (回報：收取畫面沒有音效)。server 的 uw_collect_all 已會帶同名欄位，
// 這個常數只是舊 server 的 fallback。
const SE_COLLECT_ITEM = '/audio/sound_effect/collect_item.mp3';
// uw08.png 改由 bundle 出貨 (見 assets/uwImages)。
const uwImg = uwImage;

export const UwPortalCollectButton = () => {
  const { tt } = useI18n();
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const topic = DCContext?.playerChannelTopic;

  // 可收取狀態：profile.can_collect_all (server 每次 profile 帶回)。
  const canCollect = !!DCContext?.userProfile?.can_collect_all;
  const collected = !canCollect;

  // 遊戲公版「恭喜獲得」視窗 (BundleReceivedAlert) — 與每日禮包/公告同一套。
  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });
  const showModal_BRA = exProps =>
    setModalProps_BRA(prev => ({ ...prev, ...exProps, visible: true }));
  const callbackModal_BRA = () => setModalProps_BRA(prev => ({ ...prev, visible: false }));

  // 進頁時強制重抓 profile → can_collect_all 為最新 (按鍵狀態立即正確)。
  useEffect(() => {
    DCContext.getProfile && DCContext.getProfile(true);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const onClick = () => {
    if (!canCollect || !topic) return;
    ChannelContext.sendMessage({ topic, event: 'uw_collect_all', message: {} });
  };

  // 消化 uw_collect_all 回覆：
  //   有 rewards → 遊戲公版獲得視窗；無 rewards (無可收) → 不彈窗，僅重抓 profile 轉為已領。
  //   一律 getProfile(true) 強制更新 can_collect_all → 修正按鍵不同步。
  useEffect(() => {
    const r = ChannelContext.sendMessageRes;
    if (!r || r.topic !== topic || r.event !== 'uw_collect_all') return;
    if (r.res?.status === 'ok') {
      const rewards = r.res.payload?.rewards || [];
      DCContext.getProfile && DCContext.getProfile(true);
      if (rewards.length > 0) {
        showModal_BRA({
          params: {
            title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
            showBg: true,
            // BundleReceivedAlert 的 items 為「頁陣列」，每頁一組道具；此處全部放同一頁。
            bundleItems: {
              items: [rewards],
              sound_effect: {
                items: r.res.payload?.sound_effect?.items || SE_COLLECT_ITEM,
              },
            },
          },
        });
      }
    }
  }, [ChannelContext.sendMessageRes]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className={styles.box}>
      <ClickEffect effect={{ sound: SE1 }} onClick={onClick}>
        <div className={`${styles.btn} ${collected ? styles.btnDone : ''}`}>
          {/* 圖文分開、置中對齊：uw08.png 在上、文字在下 */}
          <div
            className={styles.btnImage}
            style={{ backgroundImage: `url(${uwImg('uw08.png')})` }}
          />
          {/* 文案走 i18n (規格 p.36)：可領 uw_collect_all_b「工作站收益」/
              已領 uw_collected_all「本日已收取」。 */}
          <span className={styles.text}>
            {collected ? tt('uw_collected_all') : tt('uw_collect_all_b')}
          </span>
        </div>
      </ClickEffect>

      {/* 遊戲公版「恭喜獲得」獲得視窗 */}
      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </div>
  );
};
