import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Teams } from 'component/Teams';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { ClickEffect } from 'componentx/ClickEffect';
import iConfig from 'iConfig';
import styles from './TeamsMake.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

export const TeamsMake = props => {
  //console.log("[TeamsMake] props", props);

  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();

  //
  let mode = props.mode;
  //
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;

  console.log('[TeamsMake] useParams: ', mode, teamIdx, location);

  useEffect(() => {}, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    //
    console.log('[TeamsMake] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile, mode, teamIdx]);

  //編隊
  const handleClick_pick = e => {
    console.log('[TeamsMake] handleClick_pick');

    //出戰前選隊伍
    if (mode == 'select') {
      return;
    }

    navigate(`/user/pickactors/${teamIdx}`);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams mode={mode} teamIdx={teamIdx} />

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />
    </IbgDiv>
  );
};
