export const RewardCollect = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  const iZIndex = useRef(highestZindex({ _level: 'low' }));
  //
  let navigate = useNavigate();

  //
  const [title, setTitle] = useState();
  const [description, setDescription] = useState();

  useEffect(() => {
    if (!DCContext.showRewardCollect) {
      return;
    }

    console.log(`[RewardCollect] DCContext.showRewardCollect`, DCContext.showRewardCollect);

    DCContext.setShowProcessingModal(true); //顯示“處理中”
    DCContext.collectBundle(DCContext.showRewardCollect);
  }, [DCContext.showRewardCollect]);

  //collect_bundle 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //debug
    //_res = debugData['collect_bundle_1'];

    console.log(`[RewardCollect] ${_key}`, { ..._res });

    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    if (_res.status == 'error') {
      DCContext.setShowConfirmModal({
        confirm: {
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                //console.log('xxxxx');
                DCContext.setShowConfirmModal();
                DCContext.setShowRewardCollect();
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: '', //tt(`bundle_receive_congratulations`)/* 恭喜獲得 */,
          bundleItems: _res.payload.collected_items,
          backgroundColor: 'rgb(0,0,0,0)',
          disableFirstSound: false, //獎勵第一頁不播放音效，此畫面要播放勝利或失敗音效
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });

      //組出描述文字
      if (DCContext.showRewardCollect.reference_type == 'Minister') {
        //中央援助
        //{{union_name}} 擔負 {{hq_name}}{{department}} 的重責大任，希望這些援助有益於紓解貴單位辛勞。

        console.log('[RewardCollect] description', DCContext.myUnionNation.ministers);
        let minister = lodash_find(DCContext.myUnionNation.ministers, [
          'minister_union_id',
          DCContext.myUnion.id,
        ]);

        let tmp = tt('reward_minister_description', {
          union_name: DCContext.myUnion.name,
          hq_name: DCContext.myUnionNation.headquarters,
          department: minister?.ministry?.name,
        });
        console.log('[RewardCollect] description 2', tmp);

        setDescription(tmp);
        setTitle(minister?.ministry?.name);
      } else if (DCContext.showRewardCollect.reference_type == 'Control Union') {
        //本地援助
        //{{town_name}} 深受 {{union_name}} 的影響，本地有力人士向您提供以下援助。

        let tmp = tt('reward_control_union_description', {
          town_name: DCContext.showRewardCollect._city_name,
          union_name: DCContext.myUnion.name,
        });
        console.log('[RewardCollect] description 3', tmp);

        setDescription(tmp);
        setTitle(DCContext.showRewardCollect._city_name);
      }
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[RewardCollect] callbackPlayerModal', type, e);

    DCContext.setShowRewardCollect();

    // setModalProps_BRA((prevState)=>({
    // 	...prevState,
    // 	visible: false
    // }));
  };

  return (
    <IbgDiv
      className={styles.contentBox}
      src={null}
      transition={false}
      onReady={() => {}}
      style={{
        zIndex: iZIndex.current,
      }}
    >
      {modalProps_BRA.params && (
        <>
          <div className={styles.bodyBox}>
            <div className={styles.leftBox}>
              <Iimg
                className={styles.leftFlag}
                src={DCContext.myUnionNation?.flag}
                transition={false}
                onReady={() => {}}
              />
            </div>

            <div className={styles.middleBox}>
              <div className={styles.titleBox}>{title}</div>
              <div className={styles.descriptionBox}>{description}</div>
            </div>

            <div className={styles.rightBox}>
              <Iimg
                className={styles.rightFlag}
                src={DCContext.myUnionNation?.flag}
                transition={false}
                onReady={() => {}}
              />
            </div>
          </div>

          <div className={styles.page}>
            <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
          </div>
        </>
      )}

      {/* <Navigator navi={{
        navigator: {
          show: false,
        },
        back: {
          callback: ()=>{
            console.log('[RewardCollect] click back');
            DCContext.setShowRewardCollect();
          }
        }
      }}/> */}
    </IbgDiv>
  );
};

