import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
//i18n
import { useI18n } from 'lib/useI18n';
//
import { useDCContext } from 'lib/DCContext';
//
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import { Navigator } from 'component/modal/Navigator';
import { Loading } from 'component/Loading';

/*
 * UW 副本結算畫面 (規格書 p.20)。
 *
 * 規格明確要求採用「恭喜獲得」獲得視窗 —— 就是每日收取素材那一套公版
 * (BundleReceivedAlert)，**不是**攻城的勝利/失敗版面，也不播勝敗音效
 * (site_plots 全程不出現戰鬥畫面)。good_ending 只決定是否解鎖下一級，
 * 不影響這個畫面的呈現。
 *
 * 獎勵畫面關閉後回城內介面，並播放 cities.uw_music。
 *
 * 結算資料由 Story 於劇情播完／跳過時送出的 uw_finish_plot 回覆帶入
 * (DCContext.uwPlotResult)。
 */
export const UwPlotResult = () => {
  const { tt } = useI18n();
  const DCContext = useDCContext();
  const navigate = useNavigate();

  const result = DCContext.uwPlotResult;
  const plot = DCContext.uwPlotR;

  const [items, setItems] = useState(null);

  // 規格 p.20：進這個畫面就停掉所有背景音樂 (劇情的 BGM 會一路延續過來)。
  // 放在 mount 而不是等結算回覆才停 —— 否則等待回覆那段劇情音樂還會繼續播。
  // 獎勵畫面關閉、回到城內介面時才改播 cities.uw_music (見 goBackToCity)。
  useEffect(() => {
    DCContext.playMusic && DCContext.playMusic(false); // playMusic(false) = 暫停
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (!result) {
      return;
    }

    console.log('[UwPlotResult] uwPlotResult', result);

    const collected = result.collected_items;
    const hasReward = !!(collected?.items?.length || collected?.actors?.length);

    // 沒中獎 (spoil_probability 沒擲中) 就沒有可獲得的東西 —— 不顯示空的獲得視窗，
    // 直接回城內介面。
    if (!hasReward) {
      goBackToCity();
      return;
    }

    setItems(collected);
  }, [result]); // eslint-disable-line react-hooks/exhaustive-deps

  // 關閉後回城內介面，並播放 cities.uw_music (規格 p.20)
  const goBackToCity = () => {
    if (result?.uw_music && DCContext.playMusic) {
      DCContext.playMusic(result.uw_music);
    }

    navigate('/attacks/uwtown', {
      state: { cityId: result?.city_id ?? plot?.city_id },
    });
  };

  // 結算回覆還沒到 → 先顯示載入中，避免閃出空白畫面
  if (!result || !items) {
    return <Loading />;
  }

  return (
    <>
      {/* showBg：背後的金色時鐘裝飾 (bgClockGold)，與每日收取的獲得視窗一致 (規格 p.20)。
          注意不要像攻城結算那樣把 backgroundColor 設成透明 —— 攻城後面有勝利底圖襯著，
          副本這邊後面是空的，設透明會變成全黑、裝飾也跟著不見。 */}
      <BundleReceivedAlert
        title={tt(`bundle_receive_congratulations`) /* 恭喜獲得 */}
        showBg={true}
        bundleItems={items}
        callback={goBackToCity}
      />

      <Navigator navi={{ back: { show: false } }} />
    </>
  );
};
