export const validImageSrc = async targetSrc => {
  let url;

  //App 下載檔案存放位置
  if (window.deviceInfo?.assetsDL_path) {
    url = `${window.deviceInfo?.assetsDL_path}${targetSrc}`;
    //console.log("[validImageSrc] 1 url", url);

    const res1 = await loadImage(url);
    //console.log("[validImageSrc] 1 res", res1);

    if (res1) {
      return res1;
    }
  }

  //App reactjs 打包位置
  url = `${iConfig.Media.builtinAssets}${targetSrc}`;
  //console.log("[validImageSrc] 2 url", url);

  const res2 = await loadImage(url);
  //console.log("[validImageSrc] 2 res", res2);

  if (res2) {
    return res2;
  }

  //遠端網路
  const res3 = new Promise((resolve, reject) => {
    resolve(`${iConfig.Media.remoteAssets}${targetSrc}`);
  });
  return res3;
};

const loadImage = async src => {
  const res = await new Promise((resolve, reject) => {
    const img = new Image();

    img.onload = function () {
      //console.log("[validImageSrc] img onload", src);
      resolve(src);
    };
    img.onerror = img.onabort = function () {
      //console.log("[validImageSrc] img onerror", src);
      //reject(false);
      resolve(false);
    };
    img.src = src;
  });

  //console.log('[validImageSrc] loadImage result', res);

  return res;
};

// Handle the Promise returned by HTMLMediaElement.play(). WebView autoplay
// policy rejections are expected before a user gesture and must not become an
// unhandled application error.
export const safePlayMedia = async media => {
  if (!media || typeof media.play !== 'function') {
    return false;
  }

  try {
    await media.play();
    return true;
  } catch (error) {
    if (error?.name !== 'NotAllowedError' && error?.name !== 'AbortError') {
      console.warn('[media] play failed', error);
    }
    return false;
  }
};

export const validPlayAudio = async targetSrc => {
  let url;

  //App 下載檔案存放位置
  if (window.deviceInfo?.assetsDL_path) {
    url = `${window.deviceInfo?.assetsDL_path}${targetSrc}`;
    //console.log("[validPlayAudio] 1 url", url);

    const res1 = await playAudio(url);
    //console.log("[validPlayAudio] 1 res", res1);

    if (res1) {
      return res1;
    }
  }

  //App reactjs 打包位置
  url = `${iConfig.Media.builtinAssets}${targetSrc}`;
  //console.log("[validPlayAudio] 2 url", url);

  const res2 = await playAudio(url);
  //console.log("[validPlayAudio] 2 res", res2);

  if (res2) {
    return res2;
  }

  //遠端網路
  url = `${iConfig.Media.remoteAssets}${targetSrc}`;
  //console.log("[validPlayAudio] 3 url", url);

  const res3 = await playAudio(url);
  if (res3) {
    return res3;
  }

  return false;
};

const playAudio = async src => {
  const res = await new Promise((resolve, reject) => {
    let bgSoundRef = new Audio();
    bgSoundRef.autoplay = true;
    bgSoundRef.loop = false;

    bgSoundRef.onended = function () {
      //console.log("[validPlayAudio] playAudio onended", src);
      bgSoundRef = null;
      resolve(src);
    };
    bgSoundRef.onerror = bgSoundRef.onabort = function () {
      //console.log("[validPlayAudio] playAudio onerror", src);
      resolve(false);
    };

    bgSoundRef.src = src;
    safePlayMedia(bgSoundRef).then(played => {
      if (!played) {
        bgSoundRef = null;
        resolve(false);
      }
    });
  });

  //console.log('[validPlayAudio] playAudio result', res);

  return res;
};

export const iNumify = _text => {
  if (!_text) {
    return '0';
  }

  let tmp = numify(_text).toString();
  //console.log(`[func] [iNumify]`, tmp);

  return tmp.toUpperCase();
};

export const integerToRoman = num => {
  const romanValues = {
    M: 1000,
    CM: 900,
    D: 500,
    CD: 400,
    C: 100,
    XC: 90,
    L: 50,
    XL: 40,
    X: 10,
    IX: 9,
    V: 5,
    IV: 4,
    I: 1,
  };
  let roman = '';
  for (let key in romanValues) {
    while (num >= romanValues[key]) {
      roman += key;
      num -= romanValues[key];
    }
  }
  return roman;
};

export const highestZindex = ({ _level = 'low', _elType = '' } = {}) => {
  const levels = {
    //一般介面: 低於 modal (antd modal .ant-modal-wrap z-index: 1000)
    low: [1, 800],
    //一般介面: 高於 modal，不能被一般物件覆蓋
    middle: [2000, 3000],
    //系統介面: 絕對不能被覆蓋
    high: [4000, 5000],
  };

  let currentZindex = 0;
  let highestVisibleNavigator = {
    node: null,
    'z-index': 1,
  };

  const selector = `body *`;

  // return all the elements that matches in selector
  let elements = Array.from(document.querySelectorAll(selector));

  for (var i = 0; i < elements.length; i++) {
    // current element
    let node = elements[i];

    // get the computed css property
    let cssStyles = getComputedStyle(node);

    if (cssStyles.getPropertyValue('position') != 'static') {
      var result = 1;

      // Get the calculated CSS z-index value.
      let cssZIndex = cssStyles.getPropertyValue('z-index');

      // Get any inline z-index value.
      let inlineZIndex = node.style.zIndex;

      // Take the highest z-index for this element, whether inline or from CSS.

      if (
        cssZIndex != undefined &&
        cssZIndex != 'auto' &&
        inlineZIndex != undefined &&
        inlineZIndex != 'auto'
      ) {
        // Coerce the values as integers for comparison.
        cssZIndex = cssZIndex ? parseInt(cssZIndex) : 0;
        inlineZIndex = inlineZIndex ? parseInt(inlineZIndex) : 0;

        result = Math.max(cssZIndex, inlineZIndex);
      }

      //在範圍內 最大 z-index
      if (
        result > currentZindex &&
        //在 level 範圍內
        result >= levels[_level][0] &&
        result <= levels[_level][1]
      ) {
        currentZindex = result;
      }

      //不論範圍 最大 navigator
      if (
        _elType == 'ShortMessage' &&
        result > highestVisibleNavigator['z-index'] &&
        node.getAttribute('data-eltype') == 'Navigator'
      ) {
        highestVisibleNavigator = {
          node: node,
          'z-index': result,
        };

        //被蓋住的 navigator 也是 true，此變數暫時無用
        // let visible = node.checkVisibility({
        //   contentVisibilityAuto: true,
        //   opacityProperty: true,
        //   visibilityProperty: true
        // });

        //console.log(`[funcs] highestVisibleNavigator`, highestVisibleNavigator, visible);
      }
    }
  }

  if (_elType == 'ShortMessage' && highestVisibleNavigator.node) {
    //例外處理：快訊必須位於最高的 navigator 之下
    currentZindex = highestVisibleNavigator['z-index'] - 2;
  } else if (currentZindex < levels[_level][0]) {
    //一般處理：level 範圍內沒有符合的
    currentZindex = levels[_level][0];
  }

  //console.log(`[funcs] highestZindex`, _elType, currentZindex);

  return currentZindex + 1;
};

//小數後 digits 位 zero_fill 補零
export const decimals_digits = (number, digits, zero_fill) => {
  if (zero_fill) {
    return Number.parseFloat(number).toFixed(digits);
  } else {
    return +(Math.round(number + `e+${digits}`) + `e-${digits}`);
  }
};
