import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import useImagePreloader from 'lib/useImagePreloader';
//
import { Ivideo } from 'componentx/Ivideo';
import iConfig from 'iConfig';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

export const DemosDownload = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [loadedSectionKeys, setLoadedSectionKeys] = useState([]);

  useEffect(() => {
    if (!DCContext.demos) {
      return;
    }

    //console.log(`[DemosDownload] DCContext.demos`, DCContext.demos);

    //更新 preloads 資料
    let preloads = {};
    for (const sectionKey in DCContext.demos) {
      let o = DCContext.demos[sectionKey];
      //console.log("[DemosDownload] DCContext.demos", sectionKey, o);

      if (DCContext.userProfile?.completed_demo_section >= sectionKey) {
        //console.log("[DemosDownload] DCContext.demos 已完成， preloads 跳過", sectionKey);
        continue;
      }

      let preloadKey = `demos,${sectionKey}`;
      if (o?.images) {
        let tmpFiles = [];

        Object.entries(DCContext.demos[sectionKey].images).forEach(([key, od]) => {
          tmpFiles.push(od.image);
        });

        preloads[preloadKey] = tmpFiles;
      } else if (o?.videos) {
        let tmpFiles = [];

        Object.entries(DCContext.demos[sectionKey].videos).forEach(([key, od]) => {
          tmpFiles.push(od.path);
        });

        preloads[preloadKey] = tmpFiles;
      }
    }
    console.log('[DemosDownload] preloads', preloads);

    DCContext.setPreloads(preState => {
      return {
        ...preState,
        ...preloads,
      };
    });

    //debug
    //return;

    //開始預載各 sections 的 images video
    (async () => {
      for (const key in DCContext.demos) {
        let o = DCContext.demos[key];
        //console.log("[DemosDownload] DCContext.demos =====", key, o, {...DCContext.preloads});

        if (DCContext.userProfile?.completed_demo_section >= key) {
          //console.log("[DemosDownload] DCContext.demos 已完成，預載跳過", key);
          continue;
        }

        let preloadFiles = [];
        if (o.images) {
          Object.entries(o.images).forEach(([key2, o2]) => {
            preloadFiles.push(o2.image);
          });
        } else if (o.videos) {
          Object.entries(o.videos).forEach(([key2, o2]) => {
            preloadFiles.push(o2.path);
          });
        }

        console.log('[DemosDownload] preloadFiles', preloadFiles);

        await preloadStart(preloadFiles);

        //更新已完成預載清單
        let preloadKey = `demos,${key}`;
        setLoadedSectionKeys(preState => {
          return [...preState, preloadKey];
        });
      }
    })();
  }, [DCContext.demos]);

  useEffect(() => {
    if (!DCContext.preloads || !loadedSectionKeys?.length) {
      return;
    }

    //console.log("[DemosDownload] [AAA] DCContext.preloads", DCContext.preloads, loadedSectionKeys);

    //移除已完成的 preloads
    //debug
    loadedSectionKeys.map((o, idx) => {
      if (DCContext.preloads[o]) {
        DCContext.setPreloads(preState => {
          let tmp = { ...preState };
          tmp[o] = null;
          delete tmp[o];

          return tmp;
        });
      }
    });
  }, [DCContext.preloads, loadedSectionKeys]);

  useEffect(() => {
    console.log('[DemosDownload] DCContext.preloads', DCContext.preloads);
  }, [DCContext.preloads]);

  const preloadStart = async preloadFiles => {
    console.log('[DemosDownload] preloadStart() files', preloadFiles);

    const promiseList = [];
    for (const i of preloadFiles) {
      promiseList.push(preloadFile(i));
    }

    if (promiseList.length) {
      //allSettled => 全部跑完，即使中間有圖檔載入失敗
      //await 先等待處理結果
      await Promise.allSettled(promiseList)
        .then(value => {
          console.log('[DemosDownload] resolve all', value);
        })
        .catch(err => {
          console.log('[DemosDownload] err all', err);
        });
    }

    console.log('[DemosDownload] done all');
  };

  const preloadFile = src => {
    const loadFunc = src.toLowerCase().endsWith('mp4') ? loadVideo : loadImage;

    let preloadUrls = [
      `${iConfig.Media.builtinAssets}${src}`,
      `${window.deviceInfo?.assetsDL_path}${src}`, //,
      //`${iConfig.Media.remoteAssets}${src}`
    ];
    //console.log("[DemosDownload] preloadUrls", preloadUrls);

    const promiseList = [];
    for (const i of preloadUrls) {
      promiseList.push(loadFunc(i));
    }

    return new Promise((resolve, reject) => {
      //先試本地兩個 url，若都沒有再試遠端 url
      Promise.any(promiseList)
        .then(value => {
          //console.log("[DemosDownload] resolve", value);
          resolve(value);
        })
        .catch(err => {
          //console.log("[DemosDownload] err", err);

          //試遠端url
          let remoteUrl = `${iConfig.Media.remoteAssets}${src}`;
          loadFunc(remoteUrl)
            .then(value2 => {
              //console.log("[DemosDownload] resolve2", value2);
              resolve(value2);
            })
            .catch(err2 => {
              console.log('[DemosDownload] err2', err2);
              reject(err2);
            });
        });
    });
  };

  const loadImage = src => {
    //console.log("[DemosDownload] loadImage", src);
    return new Promise((resolve, reject) => {
      let img = new Image();
      img.onload = function () {
        //
        resolve(src);
      };
      img.onerror = img.onabort = function () {
        //
        reject(src);
      };
      img.src = src;
    });
  };

  const loadVideo = src => {
    //console.log("[DemosDownload] loadVideo", src);
    return new Promise((resolve, reject) => {
      let vdo = document.createElement('video');

      // vdo.onprogress = function() {
      //   console.log("[DemosDownload] video onprogress", src);
      // };

      // vdo.oncanplay = function() {
      //   console.log("[DemosDownload] video canplay", src);
      //   resolve(src);
      // };

      vdo.oncanplaythrough = function () {
        //console.log("[DemosDownload] video canplaythrough", src);
        resolve(src);
      };

      vdo.onerror = vdo.onabort = function () {
        //console.log("[DemosDownload] video error", src);
        reject(src);
      };

      vdo.src = src;
      vdo.load();
    });
  };

  return (
    <>
      {/* <Ivideo
              src={`/video/recruit/ESC.mp4`}
              //
              //className={styles.videoFit}
              style={{
                position: 'absolute',
                width: '1px',
                height: '1px'
              }}
              preload="auto" 
              playsInline="playsInline"
              onCanPlay={() => {
                console.log("[Demos] BBBBBBBBBB");
              }}
              onCanPlayThrough={() => {}}
              onEnded={() => {

              }}
              onError={()=>{

              }}
            /> */}
    </>
  );
};
