import React, { useContext, useState, useEffect, useRef } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Energyboost.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import bgItemGray from 'assets/img2/bgItemGray.png';
import iconBackGray from 'assets/img/modal/iconBackGray.png';
import bgSelectedItem from 'assets/img2/bgSelectedItem.png';
import icon_circleCheck from 'assets/img2/icon_circleCheck.png';
//
import iconEnergy_black from 'assets/img/iconEnergy_black.png';
import iconEnergyPlus from 'assets/img/iconEnergyPlus.png';
import bgSkillInfo from 'assets/img2/bgSkillInfo.png';

export const Energyboost = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [items, setItems] = useState();
  const [energyFulled, setEnergyFulled] = useState(false);
  const [usedQuantity, setUsedQuantity] = useState(0);

  useEffect(() => {
    console.log('[Energyboost] props', props);

    DCContext.getEnergy_boost_options();

    return () => {
      //console.log("[Energyboost] unamount");
    };
  }, []);

  //energy_boost_options 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},energy_boost_options`]) {
      return;
    }

    console.log('[Energyboost] player,energy_boost_options', {
      ...DCContext.msgRes[`${DCContext.playerChannelTopic},energy_boost_options`].res,
    });

    //todo error處理
    if (
      DCContext.msgRes[`${DCContext.playerChannelTopic},energy_boost_options`].res.status == 'error'
    ) {
      console.log('[Energyboost] player,energy_boost_options error', {
        ...DCContext.msgRes[`${DCContext.playerChannelTopic},energy_boost_options`].res,
      });
    }

    setItems(
      DCContext.msgRes[
        `${DCContext.playerChannelTopic},energy_boost_options`
      ].res.payload.energy_boost_options.map((el, idx) => {
        el.usedQuantity = 0;
        //debug
        //el.quantity = 3;
        return el;
      }),
    );

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},energy_boost_options`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},energy_boost_options`]?.uuid]);

  useEffect(() => {
    console.log('[Energyboost] items', items);
  }, [items]);

  const getCurrentEnergy = () => {
    if (!items) {
      return 0;
    }

    let tmp = DCContext.userProfile.energy;
    for (var i = 0; i < items.length; i++) {
      let el = items[i];
      if (el.full_energy && el.usedQuantity >= 1) {
        //全滿
        //console.log("[Energyboost] item 全滿");
        return DCContext.userProfile.energy_cap;
      }

      tmp += el.usedQuantity * el.energy;
    }

    if (tmp >= DCContext.userProfile.energy_cap) {
      tmp = DCContext.userProfile.energy_cap;
    }

    return tmp;
  };

  const clickItem = _idx => {
    let theItem = items[_idx];
    console.log('[Energyboost] clickItem', _idx, theItem);

    if ((theItem.usedQuantity + 1) * theItem.unit > theItem.quantity) {
      console.log('[Energyboost] clickItem 數量不足', _idx, theItem);
      return;
    }

    if (getCurrentEnergy() >= DCContext.userProfile.energy_cap) {
      console.log('[Energyboost] clickItem 能量已滿', _idx, theItem);
      setEnergyFulled(true);
      return;
    }

    setItems(prevState => {
      let tmp = [...prevState];
      tmp[_idx].usedQuantity += 1;
      return tmp;
    });

    setUsedQuantity(prevState => {
      return prevState + 1;
    });
  };

  const clickConfirm = () => {
    let tmp = [];
    items.map((el, idx) => {
      if (el.usedQuantity > 0) {
        tmp.push({
          id: el.id,
          quantity: el.usedQuantity,
        });
      }
    });

    console.log('[Energyboost] clickConfirm ', tmp);

    if (tmp.length > 0) {
      DCContext.redeem_energy_boosts({
        energy_boosts: tmp,
      });
    } else {
      props.callbackModal();
    }
  };

  //redeem_energy_boosts 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_energy_boosts`]) {
      return;
    }

    console.log('[Energyboost] player,redeem_energy_boosts', {
      ...DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_energy_boosts`].res,
    });

    //todo error處理
    if (
      DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_energy_boosts`].res.status == 'error'
    ) {
      console.log('[Energyboost] player,redeem_energy_boosts error', {
        ...DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_energy_boosts`].res,
      });
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},redeem_energy_boosts`];
      return { ...prevState };
    });

    props.callbackModal();
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_energy_boosts`]?.uuid]);

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <div className={styles.contentSubjectRow}>
            <div className={styles.subjectText}>
              {tt(`energy_recover_way_choose`) /* 點選能量恢復方式 */}
            </div>
            <div className={styles.warningBox}>
              {energyFulled && tt(`energy_recovered_over_limit`) /* 回復能量無法超過能量上限 */}
            </div>
          </div>

          <div className={styles.bodyBox}>
            {items && (
              <div className={styles.bundleItemsBox}>
                <img className={styles.bgSkillInfo} src={bgSkillInfo} />
                <div className={styles.itemsBox}>
                  {items.map((tmpItem, idx) => {
                    return (
                      <div className={styles.itemBox}>
                        <div className={styles.iconEnergyPlusBox}>
                          <img className={styles.iconEnergyPlus} src={iconEnergyPlus} />
                          <div className={styles.iconEnergyPlus_number}>
                            {tmpItem.full_energy ? tt(`full`) /*全滿*/ : tmpItem.energy}
                          </div>
                        </div>
                        <ClickEffect
                          enabled={
                            !energyFulled && tmpItem.quantity > tmpItem.usedQuantity * tmpItem.unit
                              ? true
                              : false
                          }
                          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                          onClick={() => {
                            clickItem(idx);
                          }}
                        >
                          <div className={styles.selectedItemBox}>
                            <Iimg
                              className={styles.selectedPieceImg}
                              src={tmpItem.image}
                              transition={false}
                              onReady={() => {}}
                            />
                            <div className={styles.selectedItemQuantity}>
                              {tmpItem.quantity - tmpItem.usedQuantity * tmpItem.unit}
                            </div>
                          </div>
                        </ClickEffect>
                        <div className={styles.selectedItemName}>{tmpItem.name}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          <div className={styles.footer}>
            <div className={styles.footerColL}></div>

            <div className={styles.footerColC}>
              {usedQuantity > 0 && (
                <BtnGrey
                  text={tt(`confirm`)}
                  callback={() => {
                    clickConfirm();
                  }}
                />
              )}
            </div>

            <div className={styles.footerColR}>
              <div className={styles.energyCalcBox}>
                <img className={styles.iconEnergy_black} src={iconEnergy_black} />
                <div className={styles.currentEnergy}>{getCurrentEnergy()}</div>
                <div className={styles.energyCap}>
                  &nbsp;/&nbsp;{DCContext.userProfile?.energy_cap}
                </div>
              </div>
            </div>
          </div>

          {/* <Row gutter={0} justify="center" >
          <Col span={24} justify="center">
            <ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={props.callback}>
              <div className={styles.formBtn}>
                <img src={popup_btn_bg} className={styles.btnBg}/>
                <div className={styles.btnText}>確定</div>
              </div>
            </ClickEffect>

            <div className={styles.energyCalcBox}>
              <img className={styles.iconEnergy_black} src={iconEnergy_black}/>
            </div>

          </Col>
        </Row> */}
        </div>
      </div>
    </div>
  );
};
