/*
category
{"據點戰", 0},
{"排名戰", 1},
{"入口地圖", 2},
{"指揮機關", 3},
{"牙牌", 4},
{"大地圖", 5},
{"陣營資訊", 6},
{"幹部資訊", 7}
*/

export const PopupMessages = () => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [messages, setMessages] = useState();

  useEffect(() => {
    if (!DCContext.popupMessages || DCContext.showPopupMessages?.category == undefined) {
      return;
    }

    setMessages(DCContext.popupMessages[DCContext.showPopupMessages?.category]);

    console.log(
      `[PopupMessages] popupMessages`,
      DCContext.showPopupMessages?.category,
      DCContext.popupMessages,
    );
  }, [DCContext.popupMessages, DCContext.showPopupMessages?.category]);

  return (
    <div className={styles.rootContainer}>
      <div className={styles.mainBox}>
        {messages?.length == 1 ? (
          <Page message={messages?.[0]} />
        ) : (
          <Swiper
            //slidesPerView={2}
            pagination={true}
            mousewheel={true}
            modules={[Pagination, Mousewheel]}
          >
            {/* <SwiperSlide>Slide 1</SwiperSlide>
          <SwiperSlide>Slide 2</SwiperSlide>
          <SwiperSlide>Slide 3</SwiperSlide>
          <SwiperSlide>Slide 4</SwiperSlide>
          <SwiperSlide>Slide 5</SwiperSlide>
          <SwiperSlide>Slide 6</SwiperSlide>
          <SwiperSlide>Slide 7</SwiperSlide>
          <SwiperSlide>Slide 8</SwiperSlide>
          <SwiperSlide>Slide 9</SwiperSlide> */}

            {messages?.map((el, idx) => {
              return (
                <SwiperSlide key={idx}>
                  <Page message={el} />
                </SwiperSlide>
              );
            })}
          </Swiper>
        )}
      </div>
    </div>
  );
};

const Page = props => {
  return (
    <div className={styles.nationIntroBox}>
      <div className={styles.nationIntroBox_leftBox}>
        <div className={styles.description_title}>{props.message?.title}</div>
        <Iimg
          className={styles.description_img}
          src={props.message?.image}
          transition={false}
          onReady={() => {}}
        />
      </div>
      <div className={styles.nationIntroBox_rightBox}>
        <div className={styles.description_subtitle}>{props.message?.subtitle}</div>
        <div
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: props.message?.message }}
        ></div>
      </div>
    </div>
  );
};
