import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './ActorWeapons.module.scss';
//
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BackpackItems } from 'component/BackpackItems';
import { ActorSwitch } from 'component/ActorSwitch';
//
import icon_upgrade from 'assets/img/icon_upgrade.png';
import icon_skilltree from 'assets/img/icon_skilltree.png';
import bgTitle_s from 'assets/img/bgTitle_s.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import circleGolden from 'assets/img/circleGolden.png';
import fgCharacterMask from 'assets/img2/fgCharacterMask.png';

//
import { ActorProps } from 'component/ActorProps';
import bgBackpack from 'assets/img2/bgBackpack.png';
import { BtnRing } from 'component/BtnRing';

export const ActorWeapons = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  const [actor, setActor] = useState();

  let { actionId } = useParams();
  actionId = parseInt(actionId);
  //console.log('[ActorWeapons] actionId: ', actionId);
  //

  useEffect(() => {
    console.log('[ActorWeapons] location.state', location.state);

    return () => {
      //清空暫選的符文
      console.log('[ActorWeapons] 清空暫選的符文');
      DCContext.setTmpSelectedWeapon(null);
    };
  }, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[ActorWeapons] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('channel player 斷線');
      return;
    }

    console.log('channel player 已連線');
    DCContext.getActors();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.actors) {
      return;
    }

    console.log('[ActorWeapons] DCContext.actors', DCContext.actors);

    //清空暫選的符文
    DCContext.setTmpSelectedWeapon(null);

    //
    let actorData = DCContext.getActorDataById(actionId);
    setActor(actorData);
    console.log('[ActorWeapons] actorData', actorData);
  }, [DCContext.actors, actionId]);

  const changeActor = p => {
    let newIdx = actor.idx + p;
    if (newIdx >= DCContext.actors.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = DCContext.actors.length - 1;
    }
    console.log('[ActorWeapons] newIdx', newIdx);

    navigate(`/user/actorweapons/${DCContext.actors[newIdx].id}`, {
      state: {
        returnUrl: location.state?.returnUrl,
        returnState: location.state?.returnState,
      },
    });
  };

  const callback_item = (_type, _data) => {
    console.log('[ActorWeapons] callback_item', _type, _data);
    switch (_type) {
      case 'actorPickWeapon':
        break;
    }
  };

  const callback_changeWeapon = () => {
    console.log('[ActorWeapons] callback_changeWeapon', DCContext.tmpSelectedWeapon);

    let tmp = {
      id: actor.id,
      weapon_id: DCContext.tmpSelectedWeapon.id || null,
    };
    console.log('[ActorWeapons] callback_changeWeapon', tmp);

    DCContext.updateActor(tmp);
  };

  //update_actor 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]) {
      return;
    }

    console.log('[ActorWeapons] player,update_actor', { ...DCContext.msgRes });

    //todo error處理

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},update_actor`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]?.uuid]);

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.bgBox} style={{ backgroundImage: `url(${bgBackpack})` }}></div>

      <div className={styles.mainBox}>
        <IbgDiv className={styles.leftBox} src={null} transition={false} onReady={() => {}}>
          <div className={styles.nameBox}>
            <ActorSwitch actor={actor} callback_changeActor={changeActor} />
          </div>

          <ActorProps mode={'weaponEquip'} actorData={actor} />
          {DCContext?.tmpSelectedWeapon &&
          ((!actor?.weapon?.id && DCContext?.tmpSelectedWeapon?.id) ||
            (actor?.weapon?.id && actor?.weapon?.id != DCContext?.tmpSelectedWeapon?.id)) ? (
            <BtnRing color="golden" text={tt(`swap`) /* 替換 */} callback={callback_changeWeapon} />
          ) : (
            <></>
          )}
        </IbgDiv>

        <div className={styles.rightBox}>
          {actor && (
            <BackpackItems
              itemType={2}
              mode={'actorPickWeapon'}
              actor={actor}
              callback_item={callback_item}
            />
          )}
        </div>
      </div>

      <Navigator
        navi={{
          back: {
            url: location.state?.returnUrl,
          },
        }}
      />
    </div>
  );
};
