export const Home = () => {
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();

  //基本資料準備
  const [basicDataReady, setBasicDataReady] = useState(false);
  const basicDatas = [
    //Channel player:x 加入成功時
    DCContext.userProfile,
    DCContext.unions,
    DCContext.nations,
    DCContext.cities,
    DCContext.election,
    DCContext.demos,
    DCContext.weapon_prototypes,
    //home 需要
    DCContext.bundles,
    DCContext.dailyBundles,
  ];
  const [preloadedRatio, setPreloadedRatio] = useState(0);

  useEffect(() => {
    if (ChannelContext.channels?.[DCContext.playerChannelTopic]?.state != 'joined') {
      console.log('[Home] ChannelPlayer 未連線');
      return;
    }

    //home 需要
    if (!DCContext.bundles) {
      DCContext.getBundles(true);
    }

    //home 需要
    if (!DCContext.dailyBundles) {
      DCContext.getDailyBundles(true);
    }
  }, [ChannelContext.channels?.[DCContext.playerChannelTopic]?.state]);

  /* 等待基本資料準備完整 */
  useEffect(() => {
    let readyQuantity = 0;
    basicDatas.map((el, idx) => {
      if (el) {
        readyQuantity++;
      }

      let tmpRatio = readyQuantity / basicDatas.length;
      //console.log('[Home] basicDatas', readyQuantity, tmpRatio, idx, el);
      setPreloadedRatio(tmpRatio);
    });

    if (readyQuantity == basicDatas.length) {
      setBasicDataReady(true);
    }
  }, basicDatas);

  /* demos */

  //debug 清空教學觀看紀錄
  // DCContext.updateProfile({
  // 	completed_demo_section: ''
  // });

  const demoSectionKeys = ['1.5', '2', '3', '4', '5', '6'];
  //const demoSectionKeys = ['6'];

  // if (DCContext.canShowDemos({
  // 	sectionKeys: demoSectionKeys
  // })){
  // 	return (
  // 		<Demos sectionKeys={demoSectionKeys} skipSectionKey={`6`} />
  // 	);
  // }

  return !basicDataReady ? (
    <Loading preloadedRatio={preloadedRatio}></Loading>
  ) : DCContext.canShowDemos({ sectionKeys: demoSectionKeys }) ? (
    <Demos sectionKeys={demoSectionKeys} skipSectionKey={`6`} />
  ) : (
    <_Home />
  );
};

