import React, { useContext, useState, useEffect } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { Col, Row, Modal } from 'antd';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Bundleorders.module.scss';
import stylesS from './BundleGift.module.scss';
import background from 'assets/img/bgClockGold.png';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { ClickEffect } from 'componentx/ClickEffect';
import { Confirm } from 'componentx/Confirm';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import { FitText } from 'lib/FitText';

//
import iconFunds from 'assets/img/iconFunds.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import iconExchangeArrow from 'assets/img/store/iconExchangeArrow.png';
//
import bgExchangeRate from 'assets/img/store/bgExchangeRate.png';
import iconPropsWhite from 'assets/img/iconPropsWhite.png';
import shopBtn from 'assets/img/store/shopBtn.png';
//
import bg_record_golden from 'assets/img2/actor_pools/bg_record_golden.png';
import bg_record_silver from 'assets/img2/actor_pools/bg_record_silver.png';

export const BundleGift = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [bundles, setBundles] = useState();
  const [products, setProducts] = useState();
  const [selectedProduct, setSelectedProduct] = useState();
  const catIdx = 3;

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[BundleGift] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[BundleGift] channel player 未連線');
      return;
    }

    console.log('[BundleGift] channel player 已連線');
    DCContext.getBundles(false); //錢莊 true 就可以
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.bundle_categories || !DCContext.bundles) {
      return;
    }

    let tmp = [];
    DCContext.bundles.map((item, idx) => {
      if (item.bundle_category_id == DCContext.bundle_categories[catIdx].id) {
        tmp.push(item);
      }
    });

    console.log('[BundleGift] bundles', tmp);

    setBundles(tmp);
  }, [DCContext.bundle_categories, DCContext.bundles]);

  useEffect(() => {
    if (!bundles) {
      return;
    }

    if (!DCContext.iapProducts) {
      DCContext.getIapProducts();
      return;
    }

    console.log('[BundleGift] DCContext.iapProducts', DCContext.iapProducts);

    let tmp = [];
    bundles.map((item, idx) => {
      if (item.fund > 0) {
        //用遊戲內銅錢可購買的商品
        tmp.push(item);
      } else {
        //Apple Google store IAP 商品
        let matchIapItem = DCContext.iapProducts.find(iapItem => {
          if (iapItem.productId == item.product_id) {
            return true;
          }
        });
        console.log('[BundleGift] matchIapItem', item.product_id, matchIapItem);

        if (matchIapItem) {
          tmp.push({
            ...item,
            iapData: matchIapItem,
          });
        }
      }
    });

    console.log('[BundleGift] merged products', tmp);

    setProducts(tmp);
  }, [bundles, DCContext.iapProducts]);

  //IAP 購買開始
  const buyProduct = _item => {
    console.log('[BundleGift] buyProduct _item', _item);

    //顯示購買物品內容
    DCContext.setShowStoreShopConfirm({
      data: {
        cost: `${_item.iapData?.currency} ${
          _item.iapData?.localizedPrice.startsWith('$')
            ? _item.iapData?.localizedPrice.substr(1)
            : _item.iapData?.localizedPrice
        }`,
        productName: _item.name,
      },
      callback: () => {
        //確定購買
        //console.log('xxxxx 2');

        DCContext.setShowProcessingModal(true); //顯示“處理中”
        //
        DCContext.buyIapProduct(_item.iapData.productId);
        //
        DCContext.setShowStoreShopConfirm();
      },
    });
  };

  //銅錢 購買開始
  const buyProduct_byFund = _item => {
    console.log('[BundleGift] buyProduct_byFund _item', _item, DCContext.userProfile.fund);

    //無法購買，東方大陸銅錢不足
    if (_item.fund > DCContext.userProfile.fund) {
      DCContext.setShowConfirmModal({
        confirm: {
          message: { i18nKey: `iap_cathayan_cash_not_enough` },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                //console.log('xxxxx');
                DCContext.setShowConfirmModal();
              },
            },
          ],
        },
      });

      return;
    }

    //顯示購買物品內容
    DCContext.setShowStoreShopConfirm({
      data: {
        cost: tt('iap_purchase_name_cash_exchange_amount', {
          exchange_amount: _item.fund.toLocaleString('en-US'),
        }),
        productName: _item.name,
      },
      callback: () => {
        //確定購買
        //console.log('xxxxx 2');

        //進行購買
        DCContext.redeem_bundle({
          bundle_id: _item.id,
        });

        DCContext.setShowStoreShopConfirm();
      },
    });

    //確認是否進行購買  iap_funds_for_bundle_confirm 是否使用銅錢{{funds}}文購買{{bundle_name}}？
    // DCContext.setShowConfirmModal({
    //   confirm: {

    //     message: {i18nKey:`iap_funds_for_bundle_confirm`, values:{funds:_item.fund, bundle_name:_item.name}, options:null},
    //     buttons: [
    //       {
    //         text: {i18nKey:`confirm`},
    //         callback: ()=>{
    //           //console.log('xxxxx');

    //           //進行購買
    //           DCContext.redeem_bundle({
    //             bundle_id: _item.id
    //           });

    //           DCContext.setShowConfirmModal();
    //         }
    //       }
    //     ]
    //   }
    // });
  };

  //API redeem_bundle 結果 (東方大陸銅錢購買禮包，非 IAP)
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},redeem_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[BundleGift] [redeem_bundle 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      showModal_BRA({
        params: {
          title: '', //tt(`bundle_receive_congratulations`)/* 恭喜獲得 */,
          bundleItems: _res.payload.collected_items,
          backgroundColor: 'rgb(0,0,0,1)',
          disableFirstSound: false, //獎勵第一頁不播放音效，此畫面要播放勝利或失敗音效
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('[BundleGift] redeem_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},redeem_bundle`]?.uuid]);

  useEffect(() => {
    if (!DCContext.iapPhase1) {
      return;
    }

    //iapPhase1 => OK 或 ERROR 都關閉“處理中” modal
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    DCContext.setIapPhase1(null);
  }, [DCContext.iapPhase1]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    maskClosable: false,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[BundleGift] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[BundleGift] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const aniStyles_moveup = useSpring(iConfig.aniStyles_moveup);

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <div className={stylesS.mainBox}>
        <animated.div className={stylesS.contentOutBox} style={{ ...aniStyles_moveup }}>
          {products?.map((item, idx) => {
            let price = item.iapData?.localizedPrice.startsWith('$')
              ? item.iapData?.localizedPrice.substr(1)
              : item.iapData?.localizedPrice;

            let description = item?.description;
            if (item?.limited_quantity_memo) {
              description += `<br/>${item?.limited_quantity_memo}`;
            }

            return (
              <div
                key={idx}
                className={stylesS.itemOutBox}
                style={{
                  backgroundImage: `url(${
                    item?.limited_time ? bg_record_golden : bg_record_golden
                  })`,
                  opacity: item.for_sale ? '1' : '0.5',
                }}
              >
                <div className={stylesS.itemBoxLeft}>
                  <div className={stylesS.itemBoxLeftBody}>
                    <div className={stylesS.itemBodyLeft}>
                      <Iimg
                        className={`${stylesS.giftItemImg}`}
                        src={item.image}
                        transition={false}
                        onReady={() => {}}
                      />
                      {/* <Iimg className={`${stylesS.giftItemImg}`} src={`/images/player/fund.png`} transition={false} onReady={()=>{}} /> */}
                      <div className={stylesS.giftItemName}>
                        <FitText _align="center">{item?.name}</FitText>
                      </div>
                    </div>

                    <div className={stylesS.itemBodyRight}>
                      <div
                        className={stylesS.giftItemDescription}
                        dangerouslySetInnerHTML={{ __html: description }}
                      ></div>
                    </div>

                    <div className={stylesS.giftItemPrize}>
                      {item.fund > 0 ? (
                        <>
                          {item.fund} <img className={stylesS.iconFunds} src={iconFunds} />
                        </>
                      ) : (
                        <>
                          {item.iapData?.currency} {price}
                        </>
                      )}
                    </div>
                  </div>
                </div>
                <div className={stylesS.itemBoxRight}>
                  <ClickEffect
                    enabled={item.for_sale}
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={() => {
                      item.fund > 0 ? buyProduct_byFund(item) : buyProduct(item);
                    }}
                  >
                    <div className={stylesS.recordType}>
                      {
                        DCContext.bundle_categories?.[catIdx].can_buy && item.for_sale
                          ? tt(`trade`) /* 交易 */
                          : tt(`sold_out`) /* 售罄 */
                      }
                    </div>
                  </ClickEffect>
                  <div className={stylesS.recordDate}>{item?.end_time}</div>
                </div>
              </div>
            );
          })}
        </animated.div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/user/backpack`);
          }}
        >
          <div className={styles.linkProps}>
            <img className={`rotation_1`} src={iconPropsWhite} />
            <span>{tt(`to_treasury`) /* 往庫房 */}</span>
          </div>
        </ClickEffect>
      </div>

      <div className={`tabBar ${styles.tabBar_shadow}`}>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundleorders');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`bank`) /* 錢莊 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/monthlycard');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`monthly_card`) /* 月卡 */}</div>
            {DCContext.bundle_categories?.[1].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlepass');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`activity_pass`) /* 通行證 */}</div>
            {DCContext.bundle_categories?.[2].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlegift');
          }}
        >
          <div className={`tab active`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`gift_pack`) /* 禮包 */}</div>
          </div>
        </ClickEffect>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </IbgDiv>
  );
};
