import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { ClickEffect } from 'componentx/ClickEffect';
//
import iConfig from 'iConfig';
import styles from './UnionListA.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
//
import icon_highlightCircle from 'assets/img2/icon_highlightCircle.png';

export const UnionListA = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [selectedUnion, setSelectedUnion] = useState();

  console.log(`[UnionListA]`, props);

  const clickItem = tmpUnion => {
    console.log(`[UnionListA] clickItem`, tmpUnion);
    setSelectedUnion(tmpUnion);
  };

  useEffect(() => {
    if (!selectedUnion) {
      return;
    }

    props.callback(selectedUnion);
  }, [selectedUnion]);

  return (
    <div className={styles.friendliesBox}>
      <div className={styles.friendliesScrollOutline}>
        <div className={styles.friendliesScrollInline}>
          {props.unions?.map((item, idx) => {
            //騎劫影響城鎮的影響聯盟：名稱顯示金色
            // const nameColorClass = (
            //   props.selectedCity.hijackable === false
            //   && item.id == props.selectedCity.control_union?.id
            // ) ? 'colorGolden' : '';

            const nameColorClass = item.gold ? 'colorGolden' : '';

            return (
              <>
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickItem(item);
                  }}
                >
                  <div key={item.id} className={`${styles.friendliesRow} ${nameColorClass}`}>
                    {/* 周遭友軍不顯示 icon_highlightCircle */}
                    {props.mode != 'friendlies' && selectedUnion?.id == item.id && (
                      <img className={styles.highlightImg} src={icon_highlightCircle} />
                    )}
                    <div className={styles.friendlies_power}>{item.power}</div>
                    <div className={`${styles.friendlies_unionName}`}>{item.name}</div>
                    <div className={styles.friendlies_cityName}>{item.city}</div>
                    <div className={styles.friendlies_metalIcon}>
                      <Iimg
                        className={styles.friendlies_metalImg}
                        src={item.medal}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                  </div>
                </ClickEffect>
              </>
            );
          })}
        </div>
      </div>

      <div className={styles.unionListPanel}></div>
    </div>
  );
};
