import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import styles from './NewUnion.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';

export const NewUnion = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  const [mode, setMode] = useState('CREATE');
  const [union, setUnion] = useState();

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    const data = {
      name: values.union_name,
    };

    console.log('[NewUnion] form data', mode, data);

    if (mode == 'EDIT') {
      DCContext.unionEdit(data);
    } else if (mode == 'CREATE') {
      DCContext.unionNew(data);
    }
  };

  const submitForm = () => {
    form.submit();
    console.log('submitForm');
  };

  //new_union 結果

  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},new_union`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[NewUnion] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      showModal_confirm({
        confirm: {
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackModal_confirm();
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      //關閉 modal
      props.callbackModal();
      //
      DCContext.playSound2(`/audio/sound_effect/SE116.mp3`);
    } else {
      console.log('[NewUnion] ${_key} error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},new_union`]?.uuid]);

  //edit_union 結果

  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},edit_union`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[NewUnion] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //關閉 modal
      props.callbackModal();
    } else {
      console.log(`[NewUnion] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},edit_union`]?.uuid]);

  useEffect(() => {
    let tmpUnion;
    if (DCContext?.unionForm_id?.union_id) {
      tmpUnion = DCContext.unions.find((el, idx) => {
        return el.id == DCContext.unionForm_id.union_id;
      });
      console.log('[NewUnion] tmpUnion', tmpUnion);
    }

    if (tmpUnion && tmpUnion.editable) {
      setUnion(tmpUnion);
      setMode('EDIT');
    } else if (!DCContext.myUnion?.id) {
      setUnion(null);
      setMode('CREATE');
    } else {
      //error
      setUnion(null);
      setMode(null);
    }
  }, [DCContext.myUnion, DCContext.unionForm_id]);

  useEffect(() => {
    form.setFieldsValue({ union_name: union?.name });
  }, [union]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          {mode == 'EDIT' ? (
            <div className={styles.subject_new}>{tt('union_name_change') /* 修改聯盟名稱 */}</div>
          ) : (
            <div className={styles.subject}>
              {tt(`union_create`, { nation_name: DCContext.myNation?.name }, { keySuffix: true })}{' '}
              {/* 成立效忠 {DCContext.myNation?.name} 的聯盟 */}
            </div>
          )}

          <Form
            action=""
            form={form}
            name="union_form"
            onFinish={onFinish}
            initialValues={{ union_name: union?.name }}
            labelCol={{ span: 8, className: styles.colTitle }}
            wrapperCol={{ span: 16, className: styles.colContent }}
            colon={false}
          >
            <Form.Item
              required={false} //不顯示必填星號
              name="union_name"
              label={
                <div className={styles.colTitle}>
                  {tt(`union_name`)} {/* 聯盟名稱 */}
                </div>
              }
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`union_name`) }), //聯盟名稱為必填
                },
                {
                  max: 12,
                  message: tt(`form_field_warn_max_length`, {
                    field_name: tt(`union_name`),
                    max_length: 12,
                  }), //角色名稱超過12個字
                },
              ]}
            >
              <Input bordered={true} className={styles.inputBox} />
            </Form.Item>
          </Form>

          <FitText className={`modalDescriptionFont ${styles.descriptionBox}`}>
            {mode == 'CREATE'
              ? tt(
                  `union_create_alert_description`,
                  {},
                  { keySuffix: true },
                ) /* 聯盟成立以後，您仍可更改以上名稱... */
              : ''}
          </FitText>

          <div>
            <BtnGrey text={tt(`confirm`)} callback={submitForm} />
          </div>
        </div>
      </div>

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
