import React, { useContext, useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useRoutes, useNavigate } from 'react-router-dom';
//antd
import { Form, Input, Button, Select, Checkbox } from 'antd';
//
import { UserContextProvider, useUserContext } from 'lib/UserContext';
//
import iConfig from 'iConfig';
import styles from './Register.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';

//
const { Option } = Select;
const layout = {
  labelCol: {
    span: 4,
  },
  wrapperCol: {
    span: 8,
  },
};
const tailLayout = {
  wrapperCol: {
    offset: 4,
    span: 8,
  },
};

export const Register = () => {
  let navigate = useNavigate();
  //
  const formRef = React.createRef(); //form 實例
  //
  const { ...UserContext } = useUserContext();

  useEffect(() => {
    if (!UserContext.registerResult?.status) {
      return;
    }

    console.log('UserContext.registerResult.status', UserContext.registerResult.status);

    //顯示欄位驗證錯誤訊息
    let tmp = [];
    if (UserContext.registerResult.status == 'error') {
      //console.log("UserContext.registerResult.validation_errors", UserContext.registerResult.validation_errors);
      for (var fieldName in UserContext.registerResult.validation_errors) {
        tmp.push({
          name: fieldName,
          errors: UserContext.registerResult.validation_errors[fieldName],
        });
      }

      //formRef.current.setFields([
      form.setFields(tmp);
    } else if (UserContext.registerResult.status == 'ok') {
      // showModal_confirm({
      //   confirm: {
      //     message: "註冊完成",
      //     buttons: [
      //       {
      // 				text: {i18nKey:`confirm`},
      // 				callback: ()=>{ navigate("/users/log_in")	}
      // 			},
      //     ]
      //   }
      // });
    }

    //清除本次執行結果
    UserContext.setRegisterResult(null);
  }, [UserContext.registerResult?.status]);

  //
  const [form] = Form.useForm();
  const onFinish = values => {
    //console.log("form values", values);
    UserContext.doRegister({
      account: values.email,
      password: values.password,
    });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <div>
      register
      <Form
        action=""
        ref={formRef}
        {...layout}
        form={form}
        name="control-hooks"
        onFinish={onFinish}
      >
        <Form.Item
          name="email"
          label="Email"
          rules={[
            {
              required: true,
            },
          ]}
        >
          <Input />
        </Form.Item>

        <Form.Item
          name="password"
          label="Password"
          rules={[
            {
              required: true,
            },
          ]}
        >
          <Input.Password />
        </Form.Item>

        <Form.Item {...tailLayout}>
          <Button type="primary" htmlType="submit">
            REGISTER
          </Button>
        </Form.Item>
      </Form>
      {UserContext.registerResult?.message ? (
        <div>
          {UserContext.registerResult.message}, user token: {UserContext.userToken}
        </div>
      ) : null}
      {/* modal confirm */}
      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </div>
  );
};
