/*
category
{"據點戰", 0},
{"排名戰", 1},
{"入口地圖", 2},
{"指揮機關", 3},
{"牙牌", 4},
{"大地圖", 5},
{"陣營資訊", 6},
{"幹部資訊", 7}
*/

export const PopupMessagesIcon = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const clickIcon = () => {
    DCContext.setShowPopupMessages({ category: props.category });
  };

  return props.category == undefined ? (
    <></>
  ) : (
    <div className={styles.main}>
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          clickIcon();
        }}
      >
        <div className={styles.itemBox}>
          <img className={styles.icon_info} src={icon_info} />
        </div>
      </ClickEffect>
    </div>
  );
};
