import React, { useMemo, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ClickEffect } from 'componentx/ClickEffect';
import { useI18n } from 'lib/useI18n';
import { UwFitText } from './UwFitText';
import { kmb } from '../utils/format';
import {
  extraLevelCapFromRelation,
  previewRelationAdd,
  relationThreshold,
  shouldBlockUpgrade,
} from '../utils/relation';
import uw07 from '../assets/uw07.png';
import styles from './UwActorTopBlock.module.scss';

/*
 * UW (Under World) — W3「幹部介面 / 強化介面」上方新物件
 * 規格書第 33–35 頁。幹部資訊與強化介面共用同一結構。
 * W7 (幹部關係) 增補：可接受實際 props (actor / actorPrototype / selectedProps)，
 * 真實計算 previewAdd 與 uw_relation_level_up_cap_warn 阻擋條件；缺 props 則退回
 * 尚未取得 actor 資料時不渲染，避免 production 畫面閃出測試資料。
 *
 * Props (皆為 optional)：
 *   actor:           {relation_exps, relation_level, actor_prototype_id} (本檔僅讀，不寫)
 *   actorPrototype:  {id, name, relation_level_cap, visitable_city_id, visitable_city}
 *   selectedProps:   [{relation_exps, relation_actor_exclusive, relation_actor_prototype_id, prop_prototype_id}]
 *                    來自 DCContext.tmpSelectedProps；prop 的 relation_exps 累加為 previewAdd，
 *                    exclusive 且 actor_prototype_id 不符者不計。
 *   hasVisitPlot:    true/false — 是否存在 reference_type=Visit 且關聯此 actor 的 site_plot
 *   onCapBlock:      function 由 ActorUpgrade 接收 cap 阻擋事件 (顯示 uw_relation_level_up_cap_warn 公版視窗)
 *
 * 接後端：
 *   - relationExps/relationLevel/relationLevelCap 由真實 actors/actor_prototypes
 *   - previewAdd 由 selectedProps 各 prop.relation_exps 加總 (含 exclusive 過濾)
 *   - hasVisitPlot 由 server 推導 site_plots 中是否存在對應 reference_type=Visit
 *   - cap 阻擋的公版視窗 (uw_relation_level_up_cap_warn) 由 server 推送
 */

const SE1 = '/audio/sound_effect/SE1.mp3';

const ROMAN = [
  '',
  'I',
  'II',
  'III',
  'IV',
  'V',
  'VI',
  'VII',
  'VIII',
  'IX',
  'X',
  'XI',
  'XII',
  'XIII',
  'XIV',
  'XV',
  'XVI',
  'XVII',
  'XVIII',
  'XIX',
  'XX',
];
const roman = n => ROMAN[n] || String(n);

export { extraLevelCapFromRelation, previewRelationAdd, relationThreshold, shouldBlockUpgrade };

export const UwActorTopBlock = ({
  actor: actorProp,
  actorPrototype: actorPrototypeProp,
  selectedProps: selectedPropsProp,
  hasVisitPlot: hasVisitPlotProp,
  onCapBlock,
}) => {
  const { tt } = useI18n();
  const navigate = useNavigate();

  const driven = actorProp != null && actorPrototypeProp != null;
  const hasVisitSitePlot = !!hasVisitPlotProp;
  const relationLevel = actorProp?.relation_level ?? 1;
  const relationLevelCap = actorPrototypeProp?.relation_level_cap ?? 1;
  const relationExps = actorProp?.relation_exps ?? 0;
  const previewAdd = previewRelationAdd(
    selectedPropsProp,
    actorProp?.actor_prototype_id ?? actorPrototypeProp?.id,
  );
  const visitableCityName = actorPrototypeProp?.visitable_city?.name ?? '—';
  const visitableCityId = actorPrototypeProp?.visitable_city_id ?? null;
  // 可拜訪城鎮是隱藏城鎮時不給點 (回報；規格未列舉此情況)。
  // 隱藏城鎮玩家本來就不該進得去，玩家資訊視窗的 CityLink 也是以 hidden 擋掉。
  // 城名與「前往拜訪」導向的是同一個目的地，所以兩個都要擋，只擋一個等於沒擋。
  const visitableCityHidden = !!actorPrototypeProp?.visitable_city?.hidden;
  const canVisit = hasVisitSitePlot && !visitableCityHidden && !!visitableCityId;

  const threshold = useMemo(
    () => relationThreshold(relationLevel, relationLevelCap),
    [relationLevel, relationLevelCap],
  );
  const previewExps = relationExps + previewAdd;

  /* 套用目前選取素材後「能升到的關係等級」。
     沿用 ActorProps.js 幹部等級上限預覽的同一套推算，兩處結果才會一致：
     每一級的累積門檻是 (2^level - 1) * 40000，逐級累加到上限為止。 */
  const previewRelationLevel = useMemo(() => {
    let lv = relationLevel;
    if (relationLevelCap > 1) {
      while (lv < relationLevelCap) {
        if (previewExps < (2 ** lv - 1) * 40000) break;
        lv += 1;
      }
    }
    return lv;
  }, [relationLevel, relationLevelCap, previewExps]);

  // 經驗值分子的預覽：只要素材會加到關係值就變桃色 (分子本身確實會變動)
  const relationPreviewing = previewAdd > 0;

  // 羅馬數字的預覽：必須「等級真的會提升」才變桃色 (回報)。
  // 原本沿用 relationPreviewing，等於只要選了素材就變色 —— 但素材量不足以跨過
  // 下一級門檻時等級並不會變，那時候著色是誤導 (畫面上 2.17M / 2.52M 還沒到門檻，
  // 羅馬數字卻已經是桃紅)。
  const relationLevelUp = previewRelationLevel > relationLevel;

  // 規格 p.34：cap 阻擋偵測 — 通知 parent
  const atCap = relationLevel >= relationLevelCap && relationLevelCap > 0;
  const wouldHitCap = atCap && previewAdd > 0;
  const lastCapNotifiedRef = useRef(false);
  useEffect(() => {
    if (!driven || !onCapBlock) return;
    if (wouldHitCap && !lastCapNotifiedRef.current) {
      onCapBlock({
        actorName: actorPrototypeProp?.name,
        relationLevelCap,
        /* 與{{actor_name}}的關係已達現階段極限，請待此幹部關係上限進一步開放後再使用此素材。 */
        message: tt(`uw_relation_level_up_cap_warn`, {
          actor_name: actorPrototypeProp?.name ?? tt(`uw_this_actor`) /* 此幹部 */,
        }),
      });
      lastCapNotifiedRef.current = true;
    } else if (!wouldHitCap) {
      lastCapNotifiedRef.current = false;
    }
  }, [wouldHitCap, driven, onCapBlock, actorPrototypeProp?.name, relationLevelCap]);

  // 規格 p.35：強化後閃白瞬間，數值跳動 — 用 key 變化觸發 CSS animation
  const jumpKey = `${previewExps}-${threshold}`;

  // 原本跳動特效的條件是 previewAdd > 0，但 previewAdd 是「預覽」的增加量：
  // 素材真正套用下去的瞬間 props 已被消耗、previewAdd 回到 0 —— 正好是數字真的變動的
  // 那一刻，特效反而不會觸發 (回報：提升的瞬間沒有跳動特效)。
  // 改成比對前一次算出來的顯示值，只要真的變了就跳；首次掛載不跳。
  const prevExpsRef = useRef(null);
  const shouldJump = prevExpsRef.current !== null && prevExpsRef.current !== previewExps;
  useEffect(() => {
    prevExpsRef.current = previewExps;
  }, [previewExps]);

  const onCityClick = () => {
    if (!visitableCityId) return;
    if (visitableCityHidden) {
      console.log('[UW] 可拜訪城鎮為隱藏城鎮：點擊無作用');
      return;
    }
    console.log(`[UW] 拜訪城鎮 click → #/attacks/attackmap city_id=${visitableCityId}`);
    navigate('/attacks/attackmap', { state: { focus_city_id: visitableCityId } });
  };

  const onVisitLinkClick = () => {
    if (!canVisit) {
      console.log(
        visitableCityHidden
          ? '[UW] 可拜訪城鎮為隱藏城鎮：點擊無作用'
          : '[UW] 未接受拜訪 (uw_not_visitable)：點擊無作用',
      );
      return;
    }
    console.log('[UW] 前往拜訪 (uw_to_visit) → #/attacks/attackmap');
    navigate('/attacks/attackmap', { state: { focus_city_id: visitableCityId } });
  };

  if (!driven) return null;

  return (
    <div className={styles.wrap}>
      <div className={styles.bg} style={{ backgroundImage: `url(${uw07})` }} />

      {/* 關係等級的羅馬數字：分子大字在花朵中心 (頂端切齊視窗頂端)、分母小字在下方花瓣中心。
          刻意放在 .wrap 底下而非中欄 —— 要與 .bg 共用同一個定位框，百分比才對得上底圖徽記。 */}
      {/* 分子顯示「能升到的等級」；有預覽時整個以桃色字呈現 (規格：桃色預覽)。
          分母 (關係等級上限) 是固定值、不隨素材變動，維持原色不跟著換色。 */}
      <span
        className={`${styles.romanBig} ${wouldHitCap || relationLevelUp ? styles.capWarn : ''}`}
      >
        {roman(previewRelationLevel)}
      </span>
      <span className={styles.romanSmall}>{roman(relationLevelCap)}</span>

      <div className={styles.grid}>
        {/* 左欄：城名 (上排大字，無虛線) + 前往拜訪 (下排小字) */}
        <div className={styles.col}>
          <ClickEffect effect={{ sound: SE1 }} onClick={onCityClick}>
            {/* 城名是動態資料，過長時等比縮小而不折行 (回報)。這一欄是置中，
                故 origin 用 center，否則縮小後會偏向左邊。 */}
            <UwFitText
              className={`${styles.rowTop} ${styles.big} ${styles.cityName} ${
                visitableCityHidden ? styles.cityNameDisabled : ''
              }`}
              origin="center"
            >
              {visitableCityName}
            </UwFitText>
          </ClickEffect>
          <ClickEffect effect={{ sound: SE1 }} onClick={onVisitLinkClick}>
            <div
              className={`${styles.rowBottom} ${styles.small} ${styles.visitLink} ${
                !canVisit ? styles.visitLinkDisabled : ''
              }`}
            >
              {/* 文案仍以「有無 Visit 劇情」為準 —— 城鎮被隱藏是另一回事，
                  顯示「未接受拜訪」會誤導。此時保留「前往拜訪」字樣但套用 disabled 樣式。 */}
              {
                hasVisitSitePlot
                  ? tt(`uw_to_visit`) /* 前往拜訪 */
                  : tt(`uw_not_visitable`) /* 未接受拜訪 */
              }
            </div>
          </ClickEffect>
        </div>

        {/* 中欄：僅作為左右兩欄之間的間隔 (羅馬數字已移到 .wrap 層，見上方)。 */}
        <div className={styles.colMid} />

        {/* 右欄：標題大字 (上排) + 數字小字 (下排)。標題走 phrase uw_relation_label
            (規格 p.29「右側標題」)，後台可改多語言。 */}
        <div className={styles.col}>
          {/* 「關係」是後台可改的詞句，翻成其他語言可能變長 → 同樣走自動縮小 */}
          <UwFitText className={`${styles.rowTop} ${styles.big}`} origin="center">
            {tt(`uw_relation_label`) /* 關係 */}
          </UwFitText>
          <div className={`${styles.rowBottom} ${styles.small}`}>
            {/* 分子：有預覽時「整個數字」用桃色呈現，不再另外掛括號夾註 (+N) */}
            <span
              key={jumpKey}
              className={`${styles.num} ${relationPreviewing ? styles.numPreview : ''} ${
                shouldJump ? styles.numJump : ''
              }`}
            >
              {kmb(previewExps)}
            </span>
            <span className={styles.numSep}>/</span>
            <span className={styles.num}>{threshold === 0 ? '—' : kmb(threshold)}</span>
          </div>
        </div>
      </div>
    </div>
  );
};
