import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './EquipSkillSwitch.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';
import bgSkillInfo from 'assets/img2/bgSkillInfo.png';

export const EquipSkillSwitch = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const idx = useRef(0);
  const [skill, setSkill] = useState();

  const active_skills = props.active_skills;

  useEffect(() => {
    console.log('[EquipSkillSwitch] active_skills', active_skills);
    setSkill(active_skills[idx.current]);
  }, []);

  const changeSkill = (e, p) => {
    let newIdx = idx.current + p;
    if (newIdx >= active_skills.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = active_skills.length - 1;
    }
    console.log('[EquipSkillSwitch] newIdx', newIdx);
    idx.current = newIdx;

    setSkill(active_skills[idx.current]);
  };

  const pickSkill = () => {
    const tmp = {
      id: props.actor.id,
      active_skill_id: skill.id,
    };
    console.log('[EquipSkillSwitch] pickSkill', tmp);

    if (props.callback) {
      props.callback('pickSkill', tmp);
    }
  };

  return skill ? (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <div className={styles.headBox}>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeSkill(e, -1);
              }}
            >
              <div className={styles.nameArrowL}>
                <img src={arrowL} className={styles.arrowImg} />
              </div>
            </ClickEffect>
            <FitText className={styles.actorName}>{skill.name}</FitText>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeSkill(e, 1);
              }}
            >
              <div className={styles.nameArrowR}>
                <img src={arrowR} className={styles.arrowImg} />
              </div>
            </ClickEffect>
          </div>

          <div className={styles.bodyBox}>
            <div className={styles.bundleItemsBox}>
              <img className={styles.bgSkillInfo} src={bgSkillInfo} />
              <div className={styles.skillImageBox}>
                <Iimg
                  className={styles.skillImage}
                  src={skill.image}
                  transition={false}
                  onReady={() => {}}
                />
              </div>
              {/* <div className={styles.skillLevel}>{skill.level}</div> */}
              <div className={styles.skillDescription}>{skill.description}</div>
            </div>
          </div>

          <div className={styles.footer}>
            <BtnGrey
              text={tt(`confirm`)}
              callback={e => {
                pickSkill();
              }}
            />
          </div>
        </div>
      </div>
    </div>
  ) : (
    <></>
  );
};
