import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
  config,
} from '@react-spring/web';
import Spritesheet from 'react-responsive-spritesheet';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './AniDoor.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

//
import doorL from 'assets/img2/unionbattle/doorL.png';
import doorR from 'assets/img2/unionbattle/doorR.png';
import doorFog from 'assets/img2/unionbattle/doorFog.png';
import doorFogGif from 'assets/img2/unionbattle/doorFog_once.gif';

export const AniDoor = props => {
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [doorStatus, setDoorStatus] = useState('OPENED');
  const [doorOpen, setDoorOpen] = useState(false);
  //
  let timer_Dooropen;

  const doorStyle = {
    L: {
      close: { right: '0%', filter: 'blur(0px)' },
      open: { right: '100%', filter: 'blur(20px)' },
    },
    R: {
      close: { left: '0%', filter: 'blur(0px)' },
      open: { left: '100%', filter: 'blur(20px)' },
    },
  };

  useEffect(() => {
    if (props.sound) {
      DCContext.playSound(props.sound);
    }

    return () => {
      clearTimeout(timer_Dooropen);
    };
  }, []);

  const aniStyles_leftDoor = useSpring({
    loop: false,
    from: doorOpen ? doorStyle.L.close : doorStyle.L.open,
    to: doorOpen ? doorStyle.L.open : doorStyle.L.close,
    config: {
      duration: 1500,
      easing: doorOpen ? easings.easeOutCirc : easings.easeInCirc,
    },
    // config: config.default,
    onRest: (result, spring, item) => {},
  });

  const aniStyles_rightDoor = useSpring({
    loop: false,
    from: doorOpen ? doorStyle.R.close : doorStyle.R.open,
    to: doorOpen ? doorStyle.R.open : doorStyle.R.close,
    config: {
      duration: 1500,
      easing: doorOpen ? easings.easeOutCirc : easings.easeInCirc,
    },
    // config: config.default,
    onRest: () => {
      console.log('[AniBoor] onRest', doorOpen);
      if (doorOpen) {
        //門已開
        props.doorOpen_callback();
      } else {
        //門已關
        if (props.doorClose_callback) {
          props.doorClose_callback();
        }

        //計時開門
        timer_Dooropen = setTimeout(() => {
          //setDoorStatus("OPEN");
          setDoorOpen(true);
        }, 2000);
      }
    },
    onChange: result => {
      //煙霧 (此段提早處理讓門一關上煙霧能馬上出現)
      let num = parseInt(result.value.left);
      //console.log("[AniBoor] onChange", num);

      if (!doorOpen && num < 50) {
        setDoorStatus('CLOSED'); //出現煙霧
      }
    },
  });

  return (
    <>
      <div className={styles.doorMainBox}>
        {/* <div className={styles.bgBox}>
        <div className={styles.section}>
          1
        </div>
        <div className={`${styles.section} ${styles.border}`}>2</div>
        <div className={styles.section}>3</div>
      </div> */}

        <animated.div className={styles.doorBox} style={{ ...aniStyles_leftDoor }}>
          <div className={styles.doorEmptyBox} style={{ backgroundColor: 'black' }}>
            <Iimg
              className={styles.leftFlag}
              src={props.matchData?.LEFT.flag}
              transition={false}
              onReady={() => {}}
            />
          </div>
          <div className={styles.door}>
            <img className={styles.doorImg} src={doorL} />
            <Iimg
              className={styles.leftMedal}
              src={props.matchData?.LEFT.medal_image}
              transition={false}
              onReady={() => {}}
            />
            <div className={styles.leftTitle1}>{props.matchData?.LEFT.title2}</div>
            <div className={styles.leftTitle2}>{props.matchData?.LEFT.title1}</div>
          </div>
          <div className={styles.doorEmptyBox}></div>
        </animated.div>

        <animated.div className={styles.doorBox} style={{ ...aniStyles_rightDoor }}>
          <div className={styles.doorEmptyBox}></div>
          <div className={styles.door}>
            <img className={styles.doorImg} src={doorR} />
            <Iimg
              className={styles.rightMedal}
              src={props.matchData?.RIGHT.medal_image}
              transition={false}
              onReady={() => {}}
            />
            <div className={styles.rightTitle1}>{props.matchData?.RIGHT.title2}</div>
            <div className={styles.rightTitle2}>{props.matchData?.RIGHT.title1}</div>
          </div>
          <div className={styles.doorEmptyBox} style={{ backgroundColor: 'black' }}>
            <Iimg
              className={styles.rightFlag}
              src={props.matchData?.RIGHT.flag}
              transition={false}
              onReady={() => {}}
            />
          </div>
        </animated.div>

        {doorStatus == 'CLOSED' && (
          <div className={styles.doorFogBox}>
            <img className={styles.doorFog} src={doorFogGif} />
          </div>
        )}
      </div>
    </>
  );
};
