import moment from 'moment';
import 'moment-timezone';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import RangeSlider from 'react-range-slider-input';
import 'react-range-slider-input/dist/style.css';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { ClickEffect } from 'componentx/ClickEffect';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './BattleRoom.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
//
import arrow_ATK_left from 'assets/img2/unionbattle/arrow_ATK_left.png';
import arrow_ATK_left_chosen from 'assets/img2/unionbattle/arrow_ATK_left_chosen.png';
import arrow_ATK_right from 'assets/img2/unionbattle/arrow_ATK_right.png';
import arrow_ATK_right_chosen from 'assets/img2/unionbattle/arrow_ATK_right_chosen.png';
//
import arrow_DEF_left from 'assets/img2/unionbattle/arrow_DEF_left.png';
import arrow_DEF_left_chosen from 'assets/img2/unionbattle/arrow_DEF_left_chosen.png';
import arrow_DEF_right from 'assets/img2/unionbattle/arrow_DEF_right.png';
import arrow_DEF_right_chosen from 'assets/img2/unionbattle/arrow_DEF_right_chosen.png';
//
import ChatRoom from 'component/Chat/ChatRoom';

