export const BattleRoom = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [battleData, setBattleData] = useState();
  const [arrowImgs, setArrowImgs] = useState();
  const rangeSliderRef = useRef();
  //
  const [leftBoxToggled, setLeftBoxToggled] = useState(false);
  const [powerRangerValues, setPowerRangerValues] = useState([3, 7]);
  //console.log("[BattleRoom] props", props);

  useEffect(() => {
    //console.log("[BattleRoom] redirect");
    //navigate("/user/teams/unionbattleselect", { replace: true });
  }, []);

  useEffect(() => {
    if (!props.battleData) {
      return;
    }

    console.log('[BattleRoom] props.battleData', { ...props.battleData });

    setBattleData(props.battleData);
  }, [props.battleData]);

  useEffect(() => {
    if (!battleData) {
      return;
    }

    if (battleData.match?.defender_union) {
      //有交戰雙方資料時
      let leftArrs = {
        ATK: [arrow_ATK_left, arrow_ATK_left_chosen],
        DEF: [arrow_DEF_left, arrow_DEF_left_chosen],
      };

      let rightArrs = {
        ATK: [arrow_ATK_right, arrow_ATK_right_chosen],
        DEF: [arrow_DEF_right, arrow_DEF_right_chosen],
      };

      //模擬戰？
      // setArrowImgs({
      //   LEFT: battleData.data.defender ? leftArrs.DEF : leftArrs.ATK,
      //   RIGHT: battleData.data.defender ? rightArrs.ATK : rightArrs.DEF,
      // });

      //據點戰
      setArrowImgs({
        LEFT: battleData.defender ? leftArrs.DEF : leftArrs.ATK,
        RIGHT: battleData.defender ? rightArrs.ATK : rightArrs.DEF,
      });
    }
  }, [battleData]);

  //選擇戰區
  const changeZone = zoneIdx => {
    console.log('[BattleRoom] changeZone', zoneIdx);

    //倒數結束不能再換區
    if (
      battleData?.data?.next_action &&
      moment.utc(battleData?.data.next_action).local().isBefore(moment.utc().local())
    ) {
      console.log('[BattleRoom] changeZone 資料處理中不可換區');
      return;
    }

    if (props._mode == 'unionBattle') {
      DCContext.changeUnionBattleZone({ zoneIdx: zoneIdx });
    } else if (props._mode == 'nationBattle') {
      DCContext.changeNationBattleZone({ zoneIdx: zoneIdx });
    }
  };

  //指揮官 間諜偵察
  const sendSpy = zoneIdx => {
    if (props._mode == 'unionBattle') {
      DCContext.unionBattle_sendSpy({ zoneIdx: zoneIdx });
    } else if (props._mode == 'nationBattle') {
      DCContext.nationBattle_sendSpy({ zoneIdx: zoneIdx });
    }
  };

  //指揮官 分配戰區 command_power
  const commandPower = power_positions => {
    if (props._mode == 'unionBattle') {
      DCContext.unionBattle_commandPower(power_positions);
    } else if (props._mode == 'nationBattle') {
      DCContext.nationBattle_commandPower(power_positions);
    }
  };

  useEffect(() => {
    if (!battleData?.data?.power) {
      return;
    }

    const _sum =
      battleData?.data.power?.[0]?.[0].commander +
      battleData?.data.power?.[1]?.[0].commander +
      battleData?.data.power?.[2]?.[0].commander;
    console.log('[BattleRoom] powerRangerValues sum', _sum, powerRangerValues);

    if (_sum > 0) {
      const newValues = [
        Math.round(
          (battleData?.data.power?.[0]?.[0].commander /
            (battleData?.data.power?.[0]?.[0].commander +
              battleData?.data.power?.[1]?.[0].commander +
              battleData?.data.power?.[2]?.[0].commander)) *
            10,
        ),
        Math.round(
          ((battleData?.data.power?.[0]?.[0].commander +
            battleData?.data.power?.[1]?.[0].commander) /
            (battleData?.data.power?.[0]?.[0].commander +
              battleData?.data.power?.[1]?.[0].commander +
              battleData?.data.power?.[2]?.[0].commander)) *
            10,
        ),
      ];

      console.log('[BattleRoom] powerRangerValues newValues', newValues);
      setPowerRangerValues(newValues);
    }
  }, [battleData?.data?.power]);

  /* animation */

  const [aniStyles, aniApi] = useSpring(() => ({
    from: { width: `50%` },
    //to: { width: `100%` },
    config: {
      //duration: 3000,
    },
  }));

  const toggleArrowClick = () => {
    aniApi.start({
      to: leftBoxToggled ? `50%` : `100%`,
      onRest: () => {
        //console.log("[BattleRoom] [aniStyles] onRest");
        setLeftBoxToggled(!leftBoxToggled);
      },
    });
  };

  useEffect(() => {
    //console.log("[BattleRoom] [aniStyles] leftBoxToggled", leftBoxToggled);
  }, [leftBoxToggled]);

  return (
    <IbgDiv className={styles.mainBox} src={null} transition={true} onReady={() => {}}>
      <animated.div className={styles.leftBox} style={aniStyles}>
        <div className={styles.sectionsBox}>
          {props.zonesData?.map((item, idx) => {
            return (
              <IbgDiv
                key={idx}
                className={`${styles.section}`}
                src={item.image}
                transition={false}
                onReady={() => {}}
              >
                <>
                  <div key={`L_${idx}`} className={styles.sectionLeftBox}>
                    <ClickEffect
                      enabled={
                        battleData?.status == 'maneuver' &&
                        battleData?.player_joined &&
                        battleData?.battle_zone_position !== idx
                      }
                      effect={{ sound: `/audio/sound_effect/SE139.mp3` }}
                      onClick={() => {
                        changeZone(idx);
                      }}
                    >
                      <div className={styles.sectionCont}>
                        <div className={styles.zoneNameBox}>
                          <div
                            className={styles.zoneName}
                            style={{ opacity: battleData?.status == 'roll_call' ? 1 : 0.85 }}
                          >
                            {item?.names[DCContext.locale]}
                          </div>
                          {battleData?.status != 'roll_call' && (
                            <div
                              className={styles.zoneBoost}
                              dangerouslySetInnerHTML={{
                                __html: tt(
                                  item?.boost,
                                ) /* s_zone_boost_0 => 法器、重擊、弓弩幹部戰力+10% */,
                              }}
                            ></div>
                          )}
                        </div>

                        {battleData?.status != 'roll_call' && (
                          <div className={styles.sectionContRow1}>
                            <div className={styles.sectionContRow1Props}>
                              <div className={styles.sectionProp1}>
                                {battleData?.data?.power?.[idx]?.[0]?.commander}
                              </div>
                              <div className={styles.sectionProp2}>
                                {battleData?.data?.power?.[idx]?.[0]?.power}
                              </div>
                              <div className={styles.sectionProp3}>&nbsp;</div>
                            </div>
                          </div>
                        )}
                      </div>
                    </ClickEffect>

                    {battleData?.status == 'maneuver' && (
                      <img
                        className={styles.arrow_ATK}
                        src={arrowImgs?.LEFT[battleData?.battle_zone_position === idx ? 1 : 0]}
                      />
                    )}
                  </div>

                  {/* 右半 */}
                  <div key={`R_${idx}`} className={styles.sectionRightBox}>
                    {battleData?.status == 'maneuver' && (
                      <img className={styles.arrow_DEF} src={arrowImgs?.RIGHT[0]} />
                    )}
                    <ClickEffect
                      enabled={
                        battleData?.status == 'maneuver' &&
                        battleData?.data.commander_id == DCContext.userProfile?.id
                      }
                      effect={{ sound: `/audio/sound_effect/SE140.mp3` }}
                      onClick={() => {
                        sendSpy(idx);
                      }}
                    >
                      <div className={`${styles.sectionCont} ${styles.right}`}>
                        <div className={styles.sectionContRow1}>
                          <div className={styles.sectionContRow1Props}>
                            <div className={styles.sectionProp1}>
                              {/* {battleData?.data.power && ( */}
                              {battleData?.data?.power?.[idx]?.[1]?.commander}
                              {/* )} */}
                            </div>
                            <div className={styles.sectionProp2}>
                              {/* {battleData?.data.power && ( */}
                              {battleData?.data?.power?.[idx]?.[1]?.power}
                              {/* )} */}
                            </div>
                            {battleData?.data?.power?.[idx]?.[1]?.note && (
                              <div className={styles.sectionProp3}>
                                {battleData?.data?.power?.[idx]?.[1]?.note[DCContext.locale]}
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    </ClickEffect>
                  </div>
                </>
              </IbgDiv>
            );
          })}

          {/* <IbgDiv className={`${styles.section} ${styles.border}`} src={battleData?.data.middle_zone_image} 
            transition={false} onReady={()=>{}}>
          </IbgDiv>

					<IbgDiv className={styles.section} src={battleData?.data.bottom_zone_image} 
            transition={false} onReady={()=>{}}>
          </IbgDiv> */}
        </div>

        {battleData?.status == 'maneuver' &&
          battleData?.data.commander_id == DCContext.userProfile?.id && (
            <div className={styles.sliderBox}>
              <RangeSlider
                ref={rangeSliderRef}
                className={styles.vertical_slider}
                orientation={'vertical'}
                rangeSlideDisabled={true}
                min={0}
                max={10}
                defaultValue={powerRangerValues}
                onInput={values => {
                  DCContext.playSound(`/audio/sound_effect/SE141.mp3`);
                  //console.log("[Battleroom] RangeSlider onInput", values);
                }}
                onThumbDragEnd={values => {
                  console.log(
                    '[Battleroom] RangeSlider onThumbDragEnd',
                    rangeSliderRef.current.value,
                  );
                  commandPower(rangeSliderRef.current.value);
                }}
                onThumbDragStart={values => {}}
              />
            </div>
          )}

        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            toggleArrowClick();
          }}
        >
          <div className={`${styles.toggleArrowBox} ${leftBoxToggled ? styles.toggled : ''}`}>
            {leftBoxToggled ? (
              <img className={styles.toggleArrow} src={arrow_ATK_right_chosen} />
            ) : (
              <img className={styles.toggleArrow} src={arrow_ATK_left_chosen} />
            )}
          </div>
        </ClickEffect>
      </animated.div>

      <div className={styles.rightBox}>
        {battleData?.data.room_id && (
          <ChatRoom
            _mode={props._mode}
            room_id={battleData?.data.room_id}
            battleData={battleData}
            commanderOnline={props.commanderOnline}
          />
        )}
      </div>
    </IbgDiv>
  );
};
