import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import Backend from 'i18next-http-backend';
import LanguageDetector from 'i18next-browser-languagedetector';
import iConfig from 'iConfig';

i18n
  // 使用 i18next-http-backend
  .use(Backend)
  // 偵測瀏覽器語言
  // learn more: https://github.com/i18next/i18next-browser-languageDetector
  //.use(LanguageDetector)
  // 將 i18next 傳入 react-i18next 裡面
  .use(initReactI18next)
  // 實例化 initReactI18next
  .init({
    debug: false, //開關 console.log
    backend: {
      //網頁載入時去下載語言檔的位置 (透過http方式) (!!!若在本地端執行build的版本，會因CORS問題無法載入)
      //loadPath: "./locales/{{lng}}/{{ns}}.json",
      //loadPath: "https://rf.twhawk.tw/locales/{{lng}}/{{ns}}.json",
      // loadPath 用 function：每次載入都帶一個新的 _ 參數當 cache buster。
      // 後台改完詞句，玩家端卻拿到舊字 (回報) 的其中一個原因是 WebView/Cloudflare
      // 把這個 GET 當成可快取的回應；帶上會變動的 query 就一定會回源。
      loadPath: lngs => `${iConfig.API.i18n}/phrases?locale=${lngs[0]}&_=${Date.now()}`,
      // fetch 層一併關掉快取，雙保險
      requestOptions: { cache: 'no-store' },
      //addPath: 'locales/add/{{ns}}.{{lng}}',
    },
    // 當目前的語言檔找不到對應的字詞時，會用 fallbackLng 作為預設語言
    fallbackLng: 'zh_TW',
    // 預設語言
    lng: 'zh_TW', //若上面自動偵測瀏覽器語言，這裏不用指定
    load: 'currentOnly', //只讀取指定的一種，預設是all，舉例 en-US 會讀取 en-US, en, dev
    interpolation: {
      // 是否要讓字詞 escaped 來防止 xss 攻擊，這裡因為 React.js 已經做了，就設成 false即可
      escapeValue: false,
      // 之後研究 https://cloud.tencent.com/developer/ask/sof/106825609
      //alwaysFormat: true,
      // format: (value, format, lng) => {
      //   // if (value instanceof Date) {
      //   //   return DateTime.fromJSDate(value)
      //   //     .setLocale(lng)
      //   //     .toLocaleString(DateTime[format]);
      //   // }

      // 	console.log("[i18n] format ", value, format, lng);

      //   return value;
      // },
    },
    react: {
      wait: true,
      useSuspense: true,
    },
    saveMissing: true, // must be enabled for missingKeyHandler
    missingKeyHandler: (lng, ns, key, fallbackValue) => {
      //console.log(`[i18n] missingKey`, lng, ns, key, fallbackValue)
    },
    missingInterpolationHandler: (text, value) => {
      //console.log(`[i18n] missingInterpolation`, text, value)
    },
  });
// .then(
