import React, { useContext, useState, useEffect, useRef } from 'react';
import { useDrag } from 'react-dnd';
import { useSpring, useSpringRef, useChain, animated, easings } from '@react-spring/web';
//
import iConfig from 'iConfig';
import styles from './BtnRing.module.scss';
import { ClickEffect } from 'componentx/ClickEffect';
//
import circleGolden from 'assets/img/circleGolden.png';
import circleSilver from 'assets/img/circleSilver.png';

export const BtnRing = props => {
  const ringImage = props.color == 'silver' ? circleSilver : circleGolden;
  const colorClass = props.color == 'silver' ? 'silver' : 'golden';

  const btnClick = () => {
    if (props.callback) {
      props.callback();
    }
  };

  return (
    <ClickEffect
      effect={{ sound: `/audio/sound_effect/SE2.mp3` }}
      onClick={e => {
        btnClick();
      }}
    >
      <div className={`${styles.btnCircleBox} ${styles[colorClass]}`}>
        <div className={styles.btnCircleWrap}>
          <img className={styles.btnCircleGold} src={ringImage} />
          <div className={`${styles.btnCircleText}`}>{props.text}</div>
        </div>
      </div>
    </ClickEffect>
  );
};
