import styles from './AccountDel.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';

export const AccountDel = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const { ...UserContext } = useUserContext();
  //
  let navigate = useNavigate();

  //
  const doAccountDel = () => {
    let tmp = { active: false };
    console.log('[doAccountDel] handleClick_edit_profile', tmp);
    DCContext.updateProfile(tmp);
  };

  //edit_profile 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},edit_profile`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //console.log(`[doAccountDel] ${_key}`, {..._res});

    if (_res.status == 'ok') {
      UserContext.doLogout();
    } else {
      //todo error處理
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},edit_profile`]?.uuid]);

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={`${styles.contentBox} modalContentBox`}>
          <div
            className={`${styles.descriptionBox} modalDescriptionBox`}
            dangerouslySetInnerHTML={{
              __html: tt(
                `p_account_delete_confirm_description`,
              ) /* 永久刪除帳號時的描述內容(請自行編寫) */,
            }}
          ></div>

          <div className={styles.btnBar}>
            <div className={styles.formBtnBox}>
              <BtnGrey text={tt(`delete_permanent`) /* 永久刪除 */} callback={doAccountDel} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
