import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { Col, Row, Modal } from 'antd';
import {
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  includes as lodash_includes,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useLocalStorage } from 'lib/useLocalStorage';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Backpack.module.scss';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { BackpackItems } from 'component/BackpackItems';
//
import mattest01 from 'assets/img/props/mattest01.png';
import propEmpty from 'assets/img/props/propEmpty.png';
import iconBundleordersWhite from 'assets/img/iconBundleordersWhite.png';
import propsDescriptionBg from 'assets/img/props/propsDescriptionBg.png';
import iconTrash from 'assets/img/iconTrash.png';
import iconHamer from 'assets/img/iconHamer.png';
import iconArrowL from 'assets/img2/iconArrowL.png';
import iconArrowR from 'assets/img2/iconArrowR.png';
//
import propsframe_1 from 'assets/img/props/propsframe_1.png';
import propsframe_2 from 'assets/img/props/propsframe_2.png';
import propsframe_3 from 'assets/img/props/propsframe_3.png';
import propsframe_4 from 'assets/img/props/propsframe_4.png';
import bgBackpack_actor from 'assets/img2/bgBackpack_actor.png';
import bgBackpack from 'assets/img2/bgBackpack.png';

const propsCatData = {
  1: { frameBg: propsframe_1, textColor: '#ffffff' },
  2: { frameBg: propsframe_2, textColor: '#f37878' },
  3: { frameBg: propsframe_3, textColor: '#79d8f3' },
  4: { frameBg: propsframe_4, textColor: '#be9cf0' },
};

export const Backpack = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  let { actionId } = useParams();
  actionId = parseInt(actionId) || 1;
  //
  const [itemType, setItemType] = useState(actionId);
  console.log('[Backpack] useParams: ', actionId);
  //
  const [selectedItem, setSeletedItem] = useState();
  //強化 進化 裝備 修煉 ...等等返回 幹部資訊頁 或 庫房
  const [returnUrl_actorSettings, setReturnUrl_actorSettings] = useLocalStorage(
    'returnUrl_actorSettings',
    '',
  );

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Backpack] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Backpack] channel player 未連線');
      return;
    }

    console.log('[Backpack] channel player 已連線');
    DCContext.getBackpack();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    console.log('[Backpack] DCContext.backpack', actionId, DCContext.backpack);

    if (!DCContext.backpack) {
      return;
    }

    setItemType(actionId);
    setSeletedItem(null);

    //強化 進化 裝備 修煉 ...等等返回 幹部資訊頁 或 庫房
    setReturnUrl_actorSettings(location.pathname);
  }, [DCContext.backpack, actionId]);

  const changeTab = i => {
    navigate(`/user/backpack/${i}`);
  };

  const callback_item = (_mode, _type, _data) => {
    console.log('[Backpack] callback_item', _mode, _type, _data);

    switch (_type) {
      case 1: //素材
        _data.iprops = {
          name: _data.prop_prototype.name,
          image: _data.prop_prototype.image,
          description: _data.prop_prototype.description,
        };
        break;
      case 2: //符文
        _data.iprops = {
          name: _data.weapon_prototype.name,
          image: _data.weapon_prototype.image,
          description: _data.weapon_prototype.description,
        };
        break;
      case 3: //祕笈
        _data.iprops = {
          name: _data.name,
          image: _data.image,
          description: _data.description,
        };
        break;
      case 4: //特殊
        _data.iprops = {
          name: _data.name,
          image: _data.image,
          description: _data.description,
        };
        break;
    }

    // if (_data.prop_prototype){
    //   _data.prototype = _data.prop_prototype;
    // } else if (_data.weapon_prototype){
    //   _data.prototype = _data.weapon_prototype;

    // }

    setSeletedItem(_data);

    // switch(_type){
    //   case "actorPickWeapon":
    //     break;
    // }
  };

  //點擊特殊道具
  const clickSpItem = () => {
    console.log('[Backpack] clickSpItem', selectedItem);

    switch (selectedItem.usage) {
      case 'defect_card':
        //投誠狀
        navigate(`/settings/nation_change`);
        break;
      case 'energy_boost':
        //能量恢復劑
        DCContext.showEnergyboostModal();
        break;
    }
  };

  //點擊裝備符文
  const clickEquip_runes = () => {
    let user_id = 0;

    if (selectedItem?.actor?.id) {
      //目前裝備者
      user_id = selectedItem?.actor?.id;
    } else {
      //可以裝備者
      let tmp_actor = lodash_find(DCContext.actors, o => {
        return lodash_includes(o.usable_weapon_ids, selectedItem.id);
      });
      console.log('[Backpack] clickEquip_runes', selectedItem.id, tmp_actor);

      if (tmp_actor) {
        user_id = tmp_actor.id;
      }
    }

    //
    navigate(`/user/actorweapons/${user_id}`, {
      state: {
        returnUrl: location.pathname,
        returnState: null,
      },
    });
  };

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <div className={styles.bgBox} style={{ backgroundImage: `url(${bgBackpack})` }}></div>

      <div className={styles.mainBox}>
        <div className={styles.leftBox}>
          <BackpackItems
            key={itemType}
            itemType={itemType}
            mode={'backpack'}
            actor={null}
            callback_item={callback_item}
          />

          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={e => {
              navigate(`/store/bundleorders`);
            }}
          >
            <div className={styles.fundsTextRow}>
              <div className={styles.linkProps}>
                <span>{tt(`to_procurement`) /* 往商城 */}</span>
                <img className={`rotation_1`} src={iconBundleordersWhite} />
              </div>
            </div>
          </ClickEffect>
        </div>

        <div
          className={styles.rightBox}
          style={{ backgroundImage: `url(${propsCatData[actionId].frameBg})` }}
        >
          <div className={styles.propB}>
            <div>
              <div className={styles.propBImgBox}>
                {selectedItem && (
                  <Iimg
                    className={styles.propBImg}
                    src={selectedItem?.iprops?.image}
                    transition={false}
                    onReady={() => {}}
                  />
                )}
              </div>
              <div className={styles.propBName}>{selectedItem?.iprops?.name}</div>
            </div>
          </div>

          <div className={styles.itemInfoBox}>
            {selectedItem?.actor?.image && (
              <div
                className={styles.actorImageBox}
                style={{ backgroundImage: `url(${bgBackpack_actor})` }}
              >
                <Iimg
                  className={styles.actorImage}
                  src={selectedItem?.actor?.image}
                  transition={false}
                  onReady={() => {}}
                />
              </div>
            )}
            <div
              className={styles.descriptionBox}
              style={{ backgroundImage: `url(${propsDescriptionBg})` }}
            >
              <div
                className={styles.description}
                style={{ color: propsCatData[actionId].textColor }}
                dangerouslySetInnerHTML={{ __html: selectedItem?.iprops?.description }}
              ></div>
            </div>
          </div>

          {selectedItem && (
            <>
              {/* <img className={styles.iconTrash} src={iconTrash}/>
          <img className={styles.iconHamer} src={iconHamer}/> */}

              {itemType == 1 ? (
                <>
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={() => {
                      navigate(`/user/actorupgrade`);
                    }}
                  >
                    <div className={styles.linkSymbolBox}>
                      <img src={iconArrowL} />
                      <div className={styles.linkSymbolText}>{tt(`use`) /* 使用 */}</div>
                    </div>
                  </ClickEffect>
                </>
              ) : itemType == 2 ? (
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={() => {
                    clickEquip_runes();
                  }}
                >
                  <div className={styles.linkSymbolBox}>
                    <img src={iconArrowL} />
                    <div className={styles.linkSymbolText}>{tt(`equip_runes`) /* 裝備符文 */}</div>
                  </div>
                </ClickEffect>
              ) : itemType == 3 ? (
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={() => {
                    navigate(`/user/actorevolute/${selectedItem?.actor?.id || 0}`);
                  }}
                >
                  <div className={styles.linkSymbolBox}>
                    <img src={iconArrowL} />
                    <div className={styles.linkSymbolText}>
                      {tt(`breakthrough_level_limit`) /* 突破等級限制 */}
                    </div>
                  </div>
                </ClickEffect>
              ) : itemType == 4 ? (
                <ClickEffect
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={() => {
                    clickSpItem();
                  }}
                >
                  <div className={styles.linkSymbolBox}>
                    <img src={iconArrowL} />
                    <div className={styles.linkSymbolText}>{tt(`use`) /* 使用 */}</div>
                  </div>
                </ClickEffect>
              ) : (
                <></>
              )}
            </>
          )}
        </div>
      </div>

      <div className={`tabBar`}>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            changeTab(1);
          }}
        >
          <div className={`tab ${actionId == 1 ? 'active' : ''}`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`materials`) /* 素材 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            changeTab(2);
          }}
        >
          <div className={`tab ${actionId == 2 ? 'active' : ''}`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`runes`) /* 符文 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            changeTab(3);
          }}
        >
          <div className={`tab ${actionId == 3 ? 'active' : ''}`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`secret_scrolls`) /* 祕笈 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            changeTab(4);
          }}
        >
          <div className={`tab ${actionId == 4 ? 'active' : ''}`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`special_items`) /* 特殊 */}</div>
          </div>
        </ClickEffect>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />
    </IbgDiv>
  );
};
