export const Loading = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const iZIndex = useRef(highestZindex({ _level: 'middle' }));
  //
  //const [bgs, setBgs] = useState(lodash_shuffle(iConfig.loadingBgs));
  const [bgs, setBgs] = useState(iConfig.loadingBgs);
  const [bgIdx, setBgIdx] = useState(0);
  const [bg, setBg] = useState();
  const [ratioText, setRatioText] = useState(0);

  useEffect(() => {
    if (!bgs) {
      return;
    }

    //console.log("[Loading] bgs", bgs, bgIdx);

    setBg(bgs[bgIdx % bgs.length]);
  }, [bgs, bgIdx]);

  useEffect(() => {
    if (props.preloadedRatio == undefined) {
      return;
    }

    //console.log("[Loading] props.preloadedRatio", props.preloadedRatio);

    //setRatioText(+(Math.round(props.preloadedRatio + "e+2") * 100  + "e-2") + "%");
    //setRatioText(Number.parseFloat(props.preloadedRatio*100).toFixed(1) + "%");
    setRatioText(decimals_digits(props.preloadedRatio * 100, 2, false) + '%');

    //console.log("[Loading] ratioText", ratioText);
  }, [props.preloadedRatio]);

  /* animation */

  const [aniStyles, aniApi] = useSpring(() => ({
    from: { _x: 0 },
    to: { _x: 1 },
    onRest: () => {
      //console.log("[Loading] onRest");

      setBgIdx(preState => {
        preState++;
        return preState;
      });
    },
  }));

  useEffect(() => {
    if (!bg) {
      return;
    }

    //console.log("[Loading] bg", bg);

    aniApi.start({
      from: { _x: 0, scale: 1 },
      to: { _x: 1, scale: 1.1 },
      config: {
        duration: 5000,
      },
    });
  }, [bg]);

  return (
    // <LoadingOverlay
    // 	active={true}
    // 	spinner={<RingLoader color="#ffffff" />}
    // 	text={`載入中`}
    // 	styles={{
    // 		wrapper: (base) => ({
    // 			...base,
    // 			height: "100%"
    // 		}),
    // 		overlay: (base) => ({
    // 			...base,
    // 			background: 'rgba(0, 0, 0, 0.0)',
    // 			// height: "100%"
    // 		}),
    // 	}}
    // >

    <IbgDiv
      className={styles.rootContainer}
      src={null}
      transition={false}
      onReady={() => {}}
      style={{
        zIndex: iZIndex.current,
      }}
    >
      <div className={styles.mainBox}>
        <animated.div
          className={styles.bgBox}
          style={{
            ...aniStyles,
            opacity: aniStyles._x.to({
              range: [0, 0.1, 0.9, 1],
              output: [bgIdx == 0 ? 1 : 0, 1, 1, 0], //第一個畫面背景不要是空的
            }),
          }}
        >
          <IbgDiv className={styles.bgBox} src={bg} transition={false} onReady={() => {}}></IbgDiv>
        </animated.div>

        <img src={loading_ReversedFront} className={styles.imglogo} />
        <img src={loading_border} className={styles.loading_border} />
        <div className={styles.loadingTextBox}>
          {props.loadingText ? props.loadingText : tt(`loading`) /* 載入資料 */}
        </div>
        <div className={styles.barBox}>
          <div className={styles.bar} style={{ width: ratioText }}></div>
          <div className={styles.percentText}>{ratioText || ``}</div>
        </div>

        <div className={styles.animatedRing}>
          <img className={`rotation_highlightCircle`} src={highlightCircle} />
        </div>

        {[...Array(200)].map((x, idx) => {
          return <Flylight key={idx} />;
        })}
      </div>
    </IbgDiv>

    // </LoadingOverlay>
  );
};

export const Flylight = props => {
  const [loopTimes, setLoopTimes] = useState(0);
  const [baseStyle, setBaseStyle] = useState({});

  useEffect(() => {}, []);

  /* animation */

  const [aniStyles, aniApi] = useSpring(() => ({
    from: { _x: 0 },
    to: { _x: 1 },
  }));

  useEffect(() => {
    //console.log("[Flylight] loopTimes", loopTimes);

    let h = Math.floor((Math.random() * 5 * 70) / 100) + 2; //2~5
    let w = Math.floor((Math.random() * h * 70) / 100); //~h
    let borderRadius = Math.floor(Math.random() * w) + 2; //2~w
    let opacity = (Math.random() * 70) / 100;
    let left = Math.floor(Math.random() * 100) + 2;
    let top = Math.floor(Math.random() * 100) + 2;
    let duration = Math.floor(Math.random() * top) * 500;

    setBaseStyle({
      position: `absolute`,
      left: `${left}%`,
      width: `${w}px`,
      height: `${h}px`,
      borderRadius: `${borderRadius}px`,
      opacity: opacity,
      backgroundColor: `#fdf79f`,
    });

    aniApi.start({
      from: { top: `${top}%` },
      to: { top: `-10%` },
      config: {
        duration: duration,
      },
      onRest: () => {
        //console.log("[Flylight] onRest");

        setLoopTimes(preState => {
          return preState + 1;
        });
      },
    });
  }, [loopTimes]);

  return (
    <animated.div
      style={{
        ...baseStyle,
        ...aniStyles,
      }}
    ></animated.div>
  );
};
