export const PvpTeams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const location = useLocation();
  //
  let _mode = props.mode;
  //
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;

  // 3v3 未開放 (iConfig.pvp3_enabled=false) 時，若透過網址直接進入此頁 → 導回主畫面。
  // Home / Ranking / DCContext 只是「不顯示入口」，擋不住直接輸入網址 (回報：3v3 頁面仍可開啟)。
  // 伺服器端 pvp_battle 守衛 (system_settings 3v3_enabled) 為最終保護；此為前端防線。
  useEffect(() => {
    if (_mode === '3v3' && !iConfig.pvp3_enabled) {
      navigate('/home', { replace: true });
    }
  }, [_mode]); // eslint-disable-line react-hooks/exhaustive-deps

  //console.log('[PvpTeams] useParams: ', _mode, teamIdx, location);

  const [pvpBattleStatus, setPvpBattleStatus] = useState();

  useEffect(() => {
    console.log('[PvpTeams] useParams: ', _mode, teamIdx, location);

    //debug
    // DCContext.setShowMatchingModal({
    // 	message: tt('matching'),
    // 	//callback: ()=>{ console.log(`matching closed`) }
    // });
  }, []);

  /* 預載 */
  const [preloadKey, setPreloadKey] = useState();

  const { setPreloadImages, imagesPreloaded, preloadedRatio, preloaderReset } = useImagePreloader({
    //preloadMode:'browser' //即使裝置也使用 browser 下載模式
  });
  //const preloadKey = "profile";

  useEffect(() => {
    if (!DCContext.preloads?.[preloadKey]) {
      return;
    }

    console.log('[PvpTeams] [preload] setPreloadImages', DCContext.preloads?.[preloadKey]);

    setPreloadImages(DCContext.preloads?.[preloadKey]);
  }, [DCContext.preloads?.[preloadKey]]);

  useEffect(() => {
    console.log('[PvpTeams] [preload] imagesPreloaded', imagesPreloaded, { ...DCContext.preloads });

    //清空本次該預載的
    if (imagesPreloaded && DCContext.preloads?.[preloadKey]) {
      DCContext.setPreloads(preState => {
        let tmp = { ...preState };
        tmp[preloadKey] = null;
        delete tmp[preloadKey];

        return tmp;
      });
    }
  }, [imagesPreloaded]);

  const ckeckPreloads = _preloadKey => {
    console.log('[PvpTeams] [preload] ckeckPreloads', _preloadKey);

    preloaderReset();
    setPreloadKey(_preloadKey);
  };

  //對手 preloads
  useEffect(() => {
    if (DCContext.preloads?.pvp_player2 && preloadKey == 'pvp_player1' && imagesPreloaded) {
      console.log('[PvpTeams] [preload] 對手圖檔下載 開始');
      ckeckPreloads('pvp_player2');
    } else if (preloadKey == 'pvp_player2' && imagesPreloaded) {
      console.log('[PvpTeams] [preload] 對手圖檔下載 完畢');

      //step 7
      navigate('/pvpbattle'); //進到戰鬥畫面
    }
  }, [DCContext.preloads?.pvp_player2, imagesPreloaded]);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    //
    console.log('[PvpTeams] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile, teamIdx]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[PvpTeams] channel player 未連線');
      return;
    }

    console.log('[PvpTeams] channel player 已連線');

    //step 1
    DCContext.getPvp_battle_status();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  //API pvp_battle_status 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},pvp_battle_status`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[PvpTeams] [pvp_battle_status 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //step 2
      setPvpBattleStatus(_res.payload);
    } else {
      console.log('pvp_battle_status error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},pvp_battle_status`]?.uuid]);

  useEffect(() => {
    if (!pvpBattleStatus) {
      return;
    }

    console.log(`[PvpTeams] pvpBattleStatus`, pvpBattleStatus);

    switch (pvpBattleStatus.status) {
      case `can_join`: //可參加排名戰
        //todo
        break;

      case `matching`: //已參加，等待對手中
        DCContext.setShowMatchingModal({
          message: tt('matching'),
          //callback: ()=>{ console.log(`matching closed`) }
        });
        break;

      case `in_progress`: //已參加，戰鬥中
        navigate('/pvpbattle'); //進到戰鬥畫面
        break;
    }
  }, [pvpBattleStatus]);

  /* 點擊參戰 */

  //step 3
  const clickFightCallback_3v3 = ({ team_id = 0 } = {}) => {
    console.log('[PvpTeams] clickFightCallback_3v3');

    //檢查需3隊
    if (!DCContext.checkedTeamIdxs || Object.keys(DCContext.checkedTeamIdxs).length != 3) {
      console.log('[PvpTeams] teams length != 3');

      showModal_confirm({
        confirm: {
          /* 請選定3支編隊再出戰 */
          message: { i18nKey: `pvp_need_3teams_confirm`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });

      return;
    }

    //隊伍剛好三隊
    let team_ids = Object.values(DCContext.checkedTeamIdxs);
    console.log('[PvpTeams] teams length == 3, team_ids', team_ids);

    //所選隊伍資料發送
    //step 4
    DCContext.pvp_battle(team_ids);
  };

  //
  const clickFightCallback_1v1 = ({ team_id = 0 } = {}) => {
    console.log('[PvpTeams] clickFightCallback_1v1 teamIdx,team_id', teamIdx, team_id);
    let team_ids = [team_id];
    //console.log("[PvpTeams] clickFightCallback_1v1 team_ids", team_ids);

    DCContext.pvp_battle(team_ids);
  };

  //API pvp_battle 結果 (所選隊伍資料發送結果)
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},pvp_battle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //debug
    // _res = {
    // 	...debugData.API_pvp_battle.ok,
    // 	payload: debugData.API_pvp_battle.ok.response
    // };

    console.log(`[PvpTeams] [pvp_battle 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //switch (_res.payload.status) {
      //	case `3v3 matching`: //已參加，等待對手中

      DCContext.setShowMatchingModal({
        message: tt('matching'),
        //callback: ()=>{ console.log(`matching closed`) }
      });

      //更新 preloads
      DCContext.setPreloads(preState => {
        return {
          ...preState,
          pvp_player1: _res.payload.preloads,
        };
      });

      //step 5
      //preload 我方戰鬥圖
      ckeckPreloads('pvp_player1');

      //	break;
      //}
    } else {
      console.log('pvp_battle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},pvp_battle`]?.uuid]);

  //Server broadcast player:x

  useEffect(() => {
    if (!ChannelContext.messages) {
      return;
    }

    //console.log("[DCContext] Server主動發送 ChannelContext.messages",  {...ChannelContext.messages});

    let _key = `${ChannelContext.messages.topic},${ChannelContext.messages.event}`;

    switch (_key) {
      //pvp
      case `${DCContext.playerChannelTopic},pvp_battle`:
        //console.log('[PvpTeams] server broadcast', _key, ChannelContext.messages?.res?.payload);

        let tmpData = ChannelContext.messages?.res?.payload;
        console.log('[PvpTeams] broadcast pvp_battle', tmpData);

        switch (tmpData.status) {
          case 'matched': //找到對手
            //step 6
            //更新對手 preloads
            DCContext.setPreloads(preState => {
              return {
                ...preState,
                pvp_player2: tmpData.preloads,
              };
            });

            break;
        }
        break;
    }
  }, [ChannelContext.messages]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams
        mode={_mode}
        catKey={_mode == '3v3' ? '3v3' : '1v1'}
        multiSelectable={_mode == '3v3' ? true : false}
        //
        showFightBtn={true}
        teamIdx={teamIdx}
        clickFightCallback={_mode == '3v3' ? clickFightCallback_3v3 : clickFightCallback_1v1}
      />

      {_mode == '1v1' && <PopupMessagesIcon category={1} />}

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      {/* {matchData && !doorShowed && (
        <div className={styles.pageBox}	style={{zIndex:40}}>
        <AniDoor 
          matchData={matchData}
          doorOpen_callback={doorOpen_callback}
          style={{zIndex:40}}
        />
        </div>
      )} */}
    </IbgDiv>
  );
};

