import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
  config,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Teams } from 'component/Teams';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Unionteams.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
//
import { Nationbattle_joinModal } from 'pages/unionbattle/Nationbattle_joinModal';

export const Nationteams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  const navigate = useNavigate();
  const location = useLocation();
  //
  const [teams, setTeams] = useState([]);
  const [actors, setActors] = useState([]);
  const team_id = useRef();

  let mode = props.mode;
  //
  let { teamIdx } = useParams();
  teamIdx = parseInt(teamIdx) || 1;
  //console.log('[Nationteams] useParams: ', mode, teamIdx, location);
  //
  const [selectedCity, setSelectedCity] = useState();
  //const [battleStatus, setBattleStatus] = useState();
  const selectedItem_id = useRef();
  //
  const join_nation_battle_api_processing = useRef(false);

  //console.log('[Nationteams] props, city_id', props, location.state.city_id);

  useEffect(() => {
    console.log('[Nationteams] location.state', location.state);
  }, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    //
    console.log('[Nationteams] playMusic');
    //DCContext.playMusic(`${DCContext.userProfile.music}`);
    DCContext.playMusic(iConfig.battleMusic);
  }, [DCContext.userProfile, teamIdx]);

  //監測特定 channel 連線變化狀態

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Nationteams] channel player 斷線');
      return;
    }

    console.log('[Nationteams] channel player 已連線');
    ///DCContext.getCities(true); //取最新才知道此使用者是否 可參戰 已參戰
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!ChannelContext.channels[DCContext.unionChannelTopic]) {
      console.log('[Nationteams] channel union:x 未連線');
      return;
    }

    console.log('[Nationteams] channel union:x 已連線');

    //DCContext.getUnion_battle_status();
    //DCContext.getNationBattleInfo();
  }, [ChannelContext.channels[DCContext.unionChannelTopic]]);

  useEffect(() => {
    if (!DCContext.cities) {
      return;
    }

    if (!location.state.city_id) {
      return;
    }

    let tmp = DCContext.cities.find((item, idx) => {
      return item.id == location.state.city_id;
    });

    setSelectedCity(tmp);
  }, [DCContext.cities, location.state.city_id]);

  useEffect(() => {
    if (!selectedCity) {
      return;
    }

    console.log('[Nationteams] selectedCity', selectedCity);
  }, [selectedCity]);

  /* 點擊參戰 */

  const clickFightCallback = ({ team_id = 0 } = {}) => {
    //console.log("[Nationteams] clickFightCallback, team_id", team_id);
    //console.log("[Nationteams] clickFightCallback, selectedCity.id", selectedCity.id);
    //console.log("[Nationteams] clickFightCallback, location.state.joinSide", location.state.joinSide);

    //
    if (join_nation_battle_api_processing.current) {
      console.log(
        '[Nationteams] join_nation_battle_api_processing',
        join_nation_battle_api_processing.current,
      );
      return;
    }
    join_nation_battle_api_processing.current = true;

    //
    selectedItem_id.current = team_id; //暫存起來，如果此玩家從 start 變 join 需要用到

    let tmp = {
      city_id: selectedCity.id,
      team_id: team_id,
      //
      mode: location.state.joinMode,
    };

    if (location.state.joinSide) {
      tmp.defender = location.state.joinSide == 'defender' ? true : false;
    }

    console.log('[Nationteams] clickFightCallback', tmp);

    DCContext.joinNationBattle(tmp);
  };

  //join_nation_battle 結果
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},join_nation_battle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log('[Nationteams] join_nation_battle', { ..._res });

    //
    join_nation_battle_api_processing.current = false;

    //
    if (_res.status == 'error' && _res.error.energy_boost_options) {
      //能量不足
      showModal_confirm({
        confirm: {
          /*能量不足，立即補充能量?*/
          message: { i18nKey: `replenish_energy_confirm`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
                DCContext.showEnergyboostModal();
              },
            },
            // {
            // 	text: {i18nKey:`...`},
            // 	callback: ()=>{ console.log("2"); callbackConfirm({}) }
            // },
          ],
        },
      });
    } else if (_res.status == 'error') {
      //可能 點數不足 超過距離...等，暫時只顯示發生未知錯誤
      showModal_confirm({
        confirm: {
          //發生未知錯誤
          //message: {i18nKey:`unknown_error`, values:null, options:null},
          //改為直接顯示 server message a. 聯盟解散中 b. 能量不足 c. 集結時間已過 d. 超出可攻擊範圍
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm();
              },
            },
          ],
        },
      });
    } else if (_res.status == 'ok') {
      //join_nation_battle OK 分成兩種狀況

      if (_res.payload.mode) {
        //回傳 mode 代表已有人發起(start)，此玩家本來是要(start)變成參加(join)，
        //重新顯示一次雙方交戰資料 modal

        //參戰提示 (示意圖242~245)
        showModal_nbj({ battleInfo: _res.payload });
      } else {
        //發起成功，進到據點戰畫面
        console.log('[Nationteams] join_nation_battle ok');
        navigate('/nationbattle');
      }
    } else {
      console.log('[Nationteams] join_nation_battle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},join_nation_battle`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Navigator] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* modal nation battle join */

  const [modalProps_nbj, setModalProps_nbj] = useState({
    //ratio: 0.7,
    destroyOnClose: true,
    visible: false,
  });

  const showModal_nbj = exProps => {
    setModalProps_nbj(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_nbj = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_nbj(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm_nbj = returnParams => {
    console.log('[Attackmap] callbackConfirm_nbj', returnParams);

    //
    if (join_nation_battle_api_processing.current) {
      console.log(
        '[Nationteams] join_nation_battle_api_processing 2',
        join_nation_battle_api_processing.current,
      );
      return;
    }
    join_nation_battle_api_processing.current = true;

    //
    callbackModal_nbj(null, null);

    //導向選隊伍
    // navigate("/user/teams/nationbattleselect", {
    //   state: {
    //     city_id: city.id,
    //     joinSide: returnParams.joinSide,
    //     joinMode: returnParams.mode, //start, join
    //     //
    //     returnUrl: location.pathname,
    //     returnState: { focus_city_id: city.id }
    //   }
    // });

    //重新 join_nation_battle
    let tmp = {
      city_id: selectedCity.id,
      team_id: selectedItem_id.current,
      //
      mode: returnParams.mode, //start, join 此時會是 join
    };

    if (returnParams.joinSide) {
      tmp.defender = returnParams.joinSide == 'defender' ? true : false;
    }

    console.log('[Nationteams] callbackConfirm_nbj', tmp);

    DCContext.joinNationBattle(tmp);
  };

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <Teams
        mode={mode}
        catKey={'Union'}
        //https://trello.com/c/FQNJY6gL
        //2025/4/20 JB: 已經進到選隊伍就允許參戰(實際狀況 API 會處理)
        //showFightBtn={selectedCity?.knife_clickable}
        showFightBtn={true}
        //showFightBtn={true}
        teamIdx={teamIdx}
        clickFightCallback={clickFightCallback}
      />

      <Navigator
        navi={{
          back: location.state?.returnUrl
            ? {
                callback: () => {
                  navigate(location.state?.returnUrl, {
                    state: {
                      ...location.state?.returnState,
                    },
                  });
                },
              }
            : { spot: 'home' },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <Imodal {...modalProps_nbj} callback={callbackModal_nbj}>
        <Nationbattle_joinModal {...modalProps_nbj} callback={callbackConfirm_nbj} />
      </Imodal>
    </IbgDiv>
  );
};
