/** Compact large game values without rounding up the displayed amount. */
export const compactNumber = value => {
  const number = Number(value) || 0;
  const truncate = scaled => Math.trunc(scaled * 100 + (scaled >= 0 ? 1e-6 : -1e-6)) / 100;
  const absolute = Math.abs(number);

  if (absolute >= 1e9) return `${truncate(number / 1e9)}B`;
  if (absolute >= 1e6) return `${truncate(number / 1e6)}M`;
  if (absolute >= 1e3) return `${truncate(number / 1e3)}K`;
  return `${Math.floor(number)}`;
};

// Kept as an API alias while the recovered feature is migrated incrementally.
export const kmb = compactNumber;
