import highlightCircle from 'assets/img2/highlightCircle.png';
import btnRight from 'assets/img2/actor_pools/btnRight.png';
import btnRight_active from 'assets/img2/actor_pools/btnRight_active.png';

export const DailyBundles = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //
  const [monthText, setMonthText] = useState();
  const [selectedItem_idx, setSelectedItem_idx] = useState();
  const [selectedItem, setSelectedItem] = useState();
  const [todayCollected, setTodayCollected] = useState(false);

  useEffect(() => {
    //debug
    // showModal_BRA({
    //   params:{
    //     title: tt(`bundle_receive_congratulations`)/* 恭喜獲得 */,
    //     showBg: true,
    //     bundleItems: debugData['bundleItems_payload'].collected_items,
    //     callback: ()=>{callbackModal_BRA(null, null)}
    //   }
    // });

    return () => {
      //
      let tmpDate = moment().format('YYYY-M-D');
      DCContext.setDailyBundles_date(tmpDate);
    };
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      //console.log("[DailyBundles] channel player 斷線");
      return;
    }

    //console.log("[DailyBundles] channel player 已連線");

    DCContext.getDailyBundles(true);
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.dailyBundles?.length) {
      return;
    }
    console.log('[DailyBundles] DCContext.dailyBundles', DCContext.dailyBundles);

    //
    let tmp = moment
      .utc(DCContext.dailyBundles[0].presented_on)
      .locale('en')
      .format('MMM')
      .toUpperCase();
    console.log('[DailyBundles] month', tmp);
    setMonthText(tmp);

    //
    //if (selectedItem_idx == undefined){
    let tmpIdx = lodash_findIndex(DCContext.dailyBundles, { today: true });
    console.log('[DailyBundles] setSelectedItem_idx', tmpIdx);
    if (tmpIdx >= 0) {
      setSelectedItem_idx(tmpIdx);
    }
    //}

    //
    let tmpItem = lodash_find(DCContext.dailyBundles, { today: true, collected: true });
    if (tmpItem) {
      setTodayCollected(true);
    } else {
      setTodayCollected(false);
    }
  }, [DCContext.dailyBundles]);

  useEffect(() => {
    if (selectedItem_idx == undefined) {
      return;
    }

    if (DCContext.dailyBundles?.[selectedItem_idx].daily_bundle?.[0]) {
      setSelectedItem(DCContext.dailyBundles?.[selectedItem_idx].daily_bundle[0]);
    }
  }, [DCContext.dailyBundles, selectedItem_idx]);

  const clickItem = _idx => {
    setSelectedItem_idx(_idx);
  };

  const doCollectBundle = () => {
    DCContext.setShowProcessingModal(true); //顯示“處理中”

    DCContext.collectBundle({
      reference_type: 'Daily Bundle',
    });
  };

  //collect_bundle 結果
  useEffect(() => {
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[DailyBundles] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);

            //若是有購買月卡
            console.log(
              `[DailyBundles] DCContext.bundle_categories[1].can_collect`,
              DCContext.bundle_categories?.[1]?.can_collect,
            );
            if (DCContext.bundle_categories?.[1]?.can_collect) {
              DCContext.collectBundle({
                reference_type: 'Monthly Pass',
              });
            }
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[Announcement] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return (
    <div className={styles.rootContainer}>
      <div className={styles.mainBox}>
        <div className={styles.leftBox}>
          <div className={styles.selectedItemBox}>
            <img className={styles.bgSelectedItem} src={bgSelectedItem} />
            {selectedItem && (
              <Iimg
                className={styles.selectedItemImg}
                src={selectedItem.image}
                transition={false}
                onReady={() => {}}
              />
            )}
          </div>

          <div className={styles.selectedItemName}>
            <FitText _align={'right'}>{selectedItem?.name}</FitText>
          </div>
          <div
            className={styles.selectedItemDescription}
            dangerouslySetInnerHTML={{ __html: selectedItem?.description }}
          ></div>
        </div>
        <div className={styles.rightBox}>
          <div className={styles.rightHeadBox}>
            <div className={styles.monthTextBox}>{monthText}</div>
          </div>
          <div className={styles.rightBodyBox}>
            <div className={styles.calendarBox}>
              {DCContext.dailyBundles?.map((item, idx) => {
                return (
                  <div
                    key={item?.presented_on}
                    className={`${styles.itemBox} ${item?.today ? styles.halo : null}`}
                  >
                    <div className={styles.dayText}>
                      {moment.utc(item?.presented_on).local().format('D')}
                    </div>
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        clickItem(idx);
                      }}
                    >
                      <div className={styles.itemBody}>
                        <IbgDiv
                          className={`${item.collected ? 'filter_black' : null} ${styles.itemImg}`}
                          src={item?.daily_bundle?.[0].image}
                          transition={false}
                          onReady={() => {}}
                        ></IbgDiv>
                        {item.collected && (
                          <img className={styles.icon_circleCheck} src={icon_circleCheck} />
                        )}
                      </div>
                    </ClickEffect>
                    <div className={styles.itemQuantity}>{item?.daily_bundle?.[0].quantity}</div>

                    {selectedItem_idx == idx && (
                      <div className={styles.highlightCircleBox}>
                        <img className={`rotation_highlightCircle`} src={highlightCircle} />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {todayCollected ? (
          <div className={`${styles.rightBtnBox}`}>
            <img className={styles.btnImg} src={btnRight} />
            <div className={styles.rightBtnText}>{tt(`signed_in_today`) /* 簽到完畢 */}</div>
          </div>
        ) : (
          <ClickEffect
            enabled={true}
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              doCollectBundle();
            }}
          >
            <div className={`${styles.rightBtnBox} ${styles.active}`}>
              <img className={styles.btnImg} src={btnRight_active} />
              <div className={styles.rightBtnText}>{tt(`sign_in_today`) /* 今日簽到 */}</div>
            </div>
          </ClickEffect>
        )}

        <Imodal {...modalProps_BRA}>
          <BundleReceivedAlert {...modalProps_BRA.params} />
        </Imodal>
      </div>
    </div>
  );
};

