import React, { useContext, useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useRoutes, useNavigate } from 'react-router-dom';
//
import { FitText } from 'lib/FitText';
import { ClickEffect } from 'componentx/ClickEffect';
//
import styles from './ActorSwitch.module.scss';
//
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';

export const ActorSwitch = props => {
  const changeActor = d => {
    if (props.callback_changeActor) {
      props.callback_changeActor(d);
    }
  };

  return (
    <div className={styles.nameBox}>
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          changeActor(-1);
        }}
      >
        <div className={styles.nameArrowL}>
          <img src={arrowL} className={styles.arrowImg} />
        </div>
      </ClickEffect>
      <FitText className={styles.actorName}>
        {typeof props.actor == 'string' ? props.actor : props.actor?.actor_prototype?.name}
      </FitText>
      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={() => {
          changeActor(1);
        }}
      >
        <div className={styles.nameArrowR}>
          <img src={arrowR} className={styles.arrowImg} />
        </div>
      </ClickEffect>
    </div>
  );
};
