const resetContextStates = _context => {
  //console.log("xxx", _context);
  for (const [key, value] of Object.entries(_context)) {
    if (_context.keepValues?.[key]) {
      //console.log(`[Login] in keepValues`, key);
      continue;
    }

    if (key.startsWith('set') && typeof value === 'function') {
      let defaultValue = _context.defaultVaules[key] ? _context.defaultVaules[key] : null;
      //console.log(`[Login] in defaultVaules ${key}:`, defaultValue);
      value(defaultValue);
    }
  }
};

