import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { findKey, cloneDeep } from 'lodash';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './StageZone.module.scss';
import { Character } from './Character';
//
import icon_battle_offender from 'assets/img2/unionbattle/icon_battle_offender.png';
import icon_battle_defender from 'assets/img2/unionbattle/icon_battle_defender.png';

export const StageZone = props => {
  const DCContext = useDCContext();
  //
  //const [zoneData, setZoneData] = useState();
  const [scenarios, setScenarios] = useState();
  const [fightData, setFightData] = useState(); //該輪戰鬥資料
  const turnCompletedActors = useRef({}); //本次 fight turn 完成動作的角色
  const [fightTurn, setFightTurn] = useState(0); //輪到哪一輪
  const [deadCharacters, setDeadCharacters] = useState({ L: {}, R: {} }); //死亡玩家
  const [isZoneEnd, setIsZoneEnd] = useState(false);
  //
  const timer_startDelay = useRef();

  useEffect(() => {
    return () => {
      clearTimeout(timer_startDelay.current);
    };
  }, []);

  //勝敗音效
  useEffect(() => {
    if (!isZoneEnd) {
      return;
    }

    if (props.iamDefender == props.zoneData?.defended) {
      //贏
      DCContext.playSound(`/audio/sound_effect/SE142.mp3`);
    } else {
      //輸
      DCContext.playSound(`/audio/sound_effect/SE143.mp3`);
    }
  }, [isZoneEnd]);

  useEffect(() => {
    if (!props.zoneData) {
      return;
    }
    console.log('[StageZone] zoneData', props.zoneIdx, props.zoneData);

    //setZoneData(props.zoneData);

    //重置
    setScenarios();
    setIsZoneEnd(false);
    setFightTurn(0);
    setDeadCharacters({ L: {}, R: {} });

    //
    if (!props.zoneData[0].length && !props.zoneData[1].length) {
      //左右兩邊都無人
      //此 zone 已結束
      console.log('[StageZone] round end 左右兩邊都無人 ======================');
      setIsZoneEnd(true);
    } else {
      let tmpScenarios = makeScenarios(props.zoneData);
      console.log('[StageZone] tmpScenarios', props.zoneIdx, tmpScenarios);
      setScenarios(tmpScenarios);
    }
  }, [props.zoneData]);

  const makeScenarios = tmpData => {
    let tmpAry = [];
    let lastRound = [
      tmpData[0].map((item, idx) => {
        return {
          ...item,
          id: `L${idx}`,
          side: 'L',
          action: 'STAND',
          power_last: item.power,
          defender: props.iamDefender,
        };
      }),
      tmpData[1].map((item, idx) => {
        return {
          ...item,
          id: `R${idx}`,
          side: 'R',
          action: 'STAND',
          power_last: item.power,
        };
      }),
    ];
    tmpAry.push([...lastRound]);
    //console.log("[StageZone] Round 1", lastRound, [...tmpAry]);

    //開始建構劇本
    let scenarioEnd = false;
    let newRounds;
    while (!scenarioEnd) {
      newRounds = getNextRoundScenario(lastRound);
      //console.log("[StageZone] lastRound 1", lastRound);

      if (newRounds === false) {
        //一方全滅
        scenarioEnd = true;
      } else {
        tmpAry = tmpAry.concat(newRounds);
        lastRound = tmpAry[tmpAry.length - 1];
      }
    }

    //console.log("[StageZone] lastRound", newRounds, tmpAry);

    return tmpAry;
  };

  const getNextRoundScenario = tmp => {
    let tmpData = cloneDeep(tmp);
    let leftIdx = findKey(tmpData[0], function (o) {
      return o.power_last > 0;
    });
    let rightIdx = findKey(tmpData[1], function (o) {
      return o.power_last > 0;
    });

    console.log('[StageZone] idx', leftIdx, rightIdx);

    if (leftIdx === undefined || rightIdx === undefined) {
      console.log('[StageZone] 一方全部死亡');
      return false;
    }

    //round 左攻擊
    let tmpRound0 = cloneDeep(tmpData);
    tmpRound0[0][leftIdx].action = 'ATTACK';
    tmpRound0[1][rightIdx].action = 'UNDERATTACK';

    //round 右攻擊
    let tmpRound1 = cloneDeep(tmpData);
    tmpRound1[0][leftIdx].action = 'UNDERATTACK';
    tmpRound1[1][rightIdx].action = 'ATTACK';

    //round 一方死亡
    let tmpRound2 = cloneDeep(tmpData);

    //console.log("[StageZone] power_last", tmpRound2[0][leftIdx].power_last, tmpRound2[1][rightIdx].power_last);

    if (tmpRound2[0][leftIdx].power_last > tmpRound2[1][rightIdx].power_last) {
      //左大
      tmpRound2[0][leftIdx].action = 'STAND';
      tmpRound2[0][leftIdx].power_last =
        tmpRound2[0][leftIdx].power_last - tmpRound2[1][rightIdx].power_last;
      tmpRound2[1][rightIdx].action = 'DEAD';
      tmpRound2[1][rightIdx].power_last = 0;
    } else if (tmpRound2[0][leftIdx].power_last < tmpRound2[1][rightIdx].power_last) {
      //右大
      tmpRound2[1][rightIdx].action = 'STAND';
      tmpRound2[1][rightIdx].power_last =
        tmpRound2[1][rightIdx].power_last - tmpRound2[0][leftIdx].power_last;
      tmpRound2[0][leftIdx].action = 'DEAD';
      tmpRound2[0][leftIdx].power_last = 0;
    } else {
      //一樣大 (攻方死亡，守方剩1)
      if (tmpRound2[0][leftIdx].defender) {
        tmpRound2[0][leftIdx].action = 'STAND';
        tmpRound2[0][leftIdx].power_last = 1;
        tmpRound2[1][rightIdx].action = 'DEAD';
        tmpRound2[1][rightIdx].power_last = 0;
      } else {
        tmpRound2[0][leftIdx].action = 'DEAD';
        tmpRound2[0][leftIdx].power_last = 0;
        tmpRound2[1][rightIdx].action = 'STAND';
        tmpRound2[1][rightIdx].power_last = 1;
      }
    }

    let gAry = [tmpRound0, tmpRound1, tmpRound2];
    //console.log("[StageZone] gAry", gAry);

    return gAry;
  };

  useEffect(() => {
    if (!scenarios) {
      return;
    }

    //debug
    // scenarios.map((itemX, idx)=>{
    // 	console.log("[StageZone] scenarios xxxxxxxxx", idx);
    // 	let xxx = {L:{}, R:{}};
    // 	itemX[0].map((itemX0, idx0)=>{
    // 		//console.log("[StageZone]", itemX0.action);
    // 		xxx.L[idx0] = itemX0.action;
    // 	});
    // 	itemX[1].map((itemX0, idx0)=>{
    // 		//console.log("[StageZone]", itemX0.action);
    // 		xxx.R[idx0] = itemX0.action;
    // 	});

    // 	console.log("[StageZone]", xxx);
    // });
  }, [scenarios]);

  //輪到第幾次 fight turn
  useEffect(() => {
    if (!scenarios) {
      return;
    }

    //console.log("[StageZone] scenarios ======================", scenarios, fightTurn);

    if (scenarios[fightTurn]) {
      //console.log("[StageZone] fight turn start ======================", fightTurn);
      //debug 暫停，只讓第一次 fight turn 人物出現
      setFightData(scenarios[fightTurn]);
    } else {
      //此 zone 已結束
      console.log('[StageZone] round end ======================');
      setIsZoneEnd(true);
    }
  }, [scenarios, fightTurn]);

  //角色callback：角色動作完成
  const characterActionFinished = cData => {
    //console.log("[StageZone] characterActionFinished, ", cData.id, JSON.stringify(turnCompletedActors.current));

    //死亡的角色
    if (cData.action == 'DEAD') {
      setDeadCharacters(preState => {
        let tmp = cloneDeep(preState);
        tmp[cData.side][cData.id] = {
          ...cData,
          action: 'AFTERDEAD',
        };

        return tmp;
      });
    }

    //目前完成動作的角色
    turnCompletedActors.current = {
      ...turnCompletedActors.current,
      [cData.id]: cData.action,
    };

    //本次 fight turn 所有角色完成動作
    let charactersQuantity = scenarios[fightTurn][0].length + scenarios[fightTurn][1].length;
    let finishQuantity = Object.keys(turnCompletedActors.current).length;
    console.log(
      '[StageZone] 完成動作',
      fightTurn,
      cData.id,
      finishQuantity + '/' + charactersQuantity,
      turnCompletedActors.current,
    );

    if (finishQuantity == charactersQuantity) {
      console.log('[StageZone] 全部角色 完成動作');

      //清空角色完成動作的紀錄
      turnCompletedActors.current = {};

      //輪下一個 fight turn

      //debug 暫時停止下一個 fight turn
      //return;

      if (fightTurn == 0) {
        //第一輪稍停讓使用者看清楚再開始戰鬥
        timer_startDelay.current = setTimeout(() => {
          setFightTurn(prevState => {
            return prevState + 1;
          });
        }, 2000);
      } else {
        setFightTurn(prevState => {
          return prevState + 1;
        });
      }
    }
  };

  useEffect(() => {
    console.log('[StageZone] deadCharacters', deadCharacters);
  }, [deadCharacters]);

  useEffect(() => {
    if (!isZoneEnd) {
      return;
    }

    //callback
    props.callbackZoneEnd(props.zoneIdx);
  }, [isZoneEnd]);

  return (
    <div className={styles.sectionRow}>
      <div className={styles.sectionRow_inline}>
        {/* 左半區 */}
        <div className={styles.charactersBox}>
          <div className={styles.charactersBoxInline}>
            {/* 已死亡 */}
            {/* 先產生避免閃動 */}
            {/* {Object.entries(deadCharacters.L).reverse().map(([key, data]) => { */}
            {fightData &&
              [...fightData[0]].reverse().map((data, idx) => {
                return (
                  <div
                    key={`DEAD_${data.id}`}
                    className={`${styles.characterBox} filter_black`}
                    style={{ opacity: deadCharacters.L[data.id] ? 1 : 0 }}
                  >
                    <Character
                      key={`DEAD_${data.id}`}
                      positionSide={`L`}
                      zoneData={props.zoneData}
                      characterData={{ ...data, action: 'AFTERDEAD' }}
                      //characterActionFinished={characterActionFinished}
                      zIndex={fightData[0].length - idx + fightData[0].length}
                    />
                  </div>
                );
              })}

            {/* 正常 */}
            {fightData &&
              [...fightData[0]].reverse().map((data, idx) => {
                return (
                  <div key={`L${idx}`} className={styles.characterBox}>
                    <Character
                      key={`L${idx}`}
                      positionSide={`L`}
                      zoneData={props.zoneData}
                      characterData={data}
                      characterActionFinished={characterActionFinished}
                      zIndex={fightData[0].length - idx}
                    />
                  </div>
                );
              })}
          </div>
        </div>

        {/* 中間留空 */}
        <div style={{ flex: 1 }}></div>

        {/* 右半區 */}
        <div className={`${styles.charactersBox} ${styles.right}`}>
          <div className={styles.charactersBoxInline}>
            {/* 正常 */}
            {fightData &&
              fightData[1].map((data, idx) => {
                return (
                  <div key={`R${idx}`} className={styles.characterBox}>
                    <Character
                      key={`R${idx}`}
                      positionSide={`R`}
                      zoneData={props.zoneData}
                      characterData={data}
                      characterActionFinished={characterActionFinished}
                    />
                  </div>
                );
              })}

            {/* 已死亡 */}
            {/* 先產生避免閃動 */}
            {/* {Object.entries(deadCharacters.L).reverse().map(([key, data]) => { */}
            {fightData &&
              fightData[1].map((data, idx) => {
                return (
                  <div
                    key={`DEAD_${data.id}`}
                    className={`${styles.characterBox} filter_black`}
                    style={{ opacity: deadCharacters.R[data.id] ? 1 : 0 }}
                  >
                    <Character
                      key={`DEAD_${data.id}`}
                      positionSide={`R`}
                      zoneData={props.zoneData}
                      characterData={{ ...data, action: 'AFTERDEAD' }}
                      //characterActionFinished={characterActionFinished}
                      zIndex={fightData[1].length - idx + fightData[1].length}
                    />
                  </div>
                );
              })}
          </div>
        </div>
      </div>

      {/* 勝利方旗幟 */}
      <div className={styles.flagBox}>
        {isZoneEnd && (
          <>
            <Iimg
              className={styles.winner_flag}
              src={props.zoneData?.winner_flag}
              transition={false}
              onReady={() => {}}
            />
            <img
              className={styles.winner_icon}
              src={props.zoneData?.defended ? icon_battle_defender : icon_battle_offender}
            />
          </>
        )}
      </div>
    </div>
  );
};
