import React, { useContext, useState, useEffect, useRef } from 'react';
import { BrowserRouter, Routes, Route, Link, useRoutes, useNavigate } from 'react-router-dom';
import { useSpring, useSpringRef, useChain, animated, easings } from '@react-spring/web';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
import Countdown from 'react-countdown';
//moment
import moment from 'moment';
import 'moment-timezone';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { iNumify } from 'lib/funcs';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Actorpools.module.scss';
import background from 'assets/img/sv01.jpg';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { ClickEffect } from 'componentx/ClickEffect';

//
import bgClock from 'assets/img2/bgClock.png';
//import left_gold from 'assets/img/icon_left_gold.png';
//import right_gold from 'assets/img/icon_right_gold.png';
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';

//

import bgClockSilver from 'assets/img/bgClockSilver.png';
import TB04 from 'assets/img/tmp/TB04.png';
import bgLight from 'assets/img2/bgLight.gif';
import iconBundleordersWhite from 'assets/img/iconBundleordersWhite.png';
import icon_dice from 'assets/img2/icon_dice.png';
import circleGolden from 'assets/img/circleGolden.png';
import circleSilver from 'assets/img/circleSilver.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import bg_shortMessage from 'assets/img2/home/bg_shortMessage.png';
import iconChange from 'assets/img/iconChange.png';
import iconFundsPlus from 'assets/img/iconFundsPlus.png';
import icon_recruit_plus from 'assets/img2/icon_recruit_plus.png';
//
import { Actorpicks } from 'pages/actorpools/Actorpicks';

export const Actorpools = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [actorPools, setActorPools] = useState();
  const [poolIdx, setPoolIdx] = useState(0);
  const [pool, setPool] = useState();
  const [showInfoType, setShowInfoType] = useState(1);
  const [origPicks, setOrigPicks] = useState(); //原始機率，所有卡池都用 original:true 那一個卡池
  //
  const timer = useRef();
  const recruit_api_processing = useRef(false); //是否正在呼叫 end_round

  useEffect(() => {
    return () => {
      clearTimeout(timer.current);
    };
  }, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Actorpools] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  const doRecruit = (e, quantity) => {
    console.log('[Actorpools] doRecruit', quantity);

    let tmpMsg = '';

    if (quantity == 1) {
      if (!DCContext.actorPools.recruit_coupons) {
        tmpMsg = tt(
          `recruit_funds_for_one_actor_confirm`,
        ) /*持有的招募券不足，是否消耗 100 資金購買招募券來進行1次招募？*/;
      } else {
        tmpMsg = tt(`recruit_one_actor_confirm`) /*是否消耗1張招募券進行1次招募？*/;
      }
    } else if (quantity == 10) {
      if (DCContext.actorPools.recruit_coupons < 10) {
        let tmpG =
          (10 - DCContext.actorPools.recruit_coupons) *
          DCContext.actorPools.fund_per_recruit_coupon;
        tmpMsg = tt(`recruit_funds_for_actors_confirm`, {
          funds: tmpG,
        }) /*持有的招募券不足，是否消耗 ${tmpG} 資金購買招募券來進行10次招募？*/;
      } else {
        tmpMsg = tt(`recruit_actors_confirm`) /*是否消耗10張招募券進行10次招募？*/;
      }
    }

    //console.log("[Actorpools] doRecruit tmpMsg", tmpMsg);

    if (!tmpMsg) {
      recruit_api_processing.current = false;
      return;
    }

    showModal_confirm({
      confirm: {
        message: tmpMsg,
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              //檢查執行中
              if (recruit_api_processing.current) {
                console.log(
                  `[Actorpools] API 執行中 recruit_api_processing`,
                  recruit_api_processing.current,
                );
                return;
              }
              recruit_api_processing.current = true;

              //
              callbackModal_confirm();
              //
              DCContext.recruit({
                actor_pool_id: pool.id,
                quantity: quantity,
              });
            },
          },
        ],
      },
    });
  };

  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},recruit`]) {
      return;
    }

    console.log('[Actorpools] player,recruit', { ...DCContext.msgRes });
    console.log('[Actorpools] recruitResult', DCContext.recruitResult);

    recruit_api_processing.current = false;

    //error處理 (目前error只有 召募券不足和資金不足)
    const res = DCContext.msgRes[`${DCContext.playerChannelTopic},recruit`];
    if (res.res.status && res.res.status == 'error') {
      showModal_confirm({
        confirm: {
          /*召募券或資金不足*/
          message: { i18nKey: `recruit_lack_coupons_or_funds`, values: null, options: null },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackModal_confirm();
              },
            },
          ],
        },
      });

      //清除本次 send message 結果
      DCContext.setMsgRes(prevState => {
        delete prevState[`${DCContext.playerChannelTopic},recruit`];
        return { ...prevState };
      });

      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},recruit`];
      return { ...prevState };
    });

    //
    navigate('/actorpools/recruit');
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},recruit`]?.uuid]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Actorpools] channel player 未連線');
      return;
    }

    console.log('[Actorpools] channel player 已連線');
    DCContext.getActorPools(true);
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  const filterValidPools = () => {
    let tmp = lodash_filter(DCContext.actorPools.actor_pools, item => {
      const formTime = moment.utc(item.valid_from).format('X');
      const toTime = moment.utc(item.valid_to).format('X');
      const now = moment.utc().format('X');

      //console.log("[Actorpools] filterValidPools time", now, formTime, toTime);

      return !item.limited_time || (now >= formTime && now <= toTime);
    });

    console.log('[Actorpools] filterValidPools', tmp.length, tmp);

    //正顯示的 pool index 超過可用 pool 的數量，跳回第一個 pool
    if (poolIdx >= tmp.length) {
      setPoolIdx(0);
    }
    setActorPools(tmp);

    //
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      filterValidPools();
    }, 1000 * 60); //每60秒檢查一次可用的 pool
  };

  useEffect(() => {
    if (!DCContext.actorPools) {
      return;
    }

    //console.log("[Actorpools] DCContext.actorPools", DCContext.actorPools);
    filterValidPools();

    //找出原始機率
    const tmp = DCContext.actorPools.actor_pools.find(element => element.original == true);
    console.log('[Actorpools] origPicks', tmp.actor_picks);
    setOrigPicks(tmp.actor_picks);
  }, [DCContext.actorPools]);

  useEffect(() => {
    if (!actorPools) {
      return;
    }

    console.log('[Actorpools] actorPools', actorPools);
    setPool(actorPools[poolIdx]);
  }, [actorPools, poolIdx]);

  /* */

  const changeInfoType = t => {
    // if (t == 2){
    //   setShowInfoType(2);
    // } else {
    //   setShowInfoType(1);
    // }

    if (t == 2) {
      navigate(`/actorpools/record`);
    } else {
      navigate(`/actorpools`);
    }
  };

  const changePool = p => {
    let newIdx = poolIdx + p;
    if (newIdx >= actorPools.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = actorPools.length - 1;
    }
    console.log('[Actorpools] newIdx', newIdx);

    setPoolIdx(newIdx);
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* modal */

  const [modalProps_actorpicks, setModalProps_actorpicks] = useState({
    ratio: 0.8,
    visible: false,
  });

  const showModal_actorpicks = () => {
    setModalProps_actorpicks(prevState => ({
      ...prevState,
      visible: true,
      destroyOnClose: true,
    }));
  };
  const callbackModal_actorpicks = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_actorpicks(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const aniStyles = useSpring({
    from: { opacity: 0 },
    to: { opacity: 1 },
    loop: { reverse: true },
    //reverse: true,
    config: {
      duration: 1500,
    },
  });

  return (
    <IbgDiv
      className={styles.rootContainer}
      src={pool?.background}
      transition={true}
      onReady={() => {}}
    >
      <div className={styles.mainBox} style={{ backgroundImage: `url(${bgClock})` }}>
        <div
          className={`${styles.bgLightBox} gpuRender`}
          style={{ backgroundImage: `url(${bgLight})` }}
        ></div>

        <div className={styles.poolName_bg}>{pool?.name}</div>
        <div className={styles.poolName}>{pool?.name}</div>

        <Iimg
          className={styles.actorImage}
          src={pool?.feature_actor_prototype_image}
          transition={false}
          onReady={() => {}}
        />

        <div className={styles.actorAttr}>
          <div className={styles.actorName}>{pool?.feature_actor_prototype}</div>
          <div className={styles.actorPro}>{pool?.feature_description}</div>
        </div>

        {pool?.limited_time && (
          <div className={styles.timeLimitBox}>
            <div className={styles.timeLimitText1}>{tt(`time_limit`)}</div>
            <div className={styles.timeLimitText2}>
              {/* {moment.utc(pool?.valid_to).local().format('YYYY.MM.DD HH:mm')} */}

              <Countdown
                key={pool?.valid_to}
                date={moment.utc(pool?.valid_to).local()}
                zeroPadTime={2}
                //daysInHours={true}
                renderer={props => {
                  //return <span>{props.formatted.hours}:{props.formatted.minutes}:{props.formatted.seconds}</span>;
                  return (
                    <span>
                      {props.formatted.days} {tt('iap_pass_expired_days')} {props.formatted.hours}:
                      {props.formatted.minutes}
                    </span>
                  );
                }}
              />
            </div>
          </div>
        )}

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            showModal_actorpicks();
          }}
        >
          <div className={`${styles.linkProps} ${styles.btnChance}`}>
            <span>{tt(`probability`) /* 機率 */}</span>
            <img className={`rotation_1`} src={icon_dice} />
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/store/bundleorders`);
          }}
        >
          <div className={`${styles.linkProps} ${styles.btnBundleorders}`}>
            <span>{tt(`to_procurement`) /* 往商城 */}</span>
            <img className={`rotation_1`} src={iconBundleordersWhite} />
          </div>
        </ClickEffect>

        <div className={styles.poolRule}>
          <img src={bg_shortMessage} />
          <animated.div className={styles.poolRuleText} style={{ ...aniStyles }}>
            {tt(`recruit_sr_actor_guarantee`) /* 點選招募10次，保證獲得至少一名SR幹部 */}
          </animated.div>
        </div>

        {actorPools?.length > 1 && (
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changePool(1);
            }}
          >
            <div className={styles.iconChangeBox}>
              <img className={styles.iconChange} src={iconChange} />
            </div>
          </ClickEffect>
        )}

        <div className={styles.leftTopPanel}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              navigate(`/store/bundleorders`);
            }}
          >
            <div className={styles.iconBtnBox}>
              <img className={styles.iconBtnImg} src={iconFundsPlus} />
              <div className={styles.iconBtnText}>{iNumify(DCContext?.userProfile?.fund)}</div>
            </div>
          </ClickEffect>

          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              navigate(`/store/bundlegift`);
            }}
          >
            <div className={styles.iconBtnBox}>
              <img className={styles.iconBtnImg} src={icon_recruit_plus} />
              <div className={styles.iconBtnText}>
                {iNumify(DCContext.actorPools?.recruit_coupons)}
              </div>
            </div>
          </ClickEffect>
        </div>

        <div className={`tabBar`}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(1);
            }}
          >
            <div className={`tab ${showInfoType == 1 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`recruitment`) /* 招募 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(2);
            }}
          >
            <div className={`tab ${showInfoType == 2 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`recruit_history`) /* 歷程 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 3 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            >
              <div className={`tabText1`}></div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 4 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            ></div>
          </ClickEffect>
        </div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE2.mp3` }}
          onClick={e => doRecruit(e, 10)}
        >
          <div className={styles.btnCircleBox}>
            <div className={styles.btnCircleWrap}>
              <img className={styles.btnCircleGold} src={circleGolden} />
              <div className={`${styles.btnCircleTextNo} ${styles.golden}`}>10</div>
              <div className={`${styles.btnCircleText} ${styles.golden}`}>
                {tt(`recruitment`) /* 招募 */}
              </div>
            </div>
          </div>
        </ClickEffect>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE2.mp3` }}
          onClick={e => doRecruit(e, 1)}
        >
          <div className={styles.btnCircleBox2}>
            <div className={styles.btnCircleWrap}>
              <img className={styles.btnCircleGold} src={circleSilver} />
              <div className={`${styles.btnCircleTextNo} ${styles.silver}`}>1</div>
              <div className={`${styles.btnCircleText} ${styles.silver}`}>
                {tt(`recruitment`) /* 招募 */}
              </div>
            </div>
          </div>
        </ClickEffect>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      {/* 機率 */}
      <Imodal {...modalProps_actorpicks} callback={callbackModal_actorpicks}>
        <Actorpicks markupPicks={pool?.actor_picks} origPicks={origPicks} />
      </Imodal>
    </IbgDiv>
  );
};
