export default function useImagePreloader(props) {
  const DCContext = useDCContext();
  //
  const [preloadImages, setPreloadImages] = useState();
  const [imagesPreloaded, setImagesPreloaded] = useState(false);
  const [preloadedRatio, setPreloadedRatio] = useState();
  const preloadQuantity = useRef(0);
  const downloadedQuantity = useRef(0);

  useEffect(() => {}, []);

  useEffect(() => {
    if (!preloadImages) {
      return;
    }
    //console.log('[useImagePreloader] xxxxxxxxxxxxxxx', preloadImages.length);

    console.log('[useImagePreloader] PRELOAD', preloadImages, props?.preloadMode);

    //
    downloadedQuantity.current = 0;
    preloadQuantity.current = preloadImages.length;

    if (props?.preloadMode == 'browser') {
      //強制使用 browser 方式，ex. demos
      preloadStart();
    } else if (window.deviceInfo) {
      //裝置
      preloadStart_mobile();
    } else {
      preloadStart();
    }
  }, [preloadImages]);

  const preloaderReset = () => {
    //歸零
    setImagesPreloaded(false);
    setPreloadedRatio(0);
    //
    downloadedQuantity.current = 0;
    preloadQuantity.current = 0;
  };

  const preloadStart = async () => {
    console.log('[useImagePreloader] preloadStart()');

    const imagesPromiseList = [];
    for (const i of preloadImages) {
      imagesPromiseList.push(preloadImage(i)); //web 用 img load 影片的話會直接 error 馬上 reject，這樣剛好
    }

    if (imagesPromiseList.length) {
      //allSettled => 全部跑完，即使中間有圖檔載入失敗
      //await 先等待處理結果
      await Promise.allSettled(imagesPromiseList)
        .then(value => {
          console.log('[useImagePreloader] resolve all', value);
        })
        .catch(err => {
          console.log('[useImagePreloader] err all', err);
        });
    }

    setImagesPreloaded(true);
  };

  const preloadImage = src => {
    // let preloadUrls = [
    //   `${iConfig.Media.builtinAssets}${src}`,
    //   `${window.deviceInfo?.assetsDL_path}${src}`//,
    // 	//`${iConfig.Media.remoteAssets}${src}`
    // ];

    let preloadUrls = [`${iConfig.Media.builtinAssets}${src}`];

    if (window.deviceInfo?.assetsDL_path) {
      preloadUrls.push(`${window.deviceInfo?.assetsDL_path}${src}`);
    }

    //console.log("[useImagePreloader] preloadUrls", preloadUrls);

    const imagesPromiseList = [];
    for (const i of preloadUrls) {
      imagesPromiseList.push(loadImage(i));
    }

    return new Promise((resolve, reject) => {
      //先試本地兩個 url，若都沒有再試遠端 url
      Promise.any(imagesPromiseList)
        .then(value => {
          //console.log("[useImagePreloader] resolve", value);

          //
          downloadedQuantity.current++;
          caculateRatio();

          //
          resolve(value);
        })
        .catch(err => {
          //console.log("[useImagePreloader] err", err);

          //試遠端url
          let remoteUrl = `${iConfig.Media.remoteAssets}${src}`;
          loadImage(remoteUrl)
            .then(value2 => {
              //console.log("[useImagePreloader] resolve2", value2);

              //
              downloadedQuantity.current++;
              caculateRatio();

              //
              resolve(value2);
            })
            .catch(err2 => {
              console.log('[useImagePreloader] err2', err2);

              //
              downloadedQuantity.current++;
              caculateRatio();

              //
              reject(err2);
            });
        });
    });
  };

  const loadImage = src => {
    //console.log("[useImagePreloader] loadImage", src);
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = function () {
        //
        resolve(src);
      };
      img.onerror = img.onabort = function () {
        //
        reject(src);
      };
      img.src = src;
    });
  };

  const caculateRatio = () => {
    let tmpRatio = Math.round((downloadedQuantity.current / preloadQuantity.current) * 100) / 100;
    //console.log(`[useImagePreloader] caculateRatio ${downloadedQuantity.current}/${preloadQuantity.current}`, tmpRatio);
    //todo 前一個 proload 的數量會累積到本次的，造成完成數比總數多的狀況，之後需要考慮改法
    if (tmpRatio > 1) {
      tmpRatio = 1;
    }
    setPreloadedRatio(tmpRatio);
  };

  /* for App */

  //送到 App 進行下載
  const preloadStart_mobile = () => {
    console.log('[useImagePreloader] preloadStart_mobile()');

    window.ReactNativeWebView?.postMessage(
      JSON.stringify({
        action: 'PRELOAD:images',
        data: {
          preloadImages: preloadImages,
        },
      }),
    );
  };

  // App 返回進度
  useEffect(() => {
    if (!DCContext.preloadsRatio) {
      return;
    }

    setPreloadedRatio(DCContext.preloadsRatio);

    if (DCContext.preloadsRatio == 1) {
      //console.log(`[useImagePreloader] DCContext.preloadsRatio`, DCContext.preloadsRatio);
      setImagesPreloaded(true);
      //
      DCContext.setPreloadsRatio(0);
    }
  }, [DCContext.preloadsRatio]);

  return { setPreloadImages, imagesPreloaded, preloadedRatio, preloaderReset };
}
