import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  findIndex as lodash_findIndex,
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//moment
import moment from 'moment';
import 'moment-timezone';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { FitText } from 'lib/FitText';
//
import iConfig from 'iConfig';
import styles from './Telegrams.module.scss';
import { Navigator } from 'component/modal/Navigator';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
//
import telegramBg from 'assets/img2/telegram/telegramBg.png';
import telegramBtn_blue from 'assets/img2/telegram/telegramBtn_blue.png';
import telegramBtn_red from 'assets/img2/telegram/telegramBtn_red.png';
import icon_trash_can_grey from 'assets/img2/icon_trash_can_grey.png';

export const Telegrams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const location = useLocation();
  //
  let navigate = useNavigate();

  const [telegramData, setTelegramData] = useState();

  useEffect(() => {
    return () => {};
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      //console.log("[DailyBundles] channel player 斷線");
      return;
    }

    //console.log("[DailyBundles] channel player 已連線");

    DCContext.getTelegram();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  //API telegram 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},telegram`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[Telegrams] [telegram 結果] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //沒有電報了
      if (_res.payload == 'no_telegram' || !_res.payload?.id) {
        props.callback();
        return;
      }

      //有電報
      setTelegramData(_res.payload);
    } else {
      console.log('telegram error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},telegram`]?.uuid]);

  useEffect(() => {
    if (!telegramData) {
      return;
    }

    DCContext.playSound(telegramData?.open_sound_effect);
  }, [telegramData]);

  const clickRead = () => {
    DCContext.getTelegram({ id: telegramData.id });

    //DCContext.playSound(telegramData?.read_sound_effect);
  };

  const clickGoto = () => {
    switch (telegramData?.goto) {
      case 'election':
        navigate(`/headquarter/${DCContext.myNation.id}`);
        clickRead();
        props.callback();
        break;

      case 'nation_battle':
        // navigate("/nationbattlemap", {
        //   state: {
        //     focus_city_id: DCContext.userProfile.nation_battle?.city_id,
        //     returnUrl: location.pathname,
        //     returnState: location.state
        //   }
        // });

        navigate(`/portalmap`);
        clickRead();
        props.callback();
        break;

      case 'city':
        navigate('/nationbattlemap', {
          state: {
            focus_city_id: telegramData?.goto_id,
            returnUrl: location.pathname,
            returnState: location.state,
          },
        });
        clickRead();
        props.callback();
        break;
    }
  };

  const clickReadAll = () => {
    DCContext.setShowConfirmModal({
      confirm: {
        message: tt(`telegram_read_all_confirm`), //確定要銷毀所有電報？
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              //console.log('xxxxx');
              DCContext.telegramReadAll();
              DCContext.setShowConfirmModal();
            },
          },
        ],
      },
    });
  };

  return (
    <div className={styles.rootContainer}>
      <div className={styles.mainBox} style={{ backgroundImage: `url(${telegramBg})` }}>
        <div className={styles.contentBox}>
          {telegramData?.datetime && (
            <div className={styles.datetimeBox}>{telegramData?.datetime}</div>
          )}
          <div
            className={styles.descriptionBox}
            dangerouslySetInnerHTML={{ __html: telegramData?.message }}
          ></div>

          <div className={styles.btnRow}>
            <ClickEffect
              effect={{
                sound: telegramData?.read_sound_effect
                  ? telegramData?.read_sound_effect
                  : `/audio/sound_effect/SE1.mp3`,
              }}
              onClick={() => {
                clickRead();
              }}
            >
              <div className={`${styles.buttonBox} ${styles.btnBlue}`}>
                <img className={styles.btnImg} src={telegramBtn_blue} />
                <div className={styles.btnText}>
                  <FitText>{tt(`telegram_roger_that`) /* 抄收 */}</FitText>
                </div>
              </div>
            </ClickEffect>

            {telegramData?.goto && (
              <ClickEffect
                effect={{
                  sound: telegramData?.read_sound_effect
                    ? telegramData?.read_sound_effect
                    : `/audio/sound_effect/SE1.mp3`,
                }}
                onClick={() => {
                  clickGoto();
                }}
              >
                <div className={`${styles.buttonBox} ${styles.btnRed}`}>
                  <img className={styles.btnImg} src={telegramBtn_red} />
                  <div className={styles.btnText}>
                    <FitText>{tt(`telegram_check_it`) /* 現場 */}</FitText>
                  </div>
                </div>
              </ClickEffect>
            )}
          </div>
        </div>
      </div>

      <ClickEffect
        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
        onClick={e => {
          clickReadAll();
        }}
      >
        <img className={styles.icon_trash_can_grey} src={icon_trash_can_grey} />
      </ClickEffect>
    </div>
  );
};
