import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
} from '@react-spring/web';
import { Col, Row, Modal } from 'antd';
import Picker from 'react-mobile-picker';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './Bundleorders.module.scss';
import background from 'assets/img/bgClockGold.png';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { ClickEffect } from 'componentx/ClickEffect';
import { Confirm } from 'componentx/Confirm';
import cfgStyle from 'config.module.scss';

//
import iconFunds from 'assets/img/iconFunds.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import iconExchangeArrow from 'assets/img/store/iconExchangeArrow.png';
//
import bgExchangeRate from 'assets/img/store/bgExchangeRate.png';
import iconPropsWhite from 'assets/img/iconPropsWhite.png';
import shopBtn from 'assets/img/store/shopBtn.png';

export const Bundleorders = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [bundles, setBundles] = useState();
  const [products, setProducts] = useState();
  const [selectedProduct, setSelectedProduct] = useState();
  const catIdx = 0;

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Bundleorders] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Bundleorders] channel player 未連線');
      return;
    }

    console.log('[Bundleorders] channel player 已連線');
    DCContext.getBundles(true);
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.bundle_categories || !DCContext.bundles) {
      return;
    }

    let tmp = [];
    DCContext.bundles.map((item, idx) => {
      if (item.bundle_category_id == DCContext.bundle_categories[catIdx].id) {
        tmp.push(item);
      }
    });

    console.log('[Bundleorders] bundles', tmp, DCContext.bundle_categories[catIdx]);

    setBundles(tmp);
  }, [DCContext.bundle_categories, DCContext.bundles]);

  useEffect(() => {
    if (!bundles) {
      return;
    }

    if (!DCContext.iapProducts) {
      DCContext.getIapProducts();
      return;
    }

    console.log('[Bundleorders] DCContext.iapProducts', DCContext.iapProducts);

    let tmp = [];
    bundles.map((item, idx) => {
      let matchIapItem = DCContext.iapProducts.find(iapItem => {
        if (iapItem.productId == item.product_id) {
          return true;
        }
      });
      console.log('[Bundleorders] matchIapItem', item.product_id, matchIapItem);

      if (matchIapItem) {
        tmp.push({
          ...item,
          iapData: matchIapItem,
        });
      }
    });

    console.log('[Bundleorders] merged products', tmp);

    setProducts(tmp);
  }, [bundles, DCContext.iapProducts]);

  const buyProduct = () => {
    if (!selectedProduct) {
      return;
    }

    console.log('[Bundleorders] buyProduct selectedProduct', selectedProduct);

    //購買鍵縮放效果
    aniApi.start({
      from: { _x: 0 },
      to: { _x: 1 },
      config: {
        duration: 1000,
      },
      onRest: () => {
        console.log('[Bundleorders] shop button scale complete');

        //顯示購買物品內容
        DCContext.setShowStoreShopConfirm({
          data: {
            cost: `${selectedProduct.iapData?.currency} ${
              selectedProduct.iapData?.localizedPrice.startsWith('$')
                ? selectedProduct.iapData?.localizedPrice.substr(1)
                : selectedProduct.iapData?.localizedPrice
            }`,
            productName: tt('iap_purchase_name_cash_exchange_amount', {
              exchange_amount: selectedProduct.name.toLocaleString('en-US'),
            }),
          },
          callback: () => {
            //確定購買
            //console.log('xxxxx 2');

            DCContext.setShowProcessingModal(true); //顯示“處理中”
            //
            DCContext.buyIapProduct(selectedProduct.iapData.productId);
            //
            DCContext.setShowStoreShopConfirm();
          },
        });
      },
    });
  };

  useEffect(() => {
    if (!DCContext.iapPhase1) {
      return;
    }

    //iapPhase1 => OK 或 ERROR 都關閉“處理中” modal
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    DCContext.setIapPhase1(null);
  }, [DCContext.iapPhase1]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    maskClosable: false,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* 滾輪 picker */
  const refContainer_picker = useRef();

  const [pickerValue, setPickerValue] = useState({
    prdIdx: 1,
  });

  useEffect(() => {
    if (!products) {
      return;
    }

    console.log('[Bundleorders] pickerValue', pickerValue, products[pickerValue.prdIdx]);

    setSelectedProduct(products[pickerValue.prdIdx]);
  }, [pickerValue, products]);

  //購買鍵縮放效果
  const [aniStyles, aniApi] = useSpring(() => ({
    from: { _x: 0 },
    to: { _x: 1 },
    onRest: () => {},
  }));

  return (
    <IbgDiv className={styles.rootContainer} src={background} transition={true} onReady={() => {}}>
      <div className={styles.mainBox}>
        <div className={styles.exchangeBox}>
          <div className={styles.exchangeHead}>{tt(`current_price`) /* 當前牌價 */}</div>
          <div
            className={styles.exchangeRate}
            style={{ backgroundImage: `url(${bgExchangeRate})` }}
          >
            <div>
              <span>1</span>
              <img src={iconFunds} />
            </div>
            <div> = </div>
            <div>USD 0.033</div>
          </div>
          <div className={styles.prdhead}>{tt(`special_savings_plan`) /* 優惠方案 */}</div>
        </div>
        <div className={styles.bodyBox}>
          <div className={styles.listBox}>
            <div ref={refContainer_picker} className={styles.listTable}>
              {refContainer_picker.current?.clientHeight && (
                <Picker
                  value={pickerValue}
                  onChange={setPickerValue}
                  height={refContainer_picker.current?.clientHeight}
                  itemHeight={50}
                  wheelMode="normal"
                >
                  <Picker.Column name="prdIdx">
                    {products?.map((item, idx) => {
                      let price = item.iapData?.localizedPrice.startsWith('$')
                        ? item.iapData?.localizedPrice.substr(1)
                        : item.iapData?.localizedPrice;

                      return (
                        <Picker.Item key={item.id} value={idx}>
                          {({ selected }) => (
                            <Row
                              key={item.id}
                              className={`${styles.prdRow} 
                              ${selected ? styles.selected : null}`}
                              justify="space-evenly"
                              align="middle"
                              //onClick={()=>{ setSelectedProduct(item) }}
                            >
                              <Col span={4}>{/*-*/}</Col>
                              <Col span={6}>
                                {item.iapData?.currency} {price}
                              </Col>
                              <Col flex="auto">
                                <img src={iconExchangeArrow} />
                              </Col>
                              <Col span={6}>
                                <span>{item.name}</span>
                                <img src={iconFunds} />
                              </Col>
                              <Col span={4}>{/*+*/}</Col>
                            </Row>
                          )}
                        </Picker.Item>
                      );
                    })}
                  </Picker.Column>
                </Picker>
              )}
            </div>
            <div className={styles.fundsTextRow}>
              <div className={styles.fundsText}>
                <span className={styles.fundsText1}>
                  {tt(`your_revolution_treasury`) /* 您的革命金庫 */}&nbsp;&nbsp;
                </span>
                <img src={iconFunds} />
                <span className={styles.fundsNumber}>
                  {DCContext.userProfile?.fund.toLocaleString('en-US')}
                </span>
              </div>
            </div>
          </div>
          <ClickEffect
            enabled={
              DCContext.bundle_categories?.[catIdx].can_buy && selectedProduct ? true : false
            }
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              buyProduct();
            }}
          >
            <animated.div
              className={styles.shopBtn}
              style={{
                ...aniStyles,
                transform: aniStyles._x
                  .to({
                    range: [0, 0.5, 1],
                    output: [1, 1.1, 1],
                  })
                  .to(value => {
                    return `translate(0, 0) scale(${value})`;
                  }),
              }}
            >
              <img className={styles.shopBtnImg} src={shopBtn} />
              <div className={styles.shopBtnText}>{tt(`trade`) /* 交易 */}</div>
            </animated.div>
          </ClickEffect>
        </div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/user/backpack`);
          }}
        >
          <div className={styles.linkProps}>
            <img className={`rotation_1`} src={iconPropsWhite} />
            <span>{tt(`to_treasury`) /* 往庫房 */}</span>
          </div>
        </ClickEffect>
      </div>

      <div className={`tabBar ${styles.tabBar_shadow}`}>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundleorders');
          }}
        >
          <div className={`tab active`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`bank`) /* 錢莊 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/monthlycard');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`monthly_card`) /* 月卡 */}</div>
            {DCContext.bundle_categories?.[1].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          enabled={true}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlepass');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`activity_pass`) /* 通行證 */}</div>
            {DCContext.bundle_categories?.[2].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlegift');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`gift_pack`) /* 禮包 */}</div>
          </div>
        </ClickEffect>
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>
    </IbgDiv>
  );
};
