import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  useTransition,
  useSpring,
  useSpringRef,
  useChain,
  animated,
  easings,
  config,
} from '@react-spring/web';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
import { useLocalStorage } from 'lib/useLocalStorage';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './ActorUpgrade.module.scss';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BackpackItems } from 'component/BackpackItems';
import { ActorSwitch } from 'component/ActorSwitch';
//
import { ActorProps } from 'component/ActorProps';
import { UwActorTopBlock, shouldBlockUpgrade } from 'features/underworld';
import bgBackpack from 'assets/img2/bgBackpack.png';
import { BtnRing } from 'component/BtnRing';

export const ActorUpgrade = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const [actor, setActor] = useState();

  let { actionId } = useParams();
  actionId = parseInt(actionId);
  //console.log('[ActorUpgrade] actionId: ', actionId);
  //
  //強化 進化 裝備 修煉 ...等等返回 幹部資訊頁 或 庫房
  const [returnUrl_actorSettings, setReturnUrl_actorSettings] = useLocalStorage(
    'returnUrl_actorSettings',
    '',
  );

  const upgrade_api_processing = useRef(false);

  useEffect(() => {
    console.log('cccccc2', returnUrl_actorSettings);

    return () => {
      //清空暫選的素材
      console.log('[ActorUpgrade] 清空暫選的素材1');
      DCContext.setTmpSelectedProps([]);
    };
  }, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[ActorUpgrade] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[ActorUpgrade] channel player 斷線');
      return;
    }

    console.log('[ActorUpgrade] channel player 已連線');
    DCContext.getActors();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.actors) {
      return;
    }

    console.log('[ActorUpgrade] DCContext.actors', DCContext.actors);

    //清空暫選的素材
    console.log('[ActorUpgrade] 清空暫選的素材2');
    DCContext.setTmpSelectedProps([]);

    //
    let actorData = DCContext.getActorDataById(actionId);
    setActor(actorData);
    console.log('[ActorUpgrade] actorData', actorData);
  }, [DCContext.actors, actionId]);

  const changeActor = p => {
    let newIdx = actor.idx + p;
    if (newIdx >= DCContext.actors.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = DCContext.actors.length - 1;
    }
    console.log('[ActorUpgrade] newIdx', newIdx);

    navigate(`/user/actorupgrade/${DCContext.actors[newIdx].id}`);
  };

  const callback_item = (_type, _data) => {
    // console.log("[ActorUpgrade] callback_item", _type, _data);
    // switch(_type){
    //   case "actorPickWeapon":
    //     break;
    // }
  };

  //強化
  const callback_upgrade = () => {
    console.log(
      '[ActorUpgrade] callback_upgrade',
      DCContext.tmpSelectedProps,
      DCContext.userProfile,
      upgrade_api_processing.current,
    );

    if (upgrade_api_processing.current) {
      console.log(
        '[ActorUpgrade] callback_upgrade upgrade_api_processing.current',
        upgrade_api_processing.current,
      );
      return;
    }

    if (
      shouldBlockUpgrade({
        relationLevel: actor?.relation_level ?? 1,
        relationLevelCap: actor?.actor_prototype?.relation_level_cap ?? 1,
        selectedProps: DCContext.tmpSelectedProps,
        actorPrototypeId: actor?.actor_prototype?.id,
      })
    ) {
      showModal_confirm({
        confirm: {
          message: tt('uw_relation_level_up_cap_warn', {
            actor_name: actor?.actor_prototype?.name ?? '',
          }),
          buttons: [
            {
              text: { i18nKey: 'confirm' },
              callback: () => callbackConfirm({}),
            },
          ],
        },
      });
      return;
    }
    upgrade_api_processing.current = true;

    let upgradeExp = DCContext.cacuActorUpgradeExp(actor);
    console.log('[ActorUpgrade] cacuActorUpgradeExp', upgradeExp, DCContext.userProfile);

    if (DCContext.userProfile.media < upgradeExp.finalLevel_needMedia) {
      showModal_confirm({
        confirm: {
          message: tt('p_media_not_enough') /* 動員力不足 */,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });

      upgrade_api_processing.current = false;

      return;
    }

    let tmp = {
      upgradable_type: 'Actor',
      upgradable_id: actor.id,
      skill_redeemed: upgradeExp.propsExp,
      redemptions: upgradeExp.redemptions,
    };
    console.log('[ActorUpgrade] callback_upgrade 2', tmp, upgrade_api_processing.current);

    DCContext.ActorUpgrade(tmp);
  };

  //upgrade 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},upgrade`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    console.log('[ActorUpgrade] callback_upgrade 3', upgrade_api_processing.current);

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[ActorUpgrade] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //清空暫選的素材
      console.log('[ActorUpgrade] 清空暫選的素材2');
      DCContext.setTmpSelectedProps([]);

      //螢幕閃光
      aniApi_flash.start({
        from: { opacity: 0 },
        to: [{ opacity: 1 }, { opacity: 0 }],
      });

      //音效
      DCContext.playSound('/audio/sound_effect/SE12.mp3');
    } else {
      console.log('upgrade error 其他錯誤');
    }

    upgrade_api_processing.current = false;
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},upgrade`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[ActorUpgrade] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* 閃白光特效 */
  const [aniStyles_flash, aniApi_flash] = useSpring(() => ({
    from: { opacity: 0 },
    //to: [{opacity: 1}, {opacity: 0}],
    //loop: { reverse: true },
    //reverse: true,
    config: {
      //duration: 1000,
      easing: easings.circInOut,
    },
  }));

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.bgBox} style={{ backgroundImage: `url(${bgBackpack})` }}></div>

      <div className={styles.mainBox}>
        <IbgDiv className={styles.leftBox} src={null} transition={false} onReady={() => {}}>
          <UwActorTopBlock
            mode="upgrade"
            actor={actor}
            actorPrototype={actor?.actor_prototype}
            selectedProps={DCContext.tmpSelectedProps}
            hasVisitPlot={!!actor?.actor_prototype?.has_visit_plot}
          />
          <div className={styles.nameBox}>
            <ActorSwitch actor={actor} callback_changeActor={changeActor} />
          </div>

          <ActorProps mode={'actorUpgrade'} actorData={actor} />

          {DCContext.tmpSelectedProps.length > 0 && (
            <BtnRing color="golden" text={tt('power_up') /* 強化 */} callback={callback_upgrade} />
          )}
        </IbgDiv>

        <div className={styles.rightBox}>
          {actor && (
            <BackpackItems
              itemType={1}
              mode={'actorUpgrade'}
              actor={actor}
              callback_item={callback_item}
            />
          )}
        </div>
      </div>

      <Navigator
        navi={{
          back: returnUrl_actorSettings ? { url: returnUrl_actorSettings } : { spot: 'actors' },
        }}
      />

      {/* modal confirm */}

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <animated.div
        className={styles.upgradeFlashLayer}
        style={{ ...aniStyles_flash }}
      ></animated.div>
    </div>
  );
};
