import React, { useContext, useState, useEffect, useRef } from 'react';
//
import iConfig from 'iConfig';
import { useSocketContext } from './SocketContext';

const ChannelContext = React.createContext();

export const ChannelProvider = ({ children }) => {
  // Initialize state
  const [channels, setChannels] = useState({}); //供外部檢查是否連線用
  const _channelsRef = useRef({}); //內部實際操作用
  const [join, setJoin] = useState(null); //{topic:, params:}
  const [joinRes, setJoinRes] = useState(null); //{topic: ,res: {status:, reason:}}
  const [messages, setMessages] = useState({}); //{topic: {event: {}}}
  const [sendMessageRes, setSendMessageRes] = useState(null); //{topic:, event:, res: {status:, payload:}}
  //
  const { socket } = useSocketContext();
  const queueJobs = useRef({});

  const joinChannel = ({ topic = '', params = {}, callback = () => {} } = {}) => {
    console.log('[ChannelContext] joinChannel', topic, params);

    const ch = socket.channel(topic, params);

    ch.onMessage = (_event, payload, _ref, event, ref) => {
      // console.log("mmm _event", _event);
      // console.log("mmm payload", payload);
      // console.log("mmm _ref", _ref);
      // console.log("mmm event", event);
      // console.log("mmm ref", ref);
      // console.log("mmm ch", ch);

      //console.log(`[ChannelContext] onMessage`, _event, payload, _ref, event, ref);

      if (
        _event == 'phx_reply' || //join channel 結果
        _event.startsWith('chan_reply_') //chan_reply_ 開頭屬於 API response 不是 broadcast
      ) {
        //do nothing
      } else {
        //剩下都是 broadcast
        setMessages({
          topic: ch.topic,
          event: _event,
          res: {
            status: 'ok',
            payload: payload,
          },
        });
      }

      return payload; //Must return the payload, modified or unmodified
    };

    ch.join()
      .receive('ok', ({ message }) => {
        //console.log("ch", ch);
        console.log('[ChannelContext] [join], message = ', topic, message);
        //onJoinFun.current({status: "joined"})

        //
        _channelsRef.current[topic] = ch;
        setChannels(_channelsRef.current);

        let tmp = {
          topic: topic,
          res: {
            status: 'ok',
          },
        };

        setJoinRes(tmp);
        callback(tmp);
      })
      .receive('error', ({ reason }) => {
        console.log('[ChannelContext] [join] failed', topic, reason);
        //onJoinFun.current({status: "join_failed", reason: reason})

        let tmp = {
          topic: topic,
          res: {
            status: 'error',
            reason: reason,
          },
        };

        setJoinRes(tmp);
        callback(tmp);
      })
      .receive('timeout', () => {
        console.log('[ChannelContext] [join] Networking issue. Still waiting...', topic);
        //onJoinFun.current({status: "join_timeout"})

        let tmp = {
          topic: topic,
          res: {
            status: 'timeout',
          },
        };

        setJoinRes(tmp);
        callback(tmp);
      });
  };

  const leaveChannel = ({ topic = '', params = {}, callback = () => {} } = {}) => {
    console.log(
      '[ChannelContext] leaveChannel topic',
      topic,
      params,
      _channelsRef.current,
      channels,
    );

    if (!topic || !_channelsRef.current[topic]) {
      return;
    }

    _channelsRef.current[topic].leave().receive('ok', () => {
      console.log('[ChannelContext] channel left!', topic);

      delete _channelsRef.current[topic];
      setChannels(_channelsRef.current);

      let tmp = {
        topic: topic,
        res: {
          status: 'ok',
        },
      };

      callback(tmp);
    });
  };

  useEffect(() => {
    if (!channels) {
      return;
    }

    console.log('[ChannelContext] channels', channels);
  }, [channels]);

  const sendMessage = msg => {
    console.log('[ChannelContext] sendMessage', msg, iConfig.Phoenix.push_timeout);

    let _ch = _channelsRef.current[msg.topic];
    console.log(`[ChannelContext] _ch.state`, msg.topic, msg.event, _ch?.state);

    if (!_ch) {
      console.log(`[ChannelContext] channel not join yet`, msg.topic);
      return;
    }

    //channel 尚未加入完成，保留此次 message
    if (_ch.state != 'joined') {
      if (!queueJobs[msg.event]) {
        queueJobs[msg.event] = [];
      }

      queueJobs[msg.event].push(msg);
      console.log(`[ChannelContext] queueJobs`, queueJobs);

      return;
    }

    //console.log("msg", _ch);
    _ch
      .push(msg.event, msg.message, iConfig.Phoenix.push_timeout) //timeout 預設 10 秒
      .receive('ok', payload => {
        //console.log("phoenix push replied:", payload);

        setSendMessageRes({
          topic: _ch.topic,
          event: msg.event,
          res: {
            status: 'ok',
            payload: payload,
          },
        });
      })
      .receive('error', err => {
        //console.log("phoenix push errored", err);

        setSendMessageRes({
          topic: _ch.topic,
          event: msg.event,
          res: {
            status: 'error',
            error: err,
          },
        });
      })
      .receive('timeout', () => {
        console.log('[ChannelContext] phoenix timed out pushing');

        setSendMessageRes({
          topic: _ch.topic,
          event: msg.event,
          push_data: msg.message,
          res: {
            status: 'timeout',
          },
        });
      });
  };

  return (
    <ChannelContext.Provider
      value={{
        channels,
        setChannels,
        //join, setJoin,
        joinChannel,
        leaveChannel,
        joinRes,
        setJoinRes,
        messages,
        setMessages,
        sendMessageRes,
        setSendMessageRes,
        //leave, setLeave,
        sendMessage,
      }}
    >
      {children}
    </ChannelContext.Provider>
  );
};

// Create a hook to use the APIContext, this is a Kent C. Dodds pattern
export const useChannelContext = () => {
  const context = useContext(ChannelContext);
  if (context === undefined) {
    throw new Error('Context must be used within a Provider');
  }
  return context;
};

