import React, { useContext, useState, useEffect } from 'react';
import {
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import { useSpring, useSpringRef, useChain, animated, easings } from '@react-spring/web';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal, Popover } from 'antd';
import Countdown from 'react-countdown';
//moment
import moment from 'moment';
import 'moment-timezone';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import iConfig from 'iConfig';
import styles from './BundlePass.module.scss';
import background from 'assets/img/bgClockGold.png';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { ClickEffect } from 'componentx/ClickEffect';
import { Confirm } from 'componentx/Confirm';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
import { FitText } from 'lib/FitText';
import { integerToRoman } from 'lib/funcs';
//
import { PopupMessagesIcon } from 'component/modal/PopupMessagesIcon';
import iconFunds from 'assets/img/iconFunds.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import iconExchangeArrow from 'assets/img/store/iconExchangeArrow.png';
//
import bgExchangeRate from 'assets/img/store/bgExchangeRate.png';
import iconPropsWhite from 'assets/img/iconPropsWhite.png';
import shopBtn from 'assets/img/store/shopBtn.png';
import bgTitleBar2 from 'assets/img2/bgTitleBar2.png';
import logo_monthlycard from 'assets/img2/store/logo_monthlycard.png';
import popup_btn_bg from 'assets/img2/popup_btn_bg.png';
import bgPassItem from 'assets/img2/store/bgPassItem.png';
import bgPrizesBar from 'assets/img/tmp/bgMissionStatus/bgPrizesBar.png';
import bgPropsHole_w from 'assets/img/bgPropsHole_w.png';
import bgPropsHole from 'assets/img/bgPropsHole.png';
import icon_circleCheck from 'assets/img2/icon_circleCheck.png';
import circleGolden from 'assets/img/circleGolden.png';
import circleSilver from 'assets/img/circleSilver.png';
import icon_upgrade from 'assets/img/icon_upgrade.png';
import highlightCircle from 'assets/img2/highlightCircle.png';

export const BundlePass = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [bundles, setBundles] = useState();
  const [products, setProducts] = useState();
  const [product, setProduct] = useState();
  const [selectedProduct, setSelectedProduct] = useState();
  const catIdx = 2;

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[BundlePass] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[BundlePass] channel player 未連線');
      return;
    }

    console.log('[BundlePass] channel player 已連線');
    DCContext.getBundles(false); //錢莊 true 就可以
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.bundle_categories || !DCContext.bundles) {
      return;
    }

    let tmp = [];
    DCContext.bundles.map((item, idx) => {
      if (item.bundle_category_id == DCContext.bundle_categories[catIdx].id) {
        tmp.push(item);
      }
    });

    console.log('[BundlePass] bundles', tmp);

    setBundles(tmp);
  }, [DCContext.bundle_categories, DCContext.bundles]);

  useEffect(() => {
    console.log('[BundlePass] DCContext.bundles', DCContext.bundles);

    if (!bundles) {
      return;
    }

    if (!DCContext.iapProducts) {
      DCContext.getIapProducts();
      return;
    }

    console.log('[BundlePass] DCContext.iapProducts', DCContext.iapProducts);

    let tmp;
    let matchIapItem = DCContext.iapProducts.find(iapItem => {
      if (iapItem.productId == DCContext.bundle_categories[catIdx].product_id) {
        return true;
      }
    });
    console.log(
      '[BundlePass] matchIapItem',
      DCContext.bundle_categories[catIdx].product_id,
      matchIapItem,
    );

    if (matchIapItem) {
      tmp = {
        ...DCContext.bundle_categories[catIdx],
        iapData: matchIapItem,
      };
    }

    console.log('[BundlePass] merged products', tmp);

    setProduct(tmp);
    setSelectedProduct(tmp);
  }, [bundles, DCContext.iapProducts]);

  const buyProduct = () => {
    if (!selectedProduct) {
      return;
    }

    console.log('[BundlePass] buyProduct selectedProduct', selectedProduct);

    //購買鍵縮放效果
    aniApi.start({
      from: { _x: 0 },
      to: { _x: 1 },
      config: {
        duration: 1000,
      },
      onRest: () => {
        console.log('[BundlePass] shop button scale complete');

        //顯示購買物品內容
        DCContext.setShowStoreShopConfirm({
          data: {
            cost: `${selectedProduct.iapData?.currency} ${
              selectedProduct.iapData?.localizedPrice.startsWith('$')
                ? selectedProduct.iapData?.localizedPrice.substr(1)
                : selectedProduct.iapData?.localizedPrice
            }`,
            productName: selectedProduct.name,
          },
          callback: () => {
            //確定購買
            //console.log('xxxxx 2');

            DCContext.setShowProcessingModal(true); //顯示“處理中”
            //
            DCContext.buyIapProduct(selectedProduct.iapData.productId);
            //
            DCContext.setShowStoreShopConfirm();
          },
        });
      },
    });
  };

  useEffect(() => {
    if (!DCContext.iapPhase1) {
      return;
    }

    //iapPhase1 => OK 或 ERROR 都關閉“處理中” modal
    DCContext.setShowProcessingModal(false); //隱藏“處理中”

    DCContext.setIapPhase1(null);
  }, [DCContext.iapPhase1]);

  /* 領取 */

  const collectProduct = () => {
    console.log('[BundlePass] collectProduct', selectedProduct);

    DCContext.collectBundle({
      reference_type: 'Pass',
    });
  };

  //collect_bundle 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[BundlePass] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  //領取結果
  // useEffect(()=>{
  // 	if (!DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]){
  // 		return;
  // 	}

  // 	console.log("[MonthlyCard] player,collect_bundle", {...DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res});

  // 	//todo error處理
  //   if (DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res.status == "error"){
  //     console.log("[MonthlyCard] player,collect_bundle error", {...DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res});
  //     return;
  //   }

  //   //顯示已領取狀態 & popup
  //   let returnParams = DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`].res.payload;

  //   if (returnParams.reference_type == "Pass"){
  //     //popup
  //     showModal_confirm({
  //       confirm: {
  //         /* 領取完成 */
  //         message: {i18nKey:`bundle_collected`, values:null, options:null},
  //         buttons: [
  //           {
  //             text: {i18nKey:`confirm`},
  //             callback: ()=>{
  //               callbackConfirm();
  //             }
  //           }
  //         ]
  //       }
  //     });
  //   }

  // 	//清除本次 send message 結果
  // 	DCContext.setMsgRes((prevState)=>{
  // 		delete prevState[`${DCContext.playerChannelTopic},collect_bundle`];
  // 		return {...prevState};
  // 	});

  // }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    maskClosable: false,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Attack] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[ChatBundle] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const [aniFlashStyles, aniFlashApi] = useSpring(() => ({
    from: { opacity: 0 },
    to: { opacity: 1 },
    loop: { reverse: true },
    //reverse: true,
    config: {
      duration: 1500,
    },
  }));

  //購買鍵縮放效果
  const [aniStyles, aniApi] = useSpring(() => ({
    from: { _x: 0 },
    to: { _x: 1 },
    onRest: () => {},
  }));

  return !product ? (
    <></>
  ) : (
    <IbgDiv
      className={styles.rootContainer}
      src={background}
      transition={true}
      onReady={() => {
        aniFlashApi.start();
      }}
    >
      <div className={styles.mainBox}>
        <IbgDiv
          className={styles.windowImgBox}
          src={product?.image}
          transition={false}
          onReady={() => {}}
        ></IbgDiv>

        <div className={styles.passContentBox}>
          {/* 背景光束 */}
          <div className={styles.lightBarBox}>
            <div className={styles.passItems_col}>
              <IbgDiv
                className={`${styles.passItemFixedHeigh} ${styles.winPrizesBar}`}
                src={bgPrizesBar}
                transition={false}
                onReady={() => {}}
              ></IbgDiv>
              <div className={styles.passItemLevel}></div>
              <IbgDiv
                className={`${styles.passItemFixedHeigh} ${styles.winPrizesBar}`}
                src={bgPrizesBar}
                transition={false}
                onReady={() => {}}
              ></IbgDiv>
            </div>
          </div>

          <div className={styles.passItemsBox}>
            <div className={styles.passItemsBoxCont}>
              {bundles?.map((item, idx) => {
                let level = idx + 1;
                // let darkStyle1 = (level > product.pass_level) ? "filter_black" : "";
                // let darkStyle2 = "";
                // if (product.can_buy){
                //   darkStyle2 = "filter_black";
                // } else {
                //   darkStyle2 = (level > product.pass_level) ? "filter_black" : "";
                // }

                let darkStyle1 = '';
                let darkStyle2 = '';

                //是否可領取
                let itemCanCollect_0 = level <= product.pass_level ? true : false;
                let itemCanCollect_1 = false;
                if (product.can_buy) {
                  //可以買，表示還沒買
                  itemCanCollect_1 = false;
                } else {
                  //已經買
                  itemCanCollect_1 = level <= product.pass_level ? true : false;
                }

                //是否已領取
                let itemCollected_0 = level <= product.collected_pass_level_0 ? true : false;
                let itemCollected_1 = level <= product.collected_pass_level_1 ? true : false;

                const descriptionPop_regular = (
                  <div
                    className={`popover-description`}
                    dangerouslySetInnerHTML={{ __html: item.regular_bundle?.description }}
                  ></div>
                );

                const descriptionPop_grand = (
                  <div
                    className={`popover-description`}
                    dangerouslySetInnerHTML={{ __html: item.grand_bundle?.description }}
                  ></div>
                );

                return (
                  <div key={idx} className={styles.passItems_col}>
                    <div className={`${styles.passItemBox} ${styles.passItemFixedHeigh}`}>
                      <img
                        className={styles.bgPassItem}
                        src={itemCanCollect_0 ? bgPropsHole_w : bgPropsHole}
                      />
                      <Popover
                        overlayInnerStyle={{ backgroundColor: 'unset' }}
                        content={descriptionPop_regular}
                        title={item.regular_bundle?.name}
                        placement="rightTop"
                        trigger="click"
                        overlayClassName={styles.popOver}
                      >
                        <Iimg
                          className={`${styles.passItemImg} ${darkStyle1}`}
                          src={item.regular_bundle?.image}
                          transition={false}
                          onReady={() => {}}
                        />
                      </Popover>
                      {itemCollected_0 && (
                        <img className={styles.icon_circleCheck} src={icon_circleCheck} />
                      )}
                      <div className={styles.passItemQuantity}>{item.regular_bundle?.quantity}</div>
                    </div>

                    <div
                      className={styles.passItemLevel}
                      style={{ color: itemCanCollect_0 ? 'white' : '#8a8a8a' }}
                    >
                      {integerToRoman(level)}
                    </div>

                    <div className={`${styles.passItemBox} ${styles.passItemFixedHeigh}`}>
                      <img
                        className={styles.bgPassItem}
                        src={itemCanCollect_1 ? bgPropsHole_w : bgPropsHole}
                      />
                      <Popover
                        overlayInnerStyle={{ backgroundColor: 'unset' }}
                        content={descriptionPop_grand}
                        title={item.grand_bundle?.name}
                        placement="rightTop"
                        trigger="click"
                        overlayClassName={styles.popOver}
                      >
                        <Iimg
                          className={`${styles.passItemImg} ${darkStyle2}`}
                          src={item.grand_bundle.image}
                          transition={false}
                          onReady={() => {}}
                        />
                      </Popover>
                      {itemCollected_1 && (
                        <img className={styles.icon_circleCheck} src={icon_circleCheck} />
                      )}
                      <div className={styles.passItemQuantity}>{item.grand_bundle.quantity}</div>
                    </div>
                  </div>
                );
              })}

              <div className={styles.passItems_col}>
                <div className={styles.passItemBox}></div>
              </div>
              <div className={styles.passItems_col}>
                <div className={styles.passItemBox}></div>
              </div>
            </div>
          </div>

          {/* 金銀環 */}
          <div className={styles.circlesBox}>
            <div className={styles.passItems_col}>
              <div className={`${styles.passItemFixedHeigh}`} style={{ position: 'relative' }}>
                <div className={styles.btnCircleBox}>
                  <div className={styles.btnCircleWrap}>
                    <img className={styles.btnCircleGold} src={circleSilver} />
                    <div className={`${styles.btnCircleTextNo} ${styles.silver}`}></div>
                    <div className={`${styles.btnCircleText} ${styles.silver}`}>
                      {tt(`bundle_pass_regular`) /* 常規 */}
                    </div>
                  </div>
                </div>
              </div>
              <div className={styles.passItemLevel}></div>
              <div className={`${styles.passItemFixedHeigh}`} style={{ position: 'relative' }}>
                <div className={styles.btnCircleBox2}>
                  <div className={styles.btnCircleWrap}>
                    <img className={styles.btnCircleGold} src={circleGolden} />
                    <div className={`${styles.btnCircleTextNo} ${styles.golden}`}></div>
                    <div className={`${styles.btnCircleText} ${styles.golden}`}>
                      {tt(`bundle_pass_luxery`) /* 特許 */}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* 右上通行證名稱 */}
        <div className={styles.bundleNameBox}>
          <div className={styles.bundleName}>
            <FitText>{product?.name}</FitText>
          </div>
          <animated.div className={styles.passLimitTime} style={{ ...aniFlashStyles }}>
            {/* <FitText> */}
            {tt(`bundle_pass_expiry_date`) /* 剩餘時間 */}
            &nbsp;&nbsp;
            <Countdown
              key={product?.pass_expired_at}
              date={moment.utc(product?.pass_expired_at).local()}
              zeroPadTime={2}
              renderer={props => {
                return (
                  <span>
                    {props.formatted.days} {tt('iap_pass_expired_days')} {props.formatted.hours}:
                    {props.formatted.minutes}
                  </span>
                );
              }}
            />
            {/* <span className={styles.expired_at}>{moment.utc(product?.pass_expired_at).local().format('YYYY.M.D')}</span> */}
            {/* </FitText> */}
          </animated.div>
        </div>

        <div className={styles.passPriceText}>
          {`${product?.iapData.currency} ${
            product?.iapData?.localizedPrice.startsWith('$')
              ? product?.iapData?.localizedPrice.substr(1)
              : product?.iapData?.localizedPrice
          }`}
        </div>

        {/* 等級條 */}
        <div className={styles.levelBox}>
          <div className={styles.pass_level}>{integerToRoman(product?.pass_level)}</div>
          <div>
            <div className={styles.levelTextBox}>
              <div className={styles.levelText2}>{product?.energy_charged_this_level}/100</div>
            </div>
            <div className={styles.levelBarBox}>
              <div className={styles.levelBarOurline}>
                <div
                  className={styles.levelBarfill}
                  style={{
                    width: `calc(${product?.energy_charged_this_level} / 100 * 100%)`,
                  }}
                ></div>
              </div>
            </div>
          </div>
          <div>{/* <img className={styles.icon_upgrade} src={icon_upgrade}/> */}</div>
        </div>

        <ClickEffect
          enabled={product?.can_collect ? true : false}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            collectProduct();
          }}
        >
          <div className={`${styles.highlightCircleBox}`}>
            <img className={`rotation_highlightCircle`} src={highlightCircle} />
            <div className={styles.btnText} style={{ opacity: product?.can_collect ? 1 : '0.75' }}>
              {product?.can_collect ? tt(`collect`) /*領取*/ : tt(`claimed`) /*已領取*/}
            </div>
          </div>
        </ClickEffect>

        <ClickEffect
          enabled={product?.can_buy ? true : false}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            buyProduct();
          }}
        >
          <animated.div
            className={styles.shopBtn}
            style={{
              ...aniStyles,
              transform: aniStyles._x
                .to({
                  range: [0, 0.5, 1],
                  output: [1, 1.1, 1],
                })
                .to(value => {
                  return `translate(0, 0) scale(${value})`;
                }),
            }}
          >
            <img className={styles.shopBtnImg} src={shopBtn} />
            <div className={styles.shopBtnText}>
              {product?.can_buy ? tt(`trade`) /*交易*/ : tt(`transacted`) /*已交易*/}
            </div>
          </animated.div>
        </ClickEffect>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            navigate(`/user/backpack`);
          }}
        >
          <div className={styles.linkProps}>
            <img className={`rotation_1`} src={iconPropsWhite} />
            <span>{tt(`to_treasury`) /* 往庫房 */}</span>
          </div>
        </ClickEffect>
      </div>

      <div className={`tabBar ${styles.tabBar_shadow}`}>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundleorders');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`bank`) /* 錢莊 */}</div>
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/monthlycard');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`monthly_card`) /* 月卡 */}</div>
            {DCContext.bundle_categories?.[1].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlepass');
          }}
        >
          <div className={`tab active`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`activity_pass`) /* 通行證 */}</div>
            {DCContext.bundle_categories?.[2].can_collect && (
              // <div className={`tabRedSpot`}></div>
              <div className={`tabHalo`}></div>
            )}
          </div>
        </ClickEffect>
        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            navigate('/store/bundlegift');
          }}
        >
          <div className={`tab`} style={{ width: '23%' }}>
            <div className={`tabText1`}>{tt(`gift_pack`) /* 禮包 */}</div>
          </div>
        </ClickEffect>
      </div>

      <PopupMessagesIcon category={4} />

      <Navigator
        navi={{
          back: {
            spot: 'home',
          },
        }}
      />

      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </IbgDiv>
  );
};

/*
購買後可獲得豪華通行證的獎勵        
{product?.can_buy && (
  tt(`bundle_pass_luxery_description`)
)}

每消耗100能量，可使通行證等級增加一級
{tt(`bundle_pass_level_up_description`)}          
*/
