import iconEnergy from 'assets/img/iconEnergy.png';
import iconPublicity from 'assets/img/iconPublicity.png';
import iconTelegraph from 'assets/img/iconTelegraph.png';
//
import bgMissionBigVictory from 'assets/img2/bgMissionBigVictory.png';
import bgMissionTinyVictory from 'assets/img2/bgMissionTinyVictory.png';
import bgMissionFail from 'assets/img2/bgMissionFail.png';
import bgMissionFailChain from 'assets/img2/bgMissionFailChain.png';

import { Attackresult_fail } from './Attackresult_fail';

export const Attackresult = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  //const GameDataContext = useGameDataContext();
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  //
  let navigate = useNavigate();
  const [victoryStatusData, setVictoryStatusData] = useState();
  //const [spoils, setSpoils] = useState(); //合併組合包後戰利品
  const [hasBundle, setHasBundle] = useState(false);

  //這裡的是指本單次攻城結果，與 city.spoil_reference 是兩件事
  const VictoryStatusCfg = {
    /* 攻擊結果不會有 -1 的狀況
    "-1": {
      text: "未攻擊過",
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain
    },
    */
    0: {
      text: tt(`close_defeat`) /*惜敗*/,
      bgImg: bgMissionFail,
      fgImg: bgMissionFailChain,
    },
    1: {
      text: tt(`close_victory`) /*險勝*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
    },
    2: {
      text: tt(`victory`) /*勝利*/,
      bgImg: bgMissionTinyVictory,
      fgImg: null,
    },
    3: {
      text: tt(`total_victory`) /*大獲全勝*/,
      bgImg: bgMissionBigVictory,
      fgImg: null,
    },
  };

  useEffect(() => {}, []);

  useEffect(() => {
    if (!DCContext.attackResult) {
      return;
    }

    console.log('[Attackresult] DCContext.attackResult', DCContext.attackResult);

    setVictoryStatusData(VictoryStatusCfg[DCContext.attackResult.spoil_reference]);

    //合併戰利品
    // let tmpSpoils = DCContext.combineCityspoils(DCContext.attackResult.city_spoils);
    // console.log("[Attackresult] tmpSpoils", tmpSpoils);
    // setSpoils(tmpSpoils);

    if (
      DCContext.attackResult.collected_items?.items?.length ||
      DCContext.attackResult.collected_items?.actors?.length
    ) {
      setHasBundle(true);
    }

    //勝利或失敗音效
    if (DCContext.attackResult.sound_effect) {
      //console.log("[Attackresult] DCContext.playSound", DCContext.attackResult.sound_effect);
      DCContext.pauseMusic();
      DCContext.playSound(DCContext.attackResult.sound_effect, () => {
        //DCContext.playMusic(`${DCContext.userProfile.music}`);
        DCContext.playMusic(iConfig.battleMusic);
      });
    }
  }, [DCContext.attackResult]);

  useEffect(() => {
    if (!hasBundle || !victoryStatusData) {
      return;
    }

    showModal_BRA({
      params: {
        title: victoryStatusData.text,
        bundleItems: DCContext.attackResult.collected_items,
        backgroundColor: 'rgb(0,0,0,0)',
        disableFirstSound: true, //獎勵第一頁不播放音效，此畫面要播放勝利或失敗音效
        callback: () => {
          callbackModal_BRA(null, null);
        },
      },
    });
  }, [hasBundle, victoryStatusData]);

  const goNext = () => {
    //console.log("[Attackresult] goNext");

    // 掃蕩：不進劇情、也不回大地圖，直接回到剛才那座城的任務頁，讓玩家可以連續掃蕩。
    //
    // 這裡一定要先清掉 attackResult (回報)：
    //   1. 它是 useLocalStorage，不清會一直留著 → 任何城鎮的任務頁一掛載就被判定成
    //      「有掃蕩結果」，直接彈回本頁，導致所有城的「任務」鍵都跳掃蕩獎勵。
    //   2. 掃蕩的 payload 帶 success:true，回大地圖時 Attackmap 會照「攻打成功」
    //      把鏡頭移到 cities[idx+1]，於是跑到下一關 (基隆) 的未開啟頁。
    // city_id 由 server 的 attack payload 帶回 (player_channel new_attack, battle:false)。
    //
    // 用 replace 而不是 push (回報：掃蕩完回到任務頁後，按返回會跳出戰敗畫面)：
    // Attackcondition 的 <Navigator /> 走預設設定，back 對應 spotRoutes.back = -1，
    // 也就是「瀏覽器上一頁」而不是固定回大地圖。若這裡用 push，history 會疊成
    //   attackmap → attackcondition/N → attackresult → attackcondition/N
    // 按返回就退回 attackresult；而此時 attackResult 已被清成 null，
    // victoryStatusData 是 undefined，畫面就渲染成戰敗版面。
    // 配合 Attackcondition 導向本頁時也用 replace，整趟掃蕩不會在 history 留下痕跡，
    // history 維持 attackmap → attackcondition/N，返回鍵就正確回到大地圖。
    if (DCContext.attackResult?.sweep) {
      const sweptCityId = DCContext.attackResult.city_id;
      DCContext.setAttackResult(null);
      navigate(sweptCityId ? `/attacks/attackcondition/${sweptCityId}` : '/attacks/attackmap', {
        replace: true,
      });
      return;
    }

    if (!DCContext.attackResult || DCContext.attackResult?.spoil_reference === 0) {
      //攻擊失敗，返回地圖頁
      navigate('/attacks/attackmap');
    } else {
      //攻擊成功，前往劇情頁
      navigate(`/story/after_attack/${DCContext.newAttackR?.city?.id}`);
    }
  };

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[ChatBundle] callbackPlayerModal', type, e);

    goNext();

    // setModalProps_BRA((prevState)=>({
    // 	...prevState,
    // 	visible: false
    // }));
  };

  const aniStyles = useSpring({
    from: { opacity: 1 },
    to: { opacity: 0 },
    //loop: { reverse: true },
    //reverse: true,
    delay: 2000,
    config: {
      duration: 1000,
    },
  });

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox} style={{}}>
        <div className={styles.bgBox}>
          <img className={styles.bgImg} src={victoryStatusData?.bgImg} />
          {/* 顯示解鎖動畫 */}
          {DCContext.attackResult?.first_success ? (
            <animated.img
              className={styles.bgImg_chain}
              src={bgMissionFailChain}
              style={aniStyles}
            />
          ) : (
            <img className={styles.bgImg_chain} src={victoryStatusData?.fgImg} />
          )}
        </div>

        {hasBundle && (
          <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
        )}

        {!hasBundle && (
          <div
            className={styles.clickSensorBox}
            onClick={() => {
              goNext();
            }}
          >
            <Attackresult_fail title={victoryStatusData?.text} />

            {/* <div className={`${styles.resultTitleBox} ${styles.middle}`}>{victoryStatusData?.text}</div> */}

            {/* {spoils?.Others && (
          <div className={styles.winPrizesBar} style={{backgroundImage: `url(${bgPrizesBar})`}}>
            {Object.keys(spoils?.Others).map((key)=>{
              let el = spoils?.Others[key];
              return (
                <div key={key} className={styles.prizeItem}>
                  <img className={styles.bgPrizeItem} src={bgPropsHole_w}/>
                  <Iimg className={styles.prizeImg} src={el.image} transition={false} onReady={()=>{}} />
                  <div className={styles.prizeQuantity}>{el.quantity}</div>
                </div>
              );
            })}
          </div>
          )} */}

            {/* <div className={styles.prizes2TextBox}>
            {spoils?.Media && (
              <div className={styles.prizes2TextItem}>
                <div className={styles.prizes2TextItemText}>{spoils?.Media?.quantity}</div>
                <img className={styles.prizes2TextItemIcon} src={iconPublicity} />
              </div>
            )}
            {spoils?.Fund && (
              <div className={styles.prizes2TextItem}>
                <div className={styles.prizes2TextItemText}>{spoils?.Fund?.quantity}</div>
                <img className={styles.prizes2TextItemIcon} src={iconFunds} />
              </div>
            )}
          </div> */}

            {/* 請按任意處前往下一關 */}
            {/* <div className={styles.nextStepText}>{tt(`click_to_next_mission`)}</div> */}
          </div>
        )}
      </div>

      <Navigator
        navi={{
          back: {
            spot: 'home',
            show: false,
          },
        }}
      />
    </div>
  );
};
