import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import iConfig from 'iConfig';
import styles from './MoveForceConfirm.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnGrey } from 'component/BtnGrey';
//
import popup_btn_bg from 'assets/img2/popup_btn_bg.png';
import iconEnergyPlus from 'assets/img/iconEnergyPlus.png';

export const MoveForceConfirm = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  //console.log("[MoveForceConfirm] props", props);

  const [moveData, setMoveData] = useState();
  const [errorData, setErrorData] = useState();

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[MoveForceConfirm] channel player 未連線');
      return;
    }

    if (!props.selectedCity) {
      return;
    }

    console.log('[MoveForceConfirm] channel player 已連線');

    DCContext.wish_to_move_to_city(props.selectedCity.id);
  }, [ChannelContext.channels[DCContext.playerChannelTopic], props.selectedCity]);

  //wish_to_move_to_city
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},wish_to_move_to_city`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log('[MoveForceConfirm] wish_to_move_to_city', { ..._res });

    if (_res.status == 'error') {
      setErrorData(_res.error);
    } else if (_res.status == 'ok') {
      setMoveData(_res.payload);
    } else {
      console.log('error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},wish_to_move_to_city`]?.uuid]);

  const clickConfirm = () => {
    console.log('[MoveForceConfirm] clickConfirm');

    if (moveData) {
      DCContext.move_to_city(props.selectedCity.id);
    }

    if (props.callback) {
      props.callback();
    }
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={`${styles.contentBox} modalContentBox`}>
          <div className={`${styles.descriptionBox} modalDescriptionBox`}>
            {
              moveData
                ? tt(`main_force_move_confirm`, {
                    energy: moveData?.energy,
                    union_name: DCContext?.myUnion?.name,
                    time: moveData?.time,
                    city_name: props.selectedCity.name,
                  }) /*確定要消耗{{energy}}能量將{{union_name}}的主力遷移至{{city_name}}？遷移將於{{time}}分鐘後完成。*/
                : errorData?.message
              // tt(`main_force_move_not_allowed`, {
              //   city_name: props.selectedCity.name
              // })
              /*無法遷移主力到{{city_name}}*/
            }
          </div>

          <div className={styles.foorBox}>
            <BtnGrey
              text={tt('confirm')}
              callback={() => {
                clickConfirm();
              }}
            />
          </div>
        </div>
      </div>

      {/* modal 外部按鈕 */}
      <div className={styles.outBoxTop}>
        <div className={styles.outBtnL}>
          <img src={iconEnergyPlus} className={`${styles.outBtnIcon} ${styles.icon_unionQuit}`} />
          {DCContext.userProfile?.energy}{' '}
          <span style={{ color: '#60c0bd' }}>(-{moveData?.energy})</span> /{' '}
          {DCContext.getUser_maxEnergyByLevel()}
        </div>
        {/* <div className={styles.outBtnR}>
          聯盟頻道
          <img src={icon_unionChannel} className={`${styles.outBtnIcon} ${styles.icon_unionChannel}`}/>
        </div> */}
      </div>
    </div>
  );
};
