import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { FitText } from 'lib/FitText';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './EquipSkill.module.scss';
//
import { ClickEffect } from 'componentx/ClickEffect';
import { Imodal } from 'componentx/Imodal';
import { EquipSkillSwitch } from 'component/EquipSkillSwitch';
//
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';

export const EquipSkill = props => {
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const skillData = props.skillData;
  const active_skills = props.active_skills;

  /* modal */

  const [modalProps, setModalProps] = useState({
    ratio: 0.82,
    destroyOnClose: true,
    visible: false,
  });

  const showModal = exProps => {
    //客戶要求只有一個技能也可以點開切換
    // if (active_skills.length <= 1){
    //   console.log("[EquipSkill] active_skills.length", active_skills.length);
    //   return;
    // }

    setModalProps(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal = (type, e) => {
    console.log('[EquipSkill] callbackModal', type, e);
    setModalProps(prevState => ({
      ...prevState,
      visible: false,
    }));

    switch (type) {
      case 'pickSkill':
        DCContext.updateActor(e);
        break;
    }
  };

  //update_actor 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]) {
      return;
    }

    //console.log("[EquipSkill] player,update_actor", {...DCContext.msgRes});

    //todo error處理

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},update_actor`];
      return { ...prevState };
    });
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},update_actor`]?.uuid]);

  return skillData ? (
    <>
      <div className={styles.weapon}>
        <div className={styles.weaponCont}>
          <div className={styles.weaponAttrBoxOutLine}></div>

          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={e => {
              showModal();
            }}
          >
            <Iimg
              className={styles.weaponIcon}
              src={skillData.image}
              transition={false}
              onReady={() => {}}
            />
          </ClickEffect>

          <div className={styles.weaponAttrBoxOutLine}>
            <div className={styles.weaponAttrBox}>
              <div className={styles.weaponAttr1}>
                <img className={styles.iconUpgrade} src={null} />
              </div>
              {/* 客戶要求先隱藏 */}
              {/* <div className={styles.weaponAttr2}>{skillData.level}</div> */}
            </div>
          </div>
        </div>
        <FitText className={styles.weaponName}>{skillData.name}</FitText>
      </div>

      <Imodal {...modalProps} callback={callbackModal}>
        <EquipSkillSwitch
          actor={props.actor}
          active_skills={active_skills}
          callback={callbackModal}
        />
      </Imodal>
    </>
  ) : (
    <></>
  );
};
