export const Medals = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  //
  const medalsRowRef = useRef();
  const [medalsData, setMedalsData] = useState();
  const mRefs = useRef({});
  //
  const [catKey, setCatKey] = useState(props.catKey || '1v1');
  //
  const opacityLocked = 0.3;
  const [upgradeMedal, setUpgradeMedal] = useState();
  //
  const [pageTransited, setPageTransited] = useState();
  //
  const [rankDiff, setRankDiff] = useState(0);
  const [scoreDiff, setScoreDiff] = useState(0);

  useEffect(() => {
    console.log('[Medals] props', props);

    return () => {};
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Medals] channel player 未連線');
      return;
    }

    if (props.getPreviousRecord && catKey == undefined) {
      console.log('[Medals] catKey', catKey);
      return;
    }

    console.log('[Medals] channel player 已連線, catKey', catKey);

    DCContext.getMedals({ previous_record: props.getPreviousRecord });
  }, [ChannelContext.channels[DCContext.playerChannelTopic], props.getPreviousRecord, catKey]);

  useEffect(() => {
    if (!DCContext.medals) {
      return;
    }

    console.log('[Medals] DCContext.medals', DCContext.medals);
    setMedalsData(DCContext.medals);
  }, [DCContext.medals]);

  useEffect(() => {
    if (!medalsData || !pageTransited) {
      return;
    }
    console.log('[Medals] medalsData', medalsData, catKey);

    //捲軸定位
    scrollToMedalById(medalsData[catKey].medal_id);

    //debug
    //scrollToMedalById(10);

    //是否有升級特效
    if (
      medalsData.previous_record[catKey] &&
      medalsData.previous_record[catKey].medal_id != medalsData[catKey].medal_id
    ) {
      setUpgradeMedal(medalsData.previous_record[catKey]);
    } else {
      setUpgradeMedal();
    }

    //排名數字變化
    if (medalsData.previous_record?.[catKey]?.rank) {
      setRankDiff(medalsData[catKey].rank - medalsData.previous_record[catKey].rank);
    } else {
      setRankDiff(0);
    }

    //分數變化
    if (medalsData.previous_record?.[catKey]?.score != null) {
      setScoreDiff(medalsData[catKey].score - medalsData.previous_record[catKey].score);
    } else {
      setScoreDiff(0);
    }
  }, [medalsData, catKey, pageTransited]);

  useEffect(() => {
    if (!upgradeMedal) {
      return;
    }

    // aniApi_medalFade.start({
    //   loop: false,
    //   to: [
    //     {opacity: 1},
    //     {filter: "drop-shadow(0 0 3em rgba(255, 255, 255, 1))"},
    //     {filter: "drop-shadow(0 0 3em rgba(255, 255, 255, 0))"},
    //   ],
    //   config: {
    //     duration: 700,
    //   },
    //   onRest: ()=>{
    //   }
    // });
  }, [upgradeMedal]);

  const scrollToMedalById = mid => {
    // console.log("[Medals] scrollToMedalById targetMedal", {
    //   offsetWidth: mRefs.current[mid].offsetWidth,
    //   offsetLeft: mRefs.current[mid].offsetLeft,
    // }, mRefs.current[mid]);

    //console.log("[Medals] scrollToMedalById container width", medalsRowRef.current.offsetWidth);

    let scrollLength =
      mRefs.current[mid].offsetLeft -
      medalsRowRef.current.offsetWidth / 2 +
      mRefs.current[mid].offsetWidth / 2;

    medalsRowRef.current.scrollTo(scrollLength, 0);
  };

  const changeCat = _catKey => {
    //提前隱藏 highlight
    setUpgradeMedal();

    setCatKey(_catKey);
  };

  //點擊晉升獎勵 = 點擊最高可領取牌位
  const clickUpgradeRewards = () => {
    let tmpIdx = -1;
    medalsData?.medals?.map((o, idx) => {
      if (o.score <= medalsData[catKey].score) {
        tmpIdx = idx;
      }
    });

    console.log('[Medals] clickUpgradeRewards', tmpIdx);
    if (tmpIdx >= 0) {
      showModal_MedalBundle({ params: { selectedIdx: tmpIdx } });
    }
  };

  /* animation */

  // const [aniStyles_medalFade, aniApi_medalFade] = useSpring(() => ({
  //   opacity: opacityLocked,
  //   filter: "drop-shadow(0 0 3em rgba(255, 255, 255, 0))"
  // }));

  const aniStyles_medalFade = useSpring({
    loop: false,
    to: [
      { opacity: 1 },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 1)) drop-shadow(0 0 2em rgba(255, 255, 255, 1))',
      },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 0)) drop-shadow(0 0 2em rgba(255, 255, 255, 0))',
      },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 1)) drop-shadow(0 0 2em rgba(255, 255, 255, 1))',
      },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 0)) drop-shadow(0 0 2em rgba(255, 255, 255, 0))',
      },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 1)) drop-shadow(0 0 2em rgba(255, 255, 255, 1))',
      },
      {
        filter:
          'drop-shadow(0 0 1em rgba(255, 255, 255, 0)) drop-shadow(0 0 2em rgba(255, 255, 255, 0))',
      },
    ],
    config: {
      duration: 700,
    },
    onRest: () => {},
  });

  /* modal */

  const [modalProps_MedalBundle, setModalProps_MedalBundle] = useState({
    ratio: 0.7,
    destroyOnClose: true,
    visible: false,
  });

  const showModal_MedalBundle = exProps => {
    setModalProps_MedalBundle(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_MedalBundle = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_MedalBundle(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return !medalsData?.medals || !catKey ? (
    <></>
  ) : (
    <IbgDiv
      className={styles.contentBox}
      src={bgClockSilver}
      transition={true}
      onReady={() => {}}
      onTransited={() => {
        setPageTransited(true);
      }}
    >
      <div className={styles.contBox}>
        <div className={styles.titleRow}>
          <div className={styles.titleBox}>
            <div className={styles.titleText}>{tt(`current_score`) /* 當前積分 */}</div>
            <div className={styles.titleNumText}>
              {medalsData.previous_record?.[catKey]?.score != null ? (
                <CountUp
                  prefix=""
                  preserveValue={true}
                  start={medalsData.previous_record[catKey].score}
                  end={medalsData?.[catKey].score}
                  delay={1}
                />
              ) : (
                medalsData?.[catKey].score
              )}

              {scoreDiff !== 0 && (
                <span className={scoreDiff < 0 ? styles.diffColor_sliver : styles.diffColor_golden}>
                  ({Math.abs(scoreDiff)}
                  {scoreDiff < 0 ? '↓' : '↑'})
                </span>
              )}
            </div>
          </div>
          <div className={styles.titleBox}>
            <div className={styles.titleText}>{tt(`total_ranking`) /* 總排名 */}</div>
            <div className={styles.titleNumText}>
              {medalsData.previous_record?.[catKey]?.rank ? (
                <CountUp
                  prefix=""
                  preserveValue={true}
                  start={medalsData.previous_record[catKey].rank}
                  end={medalsData?.[catKey].rank}
                  delay={1}
                />
              ) : (
                medalsData?.[catKey].rank
              )}

              {rankDiff !== 0 && (
                <span className={rankDiff > 0 ? styles.diffColor_sliver : styles.diffColor_golden}>
                  ({Math.abs(rankDiff)}
                  {rankDiff > 0 ? '↓' : '↑'})
                </span>
              )}
            </div>
          </div>
        </div>

        <div className={styles.medalsScrollView}>
          <div ref={medalsRowRef} className={styles.medalRow}>
            <div className={styles.medalRowInline}>
              {medalsData?.medals?.map((item, idx) => {
                let style = {
                  opacity: item.id > medalsData?.[catKey].medal_id ? opacityLocked : 1,
                };
                if (upgradeMedal && item.id == medalsData[catKey].medal_id) {
                  style = aniStyles_medalFade;
                }

                return (
                  <animated.div
                    key={item.id}
                    ref={tmpRef => {
                      mRefs.current[item.id] = tmpRef;
                    }}
                    className={styles.medalBox}
                    style={style}
                  >
                    <div className={styles.medalNum}>&nbsp;</div>
                    <div className={styles.medalName}>&nbsp;</div>
                    <div className={styles.medalImgBox}>
                      <ClickEffect
                        effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                        onClick={() => {
                          showModal_MedalBundle({ params: { selectedIdx: idx } });
                        }}
                      >
                        <Iimg
                          className={styles.medalImg}
                          src={item.image}
                          transition={false}
                          onReady={() => {}}
                        />
                      </ClickEffect>
                    </div>
                    <div className={styles.medalName}>
                      {catKey == 'Union' ? item.union_name : item.player_name}
                    </div>
                    <div className={styles.medalNum}>{item.score}</div>
                  </animated.div>
                );
              })}
            </div>
          </div>
        </div>

        {/* <div className={styles.medalRowShadowL}></div>
        <div className={styles.medalRowShadowR}></div> */}

        <div className={styles.footRow}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              clickUpgradeRewards();
            }}
          >
            <div className={styles.footBox}>
              <div className={styles.footImgBox}>
                <img className={styles.footImg} src={icon_rankingUpgrade} />
              </div>
              <div className={styles.footText}>{tt(`p_upgrade_rewards`) /* 晉升獎勵 */}</div>
            </div>
          </ClickEffect>

          <div className={styles.footBox}>
            <div className={styles.upgradeText}>
              {upgradeMedal && <>{tt(`p_upgrade`) /*晉升*/}</>}
            </div>
            <div className={styles.footText}>&nbsp;</div>
          </div>

          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={e => {
              DCContext.setShowRanking({ sortCat: '1v1' });
            }}
          >
            <div className={styles.footBox}>
              <div className={styles.footImg}>
                <img className={styles.footImg} src={icon_ranking} />
              </div>
              <div className={styles.footText}>{tt(`ranking`) /* 排行榜 */}</div>
            </div>
          </ClickEffect>
        </div>
      </div>

      {/* <ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={() => {changeCat(1);}}> */}
      <div className={styles.medalCatBox}>
        <MedalTypeSwitcher
          catKey={catKey}
          callback_catKey={_catKey => {
            changeCat(_catKey);
          }}
        />
      </div>
      {/* </ClickEffect> */}

      <Navigator
        navi={{
          back: props.callback_close ? { callback: props.callback_close } : { spot: 'home' },
        }}
      />

      {/* 晉陞獎勵 */}
      <Imodal {...modalProps_MedalBundle} callback={callbackModal_MedalBundle}>
        <MedalBundle
          reference_type={catKey}
          medal_catData={medalsData?.[catKey]}
          medals={medalsData?.medals}
          {...modalProps_MedalBundle.params}
          // catKey={catKey}
          // data={medalsData?.medals}
          // currentMedalId={medalsData?.[catKey].medal_id}
          // //collectedMedalId={medalsData?.collected[catKey]}
          // medalCollected_callback={()=>{
          //   DCContext.getMedals({params:{after_union_battle: true}});
          // }}
        />
      </Imodal>
    </IbgDiv>
  );
};

