import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal, Popover } from 'antd';
import { animated, useSpring } from '@react-spring/web';
import { find as lodash_find, filter as lodash_filter, orderBy as lodash_orderBy } from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { ClickEffect } from 'componentx/ClickEffect';
//
import { Iimg } from 'componentx/Iimg';
import iConfig from 'iConfig';
import styles from './Bundle.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { Imodal } from 'componentx/Imodal';
import { BundleReceivedAlert } from 'component/bundle/BundleReceivedAlert';
//
import bgSkillInfo from 'assets/img2/bgSkillInfo.png';
import icon_circleCheck from 'assets/img2/icon_circleCheck.png';
import btnLeft from 'assets/img2/actor_pools/btnLeft.png';
import btnRight from 'assets/img2/actor_pools/btnRight.png';
import btnLeft_active from 'assets/img2/actor_pools/btnLeft_active.png';
import btnRight_active from 'assets/img2/actor_pools/btnRight_active.png';
import arrowL from 'assets/img2/icon_arrow_left.png';
import arrowR from 'assets/img2/icon_arrow_right.png';

export const MedalBundle = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();
  //通用
  const [reference_type, setReference_type] = useState(props.reference_type);
  const [reference_id, setReference_id] = useState(props.reference_id);
  const [items, setItems] = useState(props.bundle_items);
  const [collected, setCollected] = useState(props.collected); //已領取
  //牌位專用
  const [selectedIdx, setSelectedIdx] = useState();
  const [medal, setMedal] = useState();
  const [unCollectedBundles, setUnCollectedBundles] = useState(0); //有多少 bundle 未領
  const [canCollect, setCanCollect] = useState(false); //積分達到可領取

  useEffect(() => {
    console.log(`[MedalBundle] props`, props);
  }, []);

  useEffect(() => {
    setSelectedIdx(props.selectedIdx);
  }, [props.selectedIdx]);

  useEffect(() => {
    setMedal(props.medals[selectedIdx]);
  }, [props.medals, selectedIdx]);

  useEffect(() => {
    if (!medal || !props.medal_catData) {
      return;
    }

    console.log('[MedalBundle] medal', medal);
    console.log('[MedalBundle] props.medal_catData', props.medal_catData);

    setItems(medal?.bundle?.[reference_type]);
    setReference_id(medal?.id);

    //積分達到，可領
    setCanCollect(props.medal_catData.score >= medal.score ? true : false);

    //是否已領
    setCollected(props.medal_catData.collected.includes(medal.id) ? true : false);

    //有任何可領未領
    let tmpUnReceived = 0;
    props.medals.map((o, idx) => {
      if (props.medal_catData.score >= o.score && !props.medal_catData.collected.includes(o.id)) {
        tmpUnReceived += 1;
      }
    });
    console.log('[MedalBundle] tmpUnReceived', tmpUnReceived);
    setUnCollectedBundles(tmpUnReceived);
  }, [medal, props.medal_catData]);

  const changeMedal = p => {
    let newIdx = selectedIdx + p;
    if (newIdx >= props.medals.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = props.medals.length - 1;
    }
    console.log('[MedalBundle] newIdx', newIdx);

    setSelectedIdx(newIdx);
  };

  //領取單個牌位獎勵
  const doCollectBundle = () => {
    console.log('[MedalBundle] doCollectBundle', reference_type, reference_id);

    DCContext.collectBundle({
      reference_type: reference_type, //1v1 3v3 Union
      reference_id: reference_id,
    });
  };

  //collect_bundle 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundle`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[MedalBundle] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundle error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundle`]?.uuid]);

  //全部領取
  const doCollectBundles = () => {
    console.log('[MedalBundle] doCollectBundles');

    DCContext.collectBundles({
      reference_type: reference_type, //1v1 3v3 Union
    });
  };

  //collect_bundles 結果
  useEffect(() => {
    let _key = `${DCContext.playerChannelTopic},collect_bundles`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    console.log(`[MedalBundle] ${_key}`, { ..._res });

    if (_res.status == 'error') {
    } else if (_res.status == 'ok') {
      //顯示已領取狀態 & popup
      showModal_BRA({
        params: {
          title: tt(`bundle_receive_congratulations`) /* 恭喜獲得 */,
          showBg: true,
          bundleItems: _res.payload.collected_items,
          callback: () => {
            callbackModal_BRA(null, null);
          },
        },
      });
    } else {
      console.log('collect_bundles error 其他錯誤');
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},collect_bundles`]?.uuid]);

  /* modal BundleReceivedAlert */

  const [modalProps_BRA, setModalProps_BRA] = useState({
    destroyOnClose: true,
    //ratio: 0.6,
    fullscreen: true,
    opacityBg: true,
    shadow: false,
    maskClosable: false,
    visible: false,
  });

  const showModal_BRA = exProps => {
    setModalProps_BRA(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_BRA = (type, e) => {
    console.log('[MedalBundle] callbackPlayerModal', type, e);

    setModalProps_BRA(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  return (
    <div className={styles.rootContainer} style={{}}>
      <div className={styles.mainBox}>
        <div className={styles.contBox}>
          <div className={styles.headBox}>
            <div className={styles.nameBox}>
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={() => {
                  changeMedal(-1);
                }}
              >
                <div className={styles.nameArrowL}>
                  <img src={arrowL} className={styles.arrowImg} />
                </div>
              </ClickEffect>
              <div className={styles.catName}>
                {reference_type == 'Union' ? medal?.union_name : medal?.player_name}
                {/* {`(${reference_type})`} */}
              </div>
              <ClickEffect
                effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                onClick={() => {
                  changeMedal(1);
                }}
              >
                <div className={styles.nameArrowR}>
                  <img src={arrowR} className={styles.arrowImg} />
                </div>
              </ClickEffect>
            </div>
          </div>

          <div className={styles.bundleItemsBox}>
            <img className={styles.bgSkillInfo} src={bgSkillInfo} />
            <div className={styles.itemsBox}>
              {items?.map((tmpItem, idx) => {
                const descriptionPop = (
                  <div
                    className={`popover-description`}
                    dangerouslySetInnerHTML={{ __html: tmpItem.description }}
                  ></div>
                );

                return (
                  <div key={idx} className={styles.itemBox}>
                    <Popover
                      overlayInnerStyle={{ backgroundColor: 'unset' }}
                      content={descriptionPop}
                      title={tmpItem.name}
                      placement="rightTop"
                      trigger="click"
                      overlayClassName={styles.popOver}
                    >
                      <div className={styles.selectedItemBox}>
                        <Iimg
                          className={styles.selectedPieceImg}
                          src={tmpItem.image}
                          transition={false}
                          onReady={() => {}}
                        />
                        {collected && (
                          <img className={styles.icon_circleCheck} src={icon_circleCheck} />
                        )}
                        <div className={styles.selectedItemQuantity}>{tmpItem.quantity}</div>
                      </div>
                    </Popover>
                    {/* <div className={styles.selectedItemName}>{tmpItem.name}</div> */}
                  </div>
                );
              })}
            </div>
          </div>

          <div className={styles.footBox}></div>
        </div>

        {canCollect && (
          <ClickEffect
            enabled={!collected}
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              doCollectBundle();
            }}
          >
            <div className={`${styles.leftBtnBox} ${collected ? '' : styles.active}`}>
              <img className={styles.btnImg} src={collected ? btnLeft : btnLeft_active} />
              <div className={styles.leftBtnText}>
                {collected ? tt(`claimed`) /* 已領取 */ : tt(`collect`) /* 領取 */}
              </div>
            </div>
          </ClickEffect>
        )}

        <ClickEffect
          enabled={unCollectedBundles > 0 ? true : false}
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={() => {
            doCollectBundles();
          }}
        >
          <div className={`${styles.rightBtnBox} ${unCollectedBundles > 0 ? styles.active : ''}`}>
            <img
              className={styles.btnImg}
              src={unCollectedBundles > 0 ? btnRight_active : btnRight}
            />
            <div className={styles.rightBtnText}>
              {
                unCollectedBundles > 0
                  ? tt(`claim_all`) /* 全部領取 */
                  : tt(`collected_all`) /* 全部已領取 */
              }
            </div>
          </div>
        </ClickEffect>
      </div>

      <Imodal {...modalProps_BRA} callback={callbackModal_BRA}>
        <BundleReceivedAlert {...modalProps_BRA.params} callback={callbackModal_BRA} />
      </Imodal>
    </div>
  );
};
