import React, { useContext, useState, useEffect, useRef } from 'react';
//
import iConfig from 'iConfig';
//
import { apiUserLogin, apiVisitorLogin, apiUserLogout, apiUserRegister } from 'lib/api';
import { reloadPhrases } from 'i18n_backend';

const UserContext = React.createContext();

export const UserContextProvider = ({ children }) => {
  const defaultVaules = {};

  //user prop
  const [userId, setUserId] = useState();
  const [userToken, setUserToken] = useState();
  const [greeting, setGreeting] = useState();
  const [account, setAccount] = useState();
  const [password, setPassword] = useState();
  //login
  const [loginResult, setLoginResult] = useState();
  const [logoutResult, setLogoutResult] = useState();
  const [registerResult, setRegisterResult] = useState();
  //
  const login_api_processing = useRef(false); //是否正在呼叫 log_in

  useEffect(() => {
    let tmpUserId = getUserId();
    let tmpUserToken = getUserToken();
    //console.log("tmpUserToken", tmpUserToken);

    if (tmpUserId && tmpUserToken) {
      setUserId(tmpUserId);
      setUserToken(tmpUserToken);
    }
  }, []);

  // register 目前無使用
  const doRegister = params => {
    setRegisterResult({
      status: '',
      message: '',
    });

    //
    apiUserRegister({
      user: {
        email: params.account,
        password: params.password,
      },
    })
      .then(res => {
        //console.log(res);

        let result = res.data;

        if (result.status == 'ok') {
          //console.log("user_token", result.data.user_token);

          setUserId(result.data.user_id);
          setUserToken(result.data.user_token);
          setGreeting(result.greeting);
          //
          setAccount(params.account);
          setPassword(params.password);

          //儲存 user token
          setUserSession(result.data.user_id, result.data.user_token, {
            account: params.account,
            user_id: result.data.user_id,
          });

          setRegisterResult({
            status: 'ok',
            message: '註冊成功',
          });
        } else {
          setRegisterResult({
            status: 'error',
            message: '註冊失敗',
            validation_errors: result.validation_errors,
          });
        }
      })
      .catch(err => {
        //console.log(err);
        setRegisterResult({
          status: 'http_error',
          error: err,
          message: '註冊發生錯誤',
        });
      });
  };

  //
  const doLogin = params => {
    if (login_api_processing.current) {
      console.log('[UserContext] log_in 執行中');
      return;
    }
    login_api_processing.current = true;

    //
    setLoginResult();

    const loginParams = {
      ...params,
      app_version: window.deviceInfo?.app_version
        ? window.deviceInfo?.app_version
        : iConfig.app_version,
    };
    if (window.iKey) {
      loginParams.key = window.iKey;
    }
    console.log('[UserContext] doLogin loginParams', loginParams);

    //
    apiUserLogin(loginParams)
      .then(res => {
        //console.log("[UserContext] login", res);

        let result = res.data;

        if (result.status == 'ok') {
          //console.log("user_token", result.data.user_token);

          setUserId(result.data.user_id);
          setUserToken(result.data.user_token);
          setGreeting(result.greeting);
          //
          //setAccount(params.account);
          //setPassword(params.password);
          setAccount(null);
          setPassword(null);

          //儲存 user token
          setUserSession(result.data.user_id, result.data.user_token, {
            //account: params.account,
            account: null,
            user_id: result.data.user_id,
          });

          // 每次登入重抓詞句，後台改字後玩家「登出再登入」就會生效 (回報)
          reloadPhrases();

          setLoginResult({
            status: 'ok',
            message: '登入成功',
            app_update: result.app_update, //none, soft ,hard
          });
        } else {
          setLoginResult({
            status: 'error',
            message: '登入失敗',
          });
        }

        login_api_processing.current = false;
      })
      .catch(err => {
        //console.log(err);
        setLoginResult({
          status: 'http_error',
          error: err,
          message: '登入發生錯誤',
        });

        login_api_processing.current = false;
      });
  };

  //無使用，已和 doLogin 合併
  const doVisitorLogin = params => {
    setLoginResult();

    //
    //apiVisitorLogin({
    apiUserLogin({
      user: {
        device_uid: params.device_uid,
        key: window.iKey,
        locale: params.locale,
        app_version: window.deviceInfo?.app_version
          ? window.deviceInfo?.app_version
          : iConfig.app_version,
      },
    })
      .then(res => {
        //console.log("[UserContext] doVisitorLogin", res);

        let result = res.data;

        if (result.status == 'ok') {
          //console.log("user_token", result.data.user_token);

          setUserId(result.data.user_id);
          setUserToken(result.data.user_token);
          setGreeting(result.greeting);
          //
          setAccount(null);
          setPassword(null);

          //儲存 user token
          setUserSession(result.data.user_id, result.data.user_token, {
            account: null,
            user_id: result.data.user_id,
          });

          // 每次登入重抓詞句，後台改字後玩家「登出再登入」就會生效 (回報)
          reloadPhrases();

          setLoginResult({
            status: 'ok',
            message: '登入成功',
            app_update: result.app_update, //none, soft ,hard
          });
        } else {
          setLoginResult({
            status: 'error',
            message: '登入失敗',
          });
        }
      })
      .catch(err => {
        //console.log(err);
        setLoginResult({
          status: 'http_error',
          error: err,
          message: '登入發生錯誤',
        });
      });
  };

  //
  const doLogout = () => {
    setLogoutResult({
      status: '',
      message: '',
    });

    //
    apiUserLogout()
      .then(res => {
        //console.log("[UserContext] logout", res);

        let result = res.data;

        if (result.status == 'ok') {
          console.log('[UserContext] logout ok');

          setUserId(null);
          setUserToken(null);
          setGreeting(null);
          //
          setAccount(null);
          setPassword(null);

          //刪除 user token
          removeUserSession();

          setLogoutResult({
            status: 'ok',
            message: '登出成功',
          });
        } else {
          setLogoutResult({
            status: 'error',
            message: '登出失敗',
          });
        }
      })
      .catch(err => {
        //console.log(err);
        setLogoutResult({
          status: 'http_error',
          error: err,
          message: '登出發生錯誤',
        });
      });
  };

  const ifLoggedIn = () => {
    return getUserToken();

    // if (userToken){
    // 	return true;
    // }

    // let tmpUserId = getUserId();
    // let tmpUserToken = getUserToken();
    // //console.log("tmpUserToken", tmpUserToken);

    // if (tmpUserId && tmpUserToken){
    // 	setUserId(tmpUserId);
    // 	setUserToken(tmpUserToken);

    // 	return true;
    // }

    // return false;
  };

  return (
    <UserContext.Provider
      value={{
        defaultVaules,
        //
        userId,
        setUserId,
        userToken,
        setUserToken,
        greeting,
        setGreeting,
        //
        account,
        setAccount,
        password,
        setPassword,
        //login
        loginResult,
        setLoginResult,
        logoutResult,
        setLogoutResult,
        registerResult,
        setRegisterResult,
        //
        doLogin,
        doVisitorLogin,
        doLogout,
        doRegister,
        ifLoggedIn,
      }}
    >
      {children}
    </UserContext.Provider>
  );
};

// Create a hook to use the APIContext, this is a Kent C. Dodds pattern
export const useUserContext = () => {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('Context must be used within a Provider');
  }
  return context;
};

// return the user data from the session storage
const getUser = () => {
  const userStr = sessionStorage.getItem('user');
  if (userStr) return JSON.parse(userStr);
  else return null;
};

// return the token from the session storage
const getUserToken = () => {
  return sessionStorage.getItem('userToken') || null;
};

const getUserId = () => {
  return sessionStorage.getItem('userId') || null;
};

// remove the token and user from the session storage
const removeUserSession = () => {
  sessionStorage.removeItem('userId');
  sessionStorage.removeItem('userToken');
  sessionStorage.removeItem('user');
};

// set the token and user from the session storage
const setUserSession = (userId, userToken, user) => {
  sessionStorage.setItem('userId', userId);
  sessionStorage.setItem('userToken', userToken);
  sessionStorage.setItem('user', JSON.stringify(user));
};
