export const Headquarter = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  const location = useLocation();
  let navigate = useNavigate();
  //
  const [nation, setNation] = useState();
  const [selectedCandidate, setSelectedCandidate] = useState();
  //
  let _mode = props.mode;
  //
  let { nation_id } = useParams();
  nation_id = parseInt(nation_id) || 0;

  /* */
  useEffect(() => {
    //console.log('[Headquarter] mode', _mode);
    //console.log('[Headquarter] nation_id', nation_id);
    //console.log('[Headquarter] DCContext.election', DCContext.election);
  }, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Headquarter] channel player 未連線');
      return;
    }

    console.log('[Headquarter] channel player 已連線');
    ///DCContext.getNations();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.nations || !nation_id) {
      return;
    }

    //console.log("[Headquarter] DCContext.nations", DCContext.nations);
    //setNationIdx(actionId);

    let tmpNation = DCContext.nations.find((el, idx) => {
      el.idx = idx; //左右箭頭切換幹部時使用
      return el.id == nation_id;
    });
    console.log('[Headquarter] nation', tmpNation);

    //debug
    //_mode = "vote";
    //tmpNation.election.can_sign_up_candidate = true;

    setNation(tmpNation);

    //debug
    //setNation(debugData.nation);
  }, [DCContext.nations, nation_id]);

  useEffect(() => {
    if (!DCContext.election) {
      return;
    }

    console.log('[Headquarter] DCContext.election', DCContext.election);

    //debug
    // DCContext.setElection((preState)=>{
    //   preState.stage = "vote"; //stage => none, sign up, vote
    //   return preState;
    // });
  }, [DCContext.election]);

  const changeNation = p => {
    let newIdx = nation.idx + p;
    if (newIdx >= DCContext.nations.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = DCContext.nations.length - 1;
    }
    //console.log("newIdx", newIdx);

    navigate(`/headquarter/${DCContext.nations[newIdx].id}`);
  };

  //參選
  const candidate_sign_up = () => {
    showModal_confirm({
      confirm: {
        /*確定要參選?*/
        message: { i18nKey: `election_run_for_confirm`, values: null, options: null },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({});
              navigate(`/strategy/${nation.id}/edit`);
            },
          },
        ],
      },
    });
  };

  //退選
  const candidate_drop_out = () => {
    showModal_confirm({
      confirm: {
        /*確定要退選?*/
        message: { i18nKey: `election_withdraw_confirm`, values: null, options: null },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({});
              DCContext.candidate_drop_out();
            },
          },
        ],
      },
    });
  };

  const goNationalStrategy = () => {
    navigate(`/strategy/${nation.id}`);
  };

  //選擇候選人
  const clickCandidate = candidate => {
    console.log('[Headquarter] clickCandidate', candidate);
    setSelectedCandidate(candidate);
  };

  useEffect(() => {
    if (!selectedCandidate) {
      return;
    }

    //console.log("[Headquarter] selectedCandidate", selectedCandidate);
  }, [selectedCandidate]);

  //投票
  const clickVote = () => {
    console.log('[Headquarter] cliakVote selectedCandidate', selectedCandidate);

    showModal_confirm({
      confirm: {
        /*確定將 ${nation.election.ballot} 票投給 ${selectedCandidate.union.chief}?*/
        message: {
          i18nKey: `election_vote_to_confirm`,
          values: {
            ballot: nation.election.ballot,
            candidate: selectedCandidate.union.chief,
          },
          options: null,
        },
        buttons: [
          {
            text: { i18nKey: `confirm` },
            callback: () => {
              callbackConfirm({});
              DCContext.cast_ballots(selectedCandidate.id);
            },
          },
        ],
      },
    });
  };

  //cast_ballots 投票結果
  useEffect(() => {
    let _key = `${DCContext.unionChannelTopic},cast_ballots`;
    let _res = DCContext.msgRes[_key]?.res;

    if (!DCContext.msgRes[_key]) {
      return;
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[_key];
      return { ...prevState };
    });

    //
    console.log(`[Headquarter] ${_key}`, { ..._res });

    if (_res.status == 'error') {
      showModal_confirm({
        confirm: {
          message: _res.error.message,
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });

      return;
    } else if (_res.status == 'ok') {
      //參選/設定政見 成功
      ///DCContext.getNations(true);
    } else {
      console.log(`[Headquarter] ${_key} error 其他錯誤`);
    }
  }, [DCContext.msgRes[`${DCContext.unionChannelTopic},cast_ballots`]?.uuid]);

  const clickChangeSeal = () => {
    navigate(`/settings/sealimage_change_nation`, {
      state: {
        returnUrl: location.pathname,
        nation: nation,
      },
    });
  };

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    console.log('callbackPlayerModal', type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Headquarter] callbackConfirm', returnParams);
    callbackModal_confirm(null, null);
  };

  // modal commander words
  const [modalProps_words, setModalProps_words] = useState({
    ratio: 0.7,
    destroyOnClose: true,
    visible: false,
  });
  const showModal_words = exProps => {
    setModalProps_words(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };
  const callbackModal_words = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_words(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  /* views */

  /* 盟主頭像 */
  const CommanderPhoto = () => {
    return (
      <div className={styles.photoFrameBox}>
        <div className={styles.photoFrameBoxInline}>
          <div className={styles.photoFrameSecL}>
            <Iimg
              className={styles.photoFrameL}
              src={photoFrameL}
              transition={false}
              onReady={() => {}}
            />
          </div>

          <div className={styles.photoFrameSecC}>
            <div className={null}>
              <Iimg
                className={styles.photoFrameT}
                src={photoFrameT}
                transition={false}
                onReady={() => {}}
              />
            </div>
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                DCContext.showPlayerinfoModal(nation?.commander.user_id);
              }}
            >
              <IbgDiv
                className={styles.photoFrame_bgPhoto}
                src={nation?.commander.image}
                transition={false}
                onReady={() => {}}
              >
                <Iimg
                  className={styles.photoFrameC}
                  src={photoFrameC}
                  transition={false}
                  onReady={() => {}}
                />
              </IbgDiv>
            </ClickEffect>
            <div className={null}>
              <Iimg
                className={styles.photoFrameB}
                src={photoFrameB}
                transition={false}
                onReady={() => {}}
              />
            </div>
          </div>

          <div className={styles.photoFrameSecR}>
            <Iimg
              className={styles.photoFrameR}
              src={photoFrameR}
              transition={false}
              onReady={() => {}}
            />
          </div>
        </div>
      </div>
    );
  };

  /* 非選舉期間 */
  const PhaseNone = () => {
    return (
      <>
        <div className={styles.contentBox}>
          <CommanderPhoto />

          <div className={styles.dataTable}>
            <div className={styles.titleBar} style={{ backgroundImage: `url(${bgTitleBar2})` }}>
              <div className={styles.titleText}>{nation?.commander.title}</div>
            </div>
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                DCContext.showPlayerinfoModal(nation?.commander.user_id);
              }}
            >
              <div className={styles.dataTextRow}>
                <div className={styles.commanderNameBox}>
                  <div className={styles.commanderNameText}>{nation?.commander.name}</div>
                  {nation?.commander.user_id && (
                    <div className={styles.excellencyText}>{tt('election_excellency')}</div>
                  )}
                </div>
              </div>
            </ClickEffect>
            <div className={styles.titleBar} style={{ backgroundImage: `url(${bgTitleBar2})` }}>
              <div className={styles.titleText}>{tt(`governing_body`) /* 當權派 */}</div>
            </div>
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                DCContext.showUnionModal(nation?.commander.union_id);
              }}
            >
              <div className={styles.dataTextRow}>{nation?.commander.union}</div>
            </ClickEffect>
            <div className={styles.titleBar} style={{ backgroundImage: `url(${bgTitleBar2})` }}>
              <div className={styles.titleText}>{tt(`reelection_day`) /* 改選日 */}</div>
            </div>
            <div className={`${styles.dataTextRow} ${styles.date}`}>
              {moment
                .utc(DCContext.election?.candidate_sign_up_from)
                .local()
                .format('YYYY.MM.DD HH:mm')}
            </div>
          </div>
        </div>

        <IbgDiv
          className={styles.sloganBarBox}
          src={nation?.slogan_background_image}
          transition={false}
          onReady={() => {}}
        >
          <img className={styles.seal} src={seal} />
          <div>
            <div className={`${styles.sloganText} ${styles.sloganText1}`}>
              {nation?.commander_words?.length ? nation?.commander_words?.[0] : 'SI VIS PACEM'}
            </div>
            <div className={`${styles.sloganText} ${styles.sloganText2}`}>
              {nation?.commander_words?.length ? nation?.commander_words?.[1] : 'PARA BELLVM'}
            </div>
            <div className={`${styles.sloganText} ${styles.sloganText3}`}>
              {nation?.commander_words?.length ? nation?.commander_words?.[2] : ''}
            </div>
          </div>

          {DCContext.isCommanderByNationId(nation?.id) && (
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                showModal_words();
              }}
            >
              <img className={styles.editBtnImg} src={icon_pen} />
            </ClickEffect>
          )}
        </IbgDiv>
      </>
    );
  };

  const phaseNone = useMemo(() => {
    console.log('[Headquarter] PhaseNone render');

    return <PhaseNone />;
  }, [nation, DCContext.election]);

  /* 參選登記期間 */
  const phaseSignup = useMemo(() => {
    return (
      <>
        <div className={styles.contentBox}>
          <CommanderPhoto />

          <div className={styles.candidateStatusBox}>
            <div className={`${styles.candidateStatusText1}`}>{tt(`reselect`) /* 改選 */}</div>
            <div className={styles.candidateStatusText2}>
              {tt(`election_voting_begin_time`) /* 投票開始時間 */}
            </div>
            <div className={styles.candidateStatusTime}>
              {moment.utc(DCContext.election?.vote_from).local().format('YYYY.MM.DD HH:mm')}
            </div>
          </div>
        </div>

        <div className={styles.footer}>
          <div style={{ width: '100%' }}>
            <div className={styles.titleBar} style={{ backgroundImage: `url(${bgTitleBar2})` }}>
              <div className={styles.titleText}>{nation?.commander.title}</div>
            </div>
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                DCContext.showPlayerinfoModal(nation?.commander.user_id);
              }}
            >
              <div className={styles.dataTextRow}>
                <div className={styles.commanderNameBox}>
                  <div className={styles.commanderNameText}>{nation?.commander.name}</div>
                  {nation?.commander.user_id && (
                    <div className={styles.excellencyText}>{tt('election_excellency')}</div>
                  )}
                </div>
              </div>
            </ClickEffect>
          </div>
        </div>
      </>
    );
  }, [DCContext.election, nation]);

  /* 投票期間 */
  const phaseVote = useMemo(() => {
    return (
      <>
        <div className={styles.contentBox}>
          <CommanderPhoto />

          <div className={styles.candidateStatusBox}>
            <div className={`${styles.candidateStatusText1}`}>{tt(`reselect`) /* 改選 */}</div>
            <div className={styles.candidateStatusText2}>
              {tt(`election_voting_end_time`) /* 投票結束時間 */}
            </div>
            <div className={styles.candidateStatusTime}>
              {moment.utc(DCContext.election?.vote_to).local().format('YYYY.MM.DD HH:mm')}
            </div>
          </div>
        </div>

        <div className={styles.footer}>
          <div style={{ width: '100%' }}>
            <div className={styles.titleBar} style={{ backgroundImage: `url(${bgTitleBar2})` }}>
              <div className={styles.titleText}>{nation?.commander.title}</div>
            </div>
            <ClickEffect
              enabled={true}
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={() => {
                DCContext.showPlayerinfoModal(nation?.commander.user_id);
              }}
            >
              <div className={styles.dataTextRow}>
                <div className={styles.commanderNameBox}>
                  <div className={styles.commanderNameText}>{nation?.commander.name}</div>
                  {nation?.commander.user_id && (
                    <div className={styles.excellencyText}>{tt('election_excellency')}</div>
                  )}
                </div>
              </div>
            </ClickEffect>
          </div>
        </div>
      </>
    );
  }, [DCContext.election, nation]);

  /* 候選人列表頁 */
  const pagecCandidate = useMemo(() => {
    let diplomatic_strategy_items = {};
    DCContext.strategies?.diplomatic.map((item, ds_idx) => {
      diplomatic_strategy_items[item.id] = item;
    });

    let general_strategy_items = {};
    DCContext.strategies?.general.map((el0, idx0) => {
      general_strategy_items[el0.id] = el0;
      //
      el0.general_strategy_routes.map((el1, idx1) => {
        Object.values(el1).map((el2, idx2) => {
          if (el2) {
            general_strategy_items[el2.id] = el2;
          }
        });
      });
    });

    console.log('[Headquarter] diplomatic_strategy_items', diplomatic_strategy_items);
    console.log('[Headquarter] general_strategy_items', general_strategy_items);

    let canCLickVote = nation?.election.can_vote && !nation?.election.voted;
    console.log('[Headquarter] canCLickVote', canCLickVote);

    return (
      <>
        <div className={styles.candidatesBox}>
          {nation?.candidates?.map((el, idx) => {
            let voteIcon = iconVote;
            if (
              el.union.id == selectedCandidate?.union.id || //投票: 被選取的候選人
              el.id == nation.election?.vote_for_candidate_id //選情: 已被此玩家投票的候選人
            ) {
              voteIcon = iconVoted;
            }

            return (
              <div key={el.id} style={{ width: '100%' }}>
                <ClickEffect
                  enabled={canCLickVote}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={() => {
                    clickCandidate(el);
                  }}
                >
                  <div className={styles.candidatesRow}>
                    <div className={styles.iconVoteBox}>
                      <img className={styles.iconVote} src={voteIcon} />
                    </div>
                    <div className={styles.candidateNameCol}>
                      <div className={styles.unionName}>{el.union.name}</div>
                      <div className={styles.candidateName}>
                        <FitText>{el.union.chief}</FitText>
                      </div>
                    </div>
                    <div className={styles.strategyTextCol}>
                      <FitText _align={'right'}>
                        {general_strategy_items[el.general_strategy_id].name}
                      </FitText>
                    </div>
                    <div className={styles.strategyIconCol}>
                      <Iimg
                        className={styles.itemIcon}
                        src={general_strategy_items[el.general_strategy_id].image}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                    <div className={styles.strategyIconCol}>
                      <Iimg
                        className={styles.itemIcon_ds}
                        src={diplomatic_strategy_items[el.diplomatic_strategy_id].image}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                    <div className={styles.votesCol}>
                      <FitText>{el.votes}</FitText>
                    </div>
                  </div>
                </ClickEffect>
              </div>
            );
          })}
        </div>

        {canCLickVote && (
          <>
            <div className={styles.footer}>
              <div className={styles.voteHintBox}>
                <img className={styles.bgVoteHint} src={bgVoteHint} />
                <div className={styles.voteHintTextBox}>
                  <div className={`${styles.voteHintText0} ${styles.voteHintText1}`}>
                    {DCContext.myUnion?.name}
                  </div>
                  <div className={`${styles.voteHintText0} ${styles.voteHintText2}`}>
                    {tt(
                      `election_own_ballot_description_1`,
                      {
                        ballot_1: 1,
                        ballot_2: nation.election.ballot - 1,
                      } /* 擁有 1 張基本票和 {nation.election.ballot-1} 張城鎮票 */,
                    )}
                  </div>
                  <div className={`${styles.voteHintText0} ${styles.voteHintText3}`}>
                    {
                      tt(`election_own_ballot_description_2`, {
                        total_ballots: nation.election.ballot,
                      }) /* 共計 {nation.election.ballot} 票之投票權 */
                    }
                  </div>
                </div>
              </div>
            </div>

            {selectedCandidate && (
              <BtnRing
                color="golden"
                text={tt(`vote`) /* 投票 */}
                callback={() => {
                  clickVote();
                }}
              />
            )}
          </>
        )}
      </>
    );
  }, [DCContext.election, nation, DCContext.strategies, DCContext.myUnion, selectedCandidate]);

  return (
    <IbgDiv
      className={styles.rootContainer}
      src={nation?.street_site.image}
      transition={true}
      onReady={() => {}}
    >
      <div className={styles.mainBox} style={{ backgroundImage: `url(${bgOverlay})` }}>
        <div className={styles.flagContainer}>
          <img className={styles.bg_layer2} src={bg_layer2} />
          <Iimg
            className={styles.flag}
            src={nation?.commander?.flag}
            transition={false}
            onReady={() => {}}
          />
        </div>

        <img className={styles.bgGunsL} src={bgGunsL} />
        <img className={styles.bgGunsR} src={bgGunsR} />

        <div className={styles.rightBox}>
          <div className={styles.headquarterNameBox}>
            <div className={`${styles.headquarterName_bg}`}>{nation?.headquarters}</div>
            <div className={`${styles.headquarterName}`}>{nation?.headquarters}</div>
          </div>

          {
            _mode == 'vote'
              ? pagecCandidate //<PagecCandidate/>
              : DCContext.election?.stage == 'sign up'
              ? phaseSignup //<PhaseSignup/>
              : DCContext.election?.stage == 'vote'
              ? phaseVote //<PhaseVote/>
              : phaseNone //<PhaseNone/>
          }
        </div>

        <ClickEffect
          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
          onClick={e => {
            goNationalStrategy();
          }}
        >
          <div
            className={styles.bgStrategyTape}
            style={{ backgroundImage: `url(${bgStrategyTape})` }}
          >
            {tt('strategy') /* 戰略 */}
          </div>
        </ClickEffect>

        {/* 更換旗幟按鈕 */}
        {DCContext.election?.stage == 'none' &&
          DCContext.isCommanderByNationId(nation?.id) &&
          nation?.can_change_seal && (
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                clickChangeSeal();
              }}
            >
              <div className={styles.iconChangeBox}>
                <img className={styles.iconChange} src={iconChange} />
              </div>
            </ClickEffect>
          )}

        {_mode == 'headquarter' && (
          <>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeNation(-1);
              }}
            >
              <img src={arrowL} className={`switchArrow ${styles.arrowL}`} />
            </ClickEffect>
            <ClickEffect
              effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
              onClick={e => {
                changeNation(1);
              }}
            >
              <img src={arrowR} className={`switchArrow ${styles.arrowR}`} />
            </ClickEffect>
          </>
        )}

        {_mode == 'headquarter' && (
          <>
            {DCContext.election?.stage == 'vote' && (
              <>
                {nation?.election.show_only_chief_can_vote ? (
                  <div className={styles.voteBtnTip}>
                    {tt(`election_vote_condition_chief`) /* 僅聯盟領袖擁有投票權 */}
                  </div>
                ) : nation?.election.show_union_level_invalid ? (
                  <div className={styles.voteBtnTip}>
                    {
                      tt(
                        `election_vote_condition_union_level`,
                      ) /* 聯盟牌位達到 金牌I 以上才有投票權 */
                    }
                  </div>
                ) : (
                  <></>
                )}
                <div className={styles.btnCircleBox}>
                  <BtnRing
                    color="golden"
                    text={
                      nation?.election.can_vote
                        ? tt(`vote`) /*投票*/
                        : tt(`election_current_results`) /*選情*/
                    }
                    callback={() => {
                      setSelectedCandidate();
                      navigate(`/headquarter/${nation?.id}/vote`);
                    }}
                  />
                </div>
              </>
            )}

            {DCContext.election?.stage == 'sign up' && (
              <>
                {nation?.election.show_only_chief_can_vote ? (
                  <div className={styles.voteBtnTip}>
                    {tt(`election_signup_condition_chief`) /* 僅聯盟領袖擁有參選權 */}
                  </div>
                ) : nation?.election.show_union_level_invalid ? (
                  <div className={styles.voteBtnTip}>
                    {
                      tt(
                        `election_signup_condition_union_level`,
                      ) /* 聯盟牌位達到 金牌I 以上才有參選權 */
                    }
                  </div>
                ) : (
                  <></>
                )}

                <div className={styles.btnCircleBox}>
                  {nation?.election.can_sign_up_candidate && (
                    <BtnRing
                      color="golden"
                      text={tt(`election_run_for`) /* 參選 */}
                      callback={candidate_sign_up}
                    />
                  )}

                  {nation?.election.is_candidate && (
                    <BtnRing
                      color="golden"
                      text={tt(`political_stance`) /* 政見 */}
                      callback={() => {
                        navigate(`/strategy/${nation?.id}/edit`);
                      }}
                    />
                  )}
                </div>

                {nation?.election.is_candidate && (
                  <div className={styles.btnCircleBox2}>
                    <BtnRing
                      color="silver"
                      text={tt(`election_withdraw`) /* 退選 */}
                      callback={candidate_drop_out}
                    />
                  </div>
                )}
              </>
            )}
          </>
        )}

        <PopupMessagesIcon category={3} />

        <Navigator
          navi={
            _mode == 'vote'
              ? {
                  back: {
                    callback: () => {
                      navigate(`/headquarter/${nation.id}`);
                    },
                  },
                }
              : {
                  back: {
                    spot: 'home',
                  },
                }
          }
        />
      </div>

      {/* modal confirm */}
      <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
        <Confirm {...modalProps_confirm.confirm} />
      </Imodal>

      {/* modal confirm words */}
      <Imodal {...modalProps_words} callback={callbackModal_words}>
        <Wordsform nation={nation} callback={callbackModal_words} />
      </Imodal>
    </IbgDiv>
  );
};

