import React, { useContext, useState, useEffect, useRef } from 'react';
import { Socket as phoenixSocket } from 'phoenix';

const SocketContext = React.createContext();

export const SocketProvider = ({ children }) => {
  const [socket, setSocket] = useState();
  //
  //const [url, setUrl] = useState();
  //const [authParams, setAuthParams] = useState();
  const url = useRef();
  const authParams = useRef(); //同時用來識別 socket.onClose 時要不要清掉 socket
  //
  const [socketStatus, setSocketStatus] = useState();
  //const [doConnect, setDoConnect] = useState(0);
  const connectedTimes = useRef(0);
  const connectTimer = useRef();

  // useEffect(() => {
  // 	if (!doConnect || !url || !authParams){
  // 		return;
  // 	}
  // 	//console.log("socket connecting...");
  // 	setSocketStatus({status: "connecting"});

  // 	const s = new Socket(url, authParams);

  // 	s.onOpen((event) => {
  // 		//console.log('socket Connected.')
  // 		setSocketStatus({status: "ok"});
  // 	});
  // 	s.onError((event) => {
  // 		//console.log('socket Cannot connect.')
  // 		setSocketStatus({status: "error"});
  // 	});
  // 	s.onClose((event) => {
  // 		//console.log('socket Closed.')
  // 		setSocketStatus({status: "closed"});
  // 	});

  // 	s.connect();
  // 	setSocket(s);

  // 	return () => {
  // 		s.disconnect();
  // 		setSocket(null);
  // 	}
  // }, [doConnect]);

  const socketConnect = () => {
    if (!url.current || !authParams.current) {
      return;
    }

    console.log(
      '[SocketContext] socket connecting...',
      connectedTimes.current,
      authParams.current,
      { ...socketStatus },
    );
    setSocketStatus({ status: 'connecting' });

    // if (socket){
    // 	console.log("[SocketContext] socket 已存在，直接 connect", authParams.current);
    // 	socket.connect();
    // 	return;
    // }

    //
    //let s = new phoenixSocket(url.current, authParams.current);

    if (socket) {
      console.log('[SocketContext] socket 以原 socket 連線', authParams.current, socket);

      //閒置過久後以原 socket 重新連線可能無反應，若超過時間則重新以新 socket 連線
      //????測試結果，會導致產生多個 socket 連線
      clearTimeout(connectTimer.current);
      connectTimer.current = setTimeout(() => {
        console.log(
          '[SocketContext] 原 socket 連線逾時，改以新 socket 連線',
          authParams.current,
          socket,
        );
        //
        socket.disconnect(() => {
          console.log(
            '[SocketContext] 原 socket 完成斷線，新 socket 開始連線',
            authParams.current,
            socket,
          );
          // setSocket(new phoenixSocket(url.current, {
          // 	//debug: true,
          // 	params: authParams.current
          // }));

          socket.connect();
        });
      }, 3000);

      socket.connect();
    } else {
      console.log('[SocketContext] socket 以新 socket 連線', authParams.current);
      setSocket(
        new phoenixSocket(url.current, {
          //debug: true,
          params: authParams.current,
        }),
      );
    }

    // s.onOpen((event) => {
    // 	console.log('[SocketContext] socket Connected.')
    // 	setSocketStatus({status: "ok"});
    // });
    // s.onError((event) => {
    // 	console.log('[SocketContext] socket Cannot connect.')
    // 	setSocketStatus({status: "error"});
    // });
    // s.onClose((event) => {
    // 	console.log('[SocketContext] socket Closed.')
    // 	s = null;
    // 	setSocketStatus({status: "closed"});
    // 	setSocket(); //登出再以另一帳號登入時，須用新 userToken 重新連線
    // });

    //s.connect();
    //setSocket(s);
  };

  useEffect(() => {
    if (!socket) {
      return;
    }

    //console.log("[SocketContext] 新 socket 開始連線", socket);

    socket.onOpen(event => {
      console.log('[SocketContext] socket Connected.', socket.connectionState(), socket);
      clearTimeout(connectTimer.current);
      setSocketStatus({ status: 'ok' });

      connectedTimes.current += 1;
    });
    socket.onError(event => {
      console.log('[SocketContext] socket Cannot connect.', socket.connectionState());
      clearTimeout(connectTimer.current);
      setSocketStatus({ status: 'error' });
    });
    socket.onClose(event => {
      console.log('[SocketContext] socket Closed.', socket.connectionState(), authParams.current);
      clearTimeout(connectTimer.current);
      setSocketStatus({ status: 'closed' });

      //斷線有可能是短暫的，不能一斷線就清掉 socket
      //若無 authParams 就清掉 socket (登出重登入後需用新 userToken 重新建立新 socket)
      if (!authParams.current) {
        setSocket();
      }
    });

    socket.connect();
  }, [socket]);

  const socketDisconnect = () => {
    console.log('[SocketContext] socket socketDisconnect', socket, socketStatus);

    if (!socket || socketStatus.status !== 'ok') {
      return;
    }

    //主動 disconnect (非網路斷線)，透過刪除 authParams 使 socket 也在 onClose 時被清除
    //目前主要用於登出
    authParams.current = null;
    socket.disconnect();

    connectedTimes.current = 0;
  };

  const props = {
    value: {
      socket,
      setSocket,
      url,
      authParams,
      socketStatus,
      setSocketStatus,
      //doConnect, setDoConnect,
      connectedTimes,
      socketConnect,
      socketDisconnect,
    },
  };

  //return React.createElement(SocketContext.Provider, props, children);

  return <SocketContext.Provider value={props.value}>{children}</SocketContext.Provider>;
};

// Create a hook to use the APIContext, this is a Kent C. Dodds pattern
export const useSocketContext = () => {
  const context = useContext(SocketContext);
  if (context === undefined) {
    throw new Error('Context must be used within a Provider');
  }
  return context;
};
