export const relationThreshold = (relationLevel, relationLevelCap) => {
  if (relationLevelCap <= 1) return 0;
  const level = relationLevel >= relationLevelCap ? relationLevel - 1 : relationLevel;
  return (2 ** level - 1) * 40000;
};

export const extraLevelCapFromRelation = relationLevel => Math.max(0, (relationLevel - 1) * 5);

export const previewRelationAdd = (selectedProps, actorPrototypeId) => {
  if (!Array.isArray(selectedProps)) return 0;

  return selectedProps.reduce((sum, prop) => {
    const relationExps = prop?.relation_exps ?? prop?.prop_prototype?.relation_exps ?? 0;
    if (relationExps <= 0) return sum;

    const exclusive =
      prop?.relation_actor_exclusive ?? prop?.prop_prototype?.relation_actor_exclusive ?? false;
    const ids =
      prop?.relation_actor_prototype_ids ??
      prop?.prop_prototype?.relation_actor_prototype_ids ??
      null;
    const singleId =
      prop?.relation_actor_prototype_id ??
      prop?.prop_prototype?.relation_actor_prototype_id ??
      null;
    const targets = Array.isArray(ids) && ids.length ? ids : singleId != null ? [singleId] : [];

    if (
      exclusive &&
      actorPrototypeId != null &&
      targets.length &&
      !targets.map(String).includes(String(actorPrototypeId))
    ) {
      return sum;
    }

    const quantity = prop?.usedQuantity ?? prop?.quantity ?? 1;
    return sum + relationExps * quantity;
  }, 0);
};

export const shouldBlockUpgrade = ({
  relationLevel,
  relationLevelCap,
  selectedProps,
  actorPrototypeId,
}) => {
  if (!Array.isArray(selectedProps) || selectedProps.length === 0) return false;
  if (relationLevelCap <= 0 || relationLevel < relationLevelCap) return false;
  return previewRelationAdd(selectedProps, actorPrototypeId) > 0;
};
