import React, { useContext, useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
} from 'react-router-dom';
import {
  Form,
  Input,
  Select,
  Checkbox,
  Col,
  Row,
  Layout,
  Menu,
  Breadcrumb,
  Button,
  message,
  Modal,
} from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import styles from './Names.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';

export const Names = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  useEffect(() => {
    console.log('[Names] DCContext.pickedSeal', DCContext.pickedSeal);
    console.log('[Names] DCContext.pickedStreetimage', DCContext.pickedStreetimage);
  }, []);

  /* form */

  const [form] = Form.useForm();
  const onFinish = values => {
    let data;

    if (props.mode == 'EDIT') {
      data = {
        nickname: values.nickname,
        organization: values.organization,
      };
    } else {
      data = {
        nation_id: props.nation_id,
        nickname: values.nickname,
        organization: values.organization,
        seal_id: DCContext.pickedSeal ? DCContext.pickedSeal.id : null,
        street_site_id: DCContext.pickedStreetimage ? DCContext.pickedStreetimage.id : null,
      };
    }

    //console.log("[Names] form data", data);
    //return;

    handleClick_edit_profile(data);
  };

  const submitForm = () => {
    form.submit();
    console.log('submitForm');
  };

  //
  const handleClick_edit_profile = tmp => {
    console.log('[Names] handleClick_edit_profile', tmp);
    DCContext.updateProfile(tmp);
  };

  //edit_profile 結果
  useEffect(() => {
    if (!DCContext.msgRes[`${DCContext.playerChannelTopic},edit_profile`]) {
      return;
    }

    console.log('[Names] player,edit_profile', { ...DCContext.msgRes });

    //todo error處理

    //第一次選完陣營，重取 demos
    if (props.mode !== 'EDIT') {
      DCContext.getDemos(true);
    }

    //清除本次 send message 結果
    DCContext.setMsgRes(prevState => {
      delete prevState[`${DCContext.playerChannelTopic},edit_profile`];
      return { ...prevState };
    });

    if (props.callback) {
      props.callback();
    }
  }, [DCContext.msgRes[`${DCContext.playerChannelTopic},edit_profile`]?.uuid]);

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div
          className={styles.contentBox}
          style={props.mode == 'EDIT' ? { paddingTop: '10%' } : {}}
        >
          <Form
            action=""
            form={form}
            name="control-hooks"
            onFinish={onFinish}
            initialValues={{
              nickname: props.mode == 'EDIT' ? DCContext.userProfile.nickname : '',
              organization: props.mode == 'EDIT' ? DCContext.userProfile.organization : '',
            }}
            labelCol={{ span: 8, className: styles.colTitle }}
            wrapperCol={{ span: 16, className: styles.colContent }}
            colon={false}
          >
            <Form.Item
              name="nickname"
              required={false}
              label={
                <div className={styles.colTitle}>
                  {tt(`your_character_name`) /* 您的角色名稱 */}
                </div>
              }
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`your_character_name`) }), //角色名稱為必填
                },
                {
                  max: 12,
                  message: tt(`form_field_warn_max_length`, {
                    field_name: tt(`your_character_name`),
                    max_length: 12,
                  }), //角色名稱超過12個字
                },
              ]}
            >
              <Input bordered={true} className={styles.inputBox} />
            </Form.Item>

            <Form.Item
              name="organization"
              required={false}
              label={
                <div className={styles.colTitle}>
                  {tt(`your_organization_name`) /* 您的組織名稱 */}
                </div>
              }
              rules={[
                {
                  required: true,
                  message: tt(`form_field_required`, { field_name: tt(`your_organization_name`) }), //組織名稱為必填
                },
                {
                  max: 12,
                  message: tt(`form_field_warn_max_length`, {
                    field_name: tt(`your_organization_name`),
                    max_length: 12,
                  }), //角色名稱超過12個字
                },
              ]}
            >
              <Input bordered={true} className={styles.inputBox} />
            </Form.Item>
          </Form>

          <FitText className={`${styles.descriptionBox} modalDescriptionFont`}>
            {
              props.mode == 'EDIT'
                ? ''
                : tt(
                    `p_name_change_alert_description`,
                  ) /* 遊戲開始以後，您仍可更改以上名稱，並且仍有機會... */
            }
          </FitText>

          <div>
            <BtnGrey text={tt(`confirm`)} callback={submitForm} />
          </div>
        </div>
      </div>
    </div>
  );
};
