import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//preload
import useImagePreloader from 'lib/useImagePreloader';
import { Loading } from 'component/Loading';
//
import { FitText } from 'lib/FitText';
//import { mediaPath } from "lib/funcs";
import { Ivideo } from 'componentx/Ivideo';
import styles from './Actorpoolsrecruit.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { Actorcard } from 'component/Actorcard';
import { ClickEffect } from 'componentx/ClickEffect';
import { safePlayMedia } from 'lib/funcs';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
//
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import circleGolden from 'assets/img/circleGolden.png';

//
import actorProPanel_red from 'assets/img/teams/actorProPanel_red.png';
//import actorProPanel_white from 'assets/img/teams/actorProPanel_white.png';
//import actorProPanel_yellow from 'assets/img/teams/actorProPanel_yellow.png';

import s_SR from 'assets/img/teams/s_SR.png';
import iconActorProA from 'assets/img/teams/iconActorProA.png';
//
import minicoa0_MC from 'assets/img/tmp/minicoa0_MC.png';
//
import avatarTW01 from 'assets/img/tmp/avatar/avatarTW01.png';
import avatarMC01 from 'assets/img/tmp/avatar/avatarMC01.png';
//
import iconSearch from 'assets/img/iconSearch.png';
import iconSort from 'assets/img/iconSort.png';
import icon_tR from 'assets/img/icon_tR.png';
import icon_tSR from 'assets/img/icon_tSR.png';
import icon_tSSR from 'assets/img/icon_tSSR.png';
import icon_tAll from 'assets/img/icon_tAll.png';

export const Actorpoolsrecruit = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();
  const ChannelContext = useChannelContext();
  //
  let navigate = useNavigate();

  const [coupons, setCoupons] = useState([]); //抽到的角色資料
  const videoRef_op = useRef(); //前半動畫
  const videoRef_characters = useRef({}); //抽中角色動畫
  const currentVideoIdx = useRef(-1); //目前播放的動畫
  const [isVideoPlaying, setIsVideoPlaying] = useState(true); //是否還在影片過場

  /* 預載 */

  const { setPreloadImages, imagesPreloaded, preloadedRatio } = useImagePreloader();
  const preloadKey = 'recruit';

  useEffect(() => {
    if (!DCContext.preloads?.[preloadKey]) {
      return;
    }

    console.log('[Actorpoolsrecruit] [preload] setPreloadImages', DCContext.preloads?.[preloadKey]);

    setPreloadImages(DCContext.preloads?.[preloadKey]);
  }, [DCContext.preloads?.[preloadKey]]);

  useEffect(() => {
    console.log('[Actorpoolsrecruit] [preload] imagesPreloaded', imagesPreloaded, {
      ...DCContext.preloads,
    });

    //清空本次該預載的
    if (imagesPreloaded && DCContext.preloads?.[preloadKey]) {
      DCContext.setPreloads(preState => {
        let tmp = { ...preState };
        tmp[preloadKey] = null;
        delete tmp[preloadKey];

        return tmp;
      });
    }
  }, [imagesPreloaded]);

  useEffect(() => {
    if (!DCContext.recruitResult) {
      return;
    }

    console.log('[Actorpoolsrecruit] DCContext.recruitResult', DCContext.recruitResult);
    setCoupons(DCContext.recruitResult?.recruit_coupons);
  }, [DCContext.recruitResult]);

  const playNextVideo = () => {
    currentVideoIdx.current++;
    console.log('[Actorpoolsrecruit] currentVideoIdx.current', currentVideoIdx.current);

    if (!videoRef_characters.current[currentVideoIdx.current]) {
      setIsVideoPlaying(false);
      return;
    }

    videoRef_characters.current[currentVideoIdx.current].style.zIndex = 99;
    void safePlayMedia(videoRef_characters.current[currentVideoIdx.current]);
  };

  const skipVideo = () => {
    setIsVideoPlaying(false);
  };

  useEffect(() => {
    if (!isVideoPlaying) {
      DCContext.playSound2(`/audio/sound_effect/SE114.mp3`);
      DCContext.resumeMusic();
    }
  }, [isVideoPlaying]);

  const aniStyles = useSpring({
    from: { opacity: 0 },
    to: { opacity: 1 },
    loop: { reverse: true },
    //reverse: true,
    config: {
      duration: 1500,
    },
  });

  return !DCContext.preloads || (DCContext.preloads?.[preloadKey] && !imagesPreloaded) ? (
    <Loading preloadedRatio={preloadedRatio}></Loading>
  ) : (
    <>
      {isVideoPlaying ? (
        //播放過場影片
        <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
          {coupons.map((e, i) => {
            return (
              /*
						<video 
							key={i} 
							ref={(ref)=>{videoRef_characters.current[i] = ref}} 
							className={styles.videoFit} 
							preload="auto" 
							playsInline 
							onCanPlay={() => {}}
							onCanPlayThrough={() => {}}
							onEnded={() => {playNextVideo();}}
							onClick={() => {}}
						> 
							<source src={mediaPath(e.actor_prototype.video)} type="video/mp4"/>
						</video>
						*/

              <Ivideo
                innerRef={ref => {
                  videoRef_characters.current[i] = ref;
                }}
                src={e.actor_prototype.video}
                //
                key={i}
                //ref={(ref)=>{videoRef_characters.current[i] = ref}}
                className={styles.videoFit}
                preload="auto"
                playsInline
                onCanPlay={() => {}}
                onCanPlayThrough={() => {}}
                onEnded={() => {
                  playNextVideo();
                }}
                onClick={() => {}}
              />
            );
          })}

          {/* <video 
					ref={videoRef_op} 
					className={styles.videoFit} 
					preload="auto" 
					autoPlay 
					playsInline 
					onCanPlay={() => {videoRef_op.current.play();}}
					onCanPlayThrough={() => {}}
					onEnded={() => {playNextVideo();}}
					onClick={() => {videoRef_op.current.play();}}
				> 
					<source src={mediaPath(DCContext.recruitResult?.video)} type="video/mp4"/>
				</video> */}

          <Ivideo
            innerRef={videoRef_op}
            src={DCContext.recruitResult?.video}
            //
            className={styles.videoFit}
            preload="auto"
            autoPlay
            playsInline
            onCanPlay={() => {
              console.log('[Actorpoolsrecruit] videoRef_op onCanPlay');
              DCContext.pauseMusic(); //暫停背景音樂
              void safePlayMedia(videoRef_op.current);
            }}
            onCanPlayThrough={() => {}}
            onEnded={() => {
              playNextVideo();
            }}
            onClick={() => {
              void safePlayMedia(videoRef_op.current);
            }}
          />

          {/* 點擊跳下個幹部動畫 */}
          <div
            className={styles.nextVideoSensor}
            onClick={() => {
              if (currentVideoIdx.current >= 0) {
                playNextVideo();
              }
            }}
          ></div>

          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE3.mp3` }}
            onClick={() => {
              skipVideo();
            }}
          >
            <div className={styles.skipText}>{tt('skip') /* 跳過 */}</div>
          </ClickEffect>
        </IbgDiv>
      ) : (
        // 顯示最後結果
        <IbgDiv
          className={styles.rootContainer}
          src={coupons.length == 1 ? coupons[0]?.scarcity_image : null}
          transition={true}
          onReady={() => {}}
        >
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE3.mp3`, flash: false }}
            onClick={() => {
              navigate(-1);
            }}
          >
            <div className={styles.clickSensor}>
              <div className={styles.mainBox}>
                {coupons.length == 1 ? (
                  <div className={styles.teamBox}>
                    <div className={styles.oneEgg_Box}>
                      <div className={styles.oneEgg_nameBox}>
                        <FitText className={styles.oneEgg_nameText}>
                          {coupons[0]?.actor_prototype?.name}
                        </FitText>
                      </div>
                      <div className={`${styles.oneEgg_actorBox} noClick`}>
                        <Actorcard actor={coupons[0]} cardType="M" dataType="recruit" />
                      </div>
                      <div className={styles.oneEgg_nameBox}></div>
                    </div>
                  </div>
                ) : (
                  coupons.length == 10 && (
                    <div className={styles.teamBox}>
                      <div className={styles.tenEggs_Box}>
                        {coupons.map((tmpActor, i) => {
                          return (
                            <div key={tmpActor.id} className={styles.actorBox}>
                              <Actorcard actor={tmpActor} cardType="S" dataType="recruit" />
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )
                )}
              </div>
              <animated.div className={styles.hintText} style={{ ...aniStyles }}>
                {tt(`click_anywhere_to_leave`) /* 點擊任何位置離開 */}
              </animated.div>
            </div>
          </ClickEffect>
        </IbgDiv>
      )}
    </>
  );
};
