import React, { useContext, useState, useEffect, useRef } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
import {
  find as lodash_find,
  findIndex as lodash_findIndex,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import iConfig from 'iConfig';
import styles from './Teams.module.scss';
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { Actorcard } from 'component/Actorcard';
import { ClickEffect } from 'componentx/ClickEffect';
import { integerToRoman } from 'lib/funcs';
//
import { Imodal } from 'componentx/Imodal';
import { Confirm } from 'componentx/Confirm';
import { Medals } from 'component/Medals';
import { MedalTypeSwitcher } from 'component/MedalTypeSwitcher';
//
import arrow from 'assets/img/teams/arrow.png';
import iconFight from 'assets/img/teams/iconFight.png';
import iconAuto from 'assets/img/iconAuto.png';
import iconChange from 'assets/img/iconChange.png';
//
import icon_radio from 'assets/img2/icon_radio.png';
import icon_radio_ckecked from 'assets/img2/icon_radio_ckecked.png';
//preload
import useImagePreloader from 'lib/useImagePreloader';
import { Loading } from 'component/Loading';
import bgMedalShadow from 'assets/img2/bgMedalShadow.png';

export const Teams = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  const navigate = useNavigate();
  const location = useLocation();
  //
  const [teams, setTeams] = useState([]);
  const [actors, setActors] = useState();
  const team_id = useRef();
  const iconFightRef = useRef();
  //
  const [showMedals, setShowMedals] = useState(false);

  //
  let { mode, teamIdx } = props;
  teamIdx = parseInt(teamIdx) || 1;

  //
  const [catIdx, setCatIdx] = useState();
  const [catKey, setCatKey] = useState(props.catKey || '1v1');
  const [medalsData, setMedalsData] = useState();
  const [medalData, setMedalData] = useState();

  useEffect(() => {}, []);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('[Teams] channel player 未連線');
      return;
    }

    console.log('[Teams] channel player 已連線');
    DCContext.getActors();
    DCContext.getMedals();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.actors) {
      return;
    }

    console.log('[Teams] DCContext.actors', DCContext.actors);

    const tmpTeams = DCContext.getActorTeams();
    setTeams(tmpTeams);
    console.log('[Teams] tmpTeams', tmpTeams);

    //取出所選隊伍成員
    let tmpActors = [];
    if (tmpTeams[teamIdx - 1]) {
      tmpActors = tmpTeams[teamIdx - 1].actors;
      team_id.current = tmpTeams[teamIdx - 1].team_id;
    }

    console.log('[Teams] tmpActors', tmpActors, team_id.current);
    setActors(tmpActors);
  }, [DCContext.actors, teamIdx]);

  useEffect(() => {
    if (!catKey || !DCContext.medalTypes) {
      return;
    }

    let tmpIdx = lodash_findIndex(DCContext.medalTypes, { key: catKey });

    if (tmpIdx === -1) {
      tmpIdx = 0;
    }

    //console.log("[Teams] tmpIdx", tmpIdx);

    setCatIdx(tmpIdx);
  }, [catKey, DCContext.medalTypes]);

  //牌位
  useEffect(() => {
    if (!DCContext.medals) {
      return;
    }

    console.log('[Teams] DCContext.medals', DCContext.medals);
    setMedalsData(DCContext.medals);
  }, [DCContext.medals]);

  useEffect(() => {
    if (!medalsData || !catKey || !medalsData?.[catKey]) {
      return;
    }
    console.log('[Teams] medalsData', medalsData);

    let tmp = lodash_find(medalsData.medals, ['id', medalsData?.[catKey]?.medal_id]);
    console.log('[Teams] medal', tmp);

    setMedalData(tmp);
  }, [medalsData, catKey]);

  //編隊
  const handleClick_pick = e => {
    console.log('[Teams] handleClick_pick', location.pathname);

    //編隊
    navigate(`/user/pickactors/${teamIdx}`, {
      state: {
        returnUrl: location.pathname,
        returnState: location.state,
      },
    });
  };

  //出戰
  const handleClick_newAttack = e => {
    console.log('[Teams] handleClick_newAttack', actors);

    //複選隊伍
    if (props.multiSelectable) {
      props.clickFightCallback();

      return;
    }

    //單選
    if (!actors?.length) {
      showModal_confirm({
        confirm: {
          /*請至少派1名幹部出戰。*/
          message: { i18nKey: `actor_needed_at_least_one` },
          buttons: [
            {
              text: { i18nKey: `confirm` },
              callback: () => {
                callbackConfirm({});
              },
            },
          ],
        },
      });

      return;
    }

    //
    props.clickFightCallback({
      team_id: team_id.current,
    });
  };

  //點擊 tab 或 checkbox
  const clickTab = (e, sn) => {
    const dataElement = e.target.closest('[data-clickEl]');
    console.log('[Teams] clickTab', dataElement.dataset.clickel, sn);

    switch (dataElement.dataset.clickel) {
      case 'tab':
        navigate(`/user/teams/${mode}/${sn}`, { state: location.state });
        break;

      case 'checkbox':
        console.log('[Teams] clickTab team id', sn, teams[sn - 1]);

        if (!teams[sn - 1]?.actors?.length) {
          return;
        }

        DCContext.setCheckedTeamIdxs(preState => {
          let tmp = { ...preState };
          if (!tmp[sn]) {
            tmp[sn] = teams[sn - 1].team_id;
          } else {
            delete tmp[sn];
          }

          return tmp;
        });

        break;
    }
  };

  useEffect(() => {
    if (!teams.length) {
      return;
    }

    console.log('[Teams] teams', teams);

    //檢查複選，若選中的隊伍中所有幹部被移除，變成空隊伍
    if (DCContext.checkedTeamIdxs) {
      let tmp = { ...DCContext.checkedTeamIdxs };
      Object.entries(DCContext.checkedTeamIdxs).forEach(([key, value]) => {
        if (!teams[key - 1]?.actors?.length) {
          delete tmp[key];
        }
      });

      DCContext.setCheckedTeamIdxs(tmp);
    }
  }, [teams]);

  useEffect(() => {
    if (!DCContext.checkedTeamIdxs) {
      return;
    }

    console.log('[Teams] checkedTeamIdxs', DCContext.checkedTeamIdxs);
  }, [DCContext.checkedTeamIdxs]);

  /* modal confirm */

  const [modalProps_confirm, setModalProps_confirm] = useState({
    //ratio: 0.7,
    visible: false,
  });

  const showModal_confirm = exProps => {
    setModalProps_confirm(prevState => ({
      ...prevState,
      ...exProps,
      visible: true,
    }));
  };

  const callbackModal_confirm = (type, e) => {
    //console.log("callbackPlayerModal", type, e);
    setModalProps_confirm(prevState => ({
      ...prevState,
      visible: false,
    }));
  };

  const callbackConfirm = returnParams => {
    console.log('[Teams] callbackConfirm', returnParams);
    //
    callbackModal_confirm(null, null);
  };

  /* 預載 */

  const { setPreloadImages, imagesPreloaded, preloadedRatio } = useImagePreloader();
  const preloadKey = 'actors';

  useEffect(() => {
    if (!DCContext.preloads?.[preloadKey]) {
      return;
    }

    console.log('[Teams] [preload] setPreloadImages', DCContext.preloads?.[preloadKey]);

    setPreloadImages(DCContext.preloads?.[preloadKey]);
  }, [DCContext.preloads?.[preloadKey]]);

  useEffect(() => {
    console.log('[Teams] [preload] imagesPreloaded', imagesPreloaded, DCContext.preloads);

    //清空本次該預載的
    if (imagesPreloaded && DCContext.preloads?.[preloadKey]) {
      DCContext.setPreloads(preState => {
        let tmp = { ...preState };
        tmp[preloadKey] = null;
        delete tmp[preloadKey];

        return tmp;
      });
    }
  }, [imagesPreloaded]);

  return (
    <>
      {!actors || !DCContext.preloads || (DCContext.preloads?.[preloadKey] && !imagesPreloaded) ? (
        <Loading preloadedRatio={preloadedRatio}></Loading>
      ) : (
        <div className={styles.rootContainer}>
          <div className={styles.mainBox}>
            <div className={styles.contBox}>
              {/* left panel */}
              <div className={styles.leftPanelBox}>
                <div className={styles.leftPanelBtnBox}>
                  {/* <div style={{top: '22%'}} className={styles.rightPanelBtnItem}>
							<img src={iconAuto}/>
						</div> */}

                  <div style={{ top: '73%' }} className={styles.rightPanelBtnItem}>
                    <MedalTypeSwitcher
                      catKey={catKey}
                      callback_catKey={_catKey => {
                        setCatKey(_catKey);
                      }}
                    />
                  </div>
                </div>

                <div className={styles.leftPanel}>
                  <img className={styles.arrowL} src={arrow} />
                  <div className={styles.iconFightBox}>
                    <img className={styles.bgMedalShadow} src={bgMedalShadow} />
                    <ClickEffect
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={() => {
                        setShowMedals(true);
                      }}
                    >
                      <Iimg
                        className={styles.medalImage}
                        src={medalData?.image}
                        transition={false}
                        onReady={() => {}}
                      />
                    </ClickEffect>
                  </div>
                  <div className={styles.textFight}>
                    {catKey == 'Union' ? medalData?.union_name : medalData?.player_name}
                  </div>
                </div>
              </div>

              {/* right panel */}
              <div className={styles.rightPanelBox}>
                <div className={styles.rightPanel}>
                  <img className={styles.arrowL} src={arrow} />

                  {props.showFightBtn && (
                    <>
                      <div className={styles.iconFightBox}>
                        <img ref={iconFightRef} className={styles.iconFight} src={iconFight} />
                        <ClickEffect
                          enabled={true}
                          effectTarget={iconFightRef}
                          effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                          onClick={e => {
                            handleClick_newAttack(e);
                          }}
                        >
                          <div className={styles.iconFightSensor}></div>
                        </ClickEffect>
                      </div>
                      <div className={styles.textFight}>{tt(`join_war`) /* 出戰 */}</div>
                    </>
                  )}
                </div>
              </div>

              {/* right panel */}
              {/* <div className={styles.rightPanelBox}>
					<div className={styles.rightPanel}>
					<img className={styles.arrowL} src={arrow}/>
						<div className={styles.iconFightBox}>
							<div className={styles.textFight}>&nbsp;</div>
							<img className={styles.iconFight} src={goldmedal}/>
							<div className={styles.textFight}>金牌3</div>
						</div>
					</div>
				</div> */}

              {/* <div className={styles.rightPanelBtnBox}>
					<div style={{top: '22%'}} className={styles.rightPanelBtnItem}>
						<img src={iconAuto}/>
					</div>
					<div style={{bottom: '18%'}} className={styles.rightPanelBtnItem}>
						<img src={iconChange}/>
					</div>
					<div style={{bottom: '6%'}} className={styles.rightPanelBtnItem}>
						<img src={icon1v1}/>
					</div>
				</div> */}

              <div className={styles.teamBox}>
                {[...Array(5)].map((x, idx) => {
                  let i = 4 - idx;
                  let tmpActor = actors[i];
                  return (
                    <ClickEffect
                      enabled={true}
                      key={tmpActor ? `actor_${tmpActor.id}` : `empty_${i + 1}`}
                      effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                      onClick={e => {
                        handleClick_pick(e);
                      }}
                    >
                      <div className={styles.actorCardBox}>
                        <Actorcard
                          actor={tmpActor}
                          positonKey={i + 1}
                          cardType="M"
                          dataType="teams"
                        />
                      </div>
                    </ClickEffect>
                  );
                })}
              </div>
            </div>
          </div>

          <div className={`tabBar ${props.multiSelectable ? 'multiSelectable' : ''}`}>
            {[...Array(5)].map((tmp, idx) => {
              let sn = idx + 1;
              return (
                <ClickEffect
                  key={idx}
                  effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                  onClick={e => {
                    clickTab(e, sn);
                  }}
                >
                  <div
                    key={idx}
                    data-clickel="tab"
                    className={`tab ${teamIdx == sn ? 'active' : ''}`}
                  >
                    {props.multiSelectable && (
                      <div data-clickel="checkbox" className={`tabCheckBox`}>
                        <img
                          className={`tabCheckBoxImg`}
                          src={DCContext.checkedTeamIdxs?.[sn] ? icon_radio_ckecked : icon_radio}
                        />
                      </div>
                    )}

                    <div className={`tabText1`}>{integerToRoman(sn)}</div>
                    <div className={`tabText2`}>{teams[idx]?._totalPower}</div>
                  </div>
                </ClickEffect>
              );
            })}

            {/* <ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e) => { clickTab(e, 1)}}>
					<div data-clickEl='tab' className={`tab ${teamIdx==1 ? "active":""}`}>
						{props.multiSelectable && (
							<div data-clickEl='checkbox' className={`tabCheckBox`}>
								<img className={`tabCheckBoxImg`} src={DCContext.checkedTeamIdxs[1] ? icon_radio_ckecked : icon_radio} />
							</div>
						)}

						<div className={`tabText1`}>Ⅰ</div>
						<div className={`tabText2`}>{teams[0]?.power}</div>
					</div>
				</ClickEffect>
				<ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e) => { clickTab(e, 2)}}>
					<div data-clickEl='tab' className={`tab ${teamIdx==2 ? "active":""}`}>
						{props.multiSelectable && (
							<div data-clickEl='checkbox' className={`tabCheckBox`}>
								<img className={`tabCheckBoxImg`} src={icon_radio} />
							</div>
						)}

						<div className={`tabText1`}>Ⅱ</div>
						<div className={`tabText2`}>{teams[1]?.power}</div>
					</div>
				</ClickEffect>
				<ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e) => { clickTab(e, 3)}}>
					<div data-clickEl='tab' className={`tab ${teamIdx==3 ? "active":""}`}>
						<div className={`tabText1`}>Ⅲ</div>
						<div className={`tabText2`}>{teams[2]?.power}</div>
					</div>
				</ClickEffect>
				<ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e) => { clickTab(e, 4)}}>
					<div data-clickEl='tab' className={`tab ${teamIdx==4 ? "active":""}`}>
						<div className={`tabText1`}>Ⅳ</div>
						<div className={`tabText2`}>{teams[3]?.power}</div>
					</div>
				</ClickEffect>
				<ClickEffect effect={{sound: `/audio/sound_effect/SE1.mp3`}} onClick={(e) => { clickTab(e, 5)}}>
					<div data-clickEl='tab' className={`tab ${teamIdx==5 ? "active":""}`}>
						<div className={`tabText1`}>Ⅴ</div>
						<div className={`tabText2`}>{teams[4]?.power}</div>
					</div>
				</ClickEffect> */}
          </div>

          {showMedals && (
            <div className={styles.pageBox} style={{ zIndex: 9999 }}>
              <Medals
                catKey={catKey}
                style={{ zIndex: 9999 }}
                callback_close={() => {
                  setShowMedals(false);
                }}
              />
            </div>
          )}

          {/* modal confirm */}
          <Imodal {...modalProps_confirm} callback={callbackModal_confirm}>
            <Confirm {...modalProps_confirm.confirm} />
          </Imodal>
        </div>
      )}
    </>
  );
};
