import React, { useContext, useState, useEffect, useRef, useMemo } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useRoutes,
  useNavigate,
  useParams,
  useLocation,
} from 'react-router-dom';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { useLocalStorage } from 'lib/useLocalStorage';
import { FitText } from 'lib/FitText';
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './Actorprofile.module.scss';
//
import background from 'assets/img/bgClockSilver.png';
import { Navigator } from 'component/modal/Navigator';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnRing } from 'component/BtnRing';
import { ActorSwitch } from 'component/ActorSwitch';
import { PopupMessagesIcon } from 'component/modal/PopupMessagesIcon';
//
import icon_upgrade from 'assets/img/icon_upgrade.png';
import icon_skilltree from 'assets/img/icon_skilltree.png';
import bgTitle_s from 'assets/img/bgTitle_s.png';
import tabSilver from 'assets/img/teams/tabSilver.png';
import tabGolden from 'assets/img/teams/tabGolden.png';
import circleGolden from 'assets/img/circleGolden.png';
import fgCharacterMask from 'assets/img2/fgCharacterMask.png';
import bgTunl from 'assets/img2/bgTunl.png';

//
import { ActorProps } from 'component/ActorProps';
import { UwActorTopBlock } from 'features/underworld';
//import {EquipSkill} from 'component/EquipSkill';

export const Actorprofile = () => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const location = useLocation();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  const [actor, setActor] = useState();

  let { actionId } = useParams();
  actionId = parseInt(actionId);
  //console.log('[Actorprofile] actionId: ', actionId);

  const [showInfoType, setShowInfoType] = useState(1);
  //強化 進化 裝備 修煉 ...等等返回 幹部資訊頁 或 庫房
  const [returnUrl_actorSettings, setReturnUrl_actorSettings] = useLocalStorage(
    'returnUrl_actorSettings',
    location.pathname,
  );

  useEffect(() => {}, []);

  /* */

  useEffect(() => {
    if (!DCContext.userProfile) {
      return;
    }

    console.log('[Actorprofile] playMusic');
    DCContext.playMusic(`${DCContext.userProfile.music}`);
  }, [DCContext.userProfile]);

  /* 初始資料 */

  //監測特定 channel 連線變化狀態
  useEffect(() => {
    if (!ChannelContext.channels[DCContext.playerChannelTopic]) {
      console.log('channel player 斷線');
      return;
    }

    console.log('channel player 已連線');
    DCContext.getActors();
  }, [ChannelContext.channels[DCContext.playerChannelTopic]]);

  useEffect(() => {
    if (!DCContext.actors) {
      return;
    }

    //console.log("[Actorprofile] DCContext.actors", DCContext.actors, actionId);

    let actorData = DCContext.getActorDataById(actionId);
    setActor(actorData);
    console.log('[Actorprofile] actorData', actorData);

    //強化 進化 裝備 修煉 ...等等返回 幹部資訊頁 或 庫房
    setReturnUrl_actorSettings(location.pathname);
  }, [DCContext.actors, actionId]);

  /* */

  const changeActor = p => {
    let newIdx = actor.idx + p;
    if (newIdx >= DCContext.actors.length) {
      newIdx = 0;
    } else if (newIdx < 0) {
      newIdx = DCContext.actors.length - 1;
    }
    console.log('[Actorprofile] newIdx', newIdx);

    navigate(`/user/actorprofile/${DCContext.actors[newIdx].id}`);
  };

  const changeOutfit = () => {
    console.log('[Actorprofile] changeOutfit', actor.outfits);
    if (!actor.outfits || actor.outfits.length <= 1) {
      return;
    }

    //
    DCContext.playSound(`/audio/sound_effect/SE1.mp3`);
    navigate(`/user/actoroutfits/${actor.id}`);
  };

  const changeInfoType = t => {
    if (t == 2) {
      setShowInfoType(2);
    } else {
      setShowInfoType(1);
    }
  };

  const goActorUpgrade = () => {
    navigate(`/user/actorupgrade/${actor.id}`);
  };

  const infoDisplay = useMemo(() => {
    return <ActorProps actorData={actor} />;
  }, [actor]);

  const LifeDisplay = () => {
    return (
      <>
        <div className={`${styles.lifeinfoBox}`}>
          <img className={`bgTunl`} src={bgTunl} />
          {/* <Iimg className={`bg_scarcity_image`} src={actor?.scarcity_image} /> */}

          <div className={styles.lifeinfoRow}>
            <div className={styles.lifeinfoLabelBox}>
              <img src={bgTitle_s} />
              <div className={styles.lifeinfoBoxTitle}>{tt(`origins`) /* 出身 */}</div>
            </div>
            <div className={styles.lifeInfoValue}>{actor?.actor_prototype.family}</div>
          </div>
          <div className={styles.lifeinfoRow}>
            <div className={styles.lifeinfoLabelBox}>
              <img src={bgTitle_s} />
              <div className={styles.lifeinfoBoxTitle}>{tt(`ethnicity`) /* 族群 */}</div>
            </div>
            <div className={styles.lifeInfoValue}>{actor?.actor_prototype.ethnic_group}</div>
          </div>
          <div className={styles.lifeinfoRow}>
            <div className={styles.lifeinfoLabelBox}>
              <img src={bgTitle_s} />
              <div className={styles.lifeinfoBoxTitle}>{tt(`religion`) /* 宗教 */}</div>
            </div>
            <div className={styles.lifeInfoValue}>
              <Iimg
                className={styles.religionIcon}
                src={actor?.actor_prototype?.religion_icon}
                transition={false}
                onReady={() => {}}
              />
              {actor?.actor_prototype.religion}
            </div>
          </div>
          <div className={styles.actorDescriptionBox}>
            <div className={styles.actorDescriptionScrollBox}>
              <div className={styles.actorDescriptionContentBox}>
                <div
                  className={styles.actorDescription}
                  dangerouslySetInnerHTML={{ __html: actor?.actor_prototype.description }}
                ></div>

                <div className={styles.sponsorBox}>
                  <div
                    className={styles.sponsorText}
                    dangerouslySetInnerHTML={{ __html: actor?.actor_prototype.sponsor_gratitude }}
                  ></div>
                  {showInfoType == 2 && actor.actor_prototype.sponsor_image && (
                    <div className={styles.sponsorImageBox}>
                      <Iimg
                        className={styles.sponsorImage}
                        src={actor?.actor_prototype.sponsor_image}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </>
    );
  };

  return (
    <IbgDiv className={styles.rootContainer} src={null} transition={true} onReady={() => {}}>
      <IbgDiv className={styles.mainBox} src={null} transition={false} onReady={() => {}}>
        <div className={styles.leftBox}>
          <div className={styles.flagContainer}>
            {/* <img className={styles.bg_layer2} src={bg_layer2} /> */}
            <Iimg className={styles.flag} src={actor?.flag} transition={false} onReady={() => {}} />
            <Iimg
              className={styles.character}
              src={actor?.gif_image}
              transition={false}
              onReady={() => {}}
            />
          </div>

          {/* <img className={styles.fgCharacterMask} src={fgCharacterMask} /> */}
          <div
            className={styles.outfitChangeSensor}
            onClick={e => {
              changeOutfit();
            }}
          ></div>
        </div>

        <div className={styles.rightBox}>
          <UwActorTopBlock
            mode="profile"
            actor={actor}
            actorPrototype={actor?.actor_prototype}
            hasVisitPlot={!!actor?.actor_prototype?.has_visit_plot}
          />
          <div className={styles.nameBox}>
            <ActorSwitch actor={actor} callback_changeActor={changeActor} />
          </div>

          <div className={styles.propsBox}>{showInfoType == 2 ? <LifeDisplay /> : infoDisplay}</div>
        </div>

        <div className={`tabBar`}>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(1);
            }}
          >
            <div className={`tab ${showInfoType == 1 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`information`) /* 資訊 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect
            effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
            onClick={() => {
              changeInfoType(2);
            }}
          >
            <div className={`tab ${showInfoType == 2 ? 'active' : null}`} style={{ width: '23%' }}>
              <div className={`tabText1`}>{tt(`biography`) /* 生平 */}</div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 3 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            >
              <div className={`tabText1`}></div>
            </div>
          </ClickEffect>
          <ClickEffect effect={{ sound: `/audio/sound_effect/SE1.mp3` }} onClick={() => {}}>
            <div
              className={`tab ${showInfoType == 4 ? 'active' : null}`}
              style={{ width: '23%', opacity: 0 }}
            ></div>
          </ClickEffect>
        </div>

        {showInfoType != 2 && (
          <BtnRing
            color="golden"
            text={tt(`power_up`) /* 強化 */}
            callback={e => {
              goActorUpgrade();
            }}
          />
        )}
      </IbgDiv>

      <PopupMessagesIcon category={7} />

      <Navigator
        navi={{
          back: {
            spot: 'actors',
          },
        }}
      />
    </IbgDiv>
  );
};
