import React, { useContext, useState, useEffect } from 'react';
import { Routes, Route, Link, useRoutes, useNavigate, useParams } from 'react-router-dom';
import { Col, Row, Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
import {
  findIndex as lodash_findIndex,
  find as lodash_find,
  filter as lodash_filter,
  orderBy as lodash_orderBy,
  merge as lodash_merge,
  cloneDeep as lodash_cloneDeep,
} from 'lodash';
//
import RangeSlider from 'react-range-slider-input';
import 'react-range-slider-input/dist/style.css';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useChannelContext } from 'lib/Phoenix/ChannelContext';
import { useDCContext } from 'lib/DCContext';
//
import { Iimg } from 'componentx/Iimg';
import { IbgDiv } from 'componentx/IbgDiv';
import styles from './ItemQuantity.module.scss';
import bgRF from 'assets/img/modal/bgRF.png';
import { ClickEffect } from 'componentx/ClickEffect';
import { BtnGrey } from 'component/BtnGrey';
import { FitText } from 'lib/FitText';
//
import bgSelectedItem from 'assets/img2/daily_bundle/bgSelectedItem.png';
import icon_plus_black from 'assets/img2/icon_plus_black.png';
import icon_minus_black from 'assets/img2/icon_minus_black.png';

export const ItemQuantity = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const ChannelContext = useChannelContext();
  const DCContext = useDCContext();
  let navigate = useNavigate();
  //
  const [data, setData] = useState();
  const [slideMaxValue, setSlideMaxValue] = useState(0);
  const [slideValue, setSlideValue] = useState(0);
  //
  const debug = false;

  useEffect(() => {
    console.log('[Energyboost] props');

    return () => {
      //console.log("[Energyboost] unamount");
    };
  }, []);

  useEffect(() => {
    if (!DCContext.showItemQuantity) {
      return;
    }

    console.log(`[ItemQuantity] DCContext.showItemQuantity`, DCContext.showItemQuantity, props);

    setData(DCContext.showItemQuantity);
  }, [DCContext.showItemQuantity]);

  useEffect(() => {
    if (!data) {
      return;
    }

    console.log(`[ItemQuantity] data`, data);

    //幹部強化時
    let addableResult;
    if (data.mode == 'actorUpgrade') {
      addableResult = DCContext.canAddToProps_actorUpgrade(data);
    } else if (data.mode == 'weaponUpgrade') {
      addableResult = DCContext.canAddToProps_weaponUpgrade(data);
    }
    console.log('[ItemQuantity] addableResult', data.mode, addableResult);

    if (addableResult && !addableResult?.errorCode) {
      const usableQuantity = Number(addableResult.usableQuantity);
      const usedQuantity = Number(addableResult.usedQuantity);
      const safeUsableQuantity = Number.isFinite(usableQuantity) ? usableQuantity : 0;
      const safeUsedQuantity = Number.isFinite(usedQuantity) ? usedQuantity : 0;
      //ex. 加入素材B之後可能導致經驗值過高，所需素材A數量減少，重新點開素材A，已選20個，但最大需求只需10個
      setSlideMaxValue(Math.max(0, safeUsableQuantity, safeUsedQuantity));
      setSlideValue(Math.max(0, safeUsedQuantity));
    }
  }, [data, DCContext.tmpSelectedProps, DCContext.weapon_prototypes, DCContext.userProfile?.media]);

  // useEffect(()=>{
  //   if (!DCContext.tmpSelectedProps){
  //     return;
  //   }

  // }, [DCContext.tmpSelectedProps]);

  const clickAddItem = p => {
    if (slideValue + p > slideMaxValue || slideValue + p < 0) {
      return;
    }

    setSlideValue(prevState => {
      return prevState + p;
    });
  };

  const clickConfirm = () => {
    //此素材是否已加過
    const itemIdx = DCContext.tmpSelectedProps.findIndex(el => {
      return el.id == data.item.id;
    });
    console.log('[ItemQuantity] calcExp itemIdx', itemIdx);

    //將所選素材加入清單
    if (itemIdx === -1) {
      //此素材未加過
      if (slideValue > 0) {
        DCContext.setTmpSelectedProps(prevState => {
          let tmp = [
            ...prevState,
            {
              ...data.item,
              usedQuantity: slideValue,
            },
          ];
          console.log('[ItemQuantity] clickConfirm 此素材未加過', tmp);

          return tmp;
        });
      }
    } else {
      //此素材已加過
      DCContext.setTmpSelectedProps(prevState => {
        let copy = lodash_cloneDeep(prevState);
        if (slideValue > 0) {
          copy[itemIdx].usedQuantity = slideValue;
          console.log(
            '[ItemQuantity] clickConfirm 此素材已加過(只改數量)',
            { ...prevState },
            { ...copy },
          );
        } else {
          //移除清單中此素材
          copy.splice(itemIdx, 1);
          console.log(
            '[ItemQuantity] clickConfirm 此素材已加過，移除此素材',
            { ...prevState },
            { ...copy },
          );
        }

        return copy;
      });
    }

    DCContext.setShowItemQuantity();
  };

  return (
    <div className={styles.rootContainer} style={{ backgroundImage: `url(${bgRF})` }}>
      <div className={styles.mainBox}>
        <div className={styles.contentBox}>
          <div className={styles.leftBox}>
            <div className={styles.selectedItemBox}>
              <img className={styles.bgSelectedItem} src={bgSelectedItem} />
              <Iimg
                className={styles.selectedItemImg}
                src={data?.item?.prop_prototype?.image}
                transition={false}
                onReady={() => {}}
              />
            </div>
          </div>

          <div className={styles.rightBox}>
            <div className={styles.rightBoxCont}>
              <div className={styles.itemNameBox}>{data?.item?.prop_prototype?.name}</div>
              <div className={styles.sliderBox}>
                <RangeSlider
                  className={styles.vertical_slider}
                  //orientation={"vertical"}
                  thumbsDisabled={[true, false]} //單選設定
                  rangeSlideDisabled={true}
                  min={0}
                  max={slideMaxValue}
                  value={[0, slideValue]} //單選設定：Set lower value to 0
                  //defaultValue={3}
                  onInput={values => {
                    //DCContext.playSound(`/audio/sound_effect/SE141.mp3`);
                    const nextValue = Number(values?.[1]);
                    if (!Number.isFinite(nextValue)) return;
                    setSlideValue(Math.min(slideMaxValue, Math.max(0, nextValue)));
                  }}
                  onThumbDragEnd={values => {
                    //console.log("[ItemQuantity] RangeSlider onThumbDragEnd", values);
                  }}
                  onThumbDragStart={values => {}}
                />
              </div>
              <div className={styles.panelBox}>
                <div className={styles.panelLeft}>
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={e => {
                      clickAddItem(-1);
                    }}
                  >
                    <div>
                      <Iimg
                        className={styles.quantityBtn}
                        src={icon_minus_black}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                  </ClickEffect>
                </div>
                <div className={styles.panelCenter}>
                  {slideValue}
                  {debug && `/${slideMaxValue}`}
                </div>
                <div className={styles.panelRight}>
                  <ClickEffect
                    effect={{ sound: `/audio/sound_effect/SE1.mp3` }}
                    onClick={e => {
                      clickAddItem(1);
                    }}
                  >
                    <div>
                      <Iimg
                        className={styles.quantityBtn}
                        src={icon_plus_black}
                        transition={false}
                        onReady={() => {}}
                      />
                    </div>
                  </ClickEffect>
                </div>
              </div>
              {debug && (
                <div className={styles.panelBox}>
                  <div className={styles.panelLeft}>{DCContext.userProfile.media}</div>
                  <div className={styles.panelRight}></div>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className={styles.footer}>
          <div className={styles.footerColL}></div>

          <div className={styles.footerColC}>
            <BtnGrey
              text={tt(`confirm`)}
              callback={() => {
                clickConfirm();
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );
};
