/*

<FitText _debug={true} _align={'right'}>{selectedItem?.name}</FitText>


*/

import React, { useContext, useState, useEffect, useRef, useLayoutEffect } from 'react';
//import useFitText from "use-fit-text";
import { useFitText } from '@flyyer/use-fit-text';

export const FitText = ({ style, className, _align, _debug, ...otherProps }) => {
  const refContainer = useRef();
  const [rect, setRect] = useState({ width: '1px', height: '1px' });

  //useFitText
  const { fontSize, ref } = useFitText({}, [otherProps, rect]);

  useEffect(() => {
    setter();

    window.addEventListener('resize', setter);
    return () => {
      window.removeEventListener('resize', setter);
    };
  }, []);

  useEffect(() => {
    setter();
  }, [refContainer.current?.clientWidth, refContainer.current?.clientHeight]);

  useEffect(() => {
    if (_debug) {
      console.log(
        `[FitText] ref.current`,
        { ...ref?.current },
        fontSize,
        _align,
        otherProps.children,
      );
    }
  }, [ref, otherProps.children]);

  const setter = () => {
    if (_debug) {
      console.log(`[FitText] setter()`, refContainer.current, ref.current);
    }

    if (!refContainer.current?.clientWidth || !refContainer.current?.clientHeight) {
      return;
    }

    const clientRect = refContainer.current.getBoundingClientRect();
    //console.log(`[FitText] ref`, refContainer.current.clientHeight, clientRect.height );

    const _rect = {
      width: refContainer.current.clientWidth,
      height: refContainer.current.clientHeight,
    };

    if (_debug) {
      console.log(`[FitText] _rect`, _rect);
    }

    setRect(_rect);
  };

  return (
    <>
      {className || style ? (
        <div ref={refContainer} className={className} style={{ ...style }}>
          <div
            ref={ref}
            className={className}
            style={{
              ...style,
              //以下覆寫原有 style
              margin: 0,
              padding: 0,
              position: 'absolute', //避免撐開容器，才能計算容器的尺寸
              left: 'auto',
              top: 'auto',
              right: 'auto',
              bottom: 'auto',
              //
              fontSize,
              height: rect.height,
              width: rect.width,
            }}
          >
            {otherProps.children}
          </div>
        </div>
      ) : (
        <>
          <div
            ref={ref}
            style={{
              fontSize,
              //display: 'flex',
              //position: 'relative',
              width: '100%',
              height: '100%',
              //alignItems: 'center'
              textAlign: _align ? _align : 'left',
            }}
          >
            {otherProps.children}
          </div>
        </>
      )}
    </>
  );
};
