import React, { useContext, useState, useEffect } from 'react';
import { lazy, Suspense } from 'react';
import { Layout, Menu, Breadcrumb, Button, message, Modal } from 'antd';
//i18n
import { useTranslation, Trans } from 'react-i18next';
import { useI18n, Itrans } from 'lib/useI18n';
//
import { useDCContext } from 'lib/DCContext';
//
import cfgStyle from 'config.module.scss';
//
import iConfig from 'iConfig';
import styles from './Imodal.module.scss';

import iconCloseGray from 'assets/img/modal/iconCloseGray.png';
import iconCloseWhite from 'assets/img2/icon_close_white.png';

export const Imodal = props => {
  /* i18n */
  const { tt } = useI18n();
  //
  const DCContext = useDCContext();

  let width;
  let height;
  let wrapClassName;
  if (props.fullscreen) {
    wrapClassName = styles.fullscreen;
    width = `100vw`;
    height = `min(calc(100vw * 3/4), 100vh)`;
  } else {
    wrapClassName = null;
    //
    const ratio = props.ratio ? props.ratio : 0.6;
    width = `calc(${cfgStyle.viewport_flex_height} * ${ratio} * (1632/960))`;
    height = `calc(${cfgStyle.viewport_flex_height} * ${ratio})`;
  }

  const shadowClassName = props.shadow === false ? '' : styles.shadow;
  const opacityBgClassName = props.opacityBg === true ? styles.opacityBg : '';

  //console.log('Imodal props', props);

  const playSound = () => {
    DCContext.playSound(`/audio/sound_effect/SE1.mp3`);
  };

  return (
    <Modal
      wrapClassName={`${wrapClassName} ${opacityBgClassName}`}
      title=""
      centered
      contentBg={`red`}
      footer={null}
      closable={false}
      visible={props.visible}
      destroyOnClose={props.destroyOnClose || false}
      onOk={e => {
        props.callback('ok', e);
      }}
      onCancel={e => {
        console.log('[Imodal] onCancel');
        playSound();
        props.callback('cancel', e);
      }}
      width={width}
      bodyStyle={{ padding: 0 }}
      maskClosable={props.maskClosable === false ? false : true}
      mask={props.opacityBg === true ? false : true}
    >
      <div className={`${styles.modalWrap} ${shadowClassName}`} style={{ height: height }}>
        {props.children}

        {props.maskClosable === false ? (
          <></>
        ) : (
          <img
            className={styles.iconClose}
            src={props.closeBtn_color == 'white' ? iconCloseWhite : iconCloseGray}
            onClick={e => {
              playSound();
              props.callback('cancel', e);
            }}
          />
        )}
      </div>
    </Modal>
  );
};
